  function saveStoreTypeSubNav(value) {
    try {
      const normalizedValue = normalizeCategoryName(value);
      if (normalizedValue) {
        window.localStorage.setItem(storeTypeSubNavStorageKey, normalizedValue);
      } else {
        window.localStorage.removeItem(storeTypeSubNavStorageKey);
      }
    } catch (error) {
      // The current business type remains selected without storage.
    }
  }

