  function ensureSuperAdminSnackbar() {
    if (
      superAdminSnackbarElements?.root?.isConnected
      && superAdminSnackbarElements?.copyButton instanceof HTMLButtonElement
    ) {
      return superAdminSnackbarElements;
    }
    if (superAdminSnackbarElements?.root?.isConnected) {
      superAdminSnackbarElements.root.remove();
      superAdminSnackbarElements = null;
    }

    const root = document.createElement("div");
    root.className = "product-editor-snackbar";
    root.style.setProperty(
      "--super-admin-snackbar-duration",
      `${superAdminSnackbarAutoDismissMs}ms`,
    );
    root.hidden = true;
    root.setAttribute("role", "status");
    root.setAttribute("aria-live", "polite");

    const icon = document.createElement("span");
    icon.className = "product-editor-snackbar__icon";
    icon.setAttribute("aria-hidden", "true");
    icon.innerHTML = snackbarIconMarkup.notice;

    const copy = document.createElement("span");
    copy.className = "product-editor-snackbar__copy";
    const title = document.createElement("strong");
    const message = document.createElement("span");
    copy.append(title, message);

    const actions = document.createElement("div");
    actions.className = "product-editor-snackbar__actions";

    const copyButton = document.createElement("button");
    copyButton.type = "button";
    copyButton.className = "product-editor-snackbar__copy-button";
    copyButton.hidden = true;
    copyButton.setAttribute("aria-label", "Copy API key");
    copyButton.title = "Copy API key";
    copyButton.innerHTML = snackbarIconMarkup.copy;
    copyButton.addEventListener("click", () => {
      const value = String(copyButton.dataset.copyValue || "").trim();
      if (!value) {
        return;
      }
      void window.GMSSuperAdminClipboard?.copy?.(value, "API key");
    });

    const closeButton = document.createElement("button");
    closeButton.type = "button";
    closeButton.className = "product-editor-snackbar__close";
    closeButton.setAttribute("aria-label", "Dismiss notification");
    closeButton.title = "Dismiss";
    closeButton.innerHTML = `
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
        <path d="M18 6 6 18"></path>
        <path d="m6 6 12 12"></path>
      </svg>
    `;
    closeButton.addEventListener("click", () => hideSuperAdminSnackbar());
    actions.append(copyButton, closeButton);

    const timer = document.createElement("div");
    timer.className = "product-editor-snackbar__timer";
    timer.setAttribute("aria-hidden", "true");
    const timerBar = document.createElement("span");
    timerBar.className = "product-editor-snackbar__timer-bar";
    timer.appendChild(timerBar);

    root.append(icon, copy, actions, timer);
    document.body?.appendChild(root);
    superAdminSnackbarElements = { root, icon, title, message, timerBar, copyButton, closeButton };
    return superAdminSnackbarElements;
  }

  function resetSuperAdminSnackbarActions({ showCopyButton = false, copyValue = "" } = {}) {
    const snackbar = ensureSuperAdminSnackbar();
    if (snackbar.copyButton instanceof HTMLButtonElement) {
      snackbar.copyButton.hidden = !showCopyButton;
      snackbar.copyButton.dataset.copyValue = showCopyButton ? String(copyValue || "").trim() : "";
      snackbar.copyButton.disabled = false;
    }
  }

  function showSuperAdminSnackbar(title, message, mode = "warning") {
    const snackbar = ensureSuperAdminSnackbar();
    snackbar.title.textContent = String(title || "Notice").trim() || "Notice";
    snackbar.message.classList.remove("product-editor-snackbar__password-line");
    snackbar.message.textContent = String(message || "").replace(/\s+/g, " ").trim();
    snackbar.root.classList.toggle("is-error", mode === "error");
    snackbar.root.classList.toggle("is-success", mode === "success");
    snackbar.root.classList.remove("is-password-reveal", "is-api-key-reveal", "is-full", "is-copy", "is-ai-summary");
    resetSuperAdminSnackbarActions();
    if (snackbar.icon instanceof HTMLElement) {
      snackbar.icon.innerHTML = snackbarIconMarkup.notice;
    }
    snackbar.root.hidden = false;
    window.clearTimeout(superAdminSnackbarTimer);
    window.requestAnimationFrame(() => {
      snackbar.root.classList.add("is-visible");
      startSuperAdminSnackbarCountdown(superAdminSnackbarAutoDismissMs);
    });
    superAdminSnackbarTimer = window.setTimeout(
      hideSuperAdminSnackbar,
      superAdminSnackbarAutoDismissMs,
    );
  }

  function showSuperAdminCopySnackbar() {
    showSuperAdminSnackbar("Copied text", "", "notice");
    const snackbar = ensureSuperAdminSnackbar();
    snackbar.root.classList.add("is-copy");
    if (snackbar.icon instanceof HTMLElement) {
      snackbar.icon.innerHTML = snackbarIconMarkup.copy;
    }
  }

  function showSuperAdminAiSummarySnackbar() {
    showSuperAdminSnackbar("AI Summary Ready", "", "notice");
    const snackbar = ensureSuperAdminSnackbar();
    snackbar.root.classList.add("is-ai-summary");
    if (snackbar.icon instanceof HTMLElement) {
      snackbar.icon.innerHTML = snackbarIconMarkup.aiSummary;
    }
  }

  function showPasswordRevealSnackbar({ title = "Password", subject = "", password = "" } = {}) {
    const normalizedPassword = String(password || "").trim();
    if (!normalizedPassword) {
      return false;
    }
    const snackbar = ensureSuperAdminSnackbar();
    const subjectText = String(subject || "").trim();
    snackbar.title.textContent = String(title || "Password").trim() || "Password";
    snackbar.message.textContent = "";
    snackbar.message.classList.add("product-editor-snackbar__password-line");
    if (subjectText) {
      const subjectLabel = document.createElement("span");
      subjectLabel.className = "product-editor-snackbar__password-label";
      subjectLabel.textContent = `${subjectText}:`;
      snackbar.message.appendChild(subjectLabel);
    }
    const passwordValue = document.createElement("span");
    passwordValue.className = "product-editor-snackbar__password-value";
    passwordValue.textContent = normalizedPassword;
    snackbar.message.appendChild(passwordValue);
    snackbar.root.classList.remove("is-error", "is-full", "is-copy", "is-api-key-reveal");
    snackbar.root.classList.add("is-success", "is-password-reveal");
    resetSuperAdminSnackbarActions();
    if (snackbar.icon instanceof HTMLElement) {
      snackbar.icon.innerHTML = snackbarIconMarkup.passwordReveal;
    }
    snackbar.root.hidden = false;
    window.clearTimeout(superAdminSnackbarTimer);
    window.requestAnimationFrame(() => {
      snackbar.root.classList.add("is-visible");
      startSuperAdminSnackbarCountdown(superAdminSnackbarAutoDismissMs);
    });
    superAdminSnackbarTimer = window.setTimeout(
      hideSuperAdminSnackbar,
      superAdminSnackbarAutoDismissMs,
    );
    return true;
  }

  function showTemporaryPasswordSnackbar({ title = "Temporary Password", subject = "", password = "" } = {}) {
    return showPasswordRevealSnackbar({
      title: String(title || "Temporary Password").trim() || "Temporary Password",
      subject: subject
        ? `${String(subject).trim()} — share securely; shown once`
        : "Share securely — shown once",
      password,
    });
  }

  function showApiKeyRevealSnackbar({ title = "See API key", subject = "", apiKey = "" } = {}) {
    const normalizedApiKey = String(apiKey || "").trim();
    if (!normalizedApiKey) {
      return false;
    }
    const snackbar = ensureSuperAdminSnackbar();
    snackbar.title.textContent = String(title || "See API key").trim() || "See API key";
    snackbar.message.textContent = "";
    snackbar.message.classList.remove("product-editor-snackbar__password-line");
    const apiKeyValue = document.createElement("span");
    apiKeyValue.className = "product-editor-snackbar__api-key-value";
    apiKeyValue.textContent = normalizedApiKey;
    snackbar.message.appendChild(apiKeyValue);
    snackbar.root.classList.remove("is-error", "is-full", "is-copy", "is-ai-summary", "is-password-reveal");
    snackbar.root.classList.add("is-success", "is-api-key-reveal");
    resetSuperAdminSnackbarActions({ showCopyButton: true, copyValue: normalizedApiKey });
    if (snackbar.icon instanceof HTMLElement) {
      snackbar.icon.innerHTML = snackbarIconMarkup.apiKey;
    }
    snackbar.root.hidden = false;
    window.clearTimeout(superAdminSnackbarTimer);
    window.requestAnimationFrame(() => {
      snackbar.root.classList.add("is-visible");
      startSuperAdminSnackbarCountdown(superAdminSnackbarAutoDismissMs);
    });
    superAdminSnackbarTimer = window.setTimeout(
      hideSuperAdminSnackbar,
      superAdminSnackbarAutoDismissMs,
    );
    return true;
  }

  window.showSuperAdminSnackbar = showSuperAdminSnackbar;

  function setChatWallpaperNamerFeedback(message, mode = "") {
    const feedback = elements.chatWallpaperNamerFeedback;
    if (!(feedback instanceof HTMLElement)) {
      return;
    }
    const normalizedMessage = String(message || "").trim();
    feedback.textContent = normalizedMessage;
    feedback.classList.toggle("is-error", mode === "error");
    feedback.hidden = !normalizedMessage;
  }

  function wallpaperLabelFromFileName(fileName) {
    return String(fileName || "")
      .replace(/\.[^.]+$/, "")
      .replace(/[-_]+/g, " ")
      .replace(/\s+/g, " ")
      .trim()
      .slice(0, 48) || "Background";
  }

  const BUILT_IN_CHAT_WALLPAPERS = [
    { id: "doodle", label: "Doodle", src: "/assets/live-chat-doodle-wallpaper.jpg" },
    { id: "cafe", label: "Cafe", src: "/assets/live-chat-cafe-wallpaper.jpg" },
    { id: "plain", label: "Plain", src: "" },
    { id: "mesh", label: "Soft light", src: "" },
  ];

  function chatWallpaperDropzoneMarkup() {
    return `
      <article class="super-admin-chat-wallpaper-card super-admin-chat-wallpaper-card--insert">
        <label
          class="super-admin-chat-wallpaper-card__preview super-admin-chat-wallpaper-dropzone"
          for="super-admin-chat-wallpaper-input"
          data-chat-wallpaper-dropzone
        >
          <span class="super-admin-chat-wallpaper-dropzone__icon" aria-hidden="true">
            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" focusable="false">
              <path d="M12 13v8" />
              <path d="M4 14.899A7 7 0 1 1 15.71 8h1.79a4.5 4.5 0 0 1 2.5 8.242" />
              <path d="m8 17 4-4 4 4" />
            </svg>
          </span>
          <strong>Drag &amp; drop photos here</strong>
          <span class="super-admin-chat-wallpaper-dropzone__or">or</span>
          <span class="super-admin-chat-wallpaper-dropzone__browse">Browse Files</span>
        </label>
        <strong>Insert background</strong>
      </article>`;
  }

  function chatWallpaperCardMarkup(item, { builtIn = false } = {}) {
    const previewClass = item.id === "plain" || item.id === "mesh"
      ? ` super-admin-chat-wallpaper-card__preview--${item.id}`
      : "";
    const previewImage = item.src
      ? `<img src="${escapeHtml(item.src)}" alt="${escapeHtml(item.label || "Chat background")}" loading="lazy" decoding="async" />`
      : "";
    const removeButton = builtIn
      ? `<span class="super-admin-chat-wallpaper-card__badge">Built-in</span>`
      : `<button type="button" class="super-admin-chat-wallpaper-card__remove" data-chat-wallpaper-remove="${escapeHtml(item.id)}" aria-label="Remove ${escapeHtml(item.label || "background")}">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
              <path d="M18 6 6 18"></path>
              <path d="m6 6 12 12"></path>
            </svg>
          </button>`;
    return `
      <article class="super-admin-chat-wallpaper-card${builtIn ? " is-builtin" : ""}">
        <div class="super-admin-chat-wallpaper-card__preview${previewClass}">
          ${previewImage}
          ${removeButton}
        </div>
        <strong>${escapeHtml(item.label || "Background")}</strong>
      </article>`;
  }

  function scrollSettingsCardCarousel(track, direction = 1) {
    if (!(track instanceof HTMLElement)) {
      return;
    }
    const firstCard = track.querySelector(":scope > *");
    const gap = 12;
    const cardWidth = firstCard instanceof HTMLElement
      ? firstCard.getBoundingClientRect().width
      : 132;
    const visibleCount = Math.max(1, Math.floor((track.clientWidth + gap) / (cardWidth + gap)));
    track.scrollBy({
      left: (cardWidth + gap) * visibleCount * (direction < 0 ? -1 : 1),
      behavior: "smooth",
    });
  }

  function syncSettingsCardCarouselControls(track, prevButton, nextButton) {
    if (!(track instanceof HTMLElement)) {
      return;
    }
    const maxScroll = Math.max(0, track.scrollWidth - track.clientWidth);
    const canScroll = maxScroll > 6;
    [prevButton, nextButton].forEach((button) => {
      if (button instanceof HTMLElement) {
        button.hidden = !canScroll;
      }
    });
    if (prevButton instanceof HTMLElement) {
      prevButton.disabled = !canScroll || track.scrollLeft <= 4;
    }
    if (nextButton instanceof HTMLElement) {
      nextButton.disabled = !canScroll || track.scrollLeft >= maxScroll - 4;
    }
  }

  function bindSettingsCardCarousel(track, prevButton, nextButton) {
    if (!(track instanceof HTMLElement)) {
      return;
    }
    const sync = () => syncSettingsCardCarouselControls(track, prevButton, nextButton);
    if (track.dataset.cardCarouselBound === "true") {
      window.requestAnimationFrame(sync);
      return;
    }
    track.dataset.cardCarouselBound = "true";
    track.addEventListener("scroll", sync, { passive: true });
    window.addEventListener("resize", sync);
    prevButton?.addEventListener("click", () => scrollSettingsCardCarousel(track, -1));
    nextButton?.addEventListener("click", () => scrollSettingsCardCarousel(track, 1));
    window.requestAnimationFrame(sync);
  }

  function renderChatWallpaperGrid() {
    if (!elements.chatWallpaperGrid) {
      return;
    }
    const customWallpapers = Array.isArray(state.chatWallpapers) ? state.chatWallpapers : [];
    elements.chatWallpaperGrid.innerHTML = [
      chatWallpaperDropzoneMarkup(),
      ...BUILT_IN_CHAT_WALLPAPERS.map((item) => chatWallpaperCardMarkup(item, { builtIn: true })),
      ...customWallpapers.map((item) => chatWallpaperCardMarkup(item)),
    ].join("");
    bindSettingsCardCarousel(
      elements.chatWallpaperGrid,
      elements.chatWallpaperCarouselPrev,
      elements.chatWallpaperCarouselNext,
    );
  }

  async function loadChatWallpapers() {
    if (!elements.chatWallpaperGrid) {
      return;
    }
    renderChatWallpaperGrid();
    state.chatWallpapersLoading = true;
    try {
      const response = await fetch("/api/chat-wallpapers", {
        cache: "no-store",
        headers: rootHeaders({ Accept: "application/json" }),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(data.message || "Unable to load chat backgrounds.");
      }
      state.chatWallpapers = Array.isArray(data.wallpapers) ? data.wallpapers : [];
      renderChatWallpaperGrid();
    } catch (error) {
      showSuperAdminSnackbar(
        "Unable to load backgrounds",
        error?.message || "Unable to load chat backgrounds.",
        "error",
      );
    } finally {
      state.chatWallpapersLoading = false;
    }
  }

  function getPlatformFeedbackStarFillPercent(rating, starIndex) {
    const normalizedRating = Math.min(5, Math.max(0, Number(rating) || 0));
    const rawFill = Math.max(0, Math.min(1, normalizedRating - starIndex));
    return Math.round(rawFill * 100);
  }

  function createPlatformFeedbackRatingStarMarkup(fillPercent) {
    const clampedFill = Math.max(0, Math.min(100, Number(fillPercent) || 0));
    return `
      <span class="platform-feedback-rating-star" style="--star-fill: ${clampedFill}%" aria-hidden="true">
        <span class="platform-feedback-rating-star__base">${createIconSvg(companyCardIconPaths.rating)}</span>
        <span class="platform-feedback-rating-star__fill">${createIconSvg(companyCardIconPaths.rating)}</span>
      </span>
    `;
  }

  function formatPlatformFeedbackStars(rating) {
    return Array.from({ length: 5 }, (_, index) =>
      createPlatformFeedbackRatingStarMarkup(getPlatformFeedbackStarFillPercent(rating, index)),
    ).join("");
  }

  function formatPlatformFeedbackDate(value) {
    const parsed = Date.parse(String(value || ""));
    if (!Number.isFinite(parsed)) {
      return "—";
    }
    return new Date(parsed).toLocaleString(undefined, {
      month: "short",
      day: "numeric",
      year: "numeric",
      hour: "numeric",
      minute: "2-digit",
    });
  }

  function escapePlatformFeedbackHtml(value) {
    return String(value ?? "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");
  }

  function normalizePlatformFeedbackAttachments(entry) {
    return (Array.isArray(entry?.attachments) ? entry.attachments : [])
      .map((attachment) => {
        const kind = String(attachment?.kind || attachment?.type || "").trim().toLowerCase();
        const url = String(attachment?.url || attachment?.mediaUrl || "").trim();
        if ((kind !== "image" && kind !== "video") || !url.startsWith("/uploads/")) {
          return null;
        }
        return {
          kind,
          url,
          name: String(attachment?.name || attachment?.fileName || (kind === "video" ? "Feedback video" : "Feedback photo")).trim(),
          sizeBytes: Math.max(0, Number(attachment?.sizeBytes) || 0),
        };
      })
      .filter(Boolean);
  }

  function formatPlatformFeedbackFileSize(sizeBytes) {
    const value = Math.max(0, Number(sizeBytes) || 0);
    if (!value) return "";
    if (value < 1024 * 1024) return `${Math.max(1, Math.round(value / 1024))} KB`;
    return `${(value / (1024 * 1024)).toFixed(value >= 10 * 1024 * 1024 ? 0 : 1)} MB`;
  }

  function formatPlatformFeedbackAttachmentSummary(attachments) {
    const items = Array.isArray(attachments) ? attachments : [];
    const photoCount = items.filter((attachment) => attachment.kind === "image").length;
    const videoCount = items.length - photoCount;
    const parts = [];
    if (photoCount) {
      parts.push(`${photoCount} Image${photoCount === 1 ? "" : "s"}`);
    }
    if (videoCount) {
      parts.push(`${videoCount} Video${videoCount === 1 ? "" : "s"}`);
    }
    return parts.join(" • ");
  }

  function renderPlatformFeedbackAttachments(entry, options = {}) {
    const drawer = options.drawer === true;
    const attachments = normalizePlatformFeedbackAttachments(entry);
    if (!attachments.length) {
      return "";
    }
    const summary = formatPlatformFeedbackAttachmentSummary(attachments);
    if (drawer) {
      return `
        <section class="platform-feedback-drawer__attachments" aria-label="Feedback attachments">
          <strong class="platform-feedback-drawer__attachments-title">Attachments</strong>
          <p class="platform-feedback-drawer__attachments-summary">${escapePlatformFeedbackHtml(summary)}</p>
          <div class="platform-feedback-drawer__media-grid">
            ${attachments.map((attachment) => {
              const url = escapePlatformFeedbackHtml(attachment.url);
              const name = escapePlatformFeedbackHtml(attachment.name);
              if (attachment.kind === "video") {
                return `
                  <button
                    type="button"
                    class="platform-feedback-drawer__media-item is-video"
                    data-platform-feedback-video="${url}"
                    data-platform-feedback-video-name="${name}"
                    aria-label="Play ${name}"
                  >
                    <span class="platform-feedback-drawer__media-preview">
                      <video src="${url}" preload="metadata" muted playsinline aria-hidden="true"></video>
                      <span class="platform-feedback-drawer__media-play" aria-hidden="true">
                        ${createIconSvg('<path d="M8 5v14l11-7z"></path>')}
                      </span>
                    </span>
                  </button>
                `;
              }
              return `
                <button
                  type="button"
                  class="platform-feedback-drawer__media-item is-image"
                  data-platform-feedback-image="${url}"
                  data-platform-feedback-image-name="${name}"
                  aria-label="View ${name}"
                >
                  <img src="${url}" alt="${name}" loading="lazy" decoding="async" />
                </button>
              `;
            }).join("")}
          </div>
        </section>
      `;
    }
    const photoCount = attachments.filter((attachment) => attachment.kind === "image").length;
    const videoCount = attachments.length - photoCount;
    const legacySummary = [
      photoCount ? `${photoCount} photo${photoCount === 1 ? "" : "s"}` : "",
      videoCount ? `${videoCount} video${videoCount === 1 ? "" : "s"}` : "",
    ].filter(Boolean).join(" · ");
    return `
      <section class="platform-feedback-card__attachments" aria-label="Feedback attachments">
        <div class="platform-feedback-card__attachments-heading">
          <strong>Supporting media</strong>
          <span>${escapePlatformFeedbackHtml(legacySummary)}</span>
        </div>
        <div class="platform-feedback-card__media-grid">
          ${attachments.map((attachment) => {
            const url = escapePlatformFeedbackHtml(attachment.url);
            const name = escapePlatformFeedbackHtml(attachment.name);
            const size = escapePlatformFeedbackHtml(formatPlatformFeedbackFileSize(attachment.sizeBytes));
            if (attachment.kind === "video") {
              return `
                <article class="platform-feedback-card__media-item is-video">
                  <video src="${url}" controls preload="metadata" playsinline aria-label="${name}"></video>
                  <div><span title="${name}">${name}</span>${size ? `<small>${size}</small>` : ""}</div>
                </article>
              `;
            }
            return `
              <button type="button" class="platform-feedback-card__media-item is-image" data-platform-feedback-image="${url}" data-platform-feedback-image-name="${name}" aria-label="View ${name}">
                <img src="${url}" alt="${name}" loading="lazy" decoding="async" />
                <span title="${name}">${name}</span>
              </button>
            `;
          }).join("")}
        </div>
      </section>
    `;
  }

  function openPlatformFeedbackImage(src, name = "Feedback photo") {
    const url = String(src || "").trim();
    if (!url.startsWith("/uploads/")) {
      return;
    }
    let viewer = document.querySelector("[data-platform-feedback-viewer]");
    if (!(viewer instanceof HTMLElement)) {
      viewer = document.createElement("div");
      viewer.className = "platform-feedback-viewer";
      viewer.dataset.platformFeedbackViewer = "";
      viewer.innerHTML = `
        <div class="platform-feedback-viewer__dialog" role="dialog" aria-modal="true" aria-label="Feedback photo preview">
          <button type="button" class="platform-feedback-viewer__close" data-platform-feedback-viewer-close aria-label="Close photo preview">×</button>
          <img data-platform-feedback-viewer-image alt="" />
          <p data-platform-feedback-viewer-name></p>
        </div>
      `;
      viewer.addEventListener("click", (event) => {
        if (event.target === viewer || event.target?.closest?.("[data-platform-feedback-viewer-close]")) {
          viewer.hidden = true;
          document.body.classList.remove("platform-feedback-viewer-open");
        }
      });
      document.body.appendChild(viewer);
    }
    const image = viewer.querySelector("[data-platform-feedback-viewer-image]");
    const label = viewer.querySelector("[data-platform-feedback-viewer-name]");
    if (image instanceof HTMLImageElement) {
      image.src = url;
      image.alt = String(name || "Feedback photo");
    }
    if (label) label.textContent = String(name || "Feedback photo");
    viewer.hidden = false;
    document.body.classList.add("platform-feedback-viewer-open");
    viewer.querySelector("[data-platform-feedback-viewer-close]")?.focus();
  }

  function normalizePlatformFeedbackStatusValue(value) {
    const status = String(value ?? "").trim().toLowerCase();
    if (status === "resolved" || status === "closed") {
      return "resolved";
    }
    if (status === "in-review" || status === "review") {
      return "in-review";
    }
    return "open";
  }

  function isPlatformFeedbackUnread(entry) {
    if (String(entry?.readAt || "").trim()) {
      return false;
    }
    return normalizePlatformFeedbackStatusValue(entry?.status) === "open";
  }

  function formatPlatformFeedbackDisplayId(entry) {
    const raw = String(entry?.id || entry || "").trim();
    if (!raw) {
      return "—";
    }
    const compact = raw.replace(/^fb[_-]?/i, "").slice(-4).toUpperCase();
    const parsed = Date.parse(String(entry?.createdAt || ""));
    const year = Number.isFinite(parsed) ? new Date(parsed).getFullYear() : new Date().getFullYear();
    return `FB-${year}-${compact || raw.slice(-4).toUpperCase()}`;
  }

  function getPlatformFeedbackStatusLabel(status) {
    const normalized = normalizePlatformFeedbackStatusValue(status);
    if (normalized === "resolved") {
      return "Resolved";
    }
    return "Pending";
  }

  function createDefaultPlatformFeedbackFilters() {
    return {
      status: "all",
      read: "all",
      rating: "all",
      date: "all",
      sort: "newest",
    };
  }

  function getPlatformFeedbackFilters(type = getPlatformFeedbackActiveType()) {
    const feedbackType = type === "user" ? "user" : "seller";
    if (!state.platformFeedback.filters || typeof state.platformFeedback.filters !== "object") {
      state.platformFeedback.filters = {};
    }
    const current = state.platformFeedback.filters[feedbackType];
    if (!current || typeof current !== "object") {
      state.platformFeedback.filters[feedbackType] = createDefaultPlatformFeedbackFilters();
    }
    return {
      ...createDefaultPlatformFeedbackFilters(),
      ...state.platformFeedback.filters[feedbackType],
    };
  }

  function getPlatformFeedbackSearchTerm(type = getPlatformFeedbackActiveType()) {
    const feedbackType = type === "user" ? "user" : "seller";
    const searchTerms = state.platformFeedback?.searchTerm;
    if (searchTerms && typeof searchTerms === "object") {
      return String(searchTerms[feedbackType] || "");
    }
    return String(searchTerms || "");
  }

  function setPlatformFeedbackSearchTerm(type, value) {
    const feedbackType = type === "user" ? "user" : "seller";
    if (!state.platformFeedback.searchTerm || typeof state.platformFeedback.searchTerm !== "object") {
      state.platformFeedback.searchTerm = { seller: "", user: "" };
    }
    state.platformFeedback.searchTerm[feedbackType] = String(value || "");
  }

  function renderPlatformFeedbackStatusPillMarkup(status, options = {}) {
    const normalized = normalizePlatformFeedbackStatusValue(status);
    const label = getPlatformFeedbackStatusLabel(normalized);
    const isResolved = normalized === "resolved";
    const indicator = isResolved
      ? `<span class="platform-feedback-status-pill__check" aria-hidden="true">${createIconSvg('<path d="M20 6 9 17l-5-5"></path>')}</span>`
      : options.drawer
        ? ""
        : `<span class="super-admin-company-card__status-pill-dot" aria-hidden="true"></span>`;
    const className = options.drawer
      ? `platform-feedback-status-pill is-${normalized}`
      : `super-admin-company-card__status-pill platform-feedback-status-pill is-${normalized}`;
    return `<span class="${className}">${indicator}<span>${escapePlatformFeedbackHtml(label)}</span></span>`;
  }

  function formatPlatformFeedbackRatingValue(rating) {
    const value = Math.min(5, Math.max(0, Math.round(Number(rating) || 0)));
    return String(value);
  }

  function formatPlatformFeedbackCategory(entry) {
    const category = String(entry?.category ?? entry?.feedbackCategory ?? "").replace(/\s+/g, " ").trim();
    return category || "Uncategorized";
  }

  function getPlatformFeedbackActiveType() {
    return state.activeSection === "user-feedback" ? "user" : "seller";
  }

  function resolvePlatformFeedbackProfile(type, entry) {
    if (type === "seller") {
      const admin = findCompanyById(entry?.adminId);
      if (admin) {
        return {
          kind: "company",
          admin,
          name: getCompanyName(admin),
          email: String(admin?.email || entry?.submitterEmail || "No email").trim(),
          phone: formatCompanyPhone(admin) || "No mobile number",
          imageUrl: getCompanyImageUrl(admin),
          toneIndex: getCompanyToneIndex(admin),
          accountState: getCompanyAccountState(admin),
          isOnline: isCompanyAdminOnline(admin),
        };
      }
      return {
        kind: "company",
        admin: null,
        name: String(entry?.companyName || entry?.submitterName || "Unknown company").trim(),
        email: String(entry?.submitterEmail || "No email").trim(),
        phone: "No mobile number",
        imageUrl: "",
        toneIndex: getCompanyToneIndex({ adminId: entry?.adminId || entry?.companyName }),
        accountState: "active",
        isOnline: false,
      };
    }

    const account = state.userAccounts.find(
      (record) => getUserAccountId(record) === String(entry?.submitterAccountId || "").trim(),
    ) || null;
    return {
      kind: "user",
      account,
      name: account ? getUserAccountName(account) : String(entry?.submitterName || "User").trim(),
      email: String(account?.email || entry?.submitterEmail || "No email").trim(),
      phone: account ? formatUserPhone(account) : "-",
      imageUrl: String(account?.profileImageUrl || account?.avatarUrl || "").trim(),
      toneIndex: 1,
      accountState: "active",
      isOnline: false,
    };
  }

  function createPlatformFeedbackProfileLogo(profile) {
    const logo = document.createElement("span");
    if (profile.kind === "company") {
      logo.className = `super-admin-company-card__logo platform-feedback-list-row__logo super-admin-company-card__logo--tone-${profile.toneIndex || 1}`;
      if (profile.imageUrl) {
        logo.classList.add("has-image");
        const image = document.createElement("img");
        image.src = profile.imageUrl;
        image.alt = `${profile.name} logo`;
        image.loading = "lazy";
        image.addEventListener("error", () => {
          image.remove();
          logo.classList.remove("has-image");
          setCompanyLogoPlaceholder(logo);
        }, { once: true });
        logo.append(image);
      } else {
        setCompanyLogoPlaceholder(logo);
      }
      return logo;
    }

    logo.className = "super-admin-integrated-card__avatar platform-feedback-list-row__avatar";
    if (profile.imageUrl) {
      const image = document.createElement("img");
      image.src = profile.imageUrl;
      image.alt = `${profile.name} profile photo`;
      image.loading = "lazy";
      image.addEventListener("error", () => {
        image.remove();
        logo.innerHTML = createIconSvg(integratedIconPaths.user);
      }, { once: true });
      logo.append(image);
    } else {
      logo.innerHTML = createIconSvg(integratedIconPaths.user);
    }
    return logo;
  }

  function createPlatformFeedbackDrawerProfile(profile) {
    const summary = document.createElement("div");
    summary.className = "super-admin-company-drawer__summary platform-feedback-drawer__profile";

    const logo = createPlatformFeedbackProfileLogo(profile);
    logo.classList.add("super-admin-company-drawer__logo");

    if (profile.kind === "company") {
      const statusDot = document.createElement("span");
      statusDot.className = "super-admin-company-drawer__profile-status";
      statusDot.classList.add(
        profile.accountState === "banned" || profile.accountState === "suspended"
          ? "is-danger"
          : profile.accountState === "restricted"
            ? "is-warning"
            : profile.isOnline
              ? "is-online"
              : "is-offline",
      );
      logo.append(statusDot);
    }

    const summaryCopy = document.createElement("div");
    summaryCopy.className = "super-admin-company-drawer__summary-copy";
    const summaryName = document.createElement("strong");
    summaryName.textContent = profile.name;
    const summaryEmail = createCompanyContactCopyField(
      profile.email,
      "Email",
      "super-admin-company-drawer__contact-line",
      profile.email !== "No email",
    );
    const summaryPhone = createCompanyContactCopyField(
      profile.phone,
      "Phone number",
      "super-admin-company-drawer__contact-line",
      profile.phone !== "No mobile number" && profile.phone !== "-",
    );
    summaryCopy.append(summaryName, summaryEmail, summaryPhone);
    summary.append(logo, summaryCopy);
    return summary;
  }

  function findPlatformFeedbackEntry(type, feedbackId) {
    const id = String(feedbackId || "").trim();
    if (!id) {
      return null;
    }
    const entries = Array.isArray(state.platformFeedback?.[type]) ? state.platformFeedback[type] : [];
    return entries.find((entry) => String(entry?.id || "").trim() === id) || null;
  }

  function getPlatformFeedbackSearchText(entry) {
    return [
      entry?.submitterName,
      entry?.submitterEmail,
      entry?.companyName,
      entry?.message,
      entry?.status,
      entry?.rating,
      entry?.id,
      entry?.type,
      formatPlatformFeedbackDisplayId(entry),
    ]
      .map((value) => String(value || "").trim().toLowerCase())
      .filter(Boolean)
      .join(" ");
  }

  function getFilteredPlatformFeedbackEntries(type) {
    const entries = Array.isArray(state.platformFeedback?.[type]) ? state.platformFeedback[type] : [];
    const searchTerm = getPlatformFeedbackSearchTerm(type).trim().toLowerCase();
    const filters = getPlatformFeedbackFilters(type);
    const today = new Date();
    const filteredEntries = entries.filter((entry) => {
      const matchesSearch = !searchTerm || getPlatformFeedbackSearchText(entry).includes(searchTerm);
      const normalizedStatus = normalizePlatformFeedbackStatusValue(entry?.status);
      const matchesStatus = filters.status === "all"
        || (filters.status === "resolved" && normalizedStatus === "resolved")
        || (filters.status === "pending" && normalizedStatus !== "resolved");
      const unread = isPlatformFeedbackUnread(entry);
      const matchesRead = filters.read === "all"
        || (filters.read === "unread" && unread)
        || (filters.read === "read" && !unread);
      const rating = Math.min(5, Math.max(0, Math.round(Number(entry?.rating) || 0)));
      const matchesRating = filters.rating === "all" || rating === Number(filters.rating);
      const createdAt = new Date(String(entry?.createdAt || ""));
      let matchesDate = filters.date === "all";
      if (!Number.isNaN(createdAt.getTime())) {
        if (filters.date === "this-month") {
          matchesDate = createdAt.getFullYear() === today.getFullYear()
            && createdAt.getMonth() === today.getMonth();
        } else if (filters.date === "30" || filters.date === "90") {
          const dayCount = Number(filters.date);
          const cutoff = new Date(today.getTime() - dayCount * 24 * 60 * 60 * 1000);
          matchesDate = createdAt >= cutoff;
        }
      }
      return matchesSearch && matchesStatus && matchesRead && matchesRating && matchesDate;
    });

    return filteredEntries.sort((left, right) => {
      const leftCreatedAt = Date.parse(String(left?.createdAt || "")) || 0;
      const rightCreatedAt = Date.parse(String(right?.createdAt || "")) || 0;
      const leftRating = Number(left?.rating) || 0;
      const rightRating = Number(right?.rating) || 0;
      if (filters.sort === "oldest") return leftCreatedAt - rightCreatedAt;
      if (filters.sort === "rating-high") return rightRating - leftRating || rightCreatedAt - leftCreatedAt;
      if (filters.sort === "rating-low") return leftRating - rightRating || rightCreatedAt - leftCreatedAt;
      return rightCreatedAt - leftCreatedAt;
    });
  }

  function syncPlatformFeedbackNavBadge() {
    const sellerEntries = Array.isArray(state.platformFeedback?.seller) ? state.platformFeedback.seller : [];
    const userEntries = Array.isArray(state.platformFeedback?.user) ? state.platformFeedback.user : [];
    const sellerUnreadCount = sellerEntries.filter(isPlatformFeedbackUnread).length;
    const userUnreadCount = userEntries.filter(isPlatformFeedbackUnread).length;
    syncSuperAdminNavNewBadge(
      elements.platformFeedbackNavBadge,
      sellerUnreadCount + userUnreadCount,
      "feedback items",
    );

    const sellerFeedbackNavItem = elements.sellerFeedbackNavBadge?.closest(".super-admin-company-status-nav__item");
    const userFeedbackNavItem = elements.userFeedbackNavBadge?.closest(".super-admin-company-status-nav__item");
    syncSuperAdminSubNavNewItem(
      sellerFeedbackNavItem,
      sellerUnreadCount,
      "companies feedback items",
      { hideWhenEmpty: false },
    );
    syncSuperAdminSubNavNewItem(
      userFeedbackNavItem,
      userUnreadCount,
      "user feedback items",
      { hideWhenEmpty: false },
    );
  }

  function updatePlatformFeedbackSummary(type, allEntries) {
    const entries = Array.isArray(allEntries) ? allEntries : [];
    const prefix = type === "seller" ? "seller" : "user";
    const stats = elements.platformFeedbackStats;
    const openCount = entries.filter(
      (entry) => normalizePlatformFeedbackStatusValue(entry?.status) !== "resolved",
    ).length;
    const resolvedCount = entries.filter(
      (entry) => normalizePlatformFeedbackStatusValue(entry?.status) === "resolved",
    ).length;
    const ratings = entries
      .map((entry) => Number(entry?.rating))
      .filter((rating) => Number.isFinite(rating) && rating > 0);
    const avgRating = ratings.length
      ? (ratings.reduce((sum, rating) => sum + rating, 0) / ratings.length)
      : null;

    if (stats[`${prefix}Total`]) stats[`${prefix}Total`].textContent = String(entries.length);
    if (stats[`${prefix}Open`]) stats[`${prefix}Open`].textContent = String(openCount);
    if (stats[`${prefix}Avg`]) {
      stats[`${prefix}Avg`].textContent = avgRating == null
        ? "—"
        : (Math.round(avgRating * 10) / 10).toFixed(1);
    }

    const tabCounts = elements.platformFeedbackTabCounts;
    if (tabCounts[`${prefix}All`]) tabCounts[`${prefix}All`].textContent = String(entries.length);
    if (tabCounts[`${prefix}Open`]) tabCounts[`${prefix}Open`].textContent = String(openCount);
    if (tabCounts[`${prefix}Resolved`]) tabCounts[`${prefix}Resolved`].textContent = String(resolvedCount);

    const totalLabel = elements.platformFeedbackTotals?.[type];
    if (totalLabel) {
      totalLabel.textContent = `(${entries.length})`;
    }
  }

  function getPlatformFeedbackPage(type) {
    const pages = state.platformFeedback?.page;
    if (pages && typeof pages === "object") {
      return Math.max(1, Number(pages[type]) || 1);
    }
    return 1;
  }

  function setPlatformFeedbackPage(type, nextPage) {
    if (!state.platformFeedback.page || typeof state.platformFeedback.page !== "object") {
      state.platformFeedback.page = { seller: 1, user: 1 };
    }
    state.platformFeedback.page[type] = Math.max(1, Number(nextPage) || 1);
  }

  function renderPlatformFeedbackPagination(type, totalItems) {
    const pagination = elements.platformFeedbackPagination?.[type];
    const pageMeta = elements.platformFeedbackPageMeta?.[type];
    const pageSize = Math.max(1, Number(state.platformFeedback?.pageSize) || superAdminListViewPageSize);
    const total = Math.max(0, Number(totalItems) || 0);
    const totalPages = Math.max(1, Math.ceil(total / pageSize));
    const page = Math.min(getPlatformFeedbackPage(type), totalPages);

    setPlatformFeedbackPage(type, page);

    const pageStart = (page - 1) * pageSize;
    const start = total > 0 ? pageStart + 1 : 0;
    const end = total > 0 ? Math.min(total, pageStart + pageSize) : 0;
    const hasPageNavigation = totalPages > 1;

    if (pageMeta) {
      pageMeta.textContent = `Showing ${numberText(start)} to ${numberText(end)} of ${numberText(total)} results`;
    }
    if (!(pagination instanceof HTMLElement)) {
      return { pageStart, pageSize, hasPageNavigation };
    }

    pagination.innerHTML = "";
    pagination.hidden = !hasPageNavigation;
    pagination.parentElement?.classList.toggle("is-empty", !hasPageNavigation);
    if (!hasPageNavigation) {
      return { pageStart, pageSize, hasPageNavigation };
    }

    const createPageButton = (label, targetPage, options = {}) => {
      const button = document.createElement("button");
      button.type = "button";
      button.dataset.platformFeedbackPage = String(targetPage);
      button.dataset.platformFeedbackPageType = type;
      button.setAttribute("aria-label", options.ariaLabel || `Page ${targetPage}`);
      button.classList.toggle("is-active", options.active === true);
      if (options.active === true) {
        button.setAttribute("aria-current", "page");
      }
      button.disabled = options.disabled === true;
      button.innerHTML = label;
      return button;
    };
    const appendEllipsis = () => {
      const marker = document.createElement("span");
      marker.className = "super-admin-pagination__ellipsis";
      marker.setAttribute("aria-hidden", "true");
      marker.textContent = "...";
      pagination.append(marker);
    };
    const visiblePages = (() => {
      if (totalPages <= 6) {
        return Array.from({ length: totalPages }, (_, index) => index + 1);
      }
      if (page <= 3) {
        return [1, 2, 3, 4, "ellipsis", totalPages];
      }
      if (page >= totalPages - 2) {
        return [1, "ellipsis", totalPages - 3, totalPages - 2, totalPages - 1, totalPages];
      }
      return [1, "ellipsis", page - 1, page, page + 1, "ellipsis", totalPages];
    })();

    pagination.append(createPageButton(
      createIconSvg('<path d="m11 17-5-5 5-5"></path><path d="m18 17-5-5 5-5"></path>'),
      1,
      { ariaLabel: "First page", disabled: page <= 1 },
    ));
    pagination.append(createPageButton(
      createIconSvg('<path d="m15 18-6-6 6-6"></path>'),
      page - 1,
      { ariaLabel: "Previous page", disabled: page <= 1 },
    ));
    for (const visiblePage of visiblePages) {
      if (visiblePage === "ellipsis") {
        appendEllipsis();
        continue;
      }
      pagination.append(createPageButton(numberText(visiblePage), visiblePage, {
        active: visiblePage === page,
      }));
    }
    pagination.append(createPageButton(
      createIconSvg('<path d="m9 18 6-6-6-6"></path>'),
      page + 1,
      { ariaLabel: "Next page", disabled: page >= totalPages },
    ));
    pagination.append(createPageButton(
      createIconSvg('<path d="m13 17 5-5-5-5"></path><path d="m6 17 5-5-5-5"></path>'),
      totalPages,
      { ariaLabel: "Last page", disabled: page >= totalPages },
    ));

    return { pageStart, pageSize, hasPageNavigation };
  }

  function createPlatformFeedbackTableHeader(type) {
    const header = document.createElement("div");
    header.className = "super-admin-data-table-header super-admin-company-table-header platform-feedback-table-header";
    header.setAttribute("role", "row");
    const labels = type === "seller"
      ? ["Feedback ID", "Company", "Phone", "Message", "Rating", "Status", "Submitted", "Actions"]
      : ["Feedback ID", "User", "Phone", "Message", "Rating", "Status", "Submitted", "Actions"];
    labels.forEach((label) => {
      const cell = document.createElement("span");
      cell.textContent = label;
      header.append(cell);
    });
    return header;
  }

  function createPlatformFeedbackIdCell(entry) {
    const cell = document.createElement("div");
    cell.className = "platform-feedback-list-row__feedback-id";
    const displayId = formatPlatformFeedbackDisplayId(entry);
    cell.append(createCompanyContactCopyField(
      displayId,
      "Feedback ID",
      "platform-feedback-list-row__feedback-id-copy",
      displayId !== "—",
    ));
    return cell;
  }

  function createPlatformFeedbackCompanyCell(type, profile) {
    const cell = document.createElement("div");
    cell.className = "platform-feedback-list-row__company";
    const identity = document.createElement("div");
    identity.className = "platform-feedback-list-row__company-identity";
    identity.append(createPlatformFeedbackProfileLogo(profile));
    const copy = document.createElement("div");
    copy.className = "platform-feedback-list-row__company-copy";
    const name = document.createElement("strong");
    name.textContent = profile.name;
    const email = createCompanyContactCopyField(
      profile.email,
      "Email",
      "platform-feedback-list-row__company-email",
      profile.email !== "No email",
    );
    copy.append(name, email);
    identity.append(copy);
    cell.append(identity);
    return cell;
  }

  function createPlatformFeedbackContactCell(value, label, className) {
    const cell = document.createElement("div");
    cell.className = className;
    cell.append(createCompanyContactCopyField(
      value,
      label,
      "platform-feedback-list-row__contact-field",
      value !== "No email" && value !== "No mobile number" && value !== "-",
    ));
    return cell;
  }

  function createPlatformFeedbackTypeCell(entry) {
    const attachments = normalizePlatformFeedbackAttachments(entry);
    const hasImage = attachments.some((attachment) => attachment.kind === "image");
    const hasVideo = attachments.some((attachment) => attachment.kind === "video");
    const cell = document.createElement("div");
    cell.className = "platform-feedback-list-row__type";
    cell.setAttribute("aria-label", [
      "Message",
      hasImage ? "Image" : "",
      hasVideo ? "Video" : "",
    ].filter(Boolean).join(", "));
    cell.innerHTML = `
      <span class="platform-feedback-list-row__type-icon is-message" title="Message feedback" aria-hidden="true">
        ${createIconSvg(platformFeedbackTypeIconPaths.message)}
      </span>
      ${hasImage ? `<span class="platform-feedback-list-row__type-icon is-image" title="Includes image" aria-hidden="true">${createIconSvg(platformFeedbackTypeIconPaths.image)}</span>` : ""}
      ${hasVideo ? `<span class="platform-feedback-list-row__type-icon is-video" title="Includes video" aria-hidden="true">${createIconSvg(platformFeedbackTypeIconPaths.video)}</span>` : ""}
    `;
    return cell;
  }

  function createPlatformFeedbackStatusCell(status) {
    const cell = document.createElement("div");
    cell.className = "super-admin-company-card__table-status platform-feedback-list-row__status";
    cell.innerHTML = renderPlatformFeedbackStatusPillMarkup(status);
    return cell;
  }

  function createPlatformFeedbackActions(entry, type) {
    const feedbackId = String(entry?.id || "").trim();
    const displayId = formatPlatformFeedbackDisplayId(entry);
    const isResolved = normalizePlatformFeedbackStatusValue(entry?.status) === "resolved";
    const actions = document.createElement("div");
    actions.className = "super-admin-company-card__actions-cell partner-data-list-row__actions platform-feedback-list-row__actions";

    const definitions = [
      ...(!isResolved
        ? [{
            id: "resolve",
            label: "Mark as Resolved",
            icon: '<path d="M20 6 9 17l-5-5"></path>',
          }]
        : []),
      {
        id: "delete",
        label: "Delete",
        icon: '<path d="M10 11v6"></path><path d="M14 11v6"></path><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6"></path><path d="M3 6h18"></path><path d="M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path>',
        danger: true,
      },
    ];

    const quickActions = document.createElement("div");
    quickActions.className = "super-admin-company-card__quick-actions partner-data-list-row__quick-actions platform-feedback-list-row__quick-actions";
    quickActions.setAttribute("aria-label", `Quick actions for ${displayId}`);
    for (const definition of definitions) {
      const button = document.createElement("button");
      button.type = "button";
      button.className = `super-admin-company-card__quick-action platform-feedback-action-button${definition.danger ? " super-admin-company-card__quick-action--danger" : ""}`;
      button.dataset.platformFeedbackAction = definition.id;
      button.dataset.platformFeedbackType = type;
      button.dataset.platformFeedbackId = feedbackId;
      button.setAttribute("aria-label", `${definition.label} ${displayId}`);
      button.title = definition.label;
      button.innerHTML = createIconSvg(definition.icon);
      quickActions.append(button);
    }

    platformFeedbackActionMenuIdCounter += 1;
    const menuId = `platform-feedback-action-menu-${platformFeedbackActionMenuIdCounter}`;
    const triggerId = `${menuId}-trigger`;
    const dropdown = document.createElement("div");
    dropdown.className = "universal-dropdown super-admin-company-card__action-dropdown partner-data-action-dropdown platform-feedback-action-dropdown";

    const trigger = document.createElement("button");
    trigger.type = "button";
    trigger.id = triggerId;
    trigger.className = "super-admin-company-card__menu super-admin-company-card__dropdown-trigger partner-data-action-menu-trigger platform-feedback-action-menu-trigger";
    trigger.dataset.companyActionMenuToggle = "";
    trigger.dataset.platformFeedbackMenuToggle = "";
    trigger.setAttribute("aria-haspopup", "menu");
    trigger.setAttribute("aria-expanded", "false");
    trigger.setAttribute("aria-controls", menuId);
    trigger.setAttribute("aria-label", `Actions for ${displayId}`);
    trigger.title = "Actions";
    trigger.innerHTML = createIconSvg(
      '<path d="M12 6.2h.01M12 12h.01M12 17.8h.01" stroke-linecap="round" stroke-width="3"></path>',
    );

    const menu = document.createElement("div");
    menu.id = menuId;
    menu.className = "universal-dropdown__panel super-admin-company-card__action-menu super-admin-company-card__dropdown-panel partner-data-action-menu platform-feedback-action-menu";
    menu.dataset.companyActionMenu = "";
    menu.dataset.platformFeedbackMenu = "";
    menu.setAttribute("role", "menu");
    menu.setAttribute("aria-labelledby", triggerId);
    menu.hidden = true;

    const caret = document.createElement("span");
    caret.className = "super-admin-company-card__action-menu-caret";
    caret.setAttribute("aria-hidden", "true");
    menu.append(caret);

    for (const definition of definitions) {
      const button = document.createElement("button");
      button.type = "button";
      button.className = `super-admin-company-card__action-item partner-data-action-menu__item platform-feedback-action-menu__item${definition.danger ? " super-admin-company-card__action-item--danger" : ""}`;
      button.dataset.companyAction = definition.id;
      button.dataset.platformFeedbackAction = definition.id;
      button.dataset.platformFeedbackType = type;
      button.dataset.platformFeedbackId = feedbackId;
      button.setAttribute("role", "menuitem");
      button.innerHTML = `${createIconSvg(definition.icon)}<span></span>`;
      button.querySelector("span").textContent = definition.label;
      menu.append(button);
    }

    dropdown.append(trigger, menu);
    actions.append(quickActions, dropdown);
    return actions;
  }

  function createPlatformFeedbackRow(type, entry) {
    const feedbackId = String(entry?.id || "").trim();
    const profile = resolvePlatformFeedbackProfile(type, entry);
    const normalizedStatus = normalizePlatformFeedbackStatusValue(entry?.status);
    const row = document.createElement("article");
    row.className = "super-admin-company-card buyer-data-list-row platform-feedback-list-row";
    const isUnread = isPlatformFeedbackUnread(entry);
    row.classList.toggle("is-unread", isUnread);
    if (normalizedStatus === "resolved") {
      row.classList.add("is-resolved");
    }
    row.dataset.platformFeedbackId = feedbackId;
    row.dataset.platformFeedbackType = type;
    row.setAttribute("role", "row");
    row.tabIndex = 0;
    row.setAttribute(
      "aria-label",
      `${isUnread ? "Unread " : ""}feedback ${formatPlatformFeedbackDisplayId(entry)}`,
    );

    const ratingCell = document.createElement("div");
    ratingCell.className = "platform-feedback-list-row__rating";
    const rating = Number(entry?.rating) || 0;
    ratingCell.setAttribute("aria-label", `${formatPlatformFeedbackRatingValue(rating)} out of 5 stars`);
    ratingCell.innerHTML = `
      <span class="platform-feedback-list-row__stars" aria-hidden="true">${formatPlatformFeedbackStars(rating)}</span>
    `;

    const submittedCell = document.createElement("div");
    submittedCell.className = "super-admin-company-card__table-registered platform-feedback-list-row__submitted";
    submittedCell.textContent = formatPlatformFeedbackDate(entry?.createdAt);

    row.append(
      createPlatformFeedbackIdCell(entry),
      createPlatformFeedbackCompanyCell(type, profile),
      createPlatformFeedbackContactCell(profile.phone, "Phone number", "platform-feedback-list-row__phone"),
      createPlatformFeedbackTypeCell(entry),
      ratingCell,
      createPlatformFeedbackStatusCell(entry?.status),
      submittedCell,
      createPlatformFeedbackActions(entry, type),
    );

    row.addEventListener("click", (event) => {
      if (
        event.target instanceof Element
        && event.target.closest(
          "[data-company-contact-copy], [data-platform-feedback-open], [data-platform-feedback-action], [data-platform-feedback-menu-toggle], [data-platform-feedback-menu]",
        )
      ) {
        return;
      }
      openPlatformFeedbackDrawer(type, feedbackId);
    });
    row.addEventListener("keydown", (event) => {
      if (handleCompanyActionMenuKeydown(event)) {
        return;
      }
      if (event.target instanceof Element && event.target.closest("button")) {
        return;
      }
      if (event.key === "ContextMenu" || (event.shiftKey && event.key === "F10")) {
        event.preventDefault();
        openIntegratedPartnerActionMenu(row, { focusFirst: true });
        return;
      }
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        openPlatformFeedbackDrawer(type, feedbackId);
      }
    });

    return row;
  }

  function syncPlatformFeedbackSelection(type) {
    const selectedId = String(state.platformFeedback?.selectedId || "").trim();
    const selectedType = String(state.platformFeedback?.selectedType || "").trim();
    const list = elements.platformFeedbackLists?.[type];
    if (!(list instanceof HTMLElement)) {
      return;
    }
    for (const row of Array.from(list.querySelectorAll("[data-platform-feedback-id]"))) {
      if (!(row instanceof HTMLElement)) {
        continue;
      }
      const isSelected = selectedType === type && row.dataset.platformFeedbackId === selectedId;
      row.classList.toggle("is-selected", isSelected);
      row.setAttribute("aria-selected", isSelected ? "true" : "false");
    }
  }

  function renderPlatformFeedbackDrawerContent(entry, type) {
    const content = elements.platformFeedbackDrawerContent;
    if (!(content instanceof HTMLElement) || !entry) {
      return;
    }

    const feedbackId = String(entry?.id || "").trim();
    const status = normalizePlatformFeedbackStatusValue(entry?.status);
    const rating = Number(entry?.rating) || 0;
    const message = String(entry?.message || "").trim();
    const categoryLabel = formatPlatformFeedbackCategory(entry);
    const displayId = formatPlatformFeedbackDisplayId(entry);
    const submittedLabel = formatPlatformFeedbackDate(entry?.createdAt);

    content.replaceChildren();

    const card = document.createElement("article");
    card.className = "platform-feedback-drawer__card";
    card.innerHTML = `
      <div class="platform-feedback-drawer__header-row">
        ${renderPlatformFeedbackStatusPillMarkup(status, { drawer: true })}
        <span class="platform-feedback-drawer__id">ID: ${escapePlatformFeedbackHtml(displayId)}</span>
      </div>
      <p class="platform-feedback-drawer__submitted">
        <time datetime="${escapePlatformFeedbackHtml(entry?.createdAt || "")}">Submitted: ${escapePlatformFeedbackHtml(submittedLabel)}</time>
      </p>
      <div class="platform-feedback-drawer__rating" aria-label="${formatPlatformFeedbackRatingValue(rating)} out of 5 stars">
        <span aria-hidden="true">${formatPlatformFeedbackStars(rating)}</span>
      </div>
      <p class="platform-feedback-drawer__message">${escapePlatformFeedbackHtml(message || "No message provided.")}</p>
    `;

    const attachmentsMarkup = renderPlatformFeedbackAttachments(entry, { drawer: true });
    if (attachmentsMarkup) {
      const attachmentsHost = document.createElement("div");
      attachmentsHost.innerHTML = attachmentsMarkup;
      card.append(attachmentsHost.firstElementChild);
    }

    const typeCard = document.createElement("div");
    typeCard.className = "platform-feedback-drawer__type-card";
    typeCard.innerHTML = `
      <span class="platform-feedback-drawer__type-icon" aria-hidden="true">
        ${createIconSvg('<path d="M22 17a2 2 0 0 1-2 2H6.828a2 2 0 0 0-1.414.586l-2.202 2.202A.71.71 0 0 1 2 21.286V5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2z"></path>')}
      </span>
      <div class="platform-feedback-drawer__type-copy">
        <span class="platform-feedback-drawer__type-label">Feedback Type</span>
        <strong class="platform-feedback-drawer__type-value">${escapePlatformFeedbackHtml(categoryLabel)}</strong>
      </div>
    `;
    card.append(typeCard);
    content.append(card);

    const statusForm = document.createElement("form");
    statusForm.className = "platform-feedback-drawer__status-form";
    statusForm.dataset.platformFeedbackStatusForm = feedbackId;
    statusForm.innerHTML = `
      <label class="platform-feedback-drawer__field">
        <span>Status</span>
        <select data-platform-feedback-status-select>
          <option value="open"${status !== "resolved" ? " selected" : ""}>Pending</option>
          <option value="resolved"${status === "resolved" ? " selected" : ""}>Resolved</option>
        </select>
      </label>
      <button type="submit" class="buyer-data-button buyer-data-button--primary">Update Status</button>
    `;
    statusForm.addEventListener("submit", (event) => {
      event.preventDefault();
      const select = statusForm.querySelector("[data-platform-feedback-status-select]");
      const nextStatus = select instanceof HTMLSelectElement ? select.value : status;
      void updatePlatformFeedbackStatus(feedbackId, nextStatus);
    });
    content.append(statusForm);

    const timeline = document.createElement("section");
    timeline.className = "platform-feedback-drawer__timeline";
    timeline.setAttribute("aria-label", "Feedback history");
    timeline.innerHTML = `
      <span class="platform-feedback-drawer__section-label">Notes History</span>
      <ol class="platform-feedback-drawer__history">
        <li>
          <strong>Feedback submitted</strong>
          <time datetime="${escapePlatformFeedbackHtml(entry?.createdAt || "")}">${escapePlatformFeedbackHtml(formatPlatformFeedbackDate(entry?.createdAt))}</time>
        </li>
        <li>
          <strong>New feedback received</strong>
          <time datetime="${escapePlatformFeedbackHtml(entry?.createdAt || "")}">${escapePlatformFeedbackHtml(formatPlatformFeedbackDate(entry?.createdAt))}</time>
        </li>
        ${entry?.resolvedAt ? `
          <li>
            <strong>Marked resolved</strong>
            <time datetime="${escapePlatformFeedbackHtml(entry.resolvedAt)}">${escapePlatformFeedbackHtml(formatPlatformFeedbackDate(entry.resolvedAt))}</time>
          </li>
        ` : ""}
      </ol>
    `;
    content.append(timeline);
  }

  async function markPlatformFeedbackRead(type, entry) {
    if (!isPlatformFeedbackUnread(entry)) {
      return;
    }

    const feedbackId = String(entry?.id || "").trim();
    if (!feedbackId) {
      return;
    }

    const previousReadAt = String(entry?.readAt || "").trim();
    const previousReadBy = String(entry?.readBy || "").trim();
    const optimisticReadAt = new Date().toISOString();
    entry.readAt = optimisticReadAt;
    entry.readBy = "root";
    renderPlatformFeedbackList(type);

    try {
      const response = await fetch(`/api/platform-feedback/${encodeURIComponent(feedbackId)}`, {
        method: "PATCH",
        headers: rootHeaders({
          Accept: "application/json",
          "Content-Type": "application/json",
        }),
        body: JSON.stringify({ isRead: true }),
      });
      const payload = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(payload?.message || "Unable to mark feedback as read.");
      }

      const updated = payload?.feedback;
      if (updated && typeof updated === "object") {
        const entries = Array.isArray(state.platformFeedback?.[type]) ? state.platformFeedback[type] : [];
        const index = entries.findIndex((record) => String(record?.id || "").trim() === feedbackId);
        if (index !== -1) {
          entries[index] = updated;
        }
      }
      renderPlatformFeedbackList(type);
    } catch (error) {
      if (String(entry?.readAt || "") === optimisticReadAt) {
        entry.readAt = previousReadAt;
        entry.readBy = previousReadBy;
        renderPlatformFeedbackList(type);
      }
      console.error("Unable to mark platform feedback as read:", error);
    }
  }

  function openPlatformFeedbackDrawer(type, feedbackId) {
    const entry = findPlatformFeedbackEntry(type, feedbackId);
    if (!entry || !elements.platformFeedbackDrawer) {
      return;
    }

    closeCompanyDrawer({ instant: true });
    closeIntegratedDrawers();

    state.platformFeedback.selectedId = String(feedbackId || "").trim();
    state.platformFeedback.selectedType = type;
    renderPlatformFeedbackDrawerContent(entry, type);
    openSuperAdminRightDrawer(
      elements.platformFeedbackDrawer,
      elements.platformFeedbackDrawerBackdrop,
      {
        bodyClass: "platform-feedback-drawer-open",
        onOpened: () => {
          elements.platformFeedbackDrawerClose?.focus?.();
        },
      },
    );
    syncPlatformFeedbackSelection("seller");
    syncPlatformFeedbackSelection("user");
    void markPlatformFeedbackRead(type, entry);
  }

  function closePlatformFeedbackDrawer(options = {}) {
    if (options.clearSelection !== false) {
      state.platformFeedback.selectedId = "";
      state.platformFeedback.selectedType = "";
    }
    closeSuperAdminRightDrawer(
      elements.platformFeedbackDrawer,
      elements.platformFeedbackDrawerBackdrop,
      {
        bodyClass: "platform-feedback-drawer-open",
        instant: options.instant === true,
        onClosed: () => {
          elements.platformFeedbackDrawerContent?.replaceChildren();
          syncPlatformFeedbackSelection("seller");
          syncPlatformFeedbackSelection("user");
        },
      },
    );
  }

  function syncPlatformFeedbackFilterControlsFromState(type = getPlatformFeedbackActiveType()) {
    const filters = getPlatformFeedbackFilters(type);
    for (const control of elements.platformFeedbackFilterControls || []) {
      if (!(control instanceof HTMLInputElement)) continue;
      const key = String(control.dataset.platformFeedbackFilter || "").trim();
      control.checked = Boolean(key && String(filters[key] || "") === String(control.value || ""));
    }
  }

  function getPlatformFeedbackFiltersFromControls() {
    const nextFilters = createDefaultPlatformFeedbackFilters();
    for (const control of elements.platformFeedbackFilterControls || []) {
      if (!(control instanceof HTMLInputElement) || !control.checked) continue;
      const key = String(control.dataset.platformFeedbackFilter || "").trim();
      if (Object.prototype.hasOwnProperty.call(nextFilters, key)) {
        nextFilters[key] = String(control.value || nextFilters[key]);
      }
    }
    return nextFilters;
  }

  function syncPlatformFeedbackFilterSummary(type = getPlatformFeedbackActiveType()) {
    const summary = elements.platformFeedbackFilterSummary;
    if (!summary) return;
    const filters = getPlatformFeedbackFilters(type);
    const labels = [];
    const statusLabels = { pending: "Pending", resolved: "Resolved" };
    const readLabels = { unread: "Unread", read: "Read" };
    const dateLabels = { "this-month": "This month", 30: "Last 30 days", 90: "Last 90 days" };
    const sortLabels = {
      newest: "Newest",
      oldest: "Oldest",
      "rating-high": "Highest rating",
      "rating-low": "Lowest rating",
    };
    if (filters.status !== "all") labels.push(statusLabels[filters.status] || filters.status);
    if (filters.read !== "all") labels.push(readLabels[filters.read] || filters.read);
    if (filters.rating !== "all") labels.push(`${filters.rating} ${filters.rating === "1" ? "star" : "stars"}`);
    if (filters.date !== "all") labels.push(dateLabels[filters.date] || filters.date);
    labels.push(sortLabels[filters.sort] || "Newest");
    summary.textContent = labels.length === 1 && filters.sort === "newest" ? "All, Newest" : labels.join(", ");
  }

  function syncPlatformFeedbackSearchPlaceholder() {
    const input = elements.platformFeedbackSearch;
    if (!(input instanceof HTMLInputElement)) {
      return;
    }
    if (state.activeSection === "user-feedback") {
      input.placeholder = "Search User Feedback";
      input.closest("label")?.setAttribute("aria-label", "Search user feedback");
      input.value = getPlatformFeedbackSearchTerm("user");
      return;
    }
    input.placeholder = "Search Companies Feedback";
    input.closest("label")?.setAttribute("aria-label", "Search companies feedback");
    input.value = getPlatformFeedbackSearchTerm("seller");
  }

  function renderPlatformFeedbackList(type) {
    const list = elements.platformFeedbackLists?.[type];
    if (!(list instanceof HTMLElement)) {
      return;
    }

    const allEntries = Array.isArray(state.platformFeedback?.[type]) ? state.platformFeedback[type] : [];
    syncPlatformFeedbackNavBadge();
    updatePlatformFeedbackSummary(type, allEntries);
    const entries = getFilteredPlatformFeedbackEntries(type);
    list.replaceChildren();

    if (!allEntries.length) {
      const empty = document.createElement("div");
      empty.className = "buyer-data-empty";
      empty.textContent = `No ${type === "seller" ? "companies" : "user"} feedback yet.`;
      list.append(empty);
      renderPlatformFeedbackPagination(type, 0);
      syncPlatformFeedbackSelection(type);
      return;
    }

    if (!entries.length) {
      list.append(createPlatformFeedbackTableHeader(type));
      const empty = document.createElement("div");
      empty.className = "buyer-data-empty";
      empty.textContent = `No matching ${type === "seller" ? "companies" : "user"} feedback.`;
      list.append(empty);
      renderPlatformFeedbackPagination(type, 0);
      syncPlatformFeedbackSelection(type);
      return;
    }

    const { pageStart, pageSize } = renderPlatformFeedbackPagination(type, entries.length);
    const pageEntries = entries.slice(pageStart, pageStart + pageSize);
    list.append(createPlatformFeedbackTableHeader(type));
    for (const entry of pageEntries) {
      list.append(createPlatformFeedbackRow(type, entry));
    }
    syncPlatformFeedbackSelection(type);

    revealSuperAdminNotificationTrace();

    const selectedId = String(state.platformFeedback?.selectedId || "").trim();
    const selectedType = String(state.platformFeedback?.selectedType || "").trim();
    if (selectedType === type && selectedId) {
      const selectedEntry = findPlatformFeedbackEntry(type, selectedId);
      if (selectedEntry && !elements.platformFeedbackDrawer?.hidden) {
        renderPlatformFeedbackDrawerContent(selectedEntry, type);
      }
    }
  }

  function renderPlatformFeedback() {
    renderPlatformFeedbackList("seller");
    renderPlatformFeedbackList("user");
  }

  async function loadPlatformFeedback(options = {}) {
    if (state.platformFeedback.loading) {
      return;
    }
    state.platformFeedback.loading = true;
    try {
      const response = await fetch("/api/platform-feedback", {
        cache: "no-store",
        headers: rootHeaders({ Accept: "application/json" }),
      });
      const payload = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(payload?.message || "Unable to load feedback.");
      }
      const rows = Array.isArray(payload?.feedback) ? payload.feedback : [];
      state.platformFeedback.seller = rows.filter((entry) => entry?.type === "seller");
      state.platformFeedback.user = rows.filter((entry) => entry?.type === "user");
      state.platformFeedback.loaded = true;
      renderPlatformFeedback();
      syncAutoSeenSuperAdminNotifications();
    } catch (error) {
      if (!options.quiet) {
        setFeedback(error instanceof Error ? error.message : "Unable to load feedback.", "error");
      }
    } finally {
      state.platformFeedback.loading = false;
    }
  }

  async function updatePlatformFeedbackStatus(feedbackId, nextStatus) {
    const id = String(feedbackId || "").trim();
    const status = normalizePlatformFeedbackStatusValue(nextStatus);
    if (!id) {
      return;
    }
    try {
      const response = await fetch(`/api/platform-feedback/${encodeURIComponent(id)}`, {
        method: "PATCH",
        headers: rootHeaders({
          Accept: "application/json",
          "Content-Type": "application/json",
        }),
        body: JSON.stringify({ status }),
      });
      const payload = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(payload?.message || "Unable to update feedback.");
      }
      setFeedback(payload?.message || "Feedback updated.", "success");
      markSuperAdminNotificationsReadForFeedback(id);
      const updated = payload?.feedback;
      if (updated && typeof updated === "object") {
        for (const type of ["seller", "user"]) {
          const entries = Array.isArray(state.platformFeedback?.[type]) ? state.platformFeedback[type] : [];
          const index = entries.findIndex((entry) => String(entry?.id || "").trim() === id);
          if (index !== -1) {
            entries[index] = updated;
            break;
          }
        }
        renderPlatformFeedback();
      } else {
        await loadPlatformFeedback({ quiet: true });
      }
      const activeType = String(state.platformFeedback.selectedType || getPlatformFeedbackActiveType());
      if (String(state.platformFeedback.selectedId || "") === id) {
        const refreshed = findPlatformFeedbackEntry(activeType, id);
        if (refreshed) {
          renderPlatformFeedbackDrawerContent(refreshed, activeType);
        }
      }
    } catch (error) {
      setFeedback(error instanceof Error ? error.message : "Unable to update feedback.", "error");
    }
  }

  async function resolvePlatformFeedback(feedbackId) {
    await updatePlatformFeedbackStatus(feedbackId, "resolved");
  }

  async function deletePlatformFeedback(type, feedbackId) {
    const id = String(feedbackId || "").trim();
    const entry = findPlatformFeedbackEntry(type, id);
    if (!id || !entry) {
      return false;
    }

    const displayId = formatPlatformFeedbackDisplayId(entry);
    const confirmed = await confirmDeleteValidationModal(
      "Delete feedback?",
      `Delete ${displayId} permanently? This feedback record cannot be recovered.`,
    );
    if (!confirmed) {
      return false;
    }

    try {
      const response = await fetch(`/api/platform-feedback/${encodeURIComponent(id)}`, {
        method: "DELETE",
        headers: rootHeaders({ Accept: "application/json" }),
      });
      const payload = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(payload?.message || "Unable to delete feedback.");
      }

      state.platformFeedback[type] = (Array.isArray(state.platformFeedback?.[type])
        ? state.platformFeedback[type]
        : []).filter((record) => String(record?.id || "").trim() !== id);
      if (String(state.platformFeedback.selectedId || "") === id) {
        closePlatformFeedbackDrawer();
      }
      renderPlatformFeedback();
      markSuperAdminNotificationsReadForFeedback(id);
      showSuperAdminSnackbar(
        "Feedback deleted",
        payload?.message || `${displayId} was deleted.`,
        "success",
      );
      return true;
    } catch (error) {
      showSuperAdminSnackbar(
        "Delete failed",
        error instanceof Error ? error.message : "Unable to delete feedback.",
        "error",
      );
      return false;
    }
  }

  async function handlePlatformFeedbackAction(action, type, feedbackId) {
    const normalizedAction = String(action || "").trim().toLowerCase();
    const normalizedType = type === "user" ? "user" : "seller";
    const id = String(feedbackId || "").trim();
    if (!id) {
      return;
    }

    if (normalizedAction === "resolve") {
      await resolvePlatformFeedback(id);
      return;
    }
    if (normalizedAction === "delete") {
      await deletePlatformFeedback(normalizedType, id);
    }
  }

  async function insertChatWallpapers(fileList) {
    const files = Array.from(fileList || []).filter((file) => file instanceof File && file.type.startsWith("image/"));
    if (!files.length) {
      showSuperAdminSnackbar(
        "Invalid file",
        "Choose a JPG, PNG, WEBP, or GIF image.",
        "error",
      );
      return;
    }
    openChatWallpaperNamer(files);
  }

  function clearChatWallpaperDrafts() {
    (state.chatWallpaperDrafts || []).forEach((draft) => {
      if (draft?.previewUrl) {
        URL.revokeObjectURL(draft.previewUrl);
      }
    });
    state.chatWallpaperDrafts = [];
  }

  function closeChatWallpaperNamer() {
    clearChatWallpaperDrafts();
    setChatWallpaperNamerFeedback("");
    const overlay = elements.chatWallpaperNamerOverlay;
    if (overlay instanceof HTMLElement) {
      overlay.classList.remove("is-open");
      overlay.setAttribute("aria-hidden", "true");
      window.setTimeout(() => {
        if (!overlay.classList.contains("is-open")) {
          overlay.hidden = true;
        }
      }, 170);
    }
    document.body.classList.remove("super-admin-chat-wallpaper-namer-open");
    if (elements.chatWallpaperNamerList) {
      elements.chatWallpaperNamerList.innerHTML = "";
    }
  }

  function openChatWallpaperNamer(files) {
    clearChatWallpaperDrafts();
    state.chatWallpaperDrafts = files.map((file, index) => ({
      id: `draft-${index}`,
      file,
      previewUrl: URL.createObjectURL(file),
      label: wallpaperLabelFromFileName(file.name),
    }));
    const overlay = elements.chatWallpaperNamerOverlay;
    if (!(overlay instanceof HTMLElement) || !elements.chatWallpaperNamerList) {
      void saveNamedChatWallpapers();
      return;
    }
    elements.chatWallpaperNamerList.innerHTML = state.chatWallpaperDrafts.map((draft) => `
      <div class="super-admin-chat-wallpaper-namer__row">
        <span class="super-admin-chat-wallpaper-namer__preview">
          <img src="${escapeHtml(draft.previewUrl)}" alt="" />
        </span>
        <label>
          Name
          <input
            type="text"
            maxlength="48"
            required
            value="${escapeHtml(draft.label)}"
            data-chat-wallpaper-name="${escapeHtml(draft.id)}"
            placeholder="Background name"
            autocomplete="off"
          />
        </label>
      </div>
    `).join("");
    setChatWallpaperNamerFeedback("");
    overlay.hidden = false;
    overlay.setAttribute("aria-hidden", "false");
    document.body.classList.add("super-admin-chat-wallpaper-namer-open");
    window.requestAnimationFrame(() => {
      overlay.classList.add("is-open");
      const firstInput = elements.chatWallpaperNamerList.querySelector("input");
      if (firstInput instanceof HTMLInputElement) {
        firstInput.focus();
        firstInput.select();
      } else if (elements.chatWallpaperNamer instanceof HTMLElement) {
        elements.chatWallpaperNamer.focus({ preventScroll: true });
      }
    });
  }

  function collectChatWallpaperDraftNames() {
    return (state.chatWallpaperDrafts || []).map((draft) => {
      const input = elements.chatWallpaperNamerList?.querySelector(`[data-chat-wallpaper-name="${draft.id}"]`);
      const typedName = input instanceof HTMLInputElement ? input.value : draft.label;
      return {
        ...draft,
        label: String(typedName || "").replace(/\s+/g, " ").trim().slice(0, 48),
      };
    });
  }

  async function saveNamedChatWallpapers() {
    if (chatWallpaperSaving) {
      return;
    }
    const drafts = collectChatWallpaperDraftNames();
    if (!drafts.length) {
      setChatWallpaperNamerFeedback("Choose a JPG, PNG, WEBP, or GIF image.", "error");
      return;
    }
    const missingName = drafts.find((draft) => !draft.label);
    if (missingName) {
      setChatWallpaperNamerFeedback("Enter a name for each background.", "error");
      const input = elements.chatWallpaperNamerList?.querySelector(`[data-chat-wallpaper-name="${missingName.id}"]`);
      if (input instanceof HTMLInputElement) {
        input.focus();
      }
      return;
    }

    chatWallpaperSaving = true;
    if (elements.chatWallpaperNamerSave instanceof HTMLButtonElement) {
      elements.chatWallpaperNamerSave.disabled = true;
    }
    if (elements.chatWallpaperNamerCancel instanceof HTMLButtonElement) {
      elements.chatWallpaperNamerCancel.disabled = true;
    }
    if (elements.chatWallpaperNamerClose instanceof HTMLButtonElement) {
      elements.chatWallpaperNamerClose.disabled = true;
    }
    setChatWallpaperNamerFeedback(`Uploading ${drafts.length} background${drafts.length === 1 ? "" : "s"}...`);
    try {
      const uploadedDrafts = await mapWithConcurrency(
        drafts,
        imageUploadConcurrency,
        async (draft, index) => {
          setChatWallpaperNamerFeedback(`Uploading ${index + 1} of ${drafts.length}...`);
          const src = await uploadSuperAdminProductImageFile(draft.file);
          return { ...draft, src };
        },
      );
      for (const draft of uploadedDrafts) {
        const response = await fetch("/api/chat-wallpapers", {
          method: "POST",
          headers: rootHeaders({
            Accept: "application/json",
            "Content-Type": "application/json",
          }),
          body: JSON.stringify({
            src: draft.src,
            label: draft.label,
          }),
        });
        const data = await response.json().catch(() => ({}));
        if (!response.ok) {
          throw new Error(data.message || "Unable to save chat background.");
        }
        state.chatWallpapers = Array.isArray(data.wallpapers) ? data.wallpapers : state.chatWallpapers;
      }
      renderChatWallpaperGrid();
      closeChatWallpaperNamer();
      showSuperAdminSnackbar(
        "Background added",
        `${drafts.length} background${drafts.length === 1 ? "" : "s"} added to Live Chat.`,
        "success",
      );
    } catch (error) {
      setChatWallpaperNamerFeedback(error?.message || "Unable to insert chat background.", "error");
    } finally {
      chatWallpaperSaving = false;
      if (elements.chatWallpaperNamerSave instanceof HTMLButtonElement) {
        elements.chatWallpaperNamerSave.disabled = false;
      }
      if (elements.chatWallpaperNamerCancel instanceof HTMLButtonElement) {
        elements.chatWallpaperNamerCancel.disabled = false;
      }
      if (elements.chatWallpaperNamerClose instanceof HTMLButtonElement) {
        elements.chatWallpaperNamerClose.disabled = false;
      }
    }
  }

  async function removeChatWallpaper(wallpaperId) {
    const id = String(wallpaperId || "").trim();
    if (!id) {
      return;
    }
    const wallpaper = (state.chatWallpapers || []).find((item) => item.id === id);
    const label = wallpaper?.label || "this background";
    const confirmed = wallpaper
      ? await openChatWallpaperDeleteModal(wallpaper)
      : await openSuperAdminCompactDeleteModal({
          title: "Delete this background?",
          message: `Remove ${label} from Live Chat? This action cannot be undone and will be permanent.`,
          titlePrefix: "super-admin-chat-wallpaper-delete-title",
        });
    if (!confirmed) {
      return;
    }
    try {
      const response = await fetch(`/api/chat-wallpapers/${encodeURIComponent(id)}`, {
        method: "DELETE",
        headers: rootHeaders({ Accept: "application/json" }),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(data.message || "Unable to remove chat background.");
      }
      state.chatWallpapers = Array.isArray(data.wallpapers) ? data.wallpapers : state.chatWallpapers.filter((item) => item.id !== id);
      renderChatWallpaperGrid();
      showSuperAdminSnackbar(
        "Background removed",
        `${label} was removed from Live Chat.`,
        "success",
      );
    } catch (error) {
      showSuperAdminSnackbar(
        "Unable to remove background",
        error?.message || "Unable to remove chat background.",
        "error",
      );
    }
  }

  // Clears validation modal auto close timer and related transient state.
  function clearValidationModalAutoCloseTimer() {
    if (validationModalAutoCloseTimer) {
      window.clearTimeout(validationModalAutoCloseTimer);
      validationModalAutoCloseTimer = 0;
    }
  }

  // Destroys validation success animation and releases its resources.
  function destroyValidationSuccessAnimation() {
    if (validationSuccessAnimation?.destroy) {
      validationSuccessAnimation.destroy();
    }
    validationSuccessAnimation = null;
  }

  // Ensures validation lottie player is ready before use.
  function ensureValidationLottiePlayer() {
    if (window.lottie?.loadAnimation) {
      return Promise.resolve(true);
    }

    if (validationLottieLoadPromise) {
      return validationLottieLoadPromise;
    }

    validationLottieLoadPromise = new Promise((resolve) => {
      const existingScript = document.querySelector(
        `script[src$="${validationLottiePlayerUrl}"], script[src*="${validationLottiePlayerUrl}?"]`,
      );

      if (existingScript) {
        existingScript.addEventListener(
          "load",
          () => resolve(Boolean(window.lottie?.loadAnimation)),
          { once: true },
        );
        existingScript.addEventListener("error", () => resolve(false), { once: true });
        if (window.lottie?.loadAnimation) {
          resolve(true);
        }
        return;
      }

      const scriptElement = document.createElement("script");
      scriptElement.src = validationLottiePlayerUrl;
      scriptElement.async = true;
      scriptElement.addEventListener(
        "load",
        () => resolve(Boolean(window.lottie?.loadAnimation)),
        { once: true },
      );
      scriptElement.addEventListener("error", () => resolve(false), { once: true });
      document.head.appendChild(scriptElement);
    });

    return validationLottieLoadPromise;
  }

  // Plays validation success animation animation when available.
  async function playValidationSuccessAnimation() {
    const container = elements.validationModalIcon?.querySelector(
      "[data-super-admin-validation-lottie-check]",
    );
    if (!(container instanceof HTMLElement)) {
      return;
    }

    destroyValidationSuccessAnimation();
    container.innerHTML = "";

    const canUseLottie = await ensureValidationLottiePlayer();
    if (
      !canUseLottie ||
      !window.lottie?.loadAnimation ||
      !container.isConnected ||
      elements.validationModalOverlay?.hidden
    ) {
      return;
    }

    validationSuccessAnimation = window.lottie.loadAnimation({
      container,
      renderer: "svg",
      loop: false,
      autoplay: true,
      path: validationSuccessAnimationPath,
    });
  }

  // Hides validation modal overlay with cleanup support.
  function hideValidationModalOverlay(callback) {
    const overlay = elements.validationModalOverlay;
    if (!(overlay instanceof HTMLElement)) {
      destroyValidationSuccessAnimation();
      if (typeof callback === "function") {
        callback();
      }
      return;
    }

    overlay.classList.remove("is-open");
    overlay.setAttribute("aria-hidden", "true");

    let cleanedUp = false;
    const cleanup = () => {
      if (cleanedUp) {
        return;
      }

      cleanedUp = true;
      destroyValidationSuccessAnimation();
      overlay.hidden = true;
      overlay.removeEventListener("transitionend", handleTransitionEnd);
      window.clearTimeout(exitTimer);
      restoreSuperAdminScrollSnapshotStable(validationModalScrollSnapshot);
      validationModalScrollSnapshot = null;

      if (typeof callback === "function") {
        callback();
      }
    };

    const handleTransitionEnd = (event) => {
      if (event.target === overlay) {
        cleanup();
      }
    };

    overlay.addEventListener("transitionend", handleTransitionEnd);
    const exitTimer = window.setTimeout(cleanup, 300);
  }

  // Closes validation modal and cleans up related state.
  function closeValidationModal(result = false) {
    const resolver = validationModalResolve;
    validationModalResolve = null;
    clearValidationModalAutoCloseTimer();

    hideValidationModalOverlay(() => {
      if (typeof resolver === "function") {
        resolver(Boolean(result));
      }
    });
  }

  // Updates validation modal icon and synchronizes related UI state.
  function setValidationModalIcon(iconVariant) {
    if (!(elements.validationModalIcon instanceof HTMLElement)) {
      return;
    }

    elements.validationModalIcon.className = "validation-modal__icon";
    if (iconVariant === "success") {
      elements.validationModalIcon.classList.add("validation-modal__icon--success");
    } else if (iconVariant === "notice") {
      elements.validationModalIcon.classList.add("validation-modal__icon--notice");
    } else {
      elements.validationModalIcon.classList.add("validation-modal__icon--error");
      if (iconVariant === "delete") {
        elements.validationModalIcon.classList.add("validation-modal__icon--delete");
      }
    }

    elements.validationModalIcon.innerHTML =
      validationModalIcons[iconVariant] || validationModalIcons.error;
  }

  // Shows validation modal and prepares its content.
  function showValidationModal(config = {}) {
    const overlay = elements.validationModalOverlay;
    const title = String(config.title || "").trim() || "Important Notice";
    const copy = String(config.copy || "").trim();
    const mode = String(config.mode || "notice").trim().toLowerCase();
    const iconVariant = String(config.iconVariant || mode).trim().toLowerCase();
    const visualMode = ["success", "notice", "error", "delete"].includes(iconVariant)
      ? iconVariant
      : "notice";

    if (
      !(overlay instanceof HTMLElement) ||
      !(elements.validationModalTitle instanceof HTMLElement) ||
      !(elements.validationModalCopy instanceof HTMLElement) ||
      !(elements.validationModalActionButton instanceof HTMLButtonElement) ||
      !(elements.validationModalSecondaryActionButton instanceof HTMLButtonElement)
    ) {
      if (mode === "delete") {
        return Promise.resolve(window.confirm(copy || title));
      }
      return Promise.resolve(true);
    }

    if (typeof validationModalResolve === "function") {
      validationModalResolve(false);
      validationModalResolve = null;
    }

    clearValidationModalAutoCloseTimer();
    destroyValidationSuccessAnimation();
    validationModalAllowManualClose = config.allowManualClose !== false;
    validationModalAllowOverlayClose = config.allowOverlayClose !== false;

    elements.validationModalTitle.textContent = title;
    elements.validationModalCopy.textContent = copy;
    elements.validationModalCopy.hidden = !copy;

    if (elements.validationModalDialog instanceof HTMLElement) {
      for (const modalMode of ["success", "notice", "error", "delete"]) {
        elements.validationModalDialog.classList.toggle(
          `validation-modal--${modalMode}`,
          modalMode === visualMode,
        );
      }
    }
    overlay.dataset.validationMode = visualMode;

    setValidationModalIcon(iconVariant);

    const hideActions = config.hideActions === true;
    if (elements.validationModalActions instanceof HTMLElement) {
      elements.validationModalActions.hidden = hideActions;
    }

    elements.validationModalActionButton.textContent =
      String(config.actionLabel || "").trim() || "Continue";
    elements.validationModalSecondaryActionButton.textContent =
      String(config.secondaryActionLabel || "").trim() || "Cancel";
    elements.validationModalActionButton.classList.toggle(
      "validation-modal__action-button--danger",
      iconVariant === "delete",
    );
    elements.validationModalSecondaryActionButton.hidden =
      hideActions || config.hideSecondaryAction === true;
    elements.validationModalActionButton.hidden = hideActions;
    elements.validationModalActionButton.disabled = false;
    elements.validationModalSecondaryActionButton.disabled = false;

    if (elements.validationModalCloseButton instanceof HTMLButtonElement) {
      elements.validationModalCloseButton.hidden = config.hideClose === true;
    }

    if (overlay.hidden) {
      validationModalScrollSnapshot = getSuperAdminScrollSnapshot();
    }
    overlay.hidden = false;
    overlay.setAttribute("aria-hidden", "false");
    window.requestAnimationFrame(() => {
      overlay.classList.add("is-open");
    });

    if (iconVariant === "success") {
      void playValidationSuccessAnimation();
    }

    const normalizedAutoCloseMs = Number(config.autoCloseMs);
    if (Number.isFinite(normalizedAutoCloseMs) && normalizedAutoCloseMs > 0) {
      validationModalAutoCloseTimer = window.setTimeout(() => {
        validationModalAutoCloseTimer = 0;
        closeValidationModal(true);
      }, normalizedAutoCloseMs);
    }

    window.requestAnimationFrame(() => {
      if (!elements.validationModalActionButton.hidden) {
        focusWithoutScroll(elements.validationModalActionButton);
        restoreSuperAdminScrollSnapshot(validationModalScrollSnapshot);
        return;
      }

      if (
        elements.validationModalCloseButton instanceof HTMLButtonElement &&
        !elements.validationModalCloseButton.hidden
      ) {
        focusWithoutScroll(elements.validationModalCloseButton);
        restoreSuperAdminScrollSnapshot(validationModalScrollSnapshot);
        return;
      }

      focusWithoutScroll(elements.validationModalDialog);
      restoreSuperAdminScrollSnapshot(validationModalScrollSnapshot);
    });

    return new Promise((resolve) => {
      validationModalResolve = resolve;
    });
  }

  // Uses the shared validation success design for every Super Admin success state.
  function showSuccessValidationModal(title, copy) {
    const normalizedTitle = String(title || "Success").trim() || "Success";
    const normalizedCopy = String(copy || "").trim();
    setFeedback(normalizedCopy, "success");
    return showValidationModal({
      mode: "success",
      title: normalizedTitle,
      copy: normalizedCopy,
      hideActions: true,
      hideClose: true,
      allowManualClose: false,
      allowOverlayClose: false,
      autoCloseMs: validationSuccessAnimationMs + validationSuccessHoldMs,
    });
  }

  // Shares the same Super Admin validation success host with scripts loaded after this file.
  window.GMSSuperAdminValidationModal = Object.freeze({
    showSuccess: showSuccessValidationModal,
  });

  window.GMSSuperAdminPasswordRevealModal = Object.freeze({
    open: showTemporaryPasswordSnackbar,
    openTemporary: showTemporaryPasswordSnackbar,
    close: hideSuperAdminSnackbar,
  });

  window.GMSSuperAdminClipboard = Object.freeze({
    copy: async (value, label = "Value") => {
      const text = String(value || "").trim();
      const normalizedLabel = String(label || "Value").trim() || "Value";
      if (!text) {
        return false;
      }
      try {
        const copied = await copyTextToClipboard(text);
        if (!copied) {
          throw new Error("Clipboard copy was not completed.");
        }
        showSuperAdminCopySnackbar();
        return true;
      } catch (error) {
        console.error(`Unable to copy ${normalizedLabel.toLowerCase()}:`, error);
        showSuperAdminSnackbar("Copy failed", `Unable to copy the ${normalizedLabel.toLowerCase()}.`, "error");
        return false;
      }
    },
  });

  // Shows a confirmation flow for delete validation modal.
  function confirmDeleteValidationModal(title, copy) {
    return openSuperAdminCompactDeleteModal({
      title: title || "Delete this item?",
      message: copy || "This action cannot be undone and will be permanent.",
      titlePrefix: "super-admin-delete-validation-title",
    });
  }

  // Reads or derives category trigger buttons for the current super admin flow.
  function getCategoryTriggerButtons() {
    return elements.categoryNavTriggers.filter((button) => button instanceof HTMLElement);
  }

  // Reads or derives store type trigger buttons for the current super admin flow.
  function getStoreTypeTriggerButtons() {
    return elements.storeTypeNavTriggers.filter((button) => button instanceof HTMLElement);
  }

  // Checks whether event within element is true for the current record or UI state.
  function isEventWithinElement(event, element) {
    if (!(element instanceof HTMLElement) || !event) {
      return false;
    }

    if (typeof event.composedPath === "function") {
      const eventPath = event.composedPath();
      if (Array.isArray(eventPath) && eventPath.includes(element)) {
        return true;
      }
    }

    return event.target instanceof Node && element.contains(event.target);
  }

  // Normalizes category name before comparison or storage.
  function normalizeCategoryName(value, { preserveTrailingSpace = false } = {}) {
    const compactedValue = String(value ?? "")
      .replace(/\s+/g, " ")
      .replace(/^\s+/, "");

    if (!compactedValue) {
      return "";
    }

    const hasTrailingSpace = preserveTrailingSpace && /\s$/.test(compactedValue);
    const formattedCoreValue = hasTrailingSpace
      ? compactedValue.slice(0, -1)
      : compactedValue.trimEnd();

    return hasTrailingSpace ? `${formattedCoreValue} ` : formattedCoreValue;
  }

  // Normalizes category values before comparison or storage.
  function normalizeCategoryValues(values) {
    const rawValues = Array.isArray(values)
      ? values
      : values === null || values === undefined
        ? []
        : [values];
    const seen = new Set();
    const normalizedValues = [];

    for (const value of rawValues) {
      const normalizedCategory = normalizeCategoryName(value);
      const normalizedKey = normalizedCategory.toLowerCase();
      if (!normalizedCategory || seen.has(normalizedKey)) {
        continue;
      }

      seen.add(normalizedKey);
      normalizedValues.push(normalizedCategory);
    }

    return normalizedValues.sort((left, right) =>
      left.localeCompare(right, undefined, { sensitivity: "base" }),
    );
  }

  // Normalizes store type values before comparison or storage.
  function normalizeStoreTypeValues(values) {
    const rawValues = Array.isArray(values)
      ? values
      : values === null || values === undefined
        ? []
        : [values];
    const seen = new Set();
    const normalizedValues = [];

    for (const value of rawValues) {
      const normalizedStoreType = normalizeCategoryName(
        value && typeof value === "object"
          ? value.name ?? value.storeType ?? value.type ?? value.label ?? value.title
          : value,
      );
      const normalizedKey = normalizedStoreType.toLowerCase();
      if (!normalizedStoreType || seen.has(normalizedKey)) {
        continue;
      }

      seen.add(normalizedKey);
      normalizedValues.push(normalizedStoreType);
    }

    return normalizedValues.sort((left, right) =>
      left.localeCompare(right, undefined, { sensitivity: "base" }),
    );
  }

  // Normalizes store type status before comparison or storage.
  function normalizeStoreTypeStatus(value) {
    return String(value ?? "").trim().toLowerCase() === "inactive"
      ? "inactive"
      : "active";
  }

  function normalizeStoreTypeCategoryStatus(value) {
    const normalizedValue = String(value ?? "").trim().toLowerCase();
    return ["inactive", "deactivated", "disabled", "off"].includes(normalizedValue)
      ? "inactive"
      : "active";
  }

  // Normalizes store type number before comparison or storage.
  function normalizeStoreTypeNumber(value) {
    const numberValue = Number(value ?? 0);
    return Number.isFinite(numberValue) && numberValue >= 0 ? numberValue : 0;
  }

  // Keeps business type imagery limited to browser-safe image sources.
  function normalizeBusinessTypeImageUrl(value) {
    const imageUrl = String(value ?? "").trim();
    if (
      imageUrl.startsWith("/")
      || imageUrl.startsWith("data:image/")
      || /^https?:\/\//i.test(imageUrl)
    ) {
      return imageUrl;
    }
    return "";
  }

  // Normalizes optional per-category details returned with a business type.
  function normalizeStoreTypeCategoryStats(value) {
    const sourceValues = Array.isArray(value)
      ? value
      : value && typeof value === "object"
        ? Object.entries(value).map(([name, details]) => ({
            name,
            ...(details && typeof details === "object"
              ? details
              : { productCount: details }),
          }))
        : [];
    const seen = new Map();

    for (const source of sourceValues) {
      const categoryName = normalizeCategoryName(
        source?.name ?? source?.category ?? source?.label,
      );
      if (!categoryName) {
        continue;
      }

      const key = categoryName.toLowerCase();
      if (!seen.has(key)) {
        seen.set(key, {
          name: categoryName,
          productCount: Math.trunc(
            normalizeStoreTypeNumber(source?.productCount ?? source?.count ?? source?.items),
          ),
          imageUrl: normalizeBusinessTypeImageUrl(
            source?.imageUrl ?? source?.mainImageUrl ?? source?.thumbnailUrl,
          ),
          iconImageUrl: normalizeBusinessTypeImageUrl(
            source?.iconImageUrl ?? source?.iconUrl ?? source?.categoryIconUrl,
          ),
          iconName: normalizeLucideCategoryIconName(
            source?.iconName ?? source?.lucideIconName ?? source?.categoryIconName,
          ),
          status: normalizeStoreTypeCategoryStatus(
            source?.status ?? source?.categoryStatus ?? source?.state,
          ),
        });
      }
    }

    return [...seen.values()];
  }

  // Normalizes store type record before comparison or storage.
  function normalizePlatformIdValue(value) {
    return String(value ?? "")
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "")
      .slice(0, 64);
  }

  function slugifyPlatformIdValue(name) {
    const fromName = normalizePlatformIdValue(name);
    return fromName || `platform-${Date.now().toString(36)}`;
  }

  function inferPlatformIdFromName(name) {
    const key = String(name || "")
      .trim()
      .toLowerCase()
      .replace(/&/g, " and ")
      .replace(/[^a-z0-9]+/g, " ")
      .trim();
    if (!key) return "shop";
    if (
      key.includes("hotel")
      || key.includes("hote ")
      || (/\bhotes?\b/.test(key) && key.includes("restaurant"))
    ) {
      return "hotels";
    }
    if (
      key === "food"
      || key === "foods"
      || key.includes("restaurant")
      || key.includes("dining")
      || key.includes("cafe")
    ) {
      return "food";
    }
    return "shop";
  }

  function normalizePlatformRecord(value, options = {}) {
    const source = value && typeof value === "object" ? value : {};
    const name = String(source.name ?? source.label ?? source.title ?? value ?? "")
      .replace(/\s+/g, " ")
      .trim()
      .slice(0, 80);
    const explicitId = normalizePlatformIdValue(source.id ?? source.platformId ?? source.slug);
    const id = explicitId || (name ? slugifyPlatformIdValue(name) : "");
    if (!id || !name) {
      return null;
    }
    const statusValue = String(source.status ?? "active").trim().toLowerCase();
    const sortOrderRaw = Number(source.sortOrder ?? source.order ?? options.fallbackSortOrder ?? 0);
    const comingSoonRaw = source.comingSoon ?? source.isComingSoon ?? source.soon;
    const primaryColorRaw = String(
      source.primaryColor ?? source.color ?? source.accentColor ?? "",
    )
      .trim()
      .toLowerCase();
    const secondaryColorRaw = String(
      source.secondaryColor ?? source.secondaryAccent ?? "",
    )
      .trim()
      .toLowerCase();
    const defaultPrimaryById = {
      shop: "#2563eb",
      food: "#ea580c",
      hotels: "#7c3aed",
      resort: "#0891b2",
    };
    const primaryColor = /^#[0-9a-f]{6}$/.test(primaryColorRaw)
      ? primaryColorRaw
      : (defaultPrimaryById[id] || "#2563eb");
    const secondaryColor = /^#[0-9a-f]{6}$/.test(secondaryColorRaw) ? secondaryColorRaw : "";
    return {
      id,
      name,
      status: statusValue === "inactive" ? "inactive" : "active",
      sortOrder: Number.isFinite(sortOrderRaw) ? Math.trunc(sortOrderRaw) : 0,
      iconName: normalizeLucideCategoryIconName(source.iconName ?? source.lucideIconName),
      comingSoon: comingSoonRaw === true || String(comingSoonRaw).trim().toLowerCase() === "true",
      heroImageUrl: normalizeBusinessTypeImageUrl(
        source.heroImageUrl ?? source.imageUrl ?? source.coverImageUrl,
      ),
      iconImageUrl: normalizeBusinessTypeImageUrl(source.iconImageUrl ?? source.iconUrl)
        || builtInPlatformArtUrls[id]
        || "",
      businessTypeCount: Math.trunc(normalizeStoreTypeNumber(source.businessTypeCount)),
      primaryColor,
      secondaryColor,
    };
  }

  function getPlatformRecordById(platformId) {
    const key = normalizePlatformIdValue(platformId);
    return state.platformDetails.find((platform) => platform.id === key) || null;
  }

  function getPlatformLabel(platformId) {
    const record = getPlatformRecordById(platformId);
    if (record?.name) {
      return record.name;
    }
    const normalized = normalizePlatformIdValue(platformId);
    if (!normalized) {
      return "Shop";
    }
    return normalized.charAt(0).toUpperCase() + normalized.slice(1);
  }

  function syncStoreTypePlatformSelect(selectedPlatformId = "shop") {
    const select = elements.storeTypePlatformSelect;
    if (!(select instanceof HTMLSelectElement)) {
      return;
    }
    const platforms = state.platformDetails.length
      ? state.platformDetails
      : [
          { id: "shop", name: "Shop", status: "active" },
          { id: "food", name: "Food", status: "active" },
          { id: "hotels", name: "Hotels", status: "active" },
        ];
    const preferred = normalizePlatformIdValue(selectedPlatformId) || "shop";
    select.replaceChildren();
    for (const platform of platforms) {
      const option = document.createElement("option");
      option.value = platform.id;
      option.textContent = platform.status === "inactive"
        ? `${platform.name} (Inactive)`
        : platform.name;
      select.append(option);
    }
    if (![...select.options].some((option) => option.value === preferred)) {
      const fallback = document.createElement("option");
      fallback.value = preferred;
      fallback.textContent = getPlatformLabel(preferred);
      select.append(fallback);
    }
    select.value = preferred;
  }

  function setPlatformData(platformDetails) {
    state.platformDetails = (Array.isArray(platformDetails) ? platformDetails : [])
      .map((item, index) => normalizePlatformRecord(item, { fallbackSortOrder: index + 1 }))
      .filter(Boolean)
      .sort((left, right) => {
        if (left.sortOrder !== right.sortOrder) {
          return left.sortOrder - right.sortOrder;
        }
        return left.name.localeCompare(right.name, undefined, { sensitivity: "base" });
      });
    state.platforms = state.platformDetails.map((platform) => platform.id);
    if (elements.platformTotal) {
      elements.platformTotal.textContent = `(${numberText(state.platformDetails.length)})`;
    }
    syncStoreTypePlatformSelect(elements.storeTypePlatformSelect?.value || "shop");
    renderPlatforms();
    renderPlatformColorPalettes();
  }

  function getPlatformPresentation(platform) {
    const key = `${platform?.id || ""} ${platform?.name || ""}`.trim().toLowerCase();
    if (/(food|restaurant|dining|cafe)/.test(key)) {
      return {
        iconClass: "fa-utensils",
        tagline: "Restaurants, meals, and local dining",
        description: "Manage the Food entry point, its connected business types, and availability in the buyer app.",
        imageUrl: "/assets/business-types/restaurant-hero.webp",
      };
    }
    if (/(hotel|stay|lodging|resort)/.test(key)) {
      return {
        iconClass: "fa-hotel",
        tagline: "Stays, rooms, and guest experiences",
        description: "Manage the Hotels entry point, its connected business types, and availability in the buyer app.",
        imageUrl: "/assets/admin-signup/signup-hero-background.png",
      };
    }
    return {
      iconClass: "fa-bag-shopping",
      tagline: "Stores, products, and everyday shopping",
      description: "Manage this buyer entry platform, its connected business types, and visibility across the app.",
      imageUrl: "/assets/root-login/root-login-hero-wide.png",
    };
  }

  function getPlatformBusinessTypes(platformId) {
    const normalizedPlatformId = normalizePlatformIdValue(platformId);
    return state.storeTypeDetails.filter(
      (record) => normalizePlatformIdValue(record.platformId) === normalizedPlatformId,
    );
  }

  function createPlatformBusinessTypeCard(record, index) {
    const presentation = getBusinessTypePresentation(record.name);
    const colors = getBusinessTypeCategoryIconColors(record.name, index);
    const card = document.createElement("article");
    card.className = "business-type-showcase__category-card platform-showcase__business-type-card";
    card.classList.toggle("is-category-inactive", record.status === "inactive");
    card.dataset.platformBusinessTypeName = record.name.toLowerCase();
    card.tabIndex = 0;
    card.setAttribute("role", "button");
    card.setAttribute("aria-label", `Open ${record.name} business type`);

    const openBusinessType = () => {
      state.selectedStoreTypeNavName = record.name;
      setActiveSection("store-types");
      renderStoreTypes();
      window.requestAnimationFrame(() => focusStoreTypeShowcase(record.name));
    };
    card.addEventListener("click", openBusinessType);
    card.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        openBusinessType();
      }
    });

    const media = document.createElement("span");
    media.className = "business-type-showcase__category-media";
    const mediaFrame = document.createElement("span");
    mediaFrame.className = "business-type-showcase__category-media-frame";
    const image = document.createElement("img");
    image.className = "business-type-showcase__category-image";
    image.src = record.heroImageUrl || presentation.imageUrl;
    image.alt = record.name;
    image.loading = "lazy";
    image.decoding = "async";
    setBusinessTypeImageFallback(image, presentation.imageUrl, media);
    mediaFrame.append(image);

    const businessTypeIcon = document.createElement("span");
    businessTypeIcon.className = "business-type-showcase__category-icon";
    businessTypeIcon.style.setProperty("--business-type-category-icon-bg", colors.background);
    businessTypeIcon.style.setProperty("--business-type-category-icon-color", colors.color);
    const iconSurface = document.createElement("span");
    iconSurface.className = "business-type-showcase__category-icon-surface";
    const iconImageUrl = normalizeBusinessTypeImageUrl(record.iconImageUrl);
    const lucideIconName = normalizeLucideCategoryIconName(record.iconName);
    if (iconImageUrl) {
      const iconImage = document.createElement("img");
      iconImage.src = iconImageUrl;
      iconImage.alt = "";
      iconSurface.append(iconImage);
    } else if (lucideIconName) {
      businessTypeIcon.classList.add("has-lucide-icon");
      iconSurface.innerHTML = createLucideCategoryIconSvg(lucideIconName);
    } else {
      const fallbackIcon = document.createElement("i");
      fallbackIcon.className = `fa-solid ${presentation.iconClass}`;
      fallbackIcon.setAttribute("aria-hidden", "true");
      iconSurface.append(fallbackIcon);
    }
    businessTypeIcon.append(iconSurface);
    media.append(mediaFrame, businessTypeIcon);

    const copy = document.createElement("span");
    copy.className = "business-type-showcase__category-copy";
    const name = document.createElement("strong");
    name.textContent = record.name;
    const meta = document.createElement("span");
    meta.textContent = `${numberText(record.categories.length)} ${record.categories.length === 1 ? "category" : "categories"}`;
    copy.append(name, meta);
    card.append(media, copy);
    return card;
  }

  function createPlatformShowcase(platform) {
    const presentation = getPlatformPresentation(platform);
    const showcase = document.createElement("article");
    showcase.className = "category-chip business-type-showcase platform-showcase";
    showcase.dataset.platformId = platform.id;

    const hero = document.createElement("div");
    hero.className = "business-type-showcase__hero";

    const content = document.createElement("div");
    content.className = "business-type-showcase__content";

    const identity = document.createElement("div");
    identity.className = "business-type-showcase__identity";

    const iconWrap = document.createElement("span");
    iconWrap.className = "business-type-showcase__icon-wrap";
    const icon = document.createElement("span");
    icon.className = "business-type-showcase__icon";
    const iconSurface = document.createElement("span");
    iconSurface.className = "business-type-showcase__icon-surface";
    const iconImageUrl = normalizeBusinessTypeImageUrl(platform.iconImageUrl)
      || builtInPlatformArtUrls[platform.id]
      || "";
    const lucideIconName = normalizeLucideCategoryIconName(platform.iconName);
    if (iconImageUrl) {
      iconWrap.classList.add("has-platform-art");
      icon.classList.add("has-platform-art");
      const iconImage = document.createElement("img");
      iconImage.src = iconImageUrl;
      iconImage.alt = `${platform.name} 3D art`;
      iconImage.loading = "lazy";
      iconImage.decoding = "async";
      iconSurface.append(iconImage);
    } else if (lucideIconName) {
      icon.classList.add("has-lucide-icon");
      iconSurface.innerHTML = createLucideCategoryIconSvg(lucideIconName);
    } else {
      const fallbackIcon = document.createElement("i");
      fallbackIcon.className = `fa-solid ${presentation.iconClass}`;
      fallbackIcon.setAttribute("aria-hidden", "true");
      iconSurface.append(fallbackIcon);
    }
    icon.append(iconSurface);
    iconWrap.append(icon);

    const heading = document.createElement("div");
    heading.className = "business-type-showcase__heading";
    const titleRow = document.createElement("div");
    titleRow.className = "business-type-showcase__title-row";
    const title = document.createElement("h3");
    title.className = "business-type-showcase__title";
    title.textContent = platform.name;
    const statusPill = document.createElement("span");
    statusPill.className = "business-type-card__status";
    statusPill.textContent = platform.status === "inactive"
      ? "Inactive"
      : (platform.comingSoon ? "Coming Soon" : "Active");
    statusPill.classList.toggle("is-inactive", platform.status === "inactive" || platform.comingSoon);
    const tagline = document.createElement("p");
    tagline.className = "business-type-showcase__tagline";
    tagline.textContent = presentation.tagline;
    titleRow.append(title, statusPill);
    heading.append(titleRow, tagline);
    identity.append(iconWrap, heading);

    const description = document.createElement("p");
    description.className = "business-type-showcase__description";
    description.textContent = presentation.description;

    const stats = document.createElement("div");
    stats.className = "business-type-showcase__stats";
    const createPlatformStat = (iconPaths, label, value) => {
      const stat = document.createElement("div");
      stat.className = "business-type-showcase__stat";
      const statIcon = document.createElement("span");
      statIcon.className = "business-type-showcase__stat-icon";
      statIcon.innerHTML = createIconSvg(iconPaths);
      const statCopy = document.createElement("span");
      statCopy.className = "business-type-showcase__stat-copy";
      const statValue = document.createElement("strong");
      statValue.textContent = value;
      const statLabel = document.createElement("span");
      statLabel.textContent = label;
      statCopy.append(statValue, statLabel);
      stat.append(statIcon, statCopy);
      return stat;
    };
    stats.append(
      createPlatformStat(
        '<rect width="7" height="7" x="3" y="3" rx="1"></rect><rect width="7" height="7" x="14" y="3" rx="1"></rect><rect width="7" height="7" x="14" y="14" rx="1"></rect><rect width="7" height="7" x="3" y="14" rx="1"></rect>',
        "Business Types",
        numberText(platform.businessTypeCount),
      ),
      createPlatformStat(
        '<path d="M12 2v10"></path><path d="M18.4 6.6a9 9 0 1 1-12.8 0"></path>',
        "Home Picker",
        platform.status === "inactive"
          ? "Unavailable"
          : (platform.comingSoon ? "Coming Soon" : "Available"),
      ),
      createPlatformStat(
        '<path d="M12 22c5.523 0 10-4.477 10-10S17.523 2 12 2 2 6.477 2 12s4.477 10 10 10z"></path><path d="m9 12 2 2 4-4"></path>',
        "Status",
        platform.status === "inactive" ? "Inactive" : "Active",
      ),
    );

    content.append(identity, description, stats);

    const media = document.createElement("div");
    media.className = "business-type-showcase__media platform-showcase__media";
    const heroImage = document.createElement("img");
    heroImage.className = "business-type-showcase__hero-image";
    heroImage.alt = `${platform.name} platform`;
    heroImage.loading = "lazy";
    heroImage.decoding = "async";
    const heroImageUrl = normalizeBusinessTypeImageUrl(platform.heroImageUrl);
    if (heroImageUrl) {
      heroImage.src = heroImageUrl;
      setBusinessTypeImageFallback(heroImage, "", media);
    } else {
      heroImage.hidden = true;
      media.classList.add("is-image-missing");
    }

    const mediaSurface = document.createElement("span");
    mediaSurface.className = "business-type-showcase__media-edit-surface";
    mediaSurface.append(heroImage);

    const mediaActions = document.createElement("div");
    mediaActions.className = "business-type-showcase__media-actions";
    const isInactive = platform.status === "inactive";
    mediaActions.append(
      createBusinessTypeActionDropdown(`Platform actions for ${platform.name}`, [
        {
          label: "Edit",
          icon: '<path d="M13 21h8"></path><path d="M21.174 6.812a1 1 0 0 0-3.986-3.987L3.842 16.174a2 2 0 0 0-.5.83l-1.321 4.352a.5.5 0 0 0 .623.622l4.353-1.32a2 2 0 0 0 .83-.497z"></path>',
          onSelect: () => openPlatformModal(platform),
        },
        {
          label: isInactive ? "Activate" : "Deactivate",
          tone: isInactive ? "" : "danger",
          icon: '<path d="M12 2v10"></path><path d="M18.4 6.6a9 9 0 1 1-12.8 0"></path>',
          onSelect: () => void handleSetPlatformStatus(platform, isInactive ? "active" : "inactive"),
        },
        {
          label: "Delete",
          tone: "danger",
          icon: '<path d="M10 11v6"></path><path d="M14 11v6"></path><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6"></path><path d="M3 6h18"></path><path d="M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path>',
          onSelect: () => void handleDeletePlatform(platform.id, platform.name),
        },
      ]),
    );
    media.append(mediaSurface, mediaActions);
    hero.append(content, media);

    const connectedBusinessTypes = getPlatformBusinessTypes(platform.id);
    const businessTypeSection = document.createElement("section");
    businessTypeSection.className = "business-type-showcase__categories platform-showcase__business-types";
    const businessTypeCarouselLimit = 8;
    const hasBusinessTypeCarousel = connectedBusinessTypes.length > businessTypeCarouselLimit;
    businessTypeSection.classList.toggle("has-carousel", hasBusinessTypeCarousel);
    businessTypeSection.setAttribute("aria-label", `${platform.name} business types`);
    const businessTypeHeader = document.createElement("div");
    businessTypeHeader.className = "business-type-showcase__categories-header";
    const businessTypeHeading = document.createElement("div");
    businessTypeHeading.className = "business-type-showcase__categories-copy";
    const businessTypeTitle = document.createElement("h4");
    businessTypeTitle.textContent = "Business Types";
    const businessTypeDescription = document.createElement("p");
    businessTypeDescription.textContent = `Business types assigned to ${platform.name}.`;
    businessTypeHeading.append(businessTypeTitle, businessTypeDescription);

    const businessTypeActions = document.createElement("div");
    businessTypeActions.className = "business-type-showcase__categories-actions";

    const businessTypeCarousel = document.createElement("div");
    businessTypeCarousel.className = "business-type-showcase__category-carousel";
    businessTypeCarousel.classList.toggle("is-carousel", hasBusinessTypeCarousel);

    const businessTypeGrid = document.createElement("div");
    businessTypeGrid.className = "business-type-showcase__category-grid platform-showcase__business-type-grid";
    businessTypeGrid.classList.toggle("is-carousel", hasBusinessTypeCarousel);
    businessTypeGrid.style.setProperty(
      "--business-type-category-count",
      String(businessTypeCarouselLimit),
    );
    businessTypeGrid.style.setProperty(
      "--business-type-category-column-width",
      `calc((100% - (var(--business-type-category-gap) * ${businessTypeCarouselLimit - 1})) / ${businessTypeCarouselLimit})`,
    );
    businessTypeGrid.setAttribute(
      "aria-label",
      hasBusinessTypeCarousel ? `Scrollable ${platform.name} business types` : `${platform.name} business types`,
    );

    if (hasBusinessTypeCarousel) {
      const carouselControls = document.createElement("span");
      carouselControls.className = "business-type-showcase__carousel-controls";

      const previousBusinessTypeButton = document.createElement("button");
      previousBusinessTypeButton.type = "button";
      previousBusinessTypeButton.className = "business-type-showcase__carousel-button";
      previousBusinessTypeButton.setAttribute("aria-label", `Previous ${platform.name} business types`);
      previousBusinessTypeButton.title = "Previous business types";
      previousBusinessTypeButton.innerHTML = createIconSvg('<path d="m15 18-6-6 6-6"></path>');
      previousBusinessTypeButton.addEventListener("click", (event) => {
        event.stopPropagation();
        scrollBusinessTypeCategoryCarousel(businessTypeGrid, -1);
      });

      const nextBusinessTypeButton = document.createElement("button");
      nextBusinessTypeButton.type = "button";
      nextBusinessTypeButton.className = "business-type-showcase__carousel-button";
      nextBusinessTypeButton.setAttribute("aria-label", `Next ${platform.name} business types`);
      nextBusinessTypeButton.title = "Next business types";
      nextBusinessTypeButton.innerHTML = createIconSvg('<path d="m9 18 6-6-6-6"></path>');
      nextBusinessTypeButton.addEventListener("click", (event) => {
        event.stopPropagation();
        scrollBusinessTypeCategoryCarousel(businessTypeGrid, 1);
      });

      carouselControls.append(previousBusinessTypeButton, nextBusinessTypeButton);
      businessTypeActions.append(carouselControls);
    }
    businessTypeHeader.append(businessTypeHeading);
    if (businessTypeActions.childElementCount) {
      businessTypeHeader.append(businessTypeActions);
    }

    if (connectedBusinessTypes.length) {
      connectedBusinessTypes.forEach((record, index) => {
        businessTypeGrid.append(createPlatformBusinessTypeCard(record, index));
      });
    } else {
      const empty = document.createElement("div");
      empty.className = "business-type-showcase__empty platform-showcase__business-type-empty";
      empty.innerHTML = `${createIconSvg('<rect width="7" height="7" x="3" y="3" rx="1"></rect><rect width="7" height="7" x="14" y="3" rx="1"></rect><rect width="7" height="7" x="14" y="14" rx="1"></rect><rect width="7" height="7" x="3" y="14" rx="1"></rect>')}<span>No business types assigned yet.</span>`;
      businessTypeGrid.append(empty);
    }
    businessTypeCarousel.append(businessTypeGrid);
    businessTypeSection.append(businessTypeHeader, businessTypeCarousel);
    showcase.append(hero, businessTypeSection);
    return showcase;
  }

  function renderPlatforms() {
    if (!(elements.platformList instanceof HTMLElement)) {
      return;
    }
    elements.platformList.replaceChildren();
    if (!state.platformDetails.length) {
      const empty = document.createElement("div");
      empty.className = "empty-state";
      empty.textContent = "No buyer platforms yet.";
      elements.platformList.append(empty);
      return;
    }

    for (const platform of state.platformDetails) {
      elements.platformList.append(createPlatformShowcase(platform));
    }
  }

  function normalizeHexColorValue(value, fallback = "#2563eb") {
    const normalized = String(value || "").trim().toLowerCase();
    return /^#[0-9a-f]{6}$/.test(normalized) ? normalized : fallback;
  }

  function syncPlatformModalPrimaryColor(color) {
    const normalized = normalizeHexColorValue(color, state.platformDraftPrimaryColor || "#2563eb");
    state.platformDraftPrimaryColor = normalized;
    if (elements.platformPrimaryColorInput instanceof HTMLInputElement) {
      elements.platformPrimaryColorInput.value = normalized;
    }
    if (elements.platformPrimaryColorHex) {
      elements.platformPrimaryColorHex.textContent = normalized.toUpperCase();
    }
    if (elements.platformModalColorSwatches instanceof HTMLElement) {
      elements.platformModalColorSwatches.querySelectorAll("[data-platform-palette-swatch]").forEach((button) => {
        const isSelected = String(button.dataset.platformPaletteSwatch || "").toLowerCase() === normalized;
        button.classList.toggle("is-selected", isSelected);
        button.setAttribute("aria-pressed", String(isSelected));
      });
    }
  }

  function renderPlatformModalColorSwatches() {
    if (!(elements.platformModalColorSwatches instanceof HTMLElement)) {
      return;
    }
    elements.platformModalColorSwatches.replaceChildren();
    const selected = normalizeHexColorValue(state.platformDraftPrimaryColor);
    for (const color of platformPaletteColors) {
      const button = document.createElement("button");
      button.type = "button";
      button.className = "super-admin-platform-palette__swatch" + (color === selected ? " is-selected" : "");
      button.style.backgroundColor = color;
      button.dataset.platformPaletteSwatch = color;
      button.setAttribute("aria-label", `Select ${color}`);
      button.setAttribute("aria-pressed", String(color === selected));
      button.title = color;
      button.addEventListener("click", () => {
        syncPlatformModalPrimaryColor(color);
      });
      elements.platformModalColorSwatches.append(button);
    }
  }

  function createPlatformPaletteSwatchButton(color, selectedColor, onSelect) {
    const button = document.createElement("button");
    button.type = "button";
    const normalized = color.toLowerCase();
    button.className = "super-admin-platform-palette__swatch"
      + (normalized === selectedColor ? " is-selected" : "");
    button.style.backgroundColor = color;
    button.dataset.platformPaletteSwatch = color;
    button.setAttribute("aria-label", `Select ${color}`);
    button.setAttribute("aria-pressed", String(normalized === selectedColor));
    button.title = color;
    button.addEventListener("click", () => {
      onSelect(color);
    });
    return button;
  }

  function renderPlatformColorPalettes() {
    const root = elements.platformColorPalettes;
    if (!(root instanceof HTMLElement)) {
      return;
    }
    root.replaceChildren();
    if (!state.platformDetails.length) {
      const empty = document.createElement("p");
      empty.className = "super-admin-platform-palettes__empty";
      empty.textContent = "No platforms yet. Add a platform and it will show up here.";
      root.append(empty);
      syncPlatformSettingsSearch();
      return;
    }

    for (const platform of state.platformDetails) {
      const row = document.createElement("div");
      row.className = "super-admin-platform-palette-row";
      row.dataset.platformPaletteId = platform.id;

      const meta = document.createElement("div");
      meta.className = "super-admin-platform-palette-row__meta";
      const preview = document.createElement("span");
      preview.className = "super-admin-platform-palette-row__preview";
      preview.style.backgroundColor = platform.primaryColor;
      preview.setAttribute("aria-hidden", "true");
      const labels = document.createElement("div");
      labels.className = "super-admin-platform-palette-row__labels";
      const title = document.createElement("strong");
      title.textContent = platform.name;
      const subtitle = document.createElement("small");
      subtitle.textContent = platform.primaryColor.toUpperCase();
      labels.append(title, subtitle);
      meta.append(preview, labels);

      const swatches = document.createElement("div");
      swatches.className = "super-admin-platform-palette-row__swatches";
      swatches.setAttribute("role", "group");
      swatches.setAttribute("aria-label", `${platform.name} color palette`);
      const selected = normalizeHexColorValue(platform.primaryColor);
      for (const color of platformPaletteColors) {
        swatches.append(
          createPlatformPaletteSwatchButton(color, selected, (nextColor) => {
            void savePlatformPrimaryColor(platform.id, nextColor);
          }),
        );
      }

      const custom = document.createElement("label");
      custom.className = "super-admin-platform-palette-row__custom";
      const customInput = document.createElement("input");
      customInput.type = "color";
      customInput.value = selected;
      customInput.setAttribute("aria-label", `${platform.name} custom color`);
      customInput.addEventListener("change", () => {
        void savePlatformPrimaryColor(platform.id, customInput.value);
      });
      custom.append(customInput);

      row.append(meta, swatches, custom);
      root.append(row);
    }
    syncPlatformSettingsSearch();
  }

  async function savePlatformPrimaryColor(platformId, color) {
    const existing = getPlatformRecordById(platformId);
    if (!existing) {
      setFeedback("Platform not found.", "error");
      return;
    }
    const normalizedColor = normalizeHexColorValue(color, existing.primaryColor);
    if (normalizedColor === normalizeHexColorValue(existing.primaryColor)) {
      return;
    }
    if (!await requireSuperAdminFingerprint(`change the ${existing.name} color palette`)) {
      renderPlatformColorPalettes();
      return;
    }

    try {
      setFeedback(`Updating ${existing.name} color palette...`);
      const response = await fetch("/api/super-admin/platforms", {
        method: "PUT",
        headers: rootHeaders({
          "Content-Type": "application/json",
          Accept: "application/json",
        }),
        body: JSON.stringify({
          oldId: existing.id,
          id: existing.id,
          name: existing.name,
          status: existing.status,
          sortOrder: existing.sortOrder,
          comingSoon: existing.comingSoon,
          heroImageUrl: existing.heroImageUrl,
          iconImageUrl: existing.iconImageUrl,
          iconName: existing.iconName,
          primaryColor: normalizedColor,
          secondaryColor: existing.secondaryColor || "",
        }),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(data.message || "Unable to save platform color.");
      }
      setPlatformData(Array.isArray(data.platformDetails) ? data.platformDetails : state.platformDetails);
      void showSuccessValidationModal(
        "Platform Color Updated",
        `${existing.name} palette changed to ${normalizedColor.toUpperCase()}.`,
      );
    } catch (error) {
      setFeedback(error instanceof Error ? error.message : "Unable to save platform color.", "error");
      renderPlatformColorPalettes();
    }
  }

  async function loadPlatforms({ quiet = false } = {}) {
    state.platformsLoading = true;
    if (!quiet) {
      setFeedback("Loading platforms...");
    }
    try {
      const response = await fetch("/api/super-admin/platforms", {
        cache: "no-store",
        headers: rootHeaders({ Accept: "application/json" }),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(data.message || "Unable to load platforms.");
      }
      setPlatformData(Array.isArray(data.platformDetails) ? data.platformDetails : []);
      if (!quiet) {
        setFeedback(
          `${numberText(state.platformDetails.length)} ${state.platformDetails.length === 1 ? "platform" : "platforms"} loaded.`,
          "notice",
        );
      }
    } catch (error) {
      if (!quiet) {
        setFeedback(error instanceof Error ? error.message : "Unable to load platforms.", "error");
      }
    } finally {
      state.platformsLoading = false;
    }
  }

  function getEffectivePlatformIconName() {
    return normalizeLucideCategoryIconName(state.platformDraftIconName)
      || getAutoLucideCategoryIconName(elements.platformNameInput?.value)
      || "layout-grid";
  }

  function syncPlatformAssetFileNames() {
    if (elements.platformImageFileName) {
      elements.platformImageFileName.textContent = state.platformDraftImageFile?.name
        || getBusinessTypeAssetFileName(state.platformDraftImageUrl, "No image selected");
    }
    if (elements.platformIconFileName) {
      const manualIconName = normalizeLucideCategoryIconName(state.platformDraftIconName);
      elements.platformIconFileName.textContent = state.platformDraftIconFile?.name
        || getBusinessTypeAssetFileName(
          state.platformDraftIconUrl,
          manualIconName ? `Art: ${formatLucideCategoryIconLabel(manualIconName)}` : "No 3D art selected",
        );
    }
  }

  function syncPlatformCreateRequiredMarks() {
    const isCreate = !state.editingPlatformId;
    document.querySelectorAll("[data-platform-create-required-mark]").forEach((mark) => {
      if (mark instanceof HTMLElement) {
        mark.hidden = !isCreate;
      }
    });
  }

  function syncPlatformModalToggles() {
    const isActive = elements.platformStatusSelect?.value !== "inactive";
    elements.platformStatusToggle?.classList.toggle("is-active", isActive);
    elements.platformStatusToggle?.setAttribute("aria-pressed", String(isActive));
    if (elements.platformStatusToggleLabel) {
      elements.platformStatusToggleLabel.textContent = isActive ? "Active" : "Inactive";
    }
    const platformRecord = getPlatformRecordById(state.editingPlatformId);
    const connectedBusinessTypeCount = state.editingPlatformId
      ? Math.max(
          Number(platformRecord?.businessTypeCount) || 0,
          getPlatformBusinessTypes(state.editingPlatformId).length,
        )
      : 0;
    const requiresComingSoon = connectedBusinessTypeCount === 0;
    if (requiresComingSoon && elements.platformComingSoonInput instanceof HTMLInputElement) {
      elements.platformComingSoonInput.checked = true;
    }
    const isAvailable = !Boolean(elements.platformComingSoonInput?.checked);
    elements.platformComingSoonToggle?.classList.toggle("is-active", isAvailable);
    elements.platformComingSoonToggle?.setAttribute("aria-pressed", String(isAvailable));
    if (elements.platformComingSoonToggle instanceof HTMLButtonElement) {
      elements.platformComingSoonToggle.disabled = requiresComingSoon;
      elements.platformComingSoonToggle.title = requiresComingSoon
        ? "Add a Business Type first to control Coming Soon."
        : "";
    }
    if (elements.platformComingSoonToggleLabel) {
      elements.platformComingSoonToggleLabel.textContent = isAvailable ? "Available" : "Coming Soon";
    }
    if (elements.platformComingSoonHelper instanceof HTMLElement) {
      elements.platformComingSoonHelper.hidden = !requiresComingSoon;
    }
  }

  function isSupportedPlatformAssetFile(file, type = "image") {
    if (!(file instanceof File)) {
      return false;
    }
    const fileType = String(file.type || "").toLowerCase();
    const fileName = String(file.name || "").toLowerCase();
    if (type === "icon") {
      return ["image/jpeg", "image/jpg", "image/png", "image/webp", "image/svg+xml", "image/gif"].includes(fileType)
        || /\.(jpe?g|png|webp|svg|gif)$/.test(fileName);
    }
    return ["image/jpeg", "image/jpg", "image/png", "image/webp"].includes(fileType)
      || /\.(jpe?g|png|webp)$/.test(fileName);
  }

  async function setPlatformAssetFile(type, file) {
    const isIcon = type === "icon";
    const input = isIcon ? elements.platformIconInput : elements.platformImageInput;
    const maxBytes = 4 * 1024 * 1024;
    if (!(file instanceof File)) {
      if (isIcon) state.platformDraftIconFile = null;
      else state.platformDraftImageFile = null;
      syncPlatformAssetFileNames();
      return;
    }
    if (!isSupportedPlatformAssetFile(file, type)) {
      setFeedback(isIcon
        ? "Choose a JPG, PNG, WEBP, SVG, or GIF platform 3D art file."
        : "Choose a JPG, PNG, or WEBP platform image.", "error");
      if (input) input.value = "";
      return;
    }
    if (file.size > maxBytes) {
      setFeedback(isIcon ? "Platform 3D art must be 4MB or smaller." : "Platform image must be 4MB or smaller.", "error");
      if (input) input.value = "";
      return;
    }
    if (isIcon) {
      state.platformDraftIconFile = file;
      state.platformDraftIconName = "";
      state.platformDraftIconUrl = "";
    } else {
      state.platformDraftImageFile = file;
      state.platformDraftImageUrl = "";
    }
    syncPlatformAssetFileNames();
    setFeedback("");
  }

  async function uploadPlatformDraftAssets(platformDraft) {
    const nextDraft = { ...platformDraft };
    const pendingUploads = [];
    if (state.platformDraftImageFile instanceof File) {
      pendingUploads.push({ key: "heroImageUrl", label: "Uploading platform image...", file: state.platformDraftImageFile });
    }
    if (state.platformDraftIconFile instanceof File) {
      pendingUploads.push({ key: "iconImageUrl", label: "Uploading platform 3D art...", file: state.platformDraftIconFile });
    }
    if (pendingUploads.length) {
      const uploadedEntries = await mapWithConcurrency(
        pendingUploads,
        imageUploadConcurrency,
        async (entry) => {
          setFeedback(entry.label);
          return {
            key: entry.key,
            url: await uploadSuperAdminProductImageFile(entry.file, { preserveFormat: true }),
          };
        },
      );
      for (const entry of uploadedEntries) {
        nextDraft[entry.key] = entry.url;
      }
    }
    return nextDraft;
  }

  function setPlatformModalOpen(isOpen, { restoreFocus = true } = {}) {
    const overlay = elements.platformModalOverlay;
    if (!(overlay instanceof HTMLElement)) {
      return;
    }
    if (platformModalCloseTimer) {
      window.clearTimeout(platformModalCloseTimer);
      platformModalCloseTimer = 0;
    }
    if (platformModalFocusTimer) {
      window.clearTimeout(platformModalFocusTimer);
      platformModalFocusTimer = 0;
    }
    if (isOpen) {
      platformModalScrollSnapshot = getSuperAdminScrollSnapshot();
      overlay.hidden = false;
      overlay.setAttribute("aria-hidden", "false");
      elements.openPlatformModalButton?.setAttribute("aria-expanded", "true");
      window.requestAnimationFrame(() => overlay.classList.add("is-open"));
      platformModalFocusTimer = window.setTimeout(() => {
        platformModalFocusTimer = 0;
        if (elements.platformNameInput instanceof HTMLInputElement) {
          focusWithoutScroll(elements.platformNameInput);
          elements.platformNameInput.select();
        } else {
          focusWithoutScroll(elements.platformModal);
        }
        restoreSuperAdminScrollSnapshot(platformModalScrollSnapshot);
      }, 90);
      return;
    }
    overlay.classList.remove("is-open");
    overlay.setAttribute("aria-hidden", "true");
    elements.openPlatformModalButton?.setAttribute("aria-expanded", "false");
    restoreSuperAdminScrollSnapshot(platformModalScrollSnapshot);
    platformModalCloseTimer = window.setTimeout(() => {
      platformModalCloseTimer = 0;
      overlay.hidden = true;
      if (restoreFocus) focusWithoutScroll(elements.openPlatformModalButton);
      restoreSuperAdminScrollSnapshotStable(platformModalScrollSnapshot);
      platformModalScrollSnapshot = null;
    }, 180);
  }

  function openPlatformModal(record = null) {
    const platform = normalizePlatformRecord(record) || {
      id: "",
      name: "",
      status: "active",
      sortOrder: (state.platformDetails.at(-1)?.sortOrder || 0) + 1,
      comingSoon: true,
      heroImageUrl: "",
      iconImageUrl: "",
      iconName: "",
      primaryColor: "#2563eb",
      secondaryColor: "",
    };
    state.editingPlatformId = platform.id || "";
    if (elements.platformModalTitle) {
      elements.platformModalTitle.textContent = state.editingPlatformId
        ? "Edit Platform Details"
        : "Add Platform Details";
    }
    if (elements.platformModalSubtitle) {
      elements.platformModalSubtitle.textContent = state.editingPlatformId
        ? `Update the details for ${platform.name}.`
        : "Add a new buyer platform by providing the details below.";
    }
    if (elements.platformNameInput) elements.platformNameInput.value = platform.name;
    if (elements.platformStatusSelect) {
      elements.platformStatusSelect.value = platform.status === "inactive" ? "inactive" : "active";
    }
    if (elements.platformComingSoonInput) {
      elements.platformComingSoonInput.checked = Boolean(platform.comingSoon);
    }
    state.platformDraftImageUrl = platform.heroImageUrl || "";
    state.platformDraftIconUrl = platform.iconImageUrl || "";
    state.platformDraftIconName = normalizeLucideCategoryIconName(platform.iconName);
    state.platformDraftPrimaryColor = normalizeHexColorValue(platform.primaryColor);
    state.platformDraftImageFile = null;
    state.platformDraftIconFile = null;
    if (elements.platformImageInput) elements.platformImageInput.value = "";
    if (elements.platformIconInput) elements.platformIconInput.value = "";
    if (elements.savePlatformButton) {
      elements.savePlatformButton.textContent = state.editingPlatformId ? "Save Platform" : "Add Platform";
    }
    syncPlatformAssetFileNames();
    syncPlatformModalToggles();
    syncPlatformCreateRequiredMarks();
    renderPlatformModalColorSwatches();
    syncPlatformModalPrimaryColor(state.platformDraftPrimaryColor);
    setPlatformModalOpen(true);
  }

  function resetPlatformEditor() {
    state.editingPlatformId = "";
    if (elements.platformNameInput) elements.platformNameInput.value = "";
    if (elements.platformStatusSelect) elements.platformStatusSelect.value = "active";
    if (elements.platformComingSoonInput) elements.platformComingSoonInput.checked = true;
    state.platformDraftImageUrl = "";
    state.platformDraftIconUrl = "";
    state.platformDraftIconName = "";
    state.platformDraftPrimaryColor = "#2563eb";
    state.platformDraftImageFile = null;
    state.platformDraftIconFile = null;
    if (elements.platformImageInput) elements.platformImageInput.value = "";
    if (elements.platformIconInput) elements.platformIconInput.value = "";
    syncPlatformAssetFileNames();
    syncPlatformModalToggles();
    renderPlatformModalColorSwatches();
    syncPlatformModalPrimaryColor("#2563eb");
  }

  async function handleSavePlatform() {
    const name = String(elements.platformNameInput?.value || "").replace(/\s+/g, " ").trim();
    if (name.length < 2) {
      setFeedback("Enter a platform name first.", "error");
      elements.platformNameInput?.focus();
      return;
    }
    const isCreate = !state.editingPlatformId;
    const hasPhoto = state.platformDraftImageFile instanceof File
      || Boolean(normalizeBusinessTypeImageUrl(state.platformDraftImageUrl));
    const hasArt = state.platformDraftIconFile instanceof File
      || Boolean(normalizeBusinessTypeImageUrl(state.platformDraftIconUrl));
    if (isCreate && !hasPhoto) {
      setFeedback("Choose a platform image before creating.", "error");
      elements.platformImageInput?.closest("label")?.scrollIntoView?.({ block: "nearest", behavior: "smooth" });
      return;
    }
    if (isCreate && !hasArt) {
      setFeedback("Choose platform 3D art before creating.", "error");
      elements.platformIconInput?.closest("label")?.scrollIntoView?.({ block: "nearest", behavior: "smooth" });
      return;
    }
    const existing = state.editingPlatformId
      ? getPlatformRecordById(state.editingPlatformId)
      : null;
    const id = state.editingPlatformId || slugifyPlatformIdValue(name);
    const nextSortOrder = existing
      ? existing.sortOrder
      : ((state.platformDetails.at(-1)?.sortOrder || 0) + 1);
    const platformArtUrl = normalizeBusinessTypeImageUrl(state.platformDraftIconUrl);
    let payload = {
      name,
      id,
      status: elements.platformStatusSelect?.value === "inactive" ? "inactive" : "active",
      sortOrder: Number.isFinite(Number(nextSortOrder)) ? Math.trunc(Number(nextSortOrder)) : undefined,
      comingSoon: Boolean(elements.platformComingSoonInput?.checked),
      heroImageUrl: normalizeBusinessTypeImageUrl(state.platformDraftImageUrl),
      iconImageUrl: platformArtUrl,
      iconName: platformArtUrl
        ? ""
        : (normalizeLucideCategoryIconName(state.platformDraftIconName) || ""),
      primaryColor: normalizeHexColorValue(
        state.platformDraftPrimaryColor || existing?.primaryColor,
      ),
      secondaryColor: existing?.secondaryColor || "",
    };

    if (!await requireSuperAdminFingerprint(isCreate ? "add this platform" : "update this platform")) {
      return;
    }

    try {
      if (elements.savePlatformButton) elements.savePlatformButton.disabled = true;
      setFeedback(isCreate ? "Adding platform..." : "Updating platform...");
      payload = await uploadPlatformDraftAssets(payload);
      if (isCreate) {
        if (!normalizeBusinessTypeImageUrl(payload.heroImageUrl)) {
          throw new Error("Platform image is required.");
        }
        if (!normalizeBusinessTypeImageUrl(payload.iconImageUrl)) {
          throw new Error("Platform 3D art is required.");
        }
      }
      const response = await fetch("/api/super-admin/platforms", {
        method: isCreate ? "POST" : "PUT",
        headers: rootHeaders({
          "Content-Type": "application/json",
          Accept: "application/json",
        }),
        body: JSON.stringify(
          isCreate
            ? payload
            : { oldId: state.editingPlatformId, ...payload },
        ),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(data.message || "Unable to save platform.");
      }
      setPlatformData(Array.isArray(data.platformDetails) ? data.platformDetails : state.platformDetails);
      resetPlatformEditor();
      setPlatformModalOpen(false, { restoreFocus: false });
      void showSuccessValidationModal(
        isCreate ? "Platform Added" : "Platform Updated",
        data.message || (isCreate ? "Platform added." : "Platform updated."),
      );
    } catch (error) {
      setFeedback(error instanceof Error ? error.message : "Unable to save platform.", "error");
    } finally {
      if (elements.savePlatformButton) elements.savePlatformButton.disabled = false;
    }
  }

  async function handleSetPlatformStatus(platform, nextStatus) {
    const record = normalizePlatformRecord(platform);
    if (!record) return;
    const status = nextStatus === "inactive" ? "inactive" : "active";
    if (!await requireSuperAdminFingerprint(`${status === "active" ? "activate" : "deactivate"} this platform`)) {
      return;
    }
    try {
      setFeedback(status === "active" ? "Activating platform..." : "Deactivating platform...");
      const response = await fetch("/api/super-admin/platforms", {
        method: "PUT",
        headers: rootHeaders({ "Content-Type": "application/json", Accept: "application/json" }),
        body: JSON.stringify({ oldId: record.id, status }),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(data.message || "Unable to update platform status.");
      }
      setPlatformData(Array.isArray(data.platformDetails) ? data.platformDetails : state.platformDetails);
      void showSuccessValidationModal(
        status === "active" ? "Platform Activated" : "Platform Deactivated",
        data.message || `Platform ${status === "active" ? "activated" : "deactivated"}.`,
      );
    } catch (error) {
      setFeedback(error instanceof Error ? error.message : "Unable to update platform status.", "error");
    }
  }

  async function handleDeletePlatform(platformId, platformName) {
    const id = normalizePlatformIdValue(platformId);
    if (!id) {
      return;
    }
    if (!window.confirm(`Delete platform "${platformName || id}"? Business types must be reassigned first.`)) {
      return;
    }
    if (!await requireSuperAdminFingerprint("delete this platform")) {
      return;
    }
    try {
      setFeedback("Deleting platform...");
      const response = await fetch(
        `/api/super-admin/platforms?id=${encodeURIComponent(id)}`,
        {
          method: "DELETE",
          headers: rootHeaders({ Accept: "application/json" }),
        },
      );
      const data = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(data.message || "Unable to delete platform.");
      }
      setPlatformData(Array.isArray(data.platformDetails) ? data.platformDetails : []);
      void showSuccessValidationModal("Platform Deleted", data.message || "Platform deleted.");
    } catch (error) {
      setFeedback(error instanceof Error ? error.message : "Unable to delete platform.", "error");
    }
  }

  function normalizeStoreTypeRecord(value) {
    const name = normalizeCategoryName(
      value && typeof value === "object"
        ? value.name ?? value.storeType ?? value.type ?? value.label ?? value.title
        : value,
    );

    if (!name) {
      return null;
    }

    const source = value && typeof value === "object" ? value : {};
    return {
      name,
      platformId: normalizePlatformIdValue(
        source.platformId ?? source.platform ?? source.buyerPlatform,
      ) || inferPlatformIdFromName(name),
      categories: normalizeCategoryValues(source.categories ?? source.category),
      status: normalizeStoreTypeStatus(source.status ?? source.businessTypeStatus),
      commissionRate: normalizeStoreTypeNumber(source.commissionRate ?? source.commission),
      serviceFee: normalizeStoreTypeNumber(source.serviceFee ?? source.serviceFeeAmount),
      companiesUsing: Math.trunc(normalizeStoreTypeNumber(source.companiesUsing)),
      productCount: Math.trunc(normalizeStoreTypeNumber(source.productCount)),
      heroImageUrl: normalizeBusinessTypeImageUrl(
        source.heroImageUrl ?? source.imageUrl ?? source.coverImageUrl,
      ),
      iconImageUrl: normalizeBusinessTypeImageUrl(
        source.iconImageUrl ?? source.iconUrl ?? source.businessTypeIconUrl,
      ),
      iconName: normalizeLucideCategoryIconName(source.iconName ?? source.lucideIconName),
      categoryStats: normalizeStoreTypeCategoryStats(
        source.categoryStats ?? source.categoryDetails ?? source.categoryCounts,
      ),
    };
  }

  // Normalizes store type records before comparison or storage.
  function normalizeStoreTypeRecords(values) {
    const seen = new Map();
    for (const value of Array.isArray(values) ? values : []) {
      const record = normalizeStoreTypeRecord(value);
      if (!record) {
        continue;
      }
      const key = record.name.toLowerCase();
      if (!seen.has(key)) {
        seen.set(key, record);
      }
    }

    return [...seen.values()].sort((left, right) =>
      left.name.localeCompare(right.name, undefined, { sensitivity: "base" }),
    );
  }

  // Reads or derives store type record by name for the current super admin flow.
  function getStoreTypeRecordByName(storeTypeName) {
    const key = normalizeCategoryName(storeTypeName).toLowerCase();
    return state.storeTypeDetails.find((storeType) => storeType.name.toLowerCase() === key) || null;
  }

  // Formats store type percent for display.
  function formatStoreTypePercent(value) {
    return `${normalizeStoreTypeNumber(value).toFixed(2).replace(/\.00$/, "")}%`;
  }

  // Formats store type money for display.
  function formatStoreTypeMoney(value) {
    return `PHP ${normalizeStoreTypeNumber(value).toLocaleString(undefined, {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    })}`;
  }

  // Checks whether same category name is true for the current record or UI state.
  function isSameCategoryName(left, right) {
    return normalizeCategoryName(left).toLowerCase() === normalizeCategoryName(right).toLowerCase();
  }

  // Checks whether same store type name is true for the current record or UI state.
  function isSameStoreTypeName(left, right) {
    return normalizeCategoryName(left).toLowerCase() === normalizeCategoryName(right).toLowerCase();
  }

  // Keeps category input casing synchronized with current state.
  function syncCategoryInputCasing(inputElement = elements.categoryNameInput) {
    if (!(inputElement instanceof HTMLInputElement)) {
      return;
    }

    const nextValue = normalizeCategoryName(inputElement.value, {
      preserveTrailingSpace: document.activeElement === inputElement,
    });
    if (inputElement.value !== nextValue) {
      inputElement.value = nextValue;
    }
  }

  // Keeps store type input casing synchronized with current state.
  function syncStoreTypeInputCasing(inputElement = elements.storeTypeNameInput) {
    if (!(inputElement instanceof HTMLInputElement)) {
      return;
    }

    const nextValue = normalizeCategoryName(inputElement.value, {
      preserveTrailingSpace: document.activeElement === inputElement,
    });
    if (inputElement.value !== nextValue) {
      inputElement.value = nextValue;
    }
  }

  // Updates store type modal tab and synchronizes related UI state.
  function setStoreTypeModalTab(tabName = "basic") {
    const normalizedTabName = String(tabName || "basic").trim();
    state.activeStoreTypeModalTab = normalizedTabName;

    for (const tabButton of elements.storeTypeModalTabs) {
      const isActive = tabButton.dataset.storeTypeModalTab === normalizedTabName;
      tabButton.classList.toggle("is-active", isActive);
      tabButton.setAttribute("aria-pressed", isActive ? "true" : "false");
    }

    for (const section of elements.storeTypeModalSections) {
      const isActive = section.dataset.storeTypeModalSection === normalizedTabName;
      section.hidden = !isActive;
      section.classList.toggle("is-active", isActive);
    }
  }

  // Renders store type draft categories from the latest state.
  function renderStoreTypeDraftCategories() {
    if (!elements.storeTypeCategoryChipList) {
      return;
    }

    if (elements.storeTypeCategoryCount) {
      elements.storeTypeCategoryCount.textContent = numberText(state.storeTypeDraftCategories.length);
    }
    elements.storeTypeCategoryChipList.innerHTML = "";
    if (!state.storeTypeDraftCategories.length) {
      const emptyState = document.createElement("div");
      emptyState.className = "empty-state super-admin-store-type-category-empty";
      emptyState.innerHTML = `${createLucideCategoryIconSvg("grid-2x2")}<span>No categories yet.</span>`;
      elements.storeTypeCategoryChipList.append(emptyState);
    } else {
      for (const categoryName of state.storeTypeDraftCategories) {
        const detail = state.storeTypeDraftCategoryDetails.find(
          (item) => isSameCategoryName(item.name, categoryName),
        ) || {};
        const chip = document.createElement("div");
        chip.className = "super-admin-store-type-category-chip super-admin-store-type-category-chip--visual";

        const visual = document.createElement("span");
        visual.className = "super-admin-store-type-category-chip__visual";
        if (detail.imageUrl) {
          const image = document.createElement("img");
          image.src = detail.imageUrl;
          image.alt = "";
          image.loading = "lazy";
          image.decoding = "async";
          visual.append(image);
        } else {
          visual.innerHTML = createIconSvg(
            '<rect width="18" height="18" x="3" y="3" rx="2" ry="2"></rect><circle cx="9" cy="9" r="2"></circle><path d="m21 15-3.086-3.086a2 2 0 0 0-2.828 0L6 21"></path>',
          );
        }

        const icon = document.createElement("span");
        icon.className = "super-admin-store-type-category-chip__icon";
        if (detail.iconImageUrl) {
          const iconImage = document.createElement("img");
          iconImage.src = detail.iconImageUrl;
          iconImage.alt = "";
          iconImage.loading = "lazy";
          iconImage.decoding = "async";
          icon.append(iconImage);
        } else {
          const selectedIconName = normalizeLucideCategoryIconName(detail.iconName)
            || getAutoLucideCategoryIconName(categoryName)
            || "tag";
          if (selectedIconName) {
            icon.classList.add("has-lucide-icon");
            icon.innerHTML = createLucideCategoryIconSvg(selectedIconName);
          } else {
            icon.classList.add("has-lucide-icon");
            icon.innerHTML = createLucideCategoryIconSvg("tag");
          }
        }

        const label = document.createElement("span");
        label.className = "super-admin-store-type-category-chip__label";
        label.textContent = categoryName;

        const editButton = document.createElement("button");
        editButton.type = "button";
        editButton.setAttribute("aria-label", `Edit ${categoryName}`);
        editButton.title = `Edit ${categoryName}`;
        editButton.innerHTML = createIconSvg('<path d="m4 20 4.2-1 9-9a2.1 2.1 0 0 0-3-3l-9 9L4 20Z"></path>');
        editButton.addEventListener("click", () => editStoreTypeDraftCategory(categoryName));

        const removeButton = document.createElement("button");
        removeButton.type = "button";
        removeButton.setAttribute("aria-label", `Remove ${categoryName}`);
        removeButton.innerHTML = createIconSvg(
          '<path d="M7 7 17 17" stroke-linecap="round"></path><path d="M17 7 7 17" stroke-linecap="round"></path>',
        );
        removeButton.addEventListener("click", () => {
          state.storeTypeDraftCategories = state.storeTypeDraftCategories.filter(
            (category) => !isSameCategoryName(category, categoryName),
          );
          state.storeTypeDraftCategoryDetails = state.storeTypeDraftCategoryDetails.filter(
            (item) => !isSameCategoryName(item.name, categoryName),
          );
          renderStoreTypeDraftCategories();
          syncStoreTypeModalSummary();
          if (isStoreTypeCategoryModalVisible() && normalizeCategoryName(state.categoryModalStoreTypeName)) {
            void handleSaveStoreTypeCategories({
              closeModal: false,
              includePendingCategory: false,
              successTitle: "Category Removed",
            });
          }
        });

        chip.append(visual, icon, label, editButton, removeButton);
        elements.storeTypeCategoryChipList.append(chip);
      }
    }

  }

  function getIconPickerInitialVisibleCount(iconOptions) {
    const iconCount = Array.isArray(iconOptions) ? iconOptions.length : 0;
    return Math.ceil(iconCount * 0.25);
  }

  function getIconPickerVisibleCount(iconOptions, visibleCount) {
    const normalizedVisibleCount = Math.trunc(Number(visibleCount) || 0);
    return normalizedVisibleCount > 0
      ? normalizedVisibleCount
      : getIconPickerInitialVisibleCount(iconOptions);
  }

  function getIconPickerNextVisibleCount(iconOptions, visibleCount) {
    const iconCount = Array.isArray(iconOptions) ? iconOptions.length : 0;
    const currentVisibleCount = Math.max(0, Math.trunc(Number(visibleCount) || 0));
    const nextBatchCount = getIconPickerInitialVisibleCount(iconOptions);
    return Math.min(iconCount, currentVisibleCount + nextBatchCount);
  }

  function getIconPickerVisibleOptions(iconOptions, visibleCount, selectedIconName) {
    const visibleIconOptions = iconOptions.slice(0, visibleCount);
    const normalizedSelectedIconName = normalizeLucideCategoryIconName(selectedIconName);
    if (
      normalizedSelectedIconName &&
      !visibleIconOptions.some((option) => option.iconName === normalizedSelectedIconName)
    ) {
      const selectedOption = iconOptions.find((option) => option.iconName === normalizedSelectedIconName);
      if (selectedOption) {
        visibleIconOptions.unshift(selectedOption);
      }
    }
    return visibleIconOptions;
  }

  function getFilteredIconPickerOptions(searchTerm = "") {
    const normalizedSearchTerm = normalizeLucideCategoryIconKey(searchTerm);
    return getLucideCategoryIconOptions().filter((option) =>
      !normalizedSearchTerm
      || option.iconName.includes(normalizedSearchTerm)
      || normalizeLucideCategoryIconKey(option.label).includes(normalizedSearchTerm)
    );
  }

  function getPanelIconPickerVisibleCount(panel, iconOptions, searchTerm) {
    const normalizedSearchTerm = normalizeLucideCategoryIconKey(searchTerm);
    const previousSearchTerm = panel.dataset.businessTypeIconPickerSearchTerm || "";
    const storedVisibleCount = previousSearchTerm === normalizedSearchTerm
      ? Number.parseInt(panel.dataset.businessTypeIconPickerVisibleCount || "", 10)
      : 0;
    const visibleCount = getIconPickerVisibleCount(iconOptions, storedVisibleCount);
    panel.dataset.businessTypeIconPickerSearchTerm = normalizedSearchTerm;
    panel.dataset.businessTypeIconPickerVisibleCount = String(visibleCount);
    return visibleCount;
  }

  function setPanelIconPickerVisibleCount(panel, visibleCount) {
    panel.dataset.businessTypeIconPickerVisibleCount = String(Math.max(0, Math.trunc(Number(visibleCount) || 0)));
  }

  function setIconPickerCurrentSearchTerm(panel, searchTerm = "") {
    if (panel instanceof HTMLElement) {
      panel.dataset.businessTypeIconPickerCurrentSearchTerm = normalizeLucideCategoryIconKey(searchTerm);
    }
  }

  function getIconPickerSearchSurface(panel) {
    if (!(panel instanceof HTMLElement)) {
      return null;
    }
    if (panel.matches(".super-admin-store-type-category-modal__icon-grid")) {
      return panel;
    }
    return panel.querySelector(".business-type-showcase__icon-picker-grid");
  }

  function getIconPickerSearchInput(panel) {
    if (!(panel instanceof HTMLElement)) {
      return null;
    }
    if (panel.matches(".super-admin-store-type-category-modal__icon-grid")) {
      return panel.closest(".super-admin-store-type-category-modal__icon-picker")?.querySelector('input[type="search"]') || null;
    }
    return panel.querySelector(".business-type-showcase__icon-picker-search");
  }

  function scheduleIconPickerSearchRender(panel, render) {
    if (!(panel instanceof HTMLElement)) {
      render?.();
      return;
    }
    const existingTimer = iconPickerSearchRenderTimers.get(panel);
    if (existingTimer) {
      window.clearTimeout(existingTimer);
    }
    const searchInput = getIconPickerSearchInput(panel);
    const searchTerm = String(searchInput?.value || "").trim();
    if (!searchTerm) {
      iconPickerSearchRenderTimers.delete(panel);
      setSuperAdminSearchInputBusy(searchInput, false);
      render?.();
      return;
    }
    const searchSurface = getIconPickerSearchSurface(panel);
    setSuperAdminSearchInputBusy(searchInput, true);
    renderSuperAdminSearchState(searchSurface, {
      variant: "loading",
      message: "Searching icons...",
      compact: true,
    });
    const timer = window.setTimeout(() => {
      iconPickerSearchRenderTimers.delete(panel);
      setSuperAdminSearchInputBusy(searchInput, false);
      render?.();
    }, 260);
    iconPickerSearchRenderTimers.set(panel, timer);
  }

  function focusIconPickerSearchInput(panel) {
    const input = panel?.querySelector?.(".business-type-showcase__icon-picker-search");
    if (!(input instanceof HTMLInputElement)) {
      return;
    }
    input.focus({ preventScroll: true });
    const valueLength = input.value.length;
    input.setSelectionRange?.(valueLength, valueLength);
  }

  function isIconPickerSearchFocused(panel) {
    const activeElement = document.activeElement;
    return panel instanceof HTMLElement
      && activeElement instanceof HTMLInputElement
      && activeElement.classList.contains("business-type-showcase__icon-picker-search")
      && panel.contains(activeElement);
  }

  function hydrateIconPickerOptions(panel, visibleIconOptions, searchTerm, rerender) {
    const normalizedSearchTerm = normalizeLucideCategoryIconKey(searchTerm);
    setIconPickerCurrentSearchTerm(panel, searchTerm);
    const visibleTablerIconNames = visibleIconOptions
      .map((option) => option.iconName)
      .filter((iconName) => getTablerIconSlug(iconName));
    const needsCatalog = Boolean(normalizedSearchTerm) && hasUndiscoveredTablerIcons();
    const needsPaths = visibleTablerIconNames.some((iconName) => !getTablerIconPathFromCache(getTablerIconSlug(iconName)));
    if (!needsCatalog && !needsPaths) {
      return;
    }
    const hydrateToken = String(++iconPickerHydrateTokenCounter);
    panel.dataset.businessTypeIconPickerHydrateToken = hydrateToken;
    Promise.all([
      needsCatalog ? ensureTablerIconCatalog() : Promise.resolve(),
      needsPaths ? ensureTablerIconPaths(visibleTablerIconNames) : Promise.resolve(),
    ])
      .then(() => {
        if (
          panel.isConnected
          && panel.dataset.businessTypeIconPickerHydrateToken === hydrateToken
          && panel.dataset.businessTypeIconPickerCurrentSearchTerm === normalizedSearchTerm
        ) {
          rerender?.();
        }
      })
      .catch(() => {
        // Search still works with available Lucide icons if the optional Tabler catalog cannot be read.
      });
  }

  function createIconPickerShowMoreButton(hiddenCount, onClick) {
    const showMoreButton = document.createElement("button");
    showMoreButton.type = "button";
    showMoreButton.className = "super-admin-store-type-category-modal__icon-show-more";
    showMoreButton.textContent = hiddenCount > 0 ? `Show more (${numberText(hiddenCount)})` : "Show more";
    showMoreButton.addEventListener("click", () => {
      void onClick?.();
    });
    return showMoreButton;
  }

  function renderStoreTypeCategoryIconPicker() {
    if (!elements.storeTypeCategoryIconPicker) {
      return;
    }

    const manualIconName = normalizeLucideCategoryIconName(state.storeTypeCategoryDraftIconName);
    const effectiveIconName = getEffectiveStoreTypeCategoryIconName();
    const searchTerm = String(state.storeTypeCategoryIconSearchTerm || "").trim().toLowerCase();
    setIconPickerCurrentSearchTerm(elements.storeTypeCategoryIconPicker, searchTerm);
    const iconOptions = getFilteredIconPickerOptions(searchTerm);
    const iconFragment = document.createDocumentFragment();
    elements.storeTypeCategoryIconPicker.innerHTML = "";
    elements.storeTypeCategoryIconPicker.classList.remove("has-super-admin-search-state");
    const visibleCount = getIconPickerVisibleCount(iconOptions, state.storeTypeCategoryIconVisibleCount);
    const visibleIconOptions = getIconPickerVisibleOptions(iconOptions, visibleCount, manualIconName);

    const autoButton = document.createElement("button");
    autoButton.type = "button";
    autoButton.className = "super-admin-store-type-category-modal__icon-option";
    autoButton.classList.toggle("is-selected", !manualIconName);
    autoButton.setAttribute("aria-pressed", String(!manualIconName));
    autoButton.setAttribute("aria-label", "Use automatic category icon");
    autoButton.dataset.storeTypeCategoryIconAutoOption = "";
    autoButton.title = "Auto";
    autoButton.innerHTML = `${createLucideCategoryIconSvg(effectiveIconName, { queueTablerRefresh: false })}<span>Auto</span>`;
    autoButton.addEventListener("click", () => {
      state.storeTypeCategoryDraftIconName = "";
      state.storeTypeCategoryDraftIconNameTouched = true;
      renderStoreTypeCategoryIconPicker();
      syncStoreTypeCategoryAssetFileNames();
    });
    if (!searchTerm || iconOptions.length) {
      iconFragment.append(autoButton);
    }

    for (const { iconName, label } of visibleIconOptions) {
      const iconButton = document.createElement("button");
      iconButton.type = "button";
      iconButton.className = "super-admin-store-type-category-modal__icon-option";
      const isSelected = manualIconName === iconName;
      iconButton.classList.toggle("is-selected", isSelected);
      iconButton.setAttribute("aria-pressed", String(isSelected));
      iconButton.setAttribute("aria-label", `Use ${label} icon`);
      iconButton.title = label;
      iconButton.innerHTML = createLucideCategoryIconSvg(iconName, { queueTablerRefresh: false });
      iconButton.addEventListener("click", () => {
        state.storeTypeCategoryDraftIconName = iconName;
        state.storeTypeCategoryDraftIconNameTouched = true;
        renderStoreTypeCategoryIconPicker();
        syncStoreTypeCategoryAssetFileNames();
      });
      iconFragment.append(iconButton);
    }
    if (visibleCount < iconOptions.length || hasUndiscoveredTablerIcons()) {
      iconFragment.append(createIconPickerShowMoreButton(Math.max(iconOptions.length - visibleCount, 0), async () => {
        await ensureTablerIconCatalog();
        const nextIconOptions = getFilteredIconPickerOptions(searchTerm);
        state.storeTypeCategoryIconVisibleCount = getIconPickerNextVisibleCount(nextIconOptions, visibleCount);
        renderStoreTypeCategoryIconPicker();
      }));
    }
    if (!iconOptions.length) {
      iconFragment.append(createSuperAdminSearchState({
        variant: "empty",
        message: "No icons match your search.",
        compact: true,
        className: "super-admin-store-type-category-modal__icon-empty",
      }));
    }
    elements.storeTypeCategoryIconPicker.append(iconFragment);
    hydrateIconPickerOptions(elements.storeTypeCategoryIconPicker, visibleIconOptions, searchTerm, () => {
      renderStoreTypeCategoryIconPicker();
    });

    syncStoreTypeCategoryIconPickerSummary();
  }

  function syncStoreTypeCategoryIconPickerSummary() {
    const manualIconName = normalizeLucideCategoryIconName(state.storeTypeCategoryDraftIconName);
    const effectiveIconName = getEffectiveStoreTypeCategoryIconName();
    const autoButton = elements.storeTypeCategoryIconPicker?.querySelector("[data-store-type-category-icon-auto-option]");
    if (autoButton instanceof HTMLButtonElement) {
      autoButton.classList.toggle("is-selected", !manualIconName);
      autoButton.setAttribute("aria-pressed", String(!manualIconName));
      autoButton.innerHTML = `${createLucideCategoryIconSvg(effectiveIconName, { queueTablerRefresh: false })}<span>Auto</span>`;
    }
    if (elements.storeTypeCategorySelectedIconName) {
      elements.storeTypeCategorySelectedIconName.textContent = manualIconName
        ? formatLucideCategoryIconLabel(manualIconName)
        : `Auto: ${formatLucideCategoryIconLabel(effectiveIconName)}`;
    }
  }

  function getEffectiveStoreTypeIconName() {
    return normalizeLucideCategoryIconName(state.storeTypeDraftIconName)
      || getAutoLucideCategoryIconName(elements.storeTypeNameInput?.value)
      || "store";
  }

  function renderStoreTypeIconPicker() {
    if (!elements.storeTypeIconPicker) {
      return;
    }

    const manualIconName = normalizeLucideCategoryIconName(state.storeTypeDraftIconName);
    const effectiveIconName = getEffectiveStoreTypeIconName();
    const searchTerm = String(state.storeTypeIconSearchTerm || "").trim().toLowerCase();
    setIconPickerCurrentSearchTerm(elements.storeTypeIconPicker, searchTerm);
    const iconOptions = getFilteredIconPickerOptions(searchTerm);
    const iconFragment = document.createDocumentFragment();
    elements.storeTypeIconPicker.innerHTML = "";
    elements.storeTypeIconPicker.classList.remove("has-super-admin-search-state");
    const visibleCount = getIconPickerVisibleCount(iconOptions, state.storeTypeIconVisibleCount);
    const visibleIconOptions = getIconPickerVisibleOptions(iconOptions, visibleCount, manualIconName);

    const autoButton = document.createElement("button");
    autoButton.type = "button";
    autoButton.className = "super-admin-store-type-category-modal__icon-option";
    autoButton.classList.toggle("is-selected", !manualIconName);
    autoButton.setAttribute("aria-pressed", String(!manualIconName));
    autoButton.setAttribute("aria-label", "Use automatic business type icon");
    autoButton.dataset.storeTypeIconAutoOption = "";
    autoButton.title = "Auto";
    autoButton.innerHTML = `${createLucideCategoryIconSvg(effectiveIconName, { queueTablerRefresh: false })}<span>Auto</span>`;
    autoButton.addEventListener("click", () => {
      state.storeTypeDraftIconName = "";
      state.storeTypeDraftIconFile = null;
      state.storeTypeDraftIconUrl = "";
      if (elements.storeTypeIconInput) {
        elements.storeTypeIconInput.value = "";
      }
      renderStoreTypeIconPicker();
      syncStoreTypeAssetFileNames();
    });
    if (!searchTerm || iconOptions.length) {
      iconFragment.append(autoButton);
    }

    for (const { iconName, label } of visibleIconOptions) {
      const iconButton = document.createElement("button");
      iconButton.type = "button";
      iconButton.className = "super-admin-store-type-category-modal__icon-option";
      const isSelected = manualIconName === iconName;
      iconButton.classList.toggle("is-selected", isSelected);
      iconButton.setAttribute("aria-pressed", String(isSelected));
      iconButton.setAttribute("aria-label", `Use ${label} icon`);
      iconButton.title = label;
      iconButton.innerHTML = createLucideCategoryIconSvg(iconName, { queueTablerRefresh: false });
      iconButton.addEventListener("click", () => {
        state.storeTypeDraftIconName = iconName;
        state.storeTypeDraftIconFile = null;
        state.storeTypeDraftIconUrl = "";
        if (elements.storeTypeIconInput) {
          elements.storeTypeIconInput.value = "";
        }
        renderStoreTypeIconPicker();
        syncStoreTypeAssetFileNames();
      });
      iconFragment.append(iconButton);
    }

    if (visibleCount < iconOptions.length || hasUndiscoveredTablerIcons()) {
      iconFragment.append(createIconPickerShowMoreButton(Math.max(iconOptions.length - visibleCount, 0), async () => {
        await ensureTablerIconCatalog();
        const nextIconOptions = getFilteredIconPickerOptions(searchTerm);
        state.storeTypeIconVisibleCount = getIconPickerNextVisibleCount(nextIconOptions, visibleCount);
        renderStoreTypeIconPicker();
      }));
    }

    if (!iconOptions.length) {
      iconFragment.append(createSuperAdminSearchState({
        variant: "empty",
        message: "No icons match your search.",
        compact: true,
        className: "super-admin-store-type-category-modal__icon-empty",
      }));
    }
    elements.storeTypeIconPicker.append(iconFragment);
    hydrateIconPickerOptions(elements.storeTypeIconPicker, visibleIconOptions, searchTerm, () => {
      renderStoreTypeIconPicker();
    });
    syncStoreTypeIconPickerSummary();
  }

  function syncStoreTypeIconPickerSummary() {
    const manualIconName = normalizeLucideCategoryIconName(state.storeTypeDraftIconName);
    const effectiveIconName = getEffectiveStoreTypeIconName();
    const autoButton = elements.storeTypeIconPicker?.querySelector("[data-store-type-icon-auto-option]");
    if (autoButton instanceof HTMLButtonElement) {
      autoButton.classList.toggle("is-selected", !manualIconName);
      autoButton.setAttribute("aria-pressed", String(!manualIconName));
      autoButton.innerHTML = `${createLucideCategoryIconSvg(effectiveIconName, { queueTablerRefresh: false })}<span>Auto</span>`;
    }
    if (elements.storeTypeSelectedIconName) {
      elements.storeTypeSelectedIconName.textContent = manualIconName
        ? formatLucideCategoryIconLabel(manualIconName)
        : `Auto: ${formatLucideCategoryIconLabel(effectiveIconName)}`;
    }
  }

  function syncStoreTypeCategoryAssetFileNames() {
    if (elements.storeTypeCategoryImageFileName) {
      elements.storeTypeCategoryImageFileName.textContent = state.storeTypeCategoryDraftImageFile?.name
        || getBusinessTypeAssetFileName(state.storeTypeCategoryDraftImageUrl, "No image selected");
    }
    if (elements.storeTypeCategoryIconFileName) {
      const manualIconName = normalizeLucideCategoryIconName(state.storeTypeCategoryDraftIconName);
      const effectiveIconName = getEffectiveStoreTypeCategoryIconName();
      elements.storeTypeCategoryIconFileName.textContent = state.storeTypeCategoryDraftIconFile?.name
        || getBusinessTypeAssetFileName(state.storeTypeCategoryDraftIconUrl, "No icon selected");
      if (
        !state.storeTypeCategoryDraftIconFile
        && !state.storeTypeCategoryDraftIconUrl
      ) {
        elements.storeTypeCategoryIconFileName.textContent = manualIconName
          ? `${formatLucideCategoryIconLabel(manualIconName)} icon`
          : `Auto: ${formatLucideCategoryIconLabel(effectiveIconName)} icon`;
      }
    }
  }

  function resetStoreTypeCategoryComposer({ focusInput = false } = {}) {
    state.editingStoreTypeCategoryName = "";
    state.storeTypeCategoryDraftImageUrl = "";
    state.storeTypeCategoryDraftIconUrl = "";
    state.storeTypeCategoryDraftIconName = "";
    state.storeTypeCategoryDraftIconNameTouched = false;
    state.storeTypeCategoryDraftImageFile = null;
    state.storeTypeCategoryDraftIconFile = null;
    state.storeTypeCategoryIconSearchTerm = "";
    state.storeTypeCategoryIconVisibleCount = 0;
    if (elements.storeTypeCategoryInput) elements.storeTypeCategoryInput.value = "";
    if (elements.storeTypeCategoryIconSearchInput) elements.storeTypeCategoryIconSearchInput.value = "";
    if (elements.storeTypeCategoryImageInput) elements.storeTypeCategoryImageInput.value = "";
    if (elements.storeTypeCategoryIconInput) elements.storeTypeCategoryIconInput.value = "";
    if (elements.addStoreTypeCategoryButton) elements.addStoreTypeCategoryButton.textContent = "Add Category";
    renderStoreTypeCategoryIconPicker();
    syncStoreTypeCategoryAssetFileNames();
    if (focusInput) elements.storeTypeCategoryInput?.focus();
  }

  function editStoreTypeDraftCategory(categoryName) {
    const detail = state.storeTypeDraftCategoryDetails.find(
      (item) => isSameCategoryName(item.name, categoryName),
    ) || {};
    state.editingStoreTypeCategoryName = categoryName;
    state.storeTypeCategoryDraftImageUrl = normalizeBusinessTypeImageUrl(detail.imageUrl);
    state.storeTypeCategoryDraftIconUrl = normalizeBusinessTypeImageUrl(detail.iconImageUrl);
    state.storeTypeCategoryDraftIconName = normalizeLucideCategoryIconName(detail.iconName);
    state.storeTypeCategoryDraftIconNameTouched = false;
    state.storeTypeCategoryDraftImageFile = null;
    state.storeTypeCategoryDraftIconFile = null;
    state.storeTypeCategoryIconVisibleCount = 0;
    if (elements.storeTypeCategoryInput) elements.storeTypeCategoryInput.value = categoryName;
    if (elements.addStoreTypeCategoryButton) elements.addStoreTypeCategoryButton.textContent = "Update Category";
    renderStoreTypeCategoryIconPicker();
    syncStoreTypeCategoryAssetFileNames();
    elements.storeTypeCategoryInput?.focus();
    elements.storeTypeCategoryInput?.select();
  }

  // Supports the add store type draft category branch of the super admin UI.
  function addStoreTypeDraftCategory({ focusInput = true } = {}) {
    const categoryName = normalizeCategoryName(elements.storeTypeCategoryInput?.value);
    if (!categoryName) {
      elements.storeTypeCategoryInput?.focus();
      return false;
    }

    if (!state.storeTypeDraftCategories.some((category) => isSameCategoryName(category, categoryName))) {
      state.storeTypeDraftCategories = normalizeCategoryValues([
        ...state.storeTypeDraftCategories,
        categoryName,
      ]);
    }

    const previousName = state.editingStoreTypeCategoryName || categoryName;
    const existingDetail = state.storeTypeDraftCategoryDetails.find(
      (item) => isSameCategoryName(item.name, previousName),
    ) || {};
    state.storeTypeDraftCategoryDetails = [
      ...state.storeTypeDraftCategoryDetails.filter(
        (item) => !isSameCategoryName(item.name, previousName) && !isSameCategoryName(item.name, categoryName),
      ),
      {
        name: categoryName,
        productCount: Math.trunc(normalizeStoreTypeNumber(existingDetail.productCount)),
        imageUrl: state.storeTypeCategoryDraftImageUrl || existingDetail.imageUrl || "",
        iconImageUrl: state.storeTypeCategoryDraftIconUrl || existingDetail.iconImageUrl || "",
        iconName: state.storeTypeCategoryDraftIconNameTouched
          ? normalizeLucideCategoryIconName(state.storeTypeCategoryDraftIconName)
          : normalizeLucideCategoryIconName(state.storeTypeCategoryDraftIconName)
            || normalizeLucideCategoryIconName(existingDetail.iconName),
        status: normalizeStoreTypeCategoryStatus(existingDetail.status),
        imageFile: state.storeTypeCategoryDraftImageFile,
        iconFile: state.storeTypeCategoryDraftIconFile,
      },
    ];
    if (state.editingStoreTypeCategoryName && !isSameCategoryName(state.editingStoreTypeCategoryName, categoryName)) {
      state.storeTypeDraftCategories = state.storeTypeDraftCategories.map((item) =>
        isSameCategoryName(item, state.editingStoreTypeCategoryName) ? categoryName : item,
      );
    }
    state.storeTypeDraftCategories = normalizeCategoryValues(state.storeTypeDraftCategories);
    renderStoreTypeDraftCategories();
    syncStoreTypeModalSummary();
    resetStoreTypeCategoryComposer({ focusInput });
    return true;
  }

  function getBusinessTypeAssetFileName(value, fallback = "") {
    const normalizedUrl = String(value || "").trim().split("#")[0].split("?")[0];
    const fileName = normalizedUrl.split(/[\\/]/).pop() || "";
    if (!fileName) {
      return fallback;
    }
    try {
      return decodeURIComponent(fileName);
    } catch (error) {
      return fileName;
    }
  }

  function syncStoreTypeAssetFileNames() {
    if (elements.storeTypeImageFileName) {
      elements.storeTypeImageFileName.textContent = state.storeTypeDraftImageFile?.name
        || getBusinessTypeAssetFileName(state.storeTypeDraftImageUrl, "No image selected");
    }
    if (elements.storeTypeIconFileName) {
      const manualIconName = normalizeLucideCategoryIconName(state.storeTypeDraftIconName);
      elements.storeTypeIconFileName.textContent = state.storeTypeDraftIconFile?.name
        || getBusinessTypeAssetFileName(
          state.storeTypeDraftIconUrl,
          manualIconName ? `Icon: ${formatLucideCategoryIconLabel(manualIconName)}` : "No icon selected",
        );
    }
    syncStoreTypeIconPickerSummary();
  }

  function syncStoreTypeStatusOptions() {
    const selectedStatus = normalizeStoreTypeStatus(elements.storeTypeStatusSelect?.value);
    const isActive = selectedStatus === "active";
    elements.storeTypeStatusToggle?.classList.toggle("is-active", isActive);
    elements.storeTypeStatusToggle?.setAttribute("aria-pressed", isActive ? "true" : "false");
    if (elements.storeTypeStatusToggleLabel) {
      elements.storeTypeStatusToggleLabel.textContent = isActive ? "Active" : "Inactive";
    }
  }

  function isSupportedBusinessTypeAssetFile(file, type = "image") {
    if (!(file instanceof File)) {
      return false;
    }
    const fileType = String(file.type || "").toLowerCase();
    const fileName = String(file.name || "").toLowerCase();
    if (type === "icon") {
      return ["image/png", "image/svg+xml"].includes(fileType) || /\.(png|svg)$/.test(fileName);
    }
    return ["image/jpeg", "image/jpg", "image/png", "image/webp"].includes(fileType)
      || /\.(jpe?g|png|webp)$/.test(fileName);
  }

  async function setStoreTypeAssetFile(type, file) {
    const isIcon = type === "icon";
    const maxBytes = isIcon ? 2 * 1024 * 1024 : 4 * 1024 * 1024;
    if (!(file instanceof File)) {
      if (isIcon) {
        state.storeTypeDraftIconFile = null;
      } else {
        state.storeTypeDraftImageFile = null;
      }
      syncStoreTypeAssetFileNames();
      return;
    }
    if (!isSupportedBusinessTypeAssetFile(file, type)) {
      setFeedback(
        isIcon ? "Choose a PNG or SVG icon." : "Choose a JPG, PNG, or WEBP image.",
        "error",
      );
      if (isIcon && elements.storeTypeIconInput) {
        elements.storeTypeIconInput.value = "";
      } else if (!isIcon && elements.storeTypeImageInput) {
        elements.storeTypeImageInput.value = "";
      }
      return;
    }
    if (file.size > maxBytes) {
      setFeedback(
        isIcon ? "Business type icon must be 2MB or smaller." : "Business type image must be 4MB or smaller.",
        "error",
      );
      if (isIcon && elements.storeTypeIconInput) {
        elements.storeTypeIconInput.value = "";
      } else if (!isIcon && elements.storeTypeImageInput) {
        elements.storeTypeImageInput.value = "";
      }
      return;
    }

    let preparedFile = file;
    if (!isIcon) {
      preparedFile = await prepareSquareImageUploadFile(file, {
        title: "Crop business type image",
        copy: "Square photos are used as-is. Wider or taller photos can be cropped to a square.",
      });
      if (elements.storeTypeImageInput) {
        elements.storeTypeImageInput.value = "";
      }
      if (!(preparedFile instanceof File)) {
        return;
      }
    }

    if (isIcon) {
      state.storeTypeDraftIconFile = preparedFile;
      state.storeTypeDraftIconName = "";
      renderStoreTypeIconPicker();
    } else {
      state.storeTypeDraftImageFile = preparedFile;
    }
    syncStoreTypeAssetFileNames();
    setFeedback("");
  }

  async function setStoreTypeCategoryAssetFile(type, file) {
    const isIcon = type === "icon";
    const input = isIcon ? elements.storeTypeCategoryIconInput : elements.storeTypeCategoryImageInput;
    const maxBytes = isIcon ? 2 * 1024 * 1024 : 4 * 1024 * 1024;
    if (!(file instanceof File)) {
      if (isIcon) state.storeTypeCategoryDraftIconFile = null;
      else state.storeTypeCategoryDraftImageFile = null;
      syncStoreTypeCategoryAssetFileNames();
      return;
    }
    if (!isSupportedBusinessTypeAssetFile(file, type)) {
      setFeedback(isIcon ? "Choose a PNG or SVG category icon." : "Choose a JPG, PNG, or WEBP category image.", "error");
      if (input) input.value = "";
      return;
    }
    if (file.size > maxBytes) {
      setFeedback(isIcon ? "Category icon must be 2MB or smaller." : "Category image must be 4MB or smaller.", "error");
      if (input) input.value = "";
      return;
    }
    let preparedFile = file;
    if (!isIcon) {
      preparedFile = await prepareSquareImageUploadFile(file, {
        title: "Crop category image",
        copy: "Square photos are used as-is. Wider or taller photos can be cropped to a square.",
      });
      if (input) input.value = "";
      if (!(preparedFile instanceof File)) {
        return;
      }
    }
    if (isIcon) state.storeTypeCategoryDraftIconFile = preparedFile;
    else state.storeTypeCategoryDraftImageFile = preparedFile;
    syncStoreTypeCategoryAssetFileNames();
    setFeedback("");
  }

  async function uploadStoreTypeCategoryDetails() {
    const detailsWithFiles = state.storeTypeDraftCategoryDetails.map((detail, index) => ({
      detail,
      index,
    }));
    const uploadedFilePairs = await mapWithConcurrency(
      detailsWithFiles.filter(({ detail }) =>
        detail.imageFile instanceof File || detail.iconFile instanceof File,
      ),
      imageUploadConcurrency,
      async ({ detail, index }) => {
        const uploads = {};
        if (detail.imageFile instanceof File) {
          setFeedback(`Uploading image for ${detail.name}...`);
          uploads.imageUrl = await uploadSuperAdminProductImageFile(detail.imageFile);
        }
        if (detail.iconFile instanceof File) {
          setFeedback(`Uploading icon for ${detail.name}...`);
          uploads.iconImageUrl = await uploadSuperAdminProductImageFile(detail.iconFile);
        }
        return { index, uploads };
      },
    );
    const uploadByIndex = new Map(uploadedFilePairs.map((entry) => [entry.index, entry.uploads]));
    const uploadedDetails = [];
    for (const [index, detail] of state.storeTypeDraftCategoryDetails.entries()) {
      const nextDetail = {
        name: detail.name,
        productCount: Math.trunc(normalizeStoreTypeNumber(detail.productCount)),
        imageUrl: normalizeBusinessTypeImageUrl(detail.imageUrl),
        iconImageUrl: normalizeBusinessTypeImageUrl(detail.iconImageUrl),
        iconName: normalizeLucideCategoryIconName(detail.iconName),
        status: normalizeStoreTypeCategoryStatus(detail.status),
      };
      const uploads = uploadByIndex.get(index);
      if (uploads?.imageUrl) {
        nextDetail.imageUrl = uploads.imageUrl;
      }
      if (uploads?.iconImageUrl) {
        nextDetail.iconImageUrl = uploads.iconImageUrl;
      }
      uploadedDetails.push(nextDetail);
    }
    return uploadedDetails;
  }

  async function uploadStoreTypeDraftAssets(storeTypeDraft) {
    const nextDraft = { ...storeTypeDraft };
    const pendingUploads = [];
    if (state.storeTypeDraftImageFile instanceof File) {
      pendingUploads.push({
        key: "heroImageUrl",
        label: "Uploading business type image...",
        file: state.storeTypeDraftImageFile,
      });
    }
    if (state.storeTypeDraftIconFile instanceof File) {
      pendingUploads.push({
        key: "iconImageUrl",
        label: "Uploading business type icon...",
        file: state.storeTypeDraftIconFile,
      });
    }
    if (pendingUploads.length) {
      const uploadedEntries = await mapWithConcurrency(
        pendingUploads,
        imageUploadConcurrency,
        async (entry) => {
          setFeedback(entry.label);
          return {
            key: entry.key,
            url: await uploadSuperAdminProductImageFile(entry.file),
          };
        },
      );
      for (const entry of uploadedEntries) {
        nextDraft[entry.key] = entry.url;
      }
    }
    return nextDraft;
  }

  // Reads or derives current store type draft for the current super admin flow.
  function getCurrentStoreTypeDraft() {
    const selectedRecord = getStoreTypeRecordByName(
      normalizeCategoryName(elements.storeTypeNameInput?.value) || state.editingStoreTypeName,
    );
    const hasIconImage = state.storeTypeDraftIconFile instanceof File || Boolean(state.storeTypeDraftIconUrl);
    const categories = [...state.storeTypeDraftCategories];
    return {
      name: normalizeCategoryName(elements.storeTypeNameInput?.value),
      platformId: normalizePlatformIdValue(elements.storeTypePlatformSelect?.value) || "shop",
      categories,
      // Persist Super Admin category photos/icons with the business type save.
      categoryDetails: getStoreTypeCategoryDetailsForSave(
        {
          categories,
          categoryStats: state.storeTypeDraftCategoryDetails,
        },
        categories,
      ),
      status: normalizeStoreTypeStatus(elements.storeTypeStatusSelect?.value),
      commissionRate: normalizeStoreTypeNumber(elements.storeTypeCommissionRateInput?.value),
      serviceFee: normalizeStoreTypeNumber(elements.storeTypeServiceFeeInput?.value),
      heroImageUrl: normalizeBusinessTypeImageUrl(state.storeTypeDraftImageUrl),
      iconImageUrl: normalizeBusinessTypeImageUrl(state.storeTypeDraftIconUrl),
      iconName: hasIconImage
        ? normalizeLucideCategoryIconName(state.storeTypeDraftIconName)
        : (
            normalizeLucideCategoryIconName(state.storeTypeDraftIconName || selectedRecord?.iconName)
            || getEffectiveStoreTypeIconName()
          ),
      companiesUsing: Math.trunc(normalizeStoreTypeNumber(selectedRecord?.companiesUsing)),
      productCount: Math.trunc(normalizeStoreTypeNumber(selectedRecord?.productCount)),
    };
  }

  // Keeps store type modal summary synchronized with current state.
  function syncStoreTypeModalSummary() {
    const draft = getCurrentStoreTypeDraft();
    const isEditing = Boolean(state.editingStoreTypeName);
    if (elements.storeTypeModalTitle) {
      elements.storeTypeModalTitle.textContent = isEditing
        ? "Edit Business Type Details"
        : "Add Business Type Details";
    }
    if (elements.storeTypeModalSubtitle) {
      elements.storeTypeModalSubtitle.textContent = isEditing
        ? `Update the details for ${draft.name || state.editingStoreTypeName}.`
        : "Add a new business type by providing the details below.";
    }
    syncStoreTypeStatusOptions();
    syncStoreTypeAssetFileNames();
  }

  // Supports the populate store type modal branch of the super admin UI.
  function populateStoreTypeModal(record = null) {
    const storeType = normalizeStoreTypeRecord(record) || {
      name: "",
      platformId: "shop",
      categories: [],
      status: "active",
      commissionRate: 0,
      serviceFee: 0,
      companiesUsing: 0,
      productCount: 0,
      heroImageUrl: "",
      iconImageUrl: "",
    };

    if (elements.storeTypeNameInput) {
      elements.storeTypeNameInput.value = storeType.name;
    }
    syncStoreTypePlatformSelect(storeType.platformId || "shop");
    if (elements.storeTypeStatusSelect) {
      elements.storeTypeStatusSelect.value = storeType.status;
    }
    if (elements.storeTypeCommissionRateInput) {
      elements.storeTypeCommissionRateInput.value = storeType.commissionRate ? String(storeType.commissionRate) : "";
    }
    if (elements.storeTypeServiceFeeInput) {
      elements.storeTypeServiceFeeInput.value = storeType.serviceFee ? String(storeType.serviceFee) : "";
    }

    state.storeTypeDraftImageUrl = storeType.heroImageUrl;
    state.storeTypeDraftIconUrl = storeType.iconImageUrl;
    state.storeTypeDraftIconName = normalizeLucideCategoryIconName(storeType.iconName);
    state.storeTypeIconSearchTerm = "";
    state.storeTypeIconVisibleCount = 0;
    state.storeTypeDraftImageFile = null;
    state.storeTypeDraftIconFile = null;
    if (elements.storeTypeImageInput) {
      elements.storeTypeImageInput.value = "";
    }
    if (elements.storeTypeIconInput) {
      elements.storeTypeIconInput.value = "";
    }

    state.storeTypeDraftCategories = [...storeType.categories];
    state.storeTypeDraftCategoryDetails = (storeType.categoryStats || []).map((detail) => ({
      ...detail,
    }));
    renderStoreTypeDraftCategories();
    if (elements.storeTypeIconSearchInput) {
      elements.storeTypeIconSearchInput.value = "";
    }
    renderStoreTypeIconPicker();
    syncStoreTypeModalSummary();
    setStoreTypeModalTab("basic");
  }

  // Supports the reset category editor branch of the super admin UI.
  function resetCategoryEditor({ clearInput = true } = {}) {
    state.editingCategoryName = "";
    if (elements.categoryInputLabel) {
      elements.categoryInputLabel.textContent = "Add Category";
    }
    if (elements.addCategoryButton) {
      elements.addCategoryButton.textContent = "Add";
    }
    if (elements.cancelCategoryEditButton) {
      elements.cancelCategoryEditButton.hidden = true;
    }
    if (clearInput && elements.categoryNameInput) {
      elements.categoryNameInput.value = "";
    }
    renderCategories(state.categories);
  }

  // Supports the reset store type editor branch of the super admin UI.
  function resetStoreTypeEditor({ clearInput = true } = {}) {
    state.editingStoreTypeName = "";
    state.inlineEditingCategoryStoreTypeName = "";
    state.inlineEditingCategoryName = "";
    state.inlineEditingStoreTypeSettingName = "";
    state.inlineEditingStoreTypeSettingKey = "";
    resetInlineStoreTypeAssetDraft();
    if (elements.storeTypeInputLabel) {
      elements.storeTypeInputLabel.textContent = "Business Type Name";
    }
    if (elements.addStoreTypeButton) {
      elements.addStoreTypeButton.textContent = "Add Business Type";
    }
    if (elements.cancelStoreTypeEditButton) {
      elements.cancelStoreTypeEditButton.hidden = false;
    }
    if (clearInput && elements.storeTypeNameInput) {
      elements.storeTypeNameInput.value = "";
    }
    if (clearInput) {
      if (elements.storeTypeCategoryInput) {
        elements.storeTypeCategoryInput.value = "";
      }
      if (elements.storeTypeStatusSelect) {
        elements.storeTypeStatusSelect.value = "active";
      }
      if (elements.storeTypeCommissionRateInput) {
        elements.storeTypeCommissionRateInput.value = "";
      }
      if (elements.storeTypeServiceFeeInput) {
        elements.storeTypeServiceFeeInput.value = "";
      }
      syncStoreTypePlatformSelect("shop");
      if (elements.storeTypeImageInput) {
        elements.storeTypeImageInput.value = "";
      }
      if (elements.storeTypeIconInput) {
        elements.storeTypeIconInput.value = "";
      }
      if (elements.storeTypeIconSearchInput) {
        elements.storeTypeIconSearchInput.value = "";
      }
      state.storeTypeDraftImageUrl = "";
      state.storeTypeDraftIconUrl = "";
      state.storeTypeDraftIconName = "";
      state.storeTypeIconSearchTerm = "";
      state.storeTypeIconVisibleCount = 0;
      state.storeTypeDraftImageFile = null;
      state.storeTypeDraftIconFile = null;
      state.storeTypeDraftCategories = [];
      state.storeTypeDraftCategoryDetails = [];
      renderStoreTypeDraftCategories();
      renderStoreTypeIconPicker();
      syncStoreTypeModalSummary();
      setStoreTypeModalTab("basic");
    }
    renderStoreTypes(state.storeTypes);
  }

  // Checks whether store type modal visible is true for the current record or UI state.
  function isStoreTypeModalVisible() {
    return (
      elements.storeTypeModalOverlay instanceof HTMLElement &&
      !elements.storeTypeModalOverlay.hidden
    );
  }

  // Updates store type modal open and synchronizes related UI state.
  function setStoreTypeModalOpen(isOpen, { resetEditor = false, restoreFocus = true } = {}) {
    const overlay = elements.storeTypeModalOverlay;

    if (!(overlay instanceof HTMLElement)) {
      if (isOpen) {
        elements.storeTypeNameInput?.focus();
      }
      return;
    }

    if (storeTypeModalCloseTimer) {
      window.clearTimeout(storeTypeModalCloseTimer);
      storeTypeModalCloseTimer = 0;
    }

    if (storeTypeModalFocusTimer) {
      window.clearTimeout(storeTypeModalFocusTimer);
      storeTypeModalFocusTimer = 0;
    }

    if (isOpen) {
      storeTypeModalScrollSnapshot = getSuperAdminScrollSnapshot();
      if (resetEditor) {
        resetStoreTypeEditor();
      }

      overlay.hidden = false;
      overlay.setAttribute("aria-hidden", "false");
      elements.openStoreTypeModalButton?.setAttribute("aria-expanded", "true");

      window.requestAnimationFrame(() => {
        overlay.classList.add("is-open");
      });

      storeTypeModalFocusTimer = window.setTimeout(() => {
        storeTypeModalFocusTimer = 0;
        if (elements.storeTypeNameInput instanceof HTMLInputElement) {
          focusWithoutScroll(elements.storeTypeNameInput);
          elements.storeTypeNameInput.select();
          restoreSuperAdminScrollSnapshot(storeTypeModalScrollSnapshot);
          return;
        }
        focusWithoutScroll(elements.storeTypeModalDialog);
        restoreSuperAdminScrollSnapshot(storeTypeModalScrollSnapshot);
      }, 90);
      return;
    }

    overlay.classList.remove("is-open");
    overlay.setAttribute("aria-hidden", "true");
    elements.openStoreTypeModalButton?.setAttribute("aria-expanded", "false");
    restoreSuperAdminScrollSnapshot(storeTypeModalScrollSnapshot);

    storeTypeModalCloseTimer = window.setTimeout(() => {
      overlay.hidden = true;
      storeTypeModalCloseTimer = 0;
      if (restoreFocus) {
        focusWithoutScroll(elements.openStoreTypeModalButton);
      }
      restoreSuperAdminScrollSnapshotStable(storeTypeModalScrollSnapshot);
      storeTypeModalScrollSnapshot = null;
    }, 180);
  }

  // Closes store type modal and cleans up related state.
  function closeStoreTypeModal({ resetEditor = true, restoreFocus = true } = {}) {
    if (resetEditor) {
      resetStoreTypeEditor();
    }
    setStoreTypeModalOpen(false, { restoreFocus });
  }

  function isStoreTypeCategoryModalVisible() {
    return (
      elements.storeTypeCategoryModalOverlay instanceof HTMLElement &&
      !elements.storeTypeCategoryModalOverlay.hidden
    );
  }

  function setStoreTypeCategoryModalOpen(isOpen, {
    storeTypeName = "",
    categoryName = "",
    focusInput = true,
    restoreFocus = true,
  } = {}) {
    const overlay = elements.storeTypeCategoryModalOverlay;
    if (!(overlay instanceof HTMLElement)) {
      return;
    }

    if (storeTypeCategoryModalCloseTimer) {
      window.clearTimeout(storeTypeCategoryModalCloseTimer);
      storeTypeCategoryModalCloseTimer = 0;
    }
    if (storeTypeCategoryModalFocusTimer) {
      window.clearTimeout(storeTypeCategoryModalFocusTimer);
      storeTypeCategoryModalFocusTimer = 0;
    }

    if (isOpen) {
      const storeTypeRecord = getStoreTypeRecordByName(storeTypeName);
      if (!storeTypeRecord) {
        setFeedback("Business type not found.", "error");
        return;
      }

      activeStoreTypeCategoryTrigger = document.activeElement instanceof HTMLElement
        ? document.activeElement
        : null;
      storeTypeCategoryModalScrollSnapshot = getSuperAdminScrollSnapshot();
      state.categoryModalStoreTypeName = storeTypeRecord.name;
      state.storeTypeDraftCategories = [...storeTypeRecord.categories];
      state.storeTypeDraftCategoryDetails = storeTypeRecord.categoryStats.map((detail) => ({ ...detail }));
      if (elements.storeTypeCategoryBusinessName) {
        elements.storeTypeCategoryBusinessName.textContent = storeTypeRecord.name;
      }
      resetStoreTypeCategoryComposer();
      renderStoreTypeDraftCategories();
      if (categoryName) editStoreTypeDraftCategory(categoryName);

      overlay.hidden = false;
      overlay.setAttribute("aria-hidden", "false");
      window.requestAnimationFrame(() => overlay.classList.add("is-open"));
      storeTypeCategoryModalFocusTimer = window.setTimeout(() => {
        storeTypeCategoryModalFocusTimer = 0;
        if (focusInput && elements.storeTypeCategoryInput instanceof HTMLInputElement) {
          focusWithoutScroll(elements.storeTypeCategoryInput);
          restoreSuperAdminScrollSnapshot(storeTypeCategoryModalScrollSnapshot);
          return;
        }
        focusWithoutScroll(elements.storeTypeCategoryModalDialog);
        restoreSuperAdminScrollSnapshot(storeTypeCategoryModalScrollSnapshot);
      }, 90);
      return;
    }

    overlay.classList.remove("is-open");
    overlay.setAttribute("aria-hidden", "true");
    restoreSuperAdminScrollSnapshot(storeTypeCategoryModalScrollSnapshot);
    storeTypeCategoryModalCloseTimer = window.setTimeout(() => {
      overlay.hidden = true;
      storeTypeCategoryModalCloseTimer = 0;
      state.categoryModalStoreTypeName = "";
      state.storeTypeDraftCategories = [];
      state.storeTypeDraftCategoryDetails = [];
      resetStoreTypeCategoryComposer();
      if (restoreFocus) {
        focusWithoutScroll(activeStoreTypeCategoryTrigger);
      }
      restoreSuperAdminScrollSnapshotStable(storeTypeCategoryModalScrollSnapshot);
      storeTypeCategoryModalScrollSnapshot = null;
      activeStoreTypeCategoryTrigger = null;
    }, 180);
  }

  async function handleSaveStoreTypeCategories({
    closeModal = true,
    includePendingCategory = true,
    requirePendingCategory = false,
    showSuccess = true,
    successTitle = "Categories Updated",
  } = {}) {
    const storeTypeName = normalizeCategoryName(state.categoryModalStoreTypeName);
    if (!storeTypeName) {
      setFeedback("Select a business type first.", "error");
      return;
    }

    const pendingCategoryName = normalizeCategoryName(elements.storeTypeCategoryInput?.value);
    const hasPendingCategoryAssets =
      state.storeTypeCategoryDraftImageFile instanceof File
      || state.storeTypeCategoryDraftIconFile instanceof File
      || Boolean(state.storeTypeCategoryDraftImageUrl)
      || Boolean(state.storeTypeCategoryDraftIconUrl);
    if (includePendingCategory && !pendingCategoryName && hasPendingCategoryAssets) {
      setFeedback("Enter a category name before saving its image and icon.", "error");
      elements.storeTypeCategoryInput?.focus();
      return;
    }
    if (includePendingCategory && requirePendingCategory && !pendingCategoryName) {
      setFeedback("Enter a category name first.", "error");
      elements.storeTypeCategoryInput?.focus();
      return;
    }
    if (includePendingCategory && pendingCategoryName && !addStoreTypeDraftCategory({ focusInput: false })) {
      return;
    }

    if (!await requireSuperAdminFingerprint("add or save categories")) {
      return;
    }

    try {
      if (elements.addStoreTypeCategoryButton) {
        elements.addStoreTypeCategoryButton.disabled = true;
      }
      const categoryDetails = await uploadStoreTypeCategoryDetails();
      state.storeTypeDraftCategoryDetails = categoryDetails.map((detail) => ({ ...detail }));
      renderStoreTypeDraftCategories();
      setFeedback(`Updating categories for ${storeTypeName}...`);
      const response = await fetch("/api/super-admin/store-types", {
        method: "PUT",
        headers: rootHeaders({
          "Content-Type": "application/json",
          Accept: "application/json",
        }),
        body: JSON.stringify({
          oldName: storeTypeName,
          name: storeTypeName,
          categories: state.storeTypeDraftCategories,
          categoryDetails,
        }),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(data.message || "Unable to update categories.");
      }

      setStoreTypeData(
        Array.isArray(data.storeTypes) ? data.storeTypes : state.storeTypes,
        Array.isArray(data.storeTypeDetails) ? data.storeTypeDetails : null,
      );
      if (closeModal) {
        setStoreTypeCategoryModalOpen(false, { restoreFocus: false });
      }
      const successMessage = `Categories for ${storeTypeName} updated.`;
      if (showSuccess) {
        void showSuccessValidationModal(successTitle, successMessage);
      } else {
        setFeedback("");
      }
      return true;
    } catch (error) {
      setFeedback(error instanceof Error ? error.message : "Unable to update categories.", "error");
      elements.storeTypeCategoryInput?.focus();
      return false;
    } finally {
      if (elements.addStoreTypeCategoryButton) {
        elements.addStoreTypeCategoryButton.disabled = false;
      }
    }
  }

  // Moves focus to category panel for keyboard flow.
  function focusCategoryPanel(focusTarget = "panel") {
    if (!elements.categoryPanel) {
      return;
    }

    if (categoryDrawerFocusTimer) {
      window.clearTimeout(categoryDrawerFocusTimer);
    }

    categoryDrawerFocusTimer = window.setTimeout(() => {
      if (focusTarget === "add" && elements.categoryNameInput) {
        elements.categoryNameInput.focus();
        elements.categoryNameInput.select();
        return;
      }

      if (focusTarget === "view") {
        const firstCategoryAction = elements.categoryList?.querySelector(
          ".category-chip__main, .category-chip__edit, .category-chip__delete",
        );
        if (firstCategoryAction instanceof HTMLElement) {
          firstCategoryAction.focus();
          return;
        }
      }

      elements.categoryPanel.focus();
    }, focusTarget === "add" ? 220 : 180);
  }

  // Moves focus to store type panel for keyboard flow.
  function focusStoreTypePanel(focusTarget = "panel") {
    if (!elements.storeTypePanel) {
      return;
    }

    if (storeTypeDrawerFocusTimer) {
      window.clearTimeout(storeTypeDrawerFocusTimer);
    }

    storeTypeDrawerFocusTimer = window.setTimeout(() => {
      if (focusTarget === "add" && elements.storeTypeNameInput) {
        elements.storeTypeNameInput.focus();
        elements.storeTypeNameInput.select();
        return;
      }

      if (focusTarget === "view") {
        const firstStoreTypeAction = elements.storeTypeList?.querySelector(
          ".category-chip__main, .category-chip__edit, .category-chip__delete",
        );
        if (firstStoreTypeAction instanceof HTMLElement) {
          firstStoreTypeAction.focus();
          return;
        }
      }

      elements.storeTypePanel.focus();
    }, focusTarget === "add" ? 220 : 180);
  }

  // Updates category drawer open and synchronizes related UI state.
  function setCategoryDrawerOpen(isOpen, options = {}) {
    if (!elements.categoryPanel) {
      return;
    }

    const { focusTarget = "panel", restoreFocus = false } = options;
    const nextIsOpen = Boolean(isOpen);

    if (nextIsOpen) {
      setStoreTypeDrawerOpen(false);
    }

    if (categoryDrawerCloseTimer) {
      window.clearTimeout(categoryDrawerCloseTimer);
      categoryDrawerCloseTimer = 0;
    }

    for (const button of getCategoryTriggerButtons()) {
      button.setAttribute("aria-expanded", nextIsOpen ? "true" : "false");
    }

    if (nextIsOpen) {
      elements.categoryPanel.hidden = false;
      elements.categoryPanel.setAttribute("aria-hidden", "false");
      elements.categoryPanel.classList.remove("is-closing");
      window.requestAnimationFrame(() => {
        elements.categoryPanel.classList.add("is-open");
      });
      focusCategoryPanel(focusTarget);
      if (!state.categories.length && !state.categoriesLoading) {
        void loadCategories({ quiet: true });
      }
      return;
    }

    elements.categoryPanel.classList.remove("is-open");
    elements.categoryPanel.classList.add("is-closing");
    elements.categoryPanel.setAttribute("aria-hidden", "true");

    if (categoryDrawerFocusTimer) {
      window.clearTimeout(categoryDrawerFocusTimer);
      categoryDrawerFocusTimer = 0;
    }

    categoryDrawerCloseTimer = window.setTimeout(() => {
      elements.categoryPanel.hidden = true;
      elements.categoryPanel.classList.remove("is-closing");
      categoryDrawerCloseTimer = 0;
      if (restoreFocus) {
        getCategoryTriggerButtons()[0]?.focus();
      }
    }, 240);
  }

  // Updates store type drawer open and synchronizes related UI state.
  function setStoreTypeDrawerOpen(isOpen, options = {}) {
    if (!elements.storeTypePanel) {
      return;
    }

    const { focusTarget = "panel", restoreFocus = false } = options;
    const nextIsOpen = Boolean(isOpen);

    if (nextIsOpen) {
      setCategoryDrawerOpen(false);
    }

    if (storeTypeDrawerCloseTimer) {
      window.clearTimeout(storeTypeDrawerCloseTimer);
      storeTypeDrawerCloseTimer = 0;
    }

    for (const button of getStoreTypeTriggerButtons()) {
      button.setAttribute("aria-expanded", nextIsOpen ? "true" : "false");
    }

    if (nextIsOpen) {
      elements.storeTypePanel.hidden = false;
      elements.storeTypePanel.setAttribute("aria-hidden", "false");
      elements.storeTypePanel.classList.remove("is-closing");
      window.requestAnimationFrame(() => {
        elements.storeTypePanel.classList.add("is-open");
      });
      focusStoreTypePanel(focusTarget);
      if (!state.storeTypes.length && !state.storeTypesLoading) {
        void loadStoreTypes({ quiet: true });
      }
      return;
    }

    elements.storeTypePanel.classList.remove("is-open");
    elements.storeTypePanel.classList.add("is-closing");
    elements.storeTypePanel.setAttribute("aria-hidden", "true");

    if (storeTypeDrawerFocusTimer) {
      window.clearTimeout(storeTypeDrawerFocusTimer);
      storeTypeDrawerFocusTimer = 0;
    }

    storeTypeDrawerCloseTimer = window.setTimeout(() => {
      elements.storeTypePanel.hidden = true;
      elements.storeTypePanel.classList.remove("is-closing");
      storeTypeDrawerCloseTimer = 0;
      if (restoreFocus) {
        getStoreTypeTriggerButtons()[0]?.focus();
      }
    }, 240);
  }

  // Checks whether category drawer visible is true for the current record or UI state.
  function isCategoryDrawerVisible() {
    return elements.categoryPanel instanceof HTMLElement && !elements.categoryPanel.hidden;
  }

  // Checks whether store type drawer visible is true for the current record or UI state.
  function isStoreTypeDrawerVisible() {
    return elements.storeTypePanel instanceof HTMLElement && !elements.storeTypePanel.hidden;
  }

  // Reads or derives visible drawer list for the current super admin flow.
  function getVisibleDrawerList() {
    if (isCategoryDrawerVisible()) {
      return elements.categoryList;
    }
    if (isStoreTypeDrawerVisible()) {
      return elements.storeTypeList;
    }
    return null;
  }

  // Checks whether the current interaction can scroll category list.
  function canScrollCategoryList(event) {
    const drawerList = getVisibleDrawerList();
    if (!(drawerList instanceof HTMLElement) || !(event instanceof WheelEvent)) {
      return false;
    }

    const deltaY = event.deltaY;
    if (!deltaY) {
      return false;
    }

    const maxScrollTop = drawerList.scrollHeight - drawerList.clientHeight;
    if (maxScrollTop <= 0) {
      return false;
    }

    return deltaY > 0
      ? drawerList.scrollTop < maxScrollTop
      : drawerList.scrollTop > 0;
  }

  // Blocks category drawer background scroll while modal drawers are active.
  function blockCategoryDrawerBackgroundScroll(event) {
    if (!isCategoryDrawerVisible() && !isStoreTypeDrawerVisible()) {
      return;
    }

    if (isEventWithinElement(event, getVisibleDrawerList()) && canScrollCategoryList(event)) {
      return;
    }

    event.preventDefault();
  }

  // Blocks mouse-wheel page movement while filtered company pages keep a fixed viewport.
  function blockSuperAdminNavOpenWheel(event) {
    if (
      !document.body.classList.contains("super-admin-nav-open") ||
      !document.body.classList.contains("super-admin-company-pagination-active")
    ) {
      return;
    }

    const scrollSnapshot = getSuperAdminScrollSnapshot();
    event.preventDefault();
    event.stopPropagation();
    restoreSuperAdminScrollSnapshot(scrollSnapshot);
    window.requestAnimationFrame(() => restoreSuperAdminScrollSnapshot(scrollSnapshot));
  }

  // Closes buyer quick-action menus from the super-admin shell before wheel blockers can freeze page scroll.
  function closeUserDataActionMenusForWheel() {
    const dropdowns = Array.from(document.querySelectorAll(".buyer-data-actions")).filter((dropdown) => {
      const menu = dropdown?.querySelector?.("[data-buyer-menu]");
      return dropdown instanceof HTMLElement
        && (dropdown.classList.contains("is-open") || (menu instanceof HTMLElement && !menu.hidden));
    });
    if (!dropdowns.length) {
      return;
    }

    for (const dropdown of dropdowns) {
      if (!(dropdown instanceof HTMLElement)) {
        continue;
      }
      dropdown.classList.remove("is-open");
      const toggle = dropdown.querySelector("[data-buyer-menu-toggle]");
      if (toggle instanceof HTMLElement) {
        toggle.setAttribute("aria-expanded", "false");
      }
      const menu = dropdown.querySelector("[data-buyer-menu]");
      if (menu instanceof HTMLElement) {
        menu.hidden = true;
        menu.classList.remove(
          "is-positioning",
          "is-cursor-positioned",
          "is-fixed-positioned",
          "is-trigger-positioned",
          "is-open-up",
        );
        for (const property of [
          "position",
          "top",
          "right",
          "bottom",
          "left",
          "transform",
          "transform-origin",
          "visibility",
          "--company-action-menu-arrow-left",
        ]) {
          menu.style.removeProperty(property);
        }
      }
    }
  }

  // Prevents hover-only quick actions from staying visible while the user scrolls the user-data list.
  function suppressUserDataQuickActionsForWheel() {
    if (!document.body.classList.contains("super-admin-user-data-active")) {
      return;
    }
    document.body.classList.add("super-admin-user-data-wheel-active");
  }

  function clearUserDataQuickActionWheelSuppression() {
    document.body.classList.remove("super-admin-user-data-wheel-active");
  }

  function handleUserDataActionWheel() {
    closeUserDataActionMenusForWheel();
    suppressUserDataQuickActionsForWheel();
  }

  // Blocks category drawer background key scroll while modal drawers are active.
  function blockCategoryDrawerBackgroundKeyScroll(event) {
    if (
      !isCategoryDrawerVisible()
      && !isStoreTypeDrawerVisible()
      || isEventWithinElement(event, elements.categoryPanel)
      || isEventWithinElement(event, elements.storeTypePanel)
      || !categoryDrawerScrollLockKeys.has(event.key)
    ) {
      return;
    }

    event.preventDefault();
  }

  // Supports the number text branch of the super admin UI.
  function numberText(value) {
    const numberValue = Number(value);
    return Number.isFinite(numberValue) ? numberValue.toLocaleString() : "0";
  }

  const superAdminTrendArrowMarkup = Object.freeze({
    up: `
      <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-arrow-up-icon lucide-arrow-up" aria-hidden="true">
        <path d="m5 12 7-7 7 7"></path>
        <path d="M12 19V5"></path>
      </svg>
    `,
    down: `
      <svg xmlns="http://www.w3.org/2000/svg" width="256" height="256" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-arrow-down-icon lucide-arrow-down" aria-hidden="true">
        <path d="M12 5v14"></path>
        <path d="m19 12-7 7-7-7"></path>
      </svg>
    `,
  });

  function setSuperAdminRawTrendPair(target, upValue = 0, downValue = 0) {
    if (!(target instanceof HTMLElement)) {
      return;
    }
    target.textContent = "";
    target.classList.add("is-raw-pair");
    [
      ["up", upValue],
      ["down", downValue],
    ].forEach(([direction, value]) => {
      const item = document.createElement("span");
      item.className = `super-admin-stat__trend-number is-${direction}`;
      item.innerHTML = superAdminTrendArrowMarkup[direction];
      const number = document.createElement("span");
      number.className = "super-admin-stat__trend-number-value";
      number.textContent = numberText(Math.abs(Math.trunc(Number(value) || 0)));
      item.appendChild(number);
      target.appendChild(item);
    });
  }

  window.GMSSuperAdminStatTrend = Object.freeze({
    setRawPair: setSuperAdminRawTrendPair,
  });

  window.GMSSuperAdminNavNewBadge = Object.freeze({
    sync: syncSuperAdminNavNewBadge,
    syncSubNavItem: syncSuperAdminSubNavNewItem,
  });

  // Supports the money text branch of the super admin UI.
  function moneyText(value) {
    const numberValue = Number(value);
    return Number.isFinite(numberValue)
      ? `\u20B1 ${numberValue.toLocaleString(undefined, {
          minimumFractionDigits: 2,
          maximumFractionDigits: 2,
        })}`
      : "\u20B1 0.00";
  }

  // Formats date time for display.
  function formatDateTime(value) {
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) {
      return "No date";
    }

    return date.toLocaleString(undefined, {
      month: "short",
      day: "numeric",
      year: "numeric",
      hour: "numeric",
      minute: "2-digit",
    });
  }

  // Formats relative time for display.
  function formatRelativeTime(value) {
    const date = new Date(value);
    const timestamp = date.getTime();
    if (Number.isNaN(timestamp)) {
      return "Never";
    }

    const elapsedSeconds = Math.max(0, Math.floor((Date.now() - timestamp) / 1000));
    if (elapsedSeconds < 45) {
      return "Just now";
    }

    const units = [
      ["year", 31536000],
      ["month", 2592000],
      ["day", 86400],
      ["hour", 3600],
      ["min", 60],
    ];

    for (const [unit, seconds] of units) {
      const amount = Math.floor(elapsedSeconds / seconds);
      if (amount >= 1) {
        return `${numberText(amount)} ${unit}${amount === 1 ? "" : "s"} ago`;
      }
    }

    return "Just now";
  }

  // Formats short relative time for display.
  function formatShortRelativeTime(value) {
    const date = new Date(value);
    const timestamp = date.getTime();
    if (Number.isNaN(timestamp)) {
      return "Never";
    }

    const elapsedSeconds = Math.max(0, Math.floor((Date.now() - timestamp) / 1000));
    if (elapsedSeconds < 45) {
      return "now";
    }

    const units = [
      ["y", 31536000],
      ["mo", 2592000],
      ["d", 86400],
      ["h", 3600],
      ["m", 60],
    ];

    for (const [unit, seconds] of units) {
      const amount = Math.floor(elapsedSeconds / seconds);
      if (amount >= 1) {
        return `${numberText(amount)}${unit} ago`;
      }
    }

    return "now";
  }

  // Reads or derives product image url for the current super admin flow.
  function normalizeSaCardImagePosition(value, fallback = 50) {
    const normalizedValue = Number(value ?? fallback);
    if (!Number.isFinite(normalizedValue)) {
      return fallback;
    }
    return Math.min(100, Math.max(0, normalizedValue));
  }

  function formatSaCardImageObjectPosition(positionX, positionY) {
    return `${normalizeSaCardImagePosition(positionX, 50).toFixed(2)}% ${normalizeSaCardImagePosition(positionY, 50).toFixed(2)}%`;
  }

  function getProductMainGalleryImageUrl(product) {
    const imageUrls = normalizeProductDetailUrlList(product?.imageUrls);
    const mainIndex = imageUrls.length
      ? Math.max(0, Math.min(imageUrls.length - 1, Math.trunc(Number(product?.mainImageIndex) || 0)))
      : 0;
    return (
      String(product?.mainImageUrl || "").trim() ||
      (imageUrls.length ? imageUrls[mainIndex] : "") ||
      String(product?.imageUrl || "").trim() ||
      imageUrls[0] ||
      ""
    );
  }

  function getProductEvidenceOverrideImageUrl(product) {
    return [
      Array.isArray(product?.superAdminUploadedImageUrls)
        ? product.superAdminUploadedImageUrls[product.superAdminUploadedImageUrls.length - 1]
        : "",
      Array.isArray(product?.yoloInspection?.rejectedEvidenceImageUrls)
        ? product.yoloInspection.rejectedEvidenceImageUrls[
            product.yoloInspection.rejectedEvidenceImageUrls.length - 1
          ]
        : "",
      Array.isArray(product?.yoloInspection?.approvedEvidence?.imageUrls)
        ? product.yoloInspection.approvedEvidence.imageUrls[
            product.yoloInspection.approvedEvidence.imageUrls.length - 1
          ]
        : "",
    ]
      .map((value) => String(value || "").trim())
      .find(Boolean) || "";
  }

  // Mirrors seller getProductCardDisplayImageData: cropped card file, else gallery + focal position.
  function getProductCardDisplayImageData(product) {
    const evidenceUrl = getProductEvidenceOverrideImageUrl(product);
    const cardImageUrl = String(product?.cardImageUrl || "").trim();
    const mainImageUrl = getProductMainGalleryImageUrl(product);

    if (cardImageUrl) {
      return {
        imageUrl: cardImageUrl,
        objectPosition: "center center",
        isCropped: true,
      };
    }

    if (mainImageUrl) {
      return {
        imageUrl: mainImageUrl,
        objectPosition: formatSaCardImageObjectPosition(
          product?.cardImagePositionX,
          product?.cardImagePosition,
        ),
        isCropped: false,
      };
    }

    if (evidenceUrl) {
      return {
        imageUrl: evidenceUrl,
        objectPosition: "center center",
        isCropped: true,
      };
    }

    return {
      imageUrl: "",
      objectPosition: "50% 50%",
      isCropped: false,
    };
  }

  function getProductListingCardSnapshot(product) {
    const listingImageUrls = normalizeProductDetailUrlList(
      Array.isArray(product?.listingImageUrls) && product.listingImageUrls.length
        ? product.listingImageUrls
        : null,
    );
    const listingDetailsImageCrops = Array.isArray(product?.listingDetailsImageCrops)
      ? product.listingDetailsImageCrops
      : Array.isArray(product?.detailsImageCrops)
        ? product.detailsImageCrops
        : [];
    return {
      listingImageUrls,
      listingMainImageUrl: String(
        product?.listingMainImageUrl || listingImageUrls[0] || "",
      ).trim(),
      listingCardImageUrl: String(
        product?.listingCardImageUrl || product?.cardImageUrl || "",
      ).trim(),
      listingCardImageSourceUrl: String(
        product?.listingCardImageSourceUrl || product?.cardImageSourceUrl || "",
      ).trim(),
      listingCardImagePositionX:
        product?.listingCardImagePositionX ?? product?.cardImagePositionX,
      listingCardImagePosition:
        product?.listingCardImagePosition ?? product?.cardImagePosition,
      listingDetailsImageCrops,
    };
  }

  function getProductListingCropMap(product) {
    const cropMap = new Map();
    const snapshot = getProductListingCardSnapshot(product);
    for (const crop of snapshot.listingDetailsImageCrops) {
      const sourceUrl = String(crop?.sourceUrl || "").trim();
      const croppedImageUrl = String(crop?.croppedImageUrl || "").trim();
      if (!sourceUrl || !croppedImageUrl) {
        continue;
      }
      const key = sourceUrl.toLowerCase();
      if (cropMap.has(key)) {
        continue;
      }
      cropMap.set(key, {
        sourceUrl,
        croppedImageUrl,
        objectPosition: "center center",
      });
    }
    return cropMap;
  }

  function getProductSellerFullUploadImageUrl(product) {
    return [
      product?.cardImageSourceUrl,
      product?.listingCardImageSourceUrl,
      Array.isArray(product?.yoloInspection?.approvedEvidence?.imageUrls)
        ? product.yoloInspection.approvedEvidence.imageUrls[0]
        : "",
      Array.isArray(product?.yoloInspection?.rejectedEvidenceImageUrls)
        ? product.yoloInspection.rejectedEvidenceImageUrls[
            product.yoloInspection.rejectedEvidenceImageUrls.length - 1
          ]
        : "",
      Array.isArray(product?.yoloInspection?.imageUrls)
        ? product.yoloInspection.imageUrls[0]
        : "",
      product?.mainImageUrl,
      product?.imageUrl,
    ]
      .map((value) => String(value || "").trim())
      .find(Boolean) || "";
  }

  // Approved/Rejected cards: show seller listing crop; zoom opens full seller upload.
  function getProductHistoryCardDisplayImageData(product) {
    const zoomImageUrl = String(
      product?.imageUrl || product?.mainImageUrl || getProductMainGalleryImageUrl(product) || "",
    ).trim();
    const uploadedImageUrls = getProductSuperAdminUploadedImageUrls(product).map((url) =>
      String(url || "").trim().toLowerCase(),
    );
    if (zoomImageUrl && uploadedImageUrls.includes(zoomImageUrl.toLowerCase())) {
      return {
        imageUrl: zoomImageUrl,
        objectPosition: "center center",
        isCropped: false,
        zoomImageUrl,
      };
    }

    const snapshot = getProductListingCardSnapshot(product);
    const cropMap = getProductListingCropMap(product);
    if (zoomImageUrl) {
      const matchedCrop = cropMap.get(zoomImageUrl.toLowerCase());
      if (matchedCrop?.croppedImageUrl) {
        return {
          imageUrl: matchedCrop.croppedImageUrl,
          objectPosition: matchedCrop.objectPosition,
          isCropped: true,
          zoomImageUrl,
        };
      }
    }

    if (
      snapshot.listingCardImageUrl &&
      snapshot.listingCardImageSourceUrl &&
      (
        !zoomImageUrl ||
        snapshot.listingCardImageSourceUrl.toLowerCase() === zoomImageUrl.toLowerCase()
      )
    ) {
      return {
        imageUrl: snapshot.listingCardImageUrl,
        objectPosition: "center center",
        isCropped: true,
        zoomImageUrl: snapshot.listingCardImageSourceUrl || zoomImageUrl,
      };
    }

    const trainingIndex = Math.max(
      0,
      Math.trunc(
        Number(
          product?.approvedTrainingImageIndex ??
            product?.rejectedTrainingImageIndex ??
            1,
        ) || 1,
      ) - 1,
    );
    const trainingCount = Math.max(
      1,
      Math.trunc(
        Number(
          product?.approvedTrainingImageCount ??
            product?.rejectedTrainingImageCount ??
            1,
        ) || 1,
      ),
    );
    const listingUrls = snapshot.listingImageUrls;
    const listingByIndex =
      listingUrls.length && trainingIndex < listingUrls.length
        ? String(listingUrls[trainingIndex] || "").trim()
        : "";

    if (
      listingByIndex &&
      zoomImageUrl &&
      listingByIndex.toLowerCase() !== zoomImageUrl.toLowerCase() &&
      (trainingCount === listingUrls.length || listingUrls.length === 1)
    ) {
      const useCardCrop =
        Boolean(snapshot.listingCardImageUrl) &&
        (
          !snapshot.listingCardImageSourceUrl ||
          snapshot.listingCardImageSourceUrl.toLowerCase() === zoomImageUrl.toLowerCase() ||
          trainingIndex === 0
        );
      return {
        imageUrl: useCardCrop && trainingIndex === 0
          ? snapshot.listingCardImageUrl
          : listingByIndex,
        objectPosition: useCardCrop && trainingIndex === 0
          ? "center center"
          : formatSaCardImageObjectPosition(
              snapshot.listingCardImagePositionX,
              snapshot.listingCardImagePosition,
            ),
        isCropped: true,
        zoomImageUrl,
      };
    }

    if (
      snapshot.listingMainImageUrl &&
      zoomImageUrl &&
      snapshot.listingMainImageUrl.toLowerCase() !== zoomImageUrl.toLowerCase() &&
      trainingCount === 1 &&
      listingUrls.length <= 1
    ) {
      return {
        imageUrl: snapshot.listingCardImageUrl || snapshot.listingMainImageUrl,
        objectPosition: snapshot.listingCardImageUrl
          ? "center center"
          : formatSaCardImageObjectPosition(
              snapshot.listingCardImagePositionX,
              snapshot.listingCardImagePosition,
            ),
        isCropped: true,
        zoomImageUrl,
      };
    }

    const fallback = getProductCardDisplayImageData(product);
    const fullUploadUrl = getProductSellerFullUploadImageUrl(product);
    const resolvedZoom =
      (fullUploadUrl &&
        fallback.imageUrl &&
        fullUploadUrl.toLowerCase() !== fallback.imageUrl.toLowerCase()
        ? fullUploadUrl
        : "") ||
      String(product?.cardImageSourceUrl || snapshot.listingCardImageSourceUrl || "").trim() ||
      zoomImageUrl ||
      fallback.imageUrl;
    return {
      ...fallback,
      zoomImageUrl: resolvedZoom,
    };
  }

  function getProductCardZoomImageUrl(product, cardDisplay = null) {
    const display = cardDisplay || getProductCardDisplayImageData(product);
    const explicitZoom = String(display?.zoomImageUrl || "").trim();
    if (explicitZoom) {
      return explicitZoom;
    }

    const cardImageUrl = String(display?.imageUrl || "").trim();
    const cardSourceUrl = String(
      product?.cardImageSourceUrl || product?.listingCardImageSourceUrl || "",
    ).trim();
    if (cardImageUrl && cardSourceUrl && display?.isCropped) {
      return cardSourceUrl;
    }

    const cropMap = getProductListingCropMap(product);
    for (const crop of cropMap.values()) {
      if (
        cardImageUrl &&
        String(crop.croppedImageUrl || "").trim().toLowerCase() === cardImageUrl.toLowerCase()
      ) {
        return String(crop.sourceUrl || "").trim() || cardImageUrl;
      }
    }

    return (
      cardSourceUrl ||
      String(product?.imageUrl || product?.mainImageUrl || "").trim() ||
      cardImageUrl ||
      getProductMainGalleryImageUrl(product)
    );
  }

  function getProductDetailsCropBySourceUrl(product) {
    const cropMap = new Map();
    const crops = Array.isArray(product?.detailsImageCrops) ? product.detailsImageCrops : [];
    for (const crop of crops) {
      const sourceUrl = String(crop?.sourceUrl || "").trim();
      const croppedImageUrl = String(crop?.croppedImageUrl || "").trim();
      if (!sourceUrl || !croppedImageUrl) {
        continue;
      }
      const key = sourceUrl.toLowerCase();
      if (cropMap.has(key)) {
        continue;
      }
      cropMap.set(key, {
        sourceUrl,
        croppedImageUrl,
        objectPosition: "center center",
      });
    }
    return cropMap;
  }

  function getProductOrderedGalleryImageUrls(product) {
    const imageUrls = normalizeProductDetailUrlList(product?.imageUrls);
    const mainImageUrl = getProductMainGalleryImageUrl(product);
    const ordered = [];
    const seen = new Set();
    const pushUrl = (value) => {
      const url = String(value || "").trim();
      if (!url) {
        return;
      }
      const key = url.toLowerCase();
      if (seen.has(key)) {
        return;
      }
      seen.add(key);
      ordered.push(url);
    };
    pushUrl(mainImageUrl);
    imageUrls.forEach(pushUrl);
    pushUrl(product?.imageUrl);
    return ordered;
  }

  function getProductImageUrl(product) {
    return getProductEvidenceOverrideImageUrl(product) || getProductCardDisplayImageData(product).imageUrl;
  }

  function getProductSuperAdminUploadedImageUrls(product) {
    return normalizeProductDetailUrlList(product?.superAdminUploadedImageUrls);
  }

  function getProductRequestUploadTargetId(product) {
    return String(
      product?.sourceProductId ||
      product?.approvedTrainingSourceProductId ||
      product?.id ||
      "",
    ).trim();
  }

  function hasProductSuperAdminUploadedImageBadge(product, imageUrl = "") {
    const uploadedImageUrls = getProductSuperAdminUploadedImageUrls(product);
    if (!uploadedImageUrls.length) {
      return Boolean(String(product?.superAdminImageUploadedAt || "").trim());
    }

    const currentImageUrl = String(imageUrl || getProductImageUrl(product) || "").trim().toLowerCase();
    const isSplitEvidenceCard = Boolean(
      (
        Number(product?.approvedTrainingImageCount || 0) > 1 &&
        String(product?.approvedTrainingSourceProductId || product?.sourceProductId || "").trim()
      ) ||
      (
        Number(product?.rejectedTrainingImageCount || 0) > 1 &&
        String(product?.rejectedTrainingSourceProductId || product?.sourceProductId || "").trim()
      ),
    );
    if (isSplitEvidenceCard && currentImageUrl) {
      return uploadedImageUrls.some((uploadedImageUrl) =>
        String(uploadedImageUrl || "").trim().toLowerCase() === currentImageUrl
      );
    }

    return true;
  }

  // Reads or derives product company label for the current super admin flow.
  function getProductCompanyLabel(product) {
    const companyAdmin = getProductCompanyAdmin(product);
    if (companyAdmin) {
      return getCompanyName(companyAdmin);
    }
    return String(
      product?.companyName ||
        product?.storeName ||
        product?.businessName ||
        product?.adminId ||
        "Company",
    ).trim();
  }

  // Reads or derives product company image url for the current super admin flow.
  function getProductCompanyImageUrl(product) {
    const companyAdmin = getProductCompanyAdmin(product);
    // The company account is the single source of truth. Product snapshots can
    // become stale after a seller changes or removes the company profile photo.
    return companyAdmin ? getCompanyImageUrl(companyAdmin) : "";
  }

  // Reads or derives product company initials for the current super admin flow.
  function getProductCompanyInitials(product) {
    const companyName = getProductCompanyLabel(product);
    return companyName
      .split(/\s+/)
      .filter(Boolean)
      .slice(0, 2)
      .map((part) => part.charAt(0).toUpperCase())
      .join("") || "CO";
  }

  function setProductCompanyAvatar(avatar, imageUrl, companyName) {
    if (!(avatar instanceof HTMLElement)) {
      return;
    }
    avatar.textContent = "";
    avatar.classList.remove("has-image");
    const normalizedImageUrl = String(imageUrl || "").trim();
    if (!normalizedImageUrl) {
      setCompanyLogoPlaceholder(avatar);
      return;
    }
    const image = document.createElement("img");
    image.src = normalizedImageUrl;
    image.alt = `${companyName || "Company"} picture`;
    image.loading = "lazy";
    image.addEventListener("error", () => {
      image.remove();
      avatar.classList.remove("has-image");
      setCompanyLogoPlaceholder(avatar);
    }, { once: true });
    avatar.classList.add("has-image");
    avatar.append(image);
  }

  // Reads or derives product category label for the current super admin flow.
  function getProductCategoryLabel(product) {
    const categories = Array.isArray(product?.categories)
      ? product.categories.map((category) => String(category || "").trim()).filter(Boolean)
      : [];
    const visibleCategories = categories.filter(
      (category) => category.toLowerCase() !== "food",
    );
    const fallbackCategory = String(product?.category || "").trim();
    if (
      fallbackCategory &&
      fallbackCategory.toLowerCase() !== "food" &&
      !visibleCategories.some(
        (category) => category.toLowerCase() === fallbackCategory.toLowerCase(),
      )
    ) {
      visibleCategories.push(fallbackCategory);
    }

    return visibleCategories.join(", ");
  }

  function getProductDetailTags(product) {
    const tags = [];
    const seen = new Set();
    const appendTag = (value) => {
      const tag = String(value || "").trim();
      const key = tag.toLowerCase();
      if (!tag || key === "food" || seen.has(key)) {
        return;
      }
      seen.add(key);
      tags.push(tag);
    };

    if (Array.isArray(product?.tags)) {
      product.tags.forEach(appendTag);
    }
    if (Array.isArray(product?.categories)) {
      product.categories.forEach(appendTag);
    }
    appendTag(product?.category);
    return tags;
  }

  // Reads or derives product stock for the current super admin flow.
  function getProductStock(product) {
    const stock = Number(product?.inventoryStock ?? product?.stock ?? 0);
    return Number.isFinite(stock) && stock >= 0 ? Math.trunc(stock) : 0;
  }

  // Reads or derives product rating score clamped to 0..5 (supports decimals).
  function normalizeProductRatingScore(productOrRating) {
    if (typeof productOrRating === "number" || typeof productOrRating === "string") {
      const numericRating = Number(productOrRating);
      return Number.isFinite(numericRating)
        ? Math.min(5, Math.max(0, numericRating))
        : 0;
    }

    const ratingCount = Number(
      productOrRating?.ratingCount
      ?? productOrRating?.ratingsCount
      ?? productOrRating?.reviewRatingCount
      ?? productOrRating?.productRatingCount,
    );
    const ratingPoints = Number(
      productOrRating?.ratingPoints
      ?? productOrRating?.totalRatingPoints
      ?? productOrRating?.productRatingPoints,
    );
    let rating = Number.isFinite(ratingCount) && ratingCount > 0 && Number.isFinite(ratingPoints)
      ? ratingPoints / ratingCount
      : Number(
        productOrRating?.rating
        ?? productOrRating?.productRating
        ?? productOrRating?.averageRating
        ?? productOrRating?.ratingAverage
        ?? productOrRating?.ratingsAverage
        ?? 0,
      );

    if ((!Number.isFinite(rating) || rating <= 0) && Array.isArray(productOrRating?.reviews)) {
      const reviewRatings = productOrRating.reviews
        .map((review) => Number(review?.rating ?? review?.productRating ?? review?.reviewRating))
        .filter((reviewRating) => Number.isFinite(reviewRating) && reviewRating > 0);
      if (reviewRatings.length) {
        rating = reviewRatings.reduce((total, reviewRating) => total + reviewRating, 0) / reviewRatings.length;
      }
    }
    if (!Number.isFinite(rating) || rating <= 0) {
      return 0;
    }
    return Math.min(5, Math.max(0, rating));
  }

  function getProductRatingFillPercent(rating, starIndex) {
    const rawFill = (normalizeProductRatingScore(rating) - Number(starIndex || 0)) * 100;
    return Math.round(Math.max(0, Math.min(100, rawFill)));
  }

  function createProductRatingStarMarkup(rating) {
    const stars = Array.from({ length: 5 }, (_, starIndex) => {
      const fillPercent = getProductRatingFillPercent(rating, starIndex);
      return `
        <span class="super-admin-product-rating-star" style="--star-fill: ${fillPercent}%" aria-hidden="true">
          <span class="super-admin-product-rating-star__base">${createIconSvg(companyCardIconPaths.rating)}</span>
          <span class="super-admin-product-rating-star__fill">${createIconSvg(companyCardIconPaths.rating)}</span>
        </span>
      `;
    }).join("");
    return `<span class="super-admin-product-rating__stars" aria-hidden="true">${stars}</span>`;
  }

  // Reads or derives product rating label for the current super admin flow.
  function getProductRatingLabel(product) {
    const rating = normalizeProductRatingScore(product);
    if (rating <= 0) {
      return "New";
    }
    return rating.toFixed(1);
  }

  function getProductRatingDetailLabel(product) {
    return normalizeProductRatingScore(product).toFixed(1);
  }

  function createProductRatingDisplayElement(product, options = {}) {
    const score = normalizeProductRatingScore(product);
    const ratingText = score > 0
      ? score.toFixed(1)
      : String(options.emptyText ?? "0.0");
    const value = document.createElement("span");
    value.className = `super-admin-product-rating ${String(options.className || "").trim()}`.trim();
    value.setAttribute("aria-label", score > 0 ? `${ratingText} out of 5 stars` : ratingText);
    const starsMarkup = createProductRatingStarMarkup(score);
    const ratingValueMarkup = '<span class="super-admin-product-rating__value"></span>';
    value.innerHTML = options.valueFirst === true
      ? `${ratingValueMarkup}${starsMarkup}`
      : `${starsMarkup}${ratingValueMarkup}`;
    const text = value.querySelector(".super-admin-product-rating__value");
    if (text) {
      text.textContent = ratingText;
    }
    return value;
  }

  function createProductDetailRatingValue(product) {
    return createProductRatingDisplayElement(product, {
      className: "super-admin-product-detail-modal__rating-value",
      emptyText: "0.0",
    });
  }

  // Switches the visible super admin branch and keeps nav/body state in sync.
  function setActiveSection(sectionName) {
    const nextSection = sectionNames.has(sectionName) ? sectionName : "dashboard";
    state.activeSection = nextSection;
    saveSuperAdminActiveSection(nextSection);
    document.body.classList.toggle("super-admin-dashboard-active", nextSection === "dashboard");
    document.body.classList.toggle("super-admin-companies-active", nextSection === "companies");
    document.body.classList.toggle("super-admin-store-types-active", nextSection === "store-types");
    document.body.classList.toggle("super-admin-platforms-active", nextSection === "platforms");
    document.body.classList.toggle("super-admin-trending-searches-active", nextSection === "trending-searches");
    document.body.classList.toggle("super-admin-vouchers-active", nextSection === "vouchers");
    document.body.classList.toggle("super-admin-flash-deals-active", nextSection === "flash-deals");
    document.body.classList.toggle("super-admin-product-requests-active", nextSection === "product-requests");
    document.body.classList.toggle("super-admin-payment-partners-active", nextSection === "payment-partners");
    document.body.classList.toggle("super-admin-delivery-partners-active", nextSection === "delivery-partners");
    document.body.classList.toggle("super-admin-ai-integration-active", nextSection === "ai-integration");
    document.body.classList.toggle("super-admin-seller-feedback-active", nextSection === "seller-feedback");
    document.body.classList.toggle("super-admin-user-feedback-active", nextSection === "user-feedback");
    document.body.classList.toggle("super-admin-user-data-active", nextSection === "user-data");
    document.body.classList.toggle("super-admin-settings-active", nextSection === "settings");
    togglePlatformFeedbackFilterDropdown(false);
    if (nextSection !== "trending-searches") {
      window.SuperAdminTrendingSearches?.closeFilter?.();
    }
    const nextHash = `#${nextSection}`;
    if (window.location.hash !== nextHash && window.history?.replaceState) {
      window.history.replaceState(null, "", nextHash);
    }

    for (const section of elements.sections) {
      section.hidden = section.dataset.superAdminSection !== nextSection;
    }

    for (const navItem of elements.sectionNavItems) {
      const isActive = navItem.dataset.superAdminSectionTarget === nextSection;
      navItem.classList.toggle("is-active", isActive);
      if (isActive) {
        navItem.setAttribute("aria-current", "page");
        navItem.setAttribute("aria-disabled", "true");
        navItem.setAttribute("tabindex", "-1");
      } else {
        navItem.removeAttribute("aria-current");
        navItem.removeAttribute("aria-disabled");
        navItem.removeAttribute("tabindex");
      }
    }

    const isServicesActive = serviceSectionNames.has(nextSection);
    if (elements.servicesNavToggle) {
      elements.servicesNavToggle.classList.toggle("is-active", isServicesActive);
      elements.servicesNavToggle.setAttribute(
        "aria-expanded",
        isServicesActive ? "true" : "false",
      );
    }

    const isFeedbackActive = feedbackSectionNames.has(nextSection);
    if (elements.feedbackNavToggle) {
      elements.feedbackNavToggle.classList.toggle("is-active", isFeedbackActive);
      elements.feedbackNavToggle.setAttribute(
        "aria-expanded",
        isFeedbackActive ? "true" : "false",
      );
    }

    if (nextSection === "dashboard") {
      renderDashboard();
    }
    if (nextSection === "companies") {
      state.companyStatusNavCollapsed = false;
      syncCompanyBreadcrumb();
      document.body.classList.toggle(
        "super-admin-company-pagination-active",
        normalizeCompanyAccountFilter(state.companyFilters.accountState) !== "all",
      );
    } else {
      closeCompanyDrawer();
      document.body.classList.remove("super-admin-company-pagination-active");
    }
    if (nextSection === "store-types") {
      syncStoreTypeBreadcrumb();
    }
    if (nextSection === "platforms" && !state.platformsLoading) {
      void loadPlatforms({ quiet: true });
    }
    if (nextSection === "settings") {
      renderPlatformColorPalettes();
      if (!state.platformDetails.length && !state.platformsLoading) {
        void loadPlatforms({ quiet: true });
      }
    }
    if (nextSection === "trending-searches") {
      window.SuperAdminTrendingSearches?.bind?.();
      if (!window.SuperAdminTrendingSearches?.loading) {
        void window.SuperAdminTrendingSearches?.load?.({ quiet: true });
      }
    }
    if (nextSection === "vouchers") {
      window.SuperAdminVouchers?.bind?.();
      if (!window.SuperAdminVouchers?.loading) {
        void window.SuperAdminVouchers?.load?.({ quiet: true });
      }
    }
    if (nextSection === "flash-deals") {
      window.SuperAdminFlashDeals?.bind?.();
      if (!window.SuperAdminFlashDeals?.loading) {
        void window.SuperAdminFlashDeals?.load?.({ quiet: true });
      }
    }
    syncCompanyAccountFilterNav();
    syncCompanyStatusNavVisibility();
    if (!["payment-partners", "delivery-partners", "ai-integration", "user-data", "seller-feedback", "user-feedback"].includes(nextSection)) {
      closeIntegratedDrawers();
      closePlatformFeedbackDrawer();
    }

    if (nextSection === "product-requests" && !state.productRequestsLoading) {
      void loadProductRequests({ quiet: true });
    }
    if (nextSection === "store-types" && !state.storeTypesLoading) {
      void loadStoreTypes({ quiet: true });
    }
    if (nextSection === "payment-partners" && !state.paymentPartnersLoading) {
      closeIntegratedDrawers();
      void loadIntegratedPartners("payment", { quiet: true });
      void loadPaymentPartnerApiKeyStatus();
    }
    if (nextSection === "delivery-partners" && !state.deliveryPartnersLoading) {
      closeIntegratedDrawers();
      void loadIntegratedPartners("delivery", { quiet: true });
    }
    if (nextSection === "ai-integration") {
      closeIntegratedDrawers();
      void loadImageEnhancementIntegrationStatus();
    }
    if (nextSection === "seller-feedback" || nextSection === "user-feedback") {
      closeIntegratedDrawers();
      closePlatformFeedbackDrawer();
      syncPlatformFeedbackSearchPlaceholder();
      syncPlatformFeedbackFilterControlsFromState();
      syncPlatformFeedbackFilterSummary();
      togglePlatformFeedbackFilterDropdown(false);
      void loadPlatformFeedback({ quiet: true });
      if (nextSection === "user-feedback" && !state.userAccountsLoading && !state.userAccounts.length) {
        void loadUserAccounts({ quiet: true });
      }
      if (nextSection === "seller-feedback" && !state.loading && !state.admins.length) {
        void loadAdmins({ quiet: true });
      }
    }
    if (nextSection === "user-data") {
      closeIntegratedDrawers();
    }
    if (nextSection === "settings") {
      void loadChatWallpapers();
    }

    window.dispatchEvent(new CustomEvent("gms:super-admin-section-changed", {
      detail: { section: nextSection },
    }));
  }

  // Reads or derives admin counts for the current super admin flow.
  function getAdminCounts(admin) {
    const counts = admin?.counts || {};
    const rating = Number(counts.rating ?? admin?.rating ?? 0);
    const commentCount = Number(
      counts.commentCount ??
      counts.reviewCount ??
      admin?.commentCount ??
      admin?.reviewCount ??
      0,
    );
    return {
      products: Number(counts.products || 0),
      employees: Number(counts.employees || 0),
      orders: Number(counts.orders || 0),
      chats: Number(counts.chatThreads || 0),
      categories: Number(counts.categories || 0),
      followers: Number(admin?.followersCount || 0),
      rating: Number.isFinite(rating) && rating > 0 ? rating : 0,
      commentCount: Number.isFinite(commentCount) && commentCount > 0 ? Math.trunc(commentCount) : 0,
    };
  }

  // Supports the fetch followers count for admin branch of the super admin UI.
  async function fetchFollowersCountForAdmin(adminId) {
    try {
      const response = await fetch(`/api/super-admin/${encodeURIComponent(adminId)}/followers-count`);
      if (response.ok) {
        const data = await response.json();
        return data.followersCount || 0;
      }
    } catch (error) {
      console.error("Error fetching followers count:", error);
    }
    return 0;
  }

  // Loads followers count for admins data and updates local state.
  async function loadFollowersCountForAdmins() {
    const adminIds = state.admins.map((admin) => String(admin?.adminId || admin?.id || "").trim()).filter(Boolean);
    const uniqueAdminIds = [...new Set(adminIds)];

    const followersPromises = uniqueAdminIds.map(async (adminId) => {
      const count = await fetchFollowersCountForAdmin(adminId);
      return { adminId, count };
    });

    const results = await Promise.all(followersPromises);
    const followersMap = {};
    results.forEach(({ adminId, count }) => {
      followersMap[adminId] = count;
    });

    // Update admins with followers count
    state.admins = state.admins.map((admin) => {
      const adminId = String(admin?.adminId || admin?.id || "").trim();
      return {
        ...admin,
        followersCount: followersMap[adminId] || 0,
      };
    });
  }

  // Reads or derives company name for the current super admin flow.
  function getCompanyName(admin) {
    return String(
      admin?.companyName || admin?.storeName || admin?.businessName || admin?.displayName || "Company",
    ).trim();
  }

  // Reads or derives company id for the current super admin flow.
  function getCompanyId(admin) {
    return String(admin?.adminId || admin?.id || "").trim();
  }

  // Reads or derives admin name for the current super admin flow.
  function getAdminName(admin) {
    return String(admin?.displayName || [admin?.firstName, admin?.lastName].filter(Boolean).join(" ")).trim();
  }

  // Reads or derives company contact name for the current super admin flow.
  function getCompanyContactName(admin) {
    return [admin?.firstName, admin?.lastName]
      .map((value) => String(value || "").trim())
      .filter(Boolean)
      .join(" ") || getAdminName(admin) || "No name";
  }

  // Reads or derives company created at for the current super admin flow.
  function getCompanyCreatedAt(admin) {
    return admin?.createdAt || admin?.created_at || admin?.registeredAt || admin?.dateCreated || "";
  }

  function isNewlyRegisteredCompany(admin) {
    const createdAt = parseCompanyDate(getCompanyCreatedAt(admin));
    if (!createdAt) {
      return false;
    }
    return Date.now() - createdAt.getTime() <= companyNewRegistrationWindowMs;
  }

  function getNewlyRegisteredCompanies(admins = state.admins) {
    return (Array.isArray(admins) ? admins : []).filter(isNewlyRegisteredCompany);
  }

  function syncCompanyNewRegistrationNavBadge(admins = state.admins) {
    const newCount = getNewlyRegisteredCompanies(admins).length;
    syncSuperAdminNavNewBadge(elements.companyNavBadge, newCount, "company registrations");
    syncSuperAdminSubNavNewItem(
      elements.companyNewFilterNavItem,
      newCount,
      "company registrations",
    );
    lastCompanyNewRegistrationCount = newCount;
    return newCount;
  }

  function refreshCompanyNewRegistrationState(admins = state.admins) {
    const previousCount = lastCompanyNewRegistrationCount;
    const newCount = syncCompanyNewRegistrationNavBadge(admins);
    if (previousCount === newCount) {
      return;
    }
    if (normalizeCompanyAccountFilter(state.companyFilters.accountState) !== "new") {
      return;
    }
    if (newCount <= 0) {
      setCompanyAccountFilter("all");
      return;
    }
    renderAdmins(admins);
  }

  // Reads or derives company last login at for the current super admin flow.
  function getCompanyLastLoginAt(admin) {
    return (
      admin?.lastLoginAt ||
      admin?.last_login_at ||
      admin?.lastSeenAt ||
      admin?.lastActiveAt ||
      admin?.presenceUpdatedAt ||
      ""
    );
  }

  // Reads or derives company plan label for the current super admin flow.
  function getCompanyPlanLabel(admin) {
    void admin;
    return "Free Plan";
  }

  // Supports the parse company date branch of the super admin UI.
  function parseCompanyDate(value) {
    const date = new Date(value);
    return Number.isNaN(date.getTime()) ? null : date;
  }

  // Checks whether company presence heartbeat is recent enough to count as online.
  function isCompanyPresenceFresh(admin) {
    const presenceDate = parseCompanyDate(
      admin?.presenceUpdatedAt ??
        admin?.lastOnlineAt ??
        admin?.lastSeenAt ??
        admin?.lastActiveAt ??
        admin?.lastLoginAt,
    );
    if (!presenceDate) {
      return false;
    }
    return Date.now() - presenceDate.getTime() <= companyPresenceStaleMs;
  }

  // Reads truthy flag from source data safely.
  function readTruthyFlag(value) {
    return value === true || ["true", "1", "yes"].includes(String(value || "").trim().toLowerCase());
  }

  // Checks whether company temporary ban expired is true for the current record or UI state.
  function isCompanyTemporaryBanExpired(admin) {
    const banType = getCompanyBanType(admin);
    if (banType !== "temporary") {
      return false;
    }
    const expiresAt = getCompanyBanExpiresAt(admin);
    return Boolean(expiresAt && expiresAt.getTime() <= Date.now());
  }

  // Reads or derives company ban type for the current super admin flow.
  function getCompanyBanType(admin) {
    return String(admin?.banType ?? admin?.banMode ?? admin?.ban_mode ?? "")
      .trim()
      .toLowerCase() === "temporary"
      ? "temporary"
      : "permanent";
  }

  // Reads or derives company ban duration unit for the current super admin flow.
  function getCompanyBanDurationUnit(admin) {
    const unit = String(admin?.banDurationUnit ?? admin?.durationUnit ?? admin?.ban_duration_unit ?? "")
      .trim()
      .toLowerCase();
    return unit === "days" || unit === "hours" ? unit : "";
  }

  // Reads or derives company ban expires at for the current super admin flow.
  function getCompanyBanExpiresAt(admin) {
    return parseCompanyDate(
      admin?.banExpiresAt ??
        admin?.ban_expires_at ??
        admin?.banExpiryAt ??
        admin?.bannedUntil ??
        admin?.banUntil,
    );
  }

  // Reads or derives company ban countdown label for the current super admin flow.
  function getCompanyBanCountdownLabel(admin) {
    if (getCompanyBanType(admin) !== "temporary") {
      return "";
    }

    const expiresAt = getCompanyBanExpiresAt(admin);
    const remainingMs = expiresAt ? expiresAt.getTime() - Date.now() : 0;
    if (!Number.isFinite(remainingMs) || remainingMs <= 0) {
      return "";
    }

    const totalSeconds = Math.max(0, Math.ceil(remainingMs / 1000));
    const hours = Math.floor(totalSeconds / 3600);
    const minutes = Math.floor((totalSeconds % 3600) / 60);
    const seconds = totalSeconds % 60;
    const unitLabel = (value, unit) => `${value} ${unit}${value === 1 ? "" : "s"}`;
    return `${unitLabel(hours, "hour")} ${unitLabel(minutes, "minute")} ${unitLabel(seconds, "second")} left`;
  }

  // Reads or derives company ban badge text for the current super admin flow.
  function getCompanyBanBadgeText(admin) {
    if (getCompanyAccountState(admin) !== "banned") {
      return "";
    }

    const countdownLabel = getCompanyBanCountdownLabel(admin);
    return countdownLabel ? `Banned - ${countdownLabel}` : "Banned";
  }

  // Reads or derives company restrict expires at for the current super admin flow.
  function getCompanyRestrictExpiresAt(admin) {
    return parseCompanyDate(
      admin?.restrictExpiresAt ?? admin?.restrictionExpiresAt ?? admin?.restrictedUntil ?? admin?.restrict_expires_at,
    );
  }

  // Normalizes company restriction limit value before comparison or storage.
  function normalizeCompanyRestrictionLimitValue(value) {
    return String(value || "")
      .trim()
      .toLowerCase()
      .replace(/[\s-]+/g, "_");
  }

  // Reads the visible restriction limit label from the dropdown option itself.
  function getCompanyRestrictionLimitOptionLabel(option) {
    if (!(option instanceof HTMLInputElement)) {
      return "";
    }

    const row = option.closest("[data-super-admin-restriction-limit-row]");
    const labelSource = row?.querySelector("strong") || row?.querySelector("span") || row;
    return String(labelSource?.textContent || "")
      .replace(/\s+/g, " ")
      .trim();
  }

  // Finds the matching restriction limit option in the super admin dropdown.
  function getCompanyRestrictionLimitOption(value) {
    const normalizedValue = normalizeCompanyRestrictionLimitValue(value);
    return elements.companyRestrictionLimitOptions.find((option) =>
      option instanceof HTMLInputElement &&
      normalizeCompanyRestrictionLimitValue(option.value) === normalizedValue
    ) || null;
  }

  // Reads or derives company restriction limit label for the current super admin flow.
  function getCompanyRestrictionLimitLabel(value) {
    const normalizedValue = normalizeCompanyRestrictionLimitValue(value);
    const optionLabel = getCompanyRestrictionLimitOptionLabel(
      getCompanyRestrictionLimitOption(normalizedValue),
    );
    if (optionLabel) {
      return optionLabel;
    }
    if (companyRestrictionLimitLabels.has(normalizedValue)) {
      return companyRestrictionLimitLabels.get(normalizedValue);
    }
    return String(value || "")
      .replace(/[_-]+/g, " ")
      .replace(/\s+/g, " ")
      .trim()
      .replace(/\b\w/g, (match) => match.toUpperCase());
  }

  // Reads or derives company restriction limit labels for the current super admin flow.
  function getCompanyRestrictionLimitLabels(admin) {
    const rawLimits = Array.isArray(admin?.restrictionLimits)
      ? admin.restrictionLimits
      : Array.isArray(admin?.restrictLimits)
        ? admin.restrictLimits
        : Array.isArray(admin?.limitedAccess)
          ? admin.limitedAccess
          : String(admin?.restrictionLimits ?? admin?.restrictLimits ?? admin?.limitedAccess ?? "")
            .split(",")
            .map((value) => value.trim())
            .filter(Boolean);
    const rawLabels = Array.isArray(admin?.restrictionLimitLabels)
      ? admin.restrictionLimitLabels
      : Array.isArray(admin?.restrictLimitLabels)
        ? admin.restrictLimitLabels
        : [];
    const labels = rawLabels.length
      ? rawLabels
      : rawLimits.map(getCompanyRestrictionLimitLabel);
    return [...new Set(labels.map((label) => String(label || "").trim()).filter(Boolean))];
  }

  // Checks whether company temporary restriction expired is true for the current record or UI state.
  function isCompanyTemporaryRestrictionExpired(admin) {
    const expiresAt = getCompanyRestrictExpiresAt(admin);
    return Boolean(expiresAt && expiresAt.getTime() <= Date.now());
  }

  // Reads the current seller warning count used for 1-3 restriction level display.
  function getCompanyWarningCount(admin) {
    const countSources = [
      admin?.restrictionWarningCount,
      admin?.restrictionLevelCount,
      admin?.restrictedLevelCount,
      admin?.superAdminWarningCount,
      admin?.warningCount,
      admin?.warnings,
    ];
    let warningCount = 0;

    for (const source of countSources) {
      const numericValue = Array.isArray(source) ? source.length : Number(source);
      if (Number.isFinite(numericValue)) {
        warningCount = Math.max(warningCount, Math.trunc(numericValue));
      }
    }

    return Math.max(0, Math.min(3, warningCount));
  }

  // Converts a 1-3 warning count into the shared restriction level descriptor.
  function getCompanyRestrictionLevelFromWarningCount(warningCount) {
    const normalizedCount = Math.max(0, Math.min(3, Math.trunc(Number(warningCount) || 0)));
    if (normalizedCount >= 3) {
      return { label: "High", tone: "danger", meter: 3 };
    }
    if (normalizedCount === 2) {
      return { label: "Medium", tone: "warning", meter: 2 };
    }
    if (normalizedCount === 1) {
      return { label: "Low", tone: "warning", meter: 1 };
    }
    return { label: "Low", tone: "neutral", meter: 1 };
  }

  // Reads or derives company restriction badge text for the current super admin flow.
  function getCompanyRestrictionBadgeText(admin) {
    if (getCompanyAccountState(admin) !== "restricted") {
      return "";
    }
    const expiresAt = getCompanyRestrictExpiresAt(admin);
    const remainingMs = expiresAt ? expiresAt.getTime() - Date.now() : 0;
    if (!Number.isFinite(remainingMs) || remainingMs <= 0) {
      return "Restricted";
    }
    const totalSeconds = Math.max(0, Math.ceil(remainingMs / 1000));
    const hours = Math.floor(totalSeconds / 3600);
    const minutes = Math.floor((totalSeconds % 3600) / 60);
    const seconds = totalSeconds % 60;
    return `Restricted - ${hours}h ${minutes}m ${seconds}s left`;
  }

  // Derives the company account state used by cards, drawers, filters, and actions.
  function getCompanyAccountState(admin) {
    const statusToken = [
      admin?.status,
      admin?.accountStatus,
      admin?.accountState,
      admin?.adminStatus,
      admin?.userStatus,
    ]
      .map((value) => String(value || "").trim().toLowerCase())
      .filter(Boolean)
      .join(" ");
    const deletionStatus = String(
      admin?.accountDeletionStatus || admin?.deletionStatus || "",
    ).trim().toLowerCase();
    const temporaryBanExpired = isCompanyTemporaryBanExpired(admin);
    const temporaryRestrictionExpired = isCompanyTemporaryRestrictionExpired(admin);

    if (
      deletionStatus === "deleted" ||
      statusToken.includes("deleted") ||
      Boolean(admin?.accountDeletedAt || admin?.deletedAt)
    ) {
      return "deleted";
    }

    if (
      deletionStatus === "scheduled" ||
      deletionStatus === "pending" ||
      Boolean(admin?.deletionScheduledAt || admin?.accountDeletionScheduledAt)
    ) {
      return "pending-deletion";
    }

    if (
      !temporaryBanExpired &&
      (
        readTruthyFlag(admin?.isBanned) ||
        readTruthyFlag(admin?.banned) ||
        Boolean(admin?.bannedAt) ||
        statusToken.includes("banned")
      )
    ) {
      return "banned";
    }

    if (
      !temporaryRestrictionExpired &&
      (
      readTruthyFlag(admin?.isRestricted) ||
      readTruthyFlag(admin?.restricted) ||
      Boolean(admin?.restrictedAt) ||
      statusToken.includes("restricted") ||
      statusToken.includes("restrict")
      )
    ) {
      return "restricted";
    }

    if (
      !temporaryBanExpired &&
      !temporaryRestrictionExpired &&
      (
        readTruthyFlag(admin?.isSuspended) ||
        readTruthyFlag(admin?.suspended) ||
        readTruthyFlag(admin?.disabled) ||
        Boolean(admin?.suspendedAt) ||
        Boolean(admin?.deactivatedAt) ||
        Boolean(admin?.disabledAt) ||
        statusToken.includes("suspended") ||
        statusToken.includes("suspend") ||
        statusToken.includes("deactivated") ||
        statusToken.includes("inactive") ||
        statusToken.includes("disabled")
      )
    ) {
      return "suspended";
    }

    return "active";
  }

  // Reads or derives company account state date for the current super admin flow.
  function getCompanyAccountStateDate(admin, metric) {
    if (metric === "banned") {
      return admin?.bannedAt || admin?.statusUpdatedAt || admin?.updatedAt || getCompanyCreatedAt(admin);
    }
    if (metric === "restricted") {
      return admin?.restrictedAt || admin?.statusUpdatedAt || admin?.updatedAt || getCompanyCreatedAt(admin);
    }
    if (metric === "suspended") {
      return (
        admin?.suspendedAt ||
        admin?.deactivatedAt ||
        admin?.disabledAt ||
        admin?.statusUpdatedAt ||
        admin?.updatedAt ||
        getCompanyCreatedAt(admin)
      );
    }
    return getCompanyCreatedAt(admin) || admin?.statusUpdatedAt || admin?.updatedAt;
  }

  // Counts company metric by period for dashboard metrics.
  function countCompanyMetricByPeriod(admins, metric, startDate, endDate) {
    return admins.filter((admin) => {
      if (metric === "online") {
        return isCompanyAdminOnline(admin);
      }
      if (metric !== "total" && getCompanyAccountState(admin) !== metric) {
        return false;
      }
      const date = parseCompanyDate(getCompanyAccountStateDate(admin, metric));
      return Boolean(date && date >= startDate && date < endDate);
    }).length;
  }

  // Reads or derives company metric trend for the current super admin flow.
  function getCompanyMetricTrend(admins, metric) {
    if (metric === "online") {
      return {
        valueText: "Live",
        periodText: "real-time",
      };
    }

    const now = new Date();
    const currentMonthStart = new Date(now.getFullYear(), now.getMonth(), 1);
    const nextMonthStart = new Date(now.getFullYear(), now.getMonth() + 1, 1);
    const previousMonthStart = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    const currentCount = countCompanyMetricByPeriod(admins, metric, currentMonthStart, nextMonthStart);
    const previousCount = countCompanyMetricByPeriod(admins, metric, previousMonthStart, currentMonthStart);
    const rawDifference = currentCount - previousCount;

    return {
      upValue: Math.max(0, rawDifference),
      downValue: Math.max(0, -rawDifference),
      periodText: "this month",
    };
  }

  // Renders company stats from the latest state.
  function renderCompanyStats(admins = state.admins) {
    const adminList = Array.isArray(admins) ? admins : [];
    const totals = adminList.reduce(
      (summary, admin) => {
        const accountState = getCompanyAccountState(admin);
        summary.total += 1;
        summary[accountState] += 1;
        if (isCompanyAdminOnline(admin)) {
          summary.online += 1;
        }
        return summary;
      },
      {
        total: 0,
        active: 0,
        online: 0,
        suspended: 0,
        banned: 0,
        restricted: 0,
      },
    );

    for (const card of elements.companyStatCards) {
      const metric = String(card.dataset.superAdminCompanyStat || "").trim();
      const valueTarget = card.querySelector("[data-super-admin-company-stat-value]");
      const trendTarget = card.querySelector("[data-super-admin-company-stat-trend]");
      if (valueTarget) {
        valueTarget.textContent = numberText(totals[metric] || 0);
      }
      if (trendTarget) {
        const trend = getCompanyMetricTrend(adminList, metric);
        trendTarget.textContent = "";
        const trendValue = document.createElement("span");
        trendValue.className = "super-admin-stat__trend-value";
        if (Object.prototype.hasOwnProperty.call(trend, "upValue")) {
          setSuperAdminRawTrendPair(trendValue, trend.upValue, trend.downValue);
        } else {
          trendValue.textContent = trend.valueText;
        }
        const trendPeriod = document.createElement("span");
        trendPeriod.className = "super-admin-stat__trend-period";
        trendPeriod.textContent = trend.periodText;
        trendTarget.append(trendValue, trendPeriod);
        trendTarget.classList.remove("is-up", "is-down");
        trendTarget.classList.toggle("is-neutral", !Object.prototype.hasOwnProperty.call(trend, "upValue"));
      }
    }
  }

  function getDashboardBuyerSnapshot() {
    const snapshot = window.GMSBuyerData?.getSnapshot?.();
    return {
      buyers: Array.isArray(snapshot?.buyers) ? snapshot.buyers : [],
      orders: Array.isArray(snapshot?.orders) ? snapshot.orders : [],
    };
  }

  function getDashboardOrderCreatedAt(order) {
    return (
      order?.createdAt
      || (order?.createdAtEpochMs ? new Date(Number(order.createdAtEpochMs)).toISOString() : "")
      || order?.updatedAt
      || ""
    );
  }

  function countRecordsByPeriod(records, getDateValue, startDate, endDate) {
    return records.filter((record) => {
      const date = parseCompanyDate(getDateValue(record));
      return Boolean(date && date >= startDate && date < endDate);
    }).length;
  }

  function formatDashboardPercentChange(currentValue, previousValue) {
    const current = Math.max(0, Math.trunc(Number(currentValue) || 0));
    const previous = Math.max(0, Math.trunc(Number(previousValue) || 0));
    if (!previous && !current) {
      return { text: "0%", direction: "neutral" };
    }
    if (!previous) {
      return { text: "+100%", direction: "up" };
    }
    const raw = ((current - previous) / previous) * 100;
    const rounded = Math.abs(raw) >= 10 ? Math.round(raw) : Math.round(raw * 10) / 10;
    return {
      text: `${raw >= 0 ? "+" : ""}${rounded}%`,
      direction: raw >= 0 ? "up" : "down",
    };
  }

  function setDashboardMetricTrend(target, primaryText, secondaryText, direction = "up") {
    if (!(target instanceof HTMLElement)) {
      return;
    }
    target.textContent = "";
    target.classList.remove("is-up", "is-down", "is-neutral");
    target.classList.add(
      direction === "down" ? "is-down" : direction === "neutral" ? "is-neutral" : "is-up",
    );
    const value = document.createElement("span");
    value.className = "super-admin-stat__trend-value";
    value.textContent = primaryText;
    const period = document.createElement("span");
    period.className = "super-admin-stat__trend-period";
    period.textContent = secondaryText;
    target.append(value, period);
  }

  function renderDashboardCompanyChart(adminList) {
    if (!(elements.dashboardCompanyChart instanceof HTMLElement)) {
      return;
    }
    const now = new Date();
    const months = [];
    for (let index = 5; index >= 0; index -= 1) {
      const monthStart = new Date(now.getFullYear(), now.getMonth() - index, 1);
      const monthEnd = new Date(now.getFullYear(), now.getMonth() - index + 1, 1);
      months.push({
        label: monthStart.toLocaleDateString(undefined, { month: "short" }),
        count: countRecordsByPeriod(adminList, getCompanyCreatedAt, monthStart, monthEnd),
        monthStart,
      });
    }
    const maxCount = Math.max(1, ...months.map((entry) => entry.count));
    const width = 640;
    const height = 220;
    const padding = { top: 18, right: 16, bottom: 34, left: 16 };
    const plotWidth = width - padding.left - padding.right;
    const plotHeight = height - padding.top - padding.bottom;
    const step = months.length > 1 ? plotWidth / (months.length - 1) : plotWidth;
    const points = months.map((entry, index) => {
      const x = padding.left + step * index;
      const y = padding.top + plotHeight - (entry.count / maxCount) * plotHeight;
      return { ...entry, x, y };
    });
    const linePath = points.map((point, index) => `${index === 0 ? "M" : "L"}${point.x.toFixed(1)} ${point.y.toFixed(1)}`).join(" ");
    const areaPath = `${linePath} L ${points[points.length - 1].x.toFixed(1)} ${(padding.top + plotHeight).toFixed(1)} L ${points[0].x.toFixed(1)} ${(padding.top + plotHeight).toFixed(1)} Z`;
    const monthTotal = months[months.length - 1]?.count || 0;
    if (elements.dashboardCompanyChartMeta instanceof HTMLElement) {
      elements.dashboardCompanyChartMeta.textContent = `${numberText(monthTotal)} new ${monthTotal === 1 ? "company" : "companies"} this month`;
    }
    elements.dashboardCompanyChart.innerHTML = `
      <svg viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" role="img" aria-label="Company registrations over the last six months">
        <defs>
          <linearGradient id="super-admin-dashboard-company-area" x1="0" x2="0" y1="0" y2="1">
            <stop offset="0%" stop-color="rgba(var(--accent-rgb), 0.28)" />
            <stop offset="100%" stop-color="rgba(var(--accent-rgb), 0.02)" />
          </linearGradient>
        </defs>
        <path d="${areaPath}" fill="url(#super-admin-dashboard-company-area)"></path>
        <path d="${linePath}" fill="none" stroke="var(--accent)" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"></path>
        ${points.map((point) => `
          <circle cx="${point.x.toFixed(1)}" cy="${point.y.toFixed(1)}" r="4.5" fill="#ffffff" stroke="var(--accent)" stroke-width="2"></circle>
        `).join("")}
        ${points.map((point) => `
          <text x="${point.x.toFixed(1)}" y="${(height - 8).toFixed(1)}" text-anchor="middle" fill="#64748b" font-size="11">${point.label}</text>
        `).join("")}
      </svg>
    `;
  }

  function renderDashboardListingDonut() {
    const segments = [
      { key: "inReview", label: "In Review", color: "#6366f1" },
      { key: "approved", label: "Approved", color: "#15803d" },
      { key: "rejected", label: "Rejected", color: "#b91c1c" },
      { key: "submitted", label: "Submitted", color: "#346E90" },
    ].map((segment) => ({
      ...segment,
      value: Math.max(0, Number(state.productRequestStats?.[segment.key === "inReview" ? "inReview" : segment.key]) || 0),
    }));
    const total = segments.reduce((sum, segment) => sum + segment.value, 0);
    if (elements.dashboardListingTotal instanceof HTMLElement) {
      elements.dashboardListingTotal.textContent = numberText(total);
    }
    if (elements.dashboardListingDonut instanceof HTMLElement) {
      const radius = 72;
      const circumference = 2 * Math.PI * radius;
      let offset = 0;
      const slices = total
        ? segments.map((segment) => {
            const length = (segment.value / total) * circumference;
            const slice = `
              <circle
                cx="90"
                cy="90"
                r="${radius}"
                fill="none"
                stroke="${segment.color}"
                stroke-width="18"
                stroke-dasharray="${length.toFixed(2)} ${(circumference - length).toFixed(2)}"
                stroke-dashoffset="${(-offset).toFixed(2)}"
                transform="rotate(-90 90 90)"
              ></circle>
            `;
            offset += length;
            return slice;
          }).join("")
        : `<circle cx="90" cy="90" r="${radius}" fill="none" stroke="rgba(15, 23, 42, 0.08)" stroke-width="18"></circle>`;
      elements.dashboardListingDonut.innerHTML = `
        <svg viewBox="0 0 180 180" role="img" aria-label="Listing status breakdown">
          ${slices}
        </svg>
      `;
    }
    if (elements.dashboardListingLegend instanceof HTMLElement) {
      elements.dashboardListingLegend.innerHTML = "";
      for (const segment of segments) {
        const item = document.createElement("li");
        const percent = total ? Math.round((segment.value / total) * 1000) / 10 : 0;
        item.innerHTML = `
          <span class="super-admin-dashboard-legend__label">
            <span class="super-admin-dashboard-legend__swatch" style="background:${segment.color}"></span>
            <span>${segment.label}</span>
          </span>
          <span class="super-admin-dashboard-legend__value">${numberText(segment.value)} (${percent}%)</span>
        `;
        elements.dashboardListingLegend.append(item);
      }
    }
  }

  function createDashboardStatusBadge(accountState) {
    const badge = document.createElement("span");
    const normalizedState = String(accountState || "active").trim().toLowerCase();
    const labelMap = {
      active: "active",
      restricted: "restricted",
      banned: "banned",
      suspended: "suspended",
      "pending-deletion": "deleting",
      deleted: "deleted",
    };
    badge.className = `super-admin-dashboard-status is-${normalizedState === "active" ? "active" : normalizedState}`;
    badge.textContent = labelMap[normalizedState] || normalizedState.replace(/-/g, " ");
    return badge;
  }

  function createDashboardLogoMarkup(admin, className) {
    const logo = document.createElement("span");
    logo.className = className;
    const imageUrl = getCompanyImageUrl(admin);
    if (imageUrl) {
      const image = document.createElement("img");
      image.src = imageUrl;
      image.alt = "";
      image.loading = "lazy";
      logo.append(image);
    } else {
      logo.textContent = getCompanyInitials(admin);
    }
    return logo;
  }

  function renderDashboardRecentCompanies(adminList) {
    if (!(elements.dashboardRecentCompanies instanceof HTMLElement)) {
      return;
    }
    const recentCompanies = [...adminList]
      .sort((left, right) => String(getCompanyCreatedAt(right)).localeCompare(String(getCompanyCreatedAt(left))))
      .slice(0, 5);
    elements.dashboardRecentCompanies.innerHTML = "";
    if (!recentCompanies.length) {
      const row = document.createElement("tr");
      const cell = document.createElement("td");
      cell.colSpan = 3;
      cell.className = "super-admin-dashboard-empty";
      cell.textContent = "No companies registered yet.";
      row.append(cell);
      elements.dashboardRecentCompanies.append(row);
      return;
    }
    for (const admin of recentCompanies) {
      const row = document.createElement("tr");
      const companyCell = document.createElement("td");
      const companyWrap = document.createElement("div");
      companyWrap.className = "super-admin-dashboard-table__company";
      companyWrap.append(
        createDashboardLogoMarkup(admin, "super-admin-dashboard-table__logo"),
      );
      const name = document.createElement("span");
      name.className = "super-admin-dashboard-table__name";
      name.textContent = getCompanyName(admin);
      companyWrap.append(name);
      companyCell.append(companyWrap);
      const statusCell = document.createElement("td");
      statusCell.append(createDashboardStatusBadge(getCompanyAccountState(admin)));
      const dateCell = document.createElement("td");
      dateCell.textContent = formatDateTime(getCompanyCreatedAt(admin)) || "-";
      row.append(companyCell, statusCell, dateCell);
      elements.dashboardRecentCompanies.append(row);
    }
  }

  function renderDashboardActivityFeed() {
    if (!(elements.dashboardActivity instanceof HTMLElement)) {
      return;
    }
    const activityEntries = getNotificationPanelEntries()
      .slice()
      .sort((left, right) => String(right.createdAt || "").localeCompare(String(left.createdAt || "")))
      .slice(0, 6);
    elements.dashboardActivity.innerHTML = "";
    if (!activityEntries.length) {
      const empty = document.createElement("li");
      empty.className = "super-admin-dashboard-empty";
      empty.textContent = "No recent super admin notifications yet.";
      elements.dashboardActivity.append(empty);
      return;
    }
    for (const entry of activityEntries) {
      const item = document.createElement("li");
      item.className = "super-admin-dashboard-activity__item";
      const visualConfig = getSuperAdminNotificationVisualConfig(entry);
      const icon = document.createElement("span");
      icon.className = `super-admin-dashboard-activity__icon super-admin-dashboard-activity__icon--${visualConfig.modifier}`;
      icon.innerHTML = createIconSvg(visualConfig.iconPaths);
      const copy = document.createElement("div");
      copy.className = "super-admin-dashboard-activity__copy";
      const title = document.createElement("strong");
      title.textContent = buildSuperAdminNotificationMessageParts(entry)
        .map((part) => part.text)
        .join("")
        .trim();
      const meta = document.createElement("span");
      meta.textContent = `${getSuperAdminNotificationActorName(entry)} • ${getSuperAdminNotificationTimestampLabel(entry)}`;
      copy.append(title, meta);
      item.append(icon, copy);
      elements.dashboardActivity.append(item);
    }
  }

  function renderDashboardTopCompanies(adminList) {
    if (!(elements.dashboardTopCompanies instanceof HTMLElement)) {
      return;
    }
    const topCompanies = [...adminList]
      .sort((left, right) => getAdminCounts(right).orders - getAdminCounts(left).orders)
      .filter((admin) => getAdminCounts(admin).orders > 0)
      .slice(0, 5);
    elements.dashboardTopCompanies.innerHTML = "";
    if (!topCompanies.length) {
      const empty = document.createElement("li");
      empty.className = "super-admin-dashboard-empty";
      empty.textContent = "No marketplace orders recorded yet.";
      elements.dashboardTopCompanies.append(empty);
      return;
    }
    for (const admin of topCompanies) {
      const counts = getAdminCounts(admin);
      const item = document.createElement("li");
      item.className = "super-admin-dashboard-rank__item";
      item.append(
        createDashboardLogoMarkup(admin, "super-admin-dashboard-rank__logo"),
      );
      const copy = document.createElement("div");
      copy.className = "super-admin-dashboard-rank__copy";
      const name = document.createElement("strong");
      name.textContent = getCompanyName(admin);
      const meta = document.createElement("span");
      meta.textContent = `${numberText(counts.products)} products • ${numberText(counts.employees)} staff`;
      copy.append(name, meta);
      const value = document.createElement("span");
      value.className = "super-admin-dashboard-rank__value";
      value.textContent = `${numberText(counts.orders)} orders`;
      item.append(copy, value);
      elements.dashboardTopCompanies.append(item);
    }
  }

  function renderDashboardMetricCards(adminList, buyerSnapshot) {
    const buyers = buyerSnapshot.buyers;
    const orders = buyerSnapshot.orders;
    const now = new Date();
    const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const tomorrowStart = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1);
    const yesterdayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1);
    const currentMonthStart = new Date(now.getFullYear(), now.getMonth(), 1);
    const nextMonthStart = new Date(now.getFullYear(), now.getMonth() + 1, 1);
    const previousMonthStart = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    const metricValues = {
      companies: adminList.length,
      buyers: buyers.length,
      "orders-today": countRecordsByPeriod(orders, getDashboardOrderCreatedAt, todayStart, tomorrowStart),
      "listings-review": Number(state.productRequestStats?.inReview || 0),
    };
    const metricTrends = {
      companies: formatDashboardPercentChange(
        countRecordsByPeriod(adminList, getCompanyCreatedAt, currentMonthStart, nextMonthStart),
        countRecordsByPeriod(adminList, getCompanyCreatedAt, previousMonthStart, currentMonthStart),
      ),
      buyers: formatDashboardPercentChange(
        countRecordsByPeriod(buyers, (buyer) => buyer?.createdAt, currentMonthStart, nextMonthStart),
        countRecordsByPeriod(buyers, (buyer) => buyer?.createdAt, previousMonthStart, currentMonthStart),
      ),
      "orders-today": formatDashboardPercentChange(
        metricValues["orders-today"],
        countRecordsByPeriod(orders, getDashboardOrderCreatedAt, yesterdayStart, todayStart),
      ),
      "listings-review": {
        text: `${numberText(Number(state.productRequestStats?.submitted || 0))} submitted`,
        direction: "neutral",
      },
    };
    for (const card of elements.dashboardStatCards) {
      const metric = String(card.dataset.superAdminDashboardStat || "").trim();
      const valueTarget = card.querySelector("[data-super-admin-dashboard-stat-value]");
      const trendTarget = card.querySelector("[data-super-admin-dashboard-stat-trend]");
      if (valueTarget) {
        valueTarget.textContent = numberText(metricValues[metric] || 0);
      }
      if (trendTarget) {
        const trend = metricTrends[metric] || { text: "Live", direction: "neutral" };
        const periodText = metric === "orders-today"
          ? "vs yesterday"
          : metric === "listings-review"
            ? "all listing records"
            : "vs last month";
        setDashboardMetricTrend(trendTarget, trend.text, periodText, trend.direction);
      }
    }
  }

  // Renders the super admin dashboard overview from live platform state.
  function renderDashboard() {
    if (state.activeSection !== "dashboard") {
      return;
    }
    const adminList = Array.isArray(state.admins) ? state.admins : [];
    const buyerSnapshot = getDashboardBuyerSnapshot();
    renderDashboardMetricCards(adminList, buyerSnapshot);
    renderDashboardCompanyChart(adminList);
    renderDashboardListingDonut();
    renderDashboardRecentCompanies(adminList);
    renderDashboardActivityFeed();
    renderDashboardTopCompanies(adminList);
  }

  window.GMSSuperAdminDashboard = Object.freeze({
    refresh: renderDashboard,
  });

  // Finds company by id in local state.
  function findCompanyById(adminId) {
    const normalizedAdminId = String(adminId || "").trim();
    if (!normalizedAdminId) {
      return null;
    }
    return state.admins.find((admin) => getCompanyId(admin) === normalizedAdminId) || null;
  }

  // Reads or derives company image url for the current super admin flow.
  function getCompanyImageUrl(admin) {
    if (!admin || admin?.businessLogoSkipped === true) {
      return "";
    }
    return [
      admin?.companyPictureUrl,
      admin?.companyProfileImageUrl,
      admin?.businessLogoUrl,
      admin?.profileImageUrl,
      admin?.avatarUrl,
      admin?.photoUrl,
      admin?.profilePhotoUrl,
      admin?.pictureUrl,
      admin?.imageUrl,
      admin?.logoUrl,
      admin?.company?.companyPictureUrl,
      admin?.company?.profileImageUrl,
      admin?.company?.logoUrl,
      admin?.store?.companyPictureUrl,
      admin?.store?.profileImageUrl,
      admin?.store?.logoUrl,
      admin?.profile?.companyPictureUrl,
      admin?.profile?.profileImageUrl,
      admin?.profile?.logoUrl,
    ]
      .map((value) => String(value || "").trim())
      .find(Boolean) || "";
  }

  // Reads or derives company initials for the current super admin flow.
  function getCompanyInitials(admin) {
    const companyName = getCompanyName(admin);
    return companyName
      .split(/\s+/)
      .filter(Boolean)
      .slice(0, 2)
      .map((part) => part.charAt(0).toUpperCase())
      .join("") || "CO";
  }

  // Reads or derives company tone index for the current super admin flow.
  function getCompanyToneIndex(admin) {
    const source = String(admin?.adminId || admin?.id || admin?.email || getCompanyName(admin));
    let hash = 0;
    for (const char of source) {
      hash = (hash + char.charCodeAt(0)) % 6;
    }
    return hash + 1;
  }

  // Checks whether company admin online is true for the current record or UI state.
  function isCompanyAdminOnline(admin) {
    const statusToken = String(
      admin?.presenceStatus ??
        admin?.onlineStatus ??
        admin?.sessionStatus ??
        admin?.loginStatus ??
        admin?.status ??
        "",
    )
      .trim()
      .toLowerCase();

    const hasOnlineSignal = Boolean(
      admin?.isOnline === true ||
        admin?.online === true ||
        admin?.loggedIn === true ||
        admin?.isLoggedIn === true ||
        admin?.sessionActive === true ||
        statusToken === "online" ||
        statusToken === "logged-in" ||
        statusToken === "logged in" ||
        statusToken.includes("online"),
    );
    return hasOnlineSignal && isCompanyPresenceFresh(admin);
  }

  // Reads or derives company search text for the current super admin flow.
  function getCompanySearchText(admin) {
    const counts = getAdminCounts(admin);
    return [
      getCompanyName(admin),
      getAdminName(admin),
      admin?.email,
      admin?.adminId,
      admin?.id,
      admin?.mobileNumber,
      `${counts.followers} followers`,
      `${counts.rating.toFixed(1)} rating`,
      `${counts.commentCount} reviews`,
      `${counts.employees} employees`,
      `${counts.orders} orders`,
      `${counts.chats} chats`,
    ].map((value) => String(value || "").toLowerCase()).join(" ");
  }

  function normalizeCompanyFilterValue(type, value) {
    const normalized = String(value || "").trim();
    if (type === "accountState") {
      return normalizeCompanyAccountFilter(normalized);
    }
    if (type === "workspace") {
      return ["with-products", "no-products", "with-orders", "with-chats"].includes(normalized)
        ? normalized
        : "all";
    }
    if (type === "team") {
      return ["no-staff", "small", "growing"].includes(normalized) ? normalized : "all";
    }
    if (type === "activity") {
      return ["online", "active", "quiet"].includes(normalized) ? normalized : "all";
    }
    return "all";
  }

  // Supports the matches company filters branch of the super admin UI.
  function matchesCompanyFilters(admin) {
    const counts = getAdminCounts(admin);
    const filters = state.companyFilters || {};
    const workspaceFilter = normalizeCompanyFilterValue("workspace", filters.workspace);
    const teamFilter = normalizeCompanyFilterValue("team", filters.team);
    const activityFilter = normalizeCompanyFilterValue("activity", filters.activity);

    if (workspaceFilter === "with-products" && counts.products <= 0) {
      return false;
    }
    if (workspaceFilter === "no-products" && counts.products > 0) {
      return false;
    }
    if (workspaceFilter === "with-orders" && counts.orders <= 0) {
      return false;
    }
    if (workspaceFilter === "with-chats" && counts.chats <= 0) {
      return false;
    }
    if (teamFilter === "no-staff" && counts.employees > 0) {
      return false;
    }
    if (teamFilter === "small" && (counts.employees < 1 || counts.employees > 10)) {
      return false;
    }
    if (teamFilter === "growing" && counts.employees < 11) {
      return false;
    }
    if (activityFilter === "online" && !isCompanyAdminOnline(admin)) {
      return false;
    }
    if (activityFilter === "active" && counts.products + counts.orders + counts.chats <= 0) {
      return false;
    }
    if (activityFilter === "quiet" && counts.products + counts.orders + counts.chats > 0) {
      return false;
    }

    const accountStateFilter = normalizeCompanyAccountFilter(filters.accountState);
    const accountState = getCompanyAccountState(admin);
    if (accountStateFilter === "new" && !isNewlyRegisteredCompany(admin)) {
      return false;
    }
    if (accountStateFilter === "low-risk" && accountState !== "active") {
      return false;
    }
    if (accountStateFilter === "banned" && accountState !== "banned") {
      return false;
    }
    if (accountStateFilter === "restricted" && accountState !== "restricted") {
      return false;
    }
    if (accountStateFilter === "suspended" && accountState !== "suspended") {
      return false;
    }
    return true;
  }

  // Reads or derives filtered admins for the current super admin flow.
  function getFilteredAdmins(admins = state.admins) {
    const searchTerm = state.companySearchTerm.trim().toLowerCase();
    return admins.filter((admin) => {
      if (searchTerm && !getCompanySearchText(admin).includes(searchTerm)) {
        return false;
      }
      return matchesCompanyFilters(admin);
    });
  }

  function normalizeCompanySortValue(value) {
    const normalized = String(value || "").trim().toLowerCase();
    return [
      "created-asc",
      "company-asc",
      "products-desc",
      "employees-desc",
      "orders-desc",
      "rating-desc",
      "reviews-desc",
      "followers-desc",
    ].includes(normalized)
      ? normalized
      : "created-desc";
  }

  function normalizeCompanySortValues(value) {
    return normalizeSortValues(value, normalizeCompanySortValue, "created-desc");
  }

  function compareCompanyNames(left, right) {
    return getCompanyName(left).localeCompare(getCompanyName(right), undefined, {
      sensitivity: "base",
    });
  }

  function compareAdminsBySortValue(left, right, leftCounts, rightCounts, sortValue) {
    if (sortValue === "company-asc") {
      return compareCompanyNames(left, right);
    }
    if (sortValue === "created-asc") {
      return String(left?.createdAt || "").localeCompare(String(right?.createdAt || ""));
    }
    if (sortValue === "products-desc") {
      return rightCounts.products - leftCounts.products;
    }
    if (sortValue === "employees-desc") {
      return rightCounts.employees - leftCounts.employees;
    }
    if (sortValue === "orders-desc") {
      return rightCounts.orders - leftCounts.orders;
    }
    if (sortValue === "rating-desc") {
      return rightCounts.rating - leftCounts.rating;
    }
    if (sortValue === "reviews-desc") {
      return rightCounts.commentCount - leftCounts.commentCount;
    }
    if (sortValue === "followers-desc") {
      return rightCounts.followers - leftCounts.followers;
    }
    return String(right?.createdAt || "").localeCompare(String(left?.createdAt || ""));
  }

  // Supports the sort admins branch of the super admin UI.
  function sortAdmins(admins) {
    const sortedAdmins = [...admins];
    sortedAdmins.sort((left, right) => {
      const leftCounts = getAdminCounts(left);
      const rightCounts = getAdminCounts(right);
      for (const sortValue of normalizeCompanySortValues(state.companySort)) {
        const compareResult = compareAdminsBySortValue(left, right, leftCounts, rightCounts, sortValue);
        if (compareResult !== 0) {
          return compareResult;
        }
      }

      return compareCompanyNames(left, right);
    });
    return sortedAdmins;
  }

  // Builds the DOM structure for company meta item.
  function createCompanyMetaItem(iconPath, text) {
    const item = document.createElement("span");
    item.className = "super-admin-company-card__meta-item";
    item.innerHTML = `${createIconSvg(iconPath)}<span></span>`;
    item.querySelector("span").textContent = text;
    return item;
  }

  // Builds the DOM structure for company meta link.
  function createCompanyMetaLink(iconPath, text, href, label) {
    const item = document.createElement("a");
    item.className = "super-admin-company-card__meta-item super-admin-company-card__meta-item--link";
    item.href = href;
    item.setAttribute("aria-label", label || text);
    item.innerHTML = `${createIconSvg(iconPath)}<span></span>`;
    item.querySelector("span").textContent = text;
    return item;
  }

  // Builds the DOM structure for company grid pill.
  function createCompanyGridPill(label, tone = "gray") {
    const pill = document.createElement("span");
    pill.className = `super-admin-company-card__grid-pill is-${tone}`;
    pill.textContent = label;
    return pill;
  }

  // Supports the configure company status indicator branch of the super admin UI.
  function configureCompanyStatusIndicator(indicator, admin, fallbackLabel, isOnline) {
    if (!(indicator instanceof HTMLElement)) {
      return;
    }

    const banLabel = getCompanyBanBadgeText(admin);
    const restrictionLabel = getCompanyRestrictionBadgeText(admin);
    indicator.textContent = "";
    indicator.innerHTML = "";
    indicator.classList.toggle("is-online", !banLabel && !restrictionLabel && Boolean(isOnline));
    indicator.classList.toggle("is-banned", Boolean(banLabel));
    indicator.classList.toggle("is-restricted", Boolean(restrictionLabel));
    delete indicator.dataset.companyBanCountdown;
    delete indicator.dataset.companyBanAdminId;
    delete indicator.dataset.companyRestrictionCountdown;
    delete indicator.dataset.companyRestrictionAdminId;

    if (banLabel) {
      indicator.innerHTML = createIconSvg(companyCardIconPaths.ban);
      indicator.dataset.companyBanCountdown = banLabel;
      indicator.dataset.companyBanAdminId = getCompanyId(admin);
      indicator.setAttribute("aria-label", banLabel);
      indicator.removeAttribute("title");
      indicator.tabIndex = 0;
      return;
    }

    if (restrictionLabel) {
      indicator.innerHTML = createIconSvg(companyCardIconPaths.restrict);
      indicator.dataset.companyRestrictionCountdown = restrictionLabel;
      indicator.dataset.companyRestrictionAdminId = getCompanyId(admin);
      indicator.setAttribute("aria-label", restrictionLabel);
      indicator.removeAttribute("title");
      indicator.tabIndex = 0;
      return;
    }

    indicator.setAttribute("aria-label", fallbackLabel);
    indicator.removeAttribute("title");
    indicator.removeAttribute("tabindex");
  }

  // Supports the configure company online indicator branch of the super admin UI.
  function configureCompanyOnlineIndicator(indicator, fallbackLabel, isOnline) {
    if (!(indicator instanceof HTMLElement)) {
      return;
    }

    indicator.textContent = "";
    indicator.innerHTML = "";
    indicator.classList.toggle("is-online", Boolean(isOnline));
    indicator.classList.toggle("is-offline", !isOnline);
    indicator.classList.remove("is-banned", "is-restricted");
    delete indicator.dataset.companyBanCountdown;
    delete indicator.dataset.companyBanAdminId;
    delete indicator.dataset.companyRestrictionCountdown;
    delete indicator.dataset.companyRestrictionAdminId;
    indicator.setAttribute("role", "img");
    indicator.setAttribute("aria-label", fallbackLabel);
    indicator.title = fallbackLabel;
    indicator.removeAttribute("tabindex");
  }

