  async function resetCompanyPassword(toggleButton) {
    if (!(toggleButton instanceof HTMLButtonElement)) {
      return;
    }

    const adminId = String(toggleButton.dataset.companyId || "").trim();
    const companyName = String(toggleButton.dataset.companyName || "").trim();
    if (!adminId) {
      return;
    }

    toggleButton.disabled = true;
    try {
      if (!await requireSuperAdminFingerprint("reset this company password")) {
        return;
      }
      const confirmed = window.confirm(
        `Reset login password for ${companyName || "this seller"}?\n\n` +
          "A temporary password will be shown once. Existing passwords cannot be viewed.",
      );
      if (!confirmed) {
        return;
      }
      const response = await fetch(`/api/super-admin/admins/${encodeURIComponent(adminId)}/reset-password`, {
        method: "POST",
        cache: "no-store",
        headers: rootHeaders({
          Accept: "application/json",
          "Content-Type": "application/json",
        }),
        body: "{}",
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(data.message || "Unable to reset password.");
      }
      const temporaryPassword = String(data.temporaryPassword ?? "").trim();
      if (!temporaryPassword) {
        throw new Error("Reset succeeded but no temporary password was returned.");
      }
      showTemporaryPasswordSnackbar({
        title: "Temporary Password",
        subject: companyName || adminId,
        password: temporaryPassword,
      });
      setFeedback("Password reset. Share the temporary password securely once.", "success");
    } catch (error) {
      setFeedback(
        error instanceof Error ? error.message : "Unable to reset password.",
        "error",
      );
    } finally {
      toggleButton.disabled = false;
    }
  }

  // Builds the DOM structure for company list last active cell.
