  function openRejectEvidenceModal(product, imageItems) {
    closeRejectEvidenceModal(null);
    const productName = String(product?.name || "product").trim();
    const normalizedImageItems = (Array.isArray(imageItems) ? imageItems : [])
      .map((item, index) => ({
        label: String(item?.label || `Image ${index + 1}`).trim(),
        url: String(item?.url || "").trim(),
      }))
      .filter((item) => item.url);
    return new Promise((resolve) => {
      activeRejectEvidenceModalResolve = resolve;
      const overlay = document.createElement("div");
      overlay.className = "super-admin-reject-evidence-modal-overlay";
      overlay.setAttribute("aria-hidden", "false");

      const dialog = document.createElement("section");
      dialog.className = "super-admin-reject-evidence-modal";
      dialog.setAttribute("role", "dialog");
      dialog.setAttribute("aria-modal", "true");
      const titleId = `super-admin-reject-evidence-title-${Date.now()}`;
      dialog.setAttribute("aria-labelledby", titleId);
      dialog.tabIndex = -1;

      const header = document.createElement("div");
      header.className = "super-admin-reject-evidence-modal__header";
      header.innerHTML = `
        <div>
          <h2 id="${titleId}">Select Images</h2>
          <p>Choose product images to archive as rejected evidence for ${escapeHtml(productName)}.</p>
        </div>
      `;

      const closeButton = document.createElement("button");
      closeButton.type = "button";
      closeButton.className = "product-gallery-modal__close validation-modal__close product-description-modal__close super-admin-reject-evidence-modal__close";
      closeButton.setAttribute("aria-label", "Close reject evidence");
      closeButton.innerHTML = createCloseIconSvg();

      const body = document.createElement("div");
      body.className = "super-admin-reject-evidence-modal__body";

      const toolbar = document.createElement("div");
      toolbar.className = "super-admin-reject-evidence-modal__toolbar";

      const selectAllLabel = document.createElement("label");
      selectAllLabel.className = "super-admin-reject-evidence-modal__select-all";
      selectAllLabel.setAttribute("aria-label", "Select all visible images");
      selectAllLabel.innerHTML = `
        <input class="super-admin-reject-evidence-modal__select-all-checkbox" type="checkbox">
        <span>Select all</span>
      `;
      const selectAllCheckbox = selectAllLabel.querySelector("input");
      toolbar.append(selectAllLabel);

      const list = document.createElement("div");
      list.className = "super-admin-reject-evidence-modal__grid";
      const tiles = [];
      const checkboxes = [];
      normalizedImageItems.forEach((item, index) => {
        const displayName = getRejectEvidenceImageDisplayName(item, index);
        const option = document.createElement("label");
        option.className = "super-admin-reject-evidence-modal__tile";
        const inputId = `super-admin-reject-evidence-image-${Date.now()}-${index}`;
        const searchText = [
          displayName,
          item.label,
          item.url,
          productName,
        ].join(" ").toLowerCase();
        option.dataset.searchText = searchText;
        option.innerHTML = `
          <input id="${inputId}" class="super-admin-reject-evidence-modal__checkbox" type="checkbox" value="${escapeHtml(item.url)}">
          <span class="super-admin-reject-evidence-modal__thumb">
            <img src="${escapeHtml(item.url)}" alt="${escapeHtml(item.label)}" loading="lazy">
            <span class="super-admin-reject-evidence-modal__check" aria-hidden="true">
              ${createIconSvg('<path d="m5 12 4 4L19 6"></path>')}
            </span>
          </span>
          <span class="super-admin-reject-evidence-modal__filename">
            ${escapeHtml(displayName)}
          </span>
        `;
        const checkbox = option.querySelector("input");
        if (checkbox instanceof HTMLInputElement) {
          checkboxes.push(checkbox);
          checkbox.addEventListener("change", () => {
            option.classList.toggle("is-selected", checkbox.checked);
            syncSelection();
          });
        }
        list.append(option);
        tiles.push(option);
      });

      body.append(toolbar, list);

      const actions = document.createElement("div");
      actions.className = "super-admin-reject-evidence-modal__actions";
      const selectedSummary = document.createElement("span");
      selectedSummary.className = "super-admin-reject-evidence-modal__selected-summary";
      selectedSummary.innerHTML = `
        <span class="super-admin-reject-evidence-modal__selected-icon" aria-hidden="true">
          ${createIconSvg('<rect width="18" height="18" x="3" y="3" rx="2" ry="2"></rect><circle cx="9" cy="9" r="2"></circle><path d="m21 15-3.086-3.086a2 2 0 0 0-2.828 0L6 21"></path>')}
        </span>
        <span data-reject-evidence-selected-count>0 images selected</span>
      `;
      const actionButtons = document.createElement("span");
      actionButtons.className = "super-admin-reject-evidence-modal__action-buttons";
      const cancelButton = document.createElement("button");
      cancelButton.type = "button";
      cancelButton.className = "super-admin-reject-evidence-modal__cancel";
      cancelButton.textContent = "Cancel";
      const confirmButton = document.createElement("button");
      confirmButton.type = "button";
      confirmButton.className = "super-admin-reject-evidence-modal__confirm";
      confirmButton.textContent = "Reject Selected";
      confirmButton.disabled = true;
      actionButtons.append(cancelButton, confirmButton);
      actions.append(selectedSummary, actionButtons);

      function getVisibleCheckboxes() {
        return checkboxes.filter((checkbox) => {
          const tile = checkbox.closest(".super-admin-reject-evidence-modal__tile");
          return tile instanceof HTMLElement && !tile.hidden;
        });
      }

      function syncSelection() {
        const selectedCount = checkboxes.filter((checkbox) => checkbox.checked).length;
        const visibleCheckboxes = getVisibleCheckboxes();
        const visibleSelectedCount = visibleCheckboxes.filter((checkbox) => checkbox.checked).length;
        const selectedLabel = selectedSummary.querySelector("[data-reject-evidence-selected-count]");
        if (selectedLabel) {
          selectedLabel.textContent = `${numberText(selectedCount)} image${selectedCount === 1 ? "" : "s"} selected`;
        }
        confirmButton.disabled = selectedCount === 0;
        if (selectAllCheckbox instanceof HTMLInputElement) {
          selectAllCheckbox.checked = visibleCheckboxes.length > 0 && visibleSelectedCount === visibleCheckboxes.length;
          selectAllCheckbox.indeterminate = visibleCheckboxes.length > 0 && visibleSelectedCount > 0 && visibleSelectedCount < visibleCheckboxes.length;
          selectAllCheckbox.disabled = visibleCheckboxes.length === 0;
        }
      }

      if (selectAllCheckbox instanceof HTMLInputElement) {
        selectAllCheckbox.addEventListener("change", () => {
          const visibleCheckboxes = getVisibleCheckboxes();
          const shouldSelect = selectAllCheckbox.checked;
          for (const checkbox of visibleCheckboxes) {
            checkbox.checked = shouldSelect;
            const tile = checkbox.closest(".super-admin-reject-evidence-modal__tile");
            if (tile instanceof HTMLElement) {
              tile.classList.toggle("is-selected", checkbox.checked);
            }
          }
          syncSelection();
        });
      }

      syncSelection();

      closeButton.addEventListener("click", () => closeRejectEvidenceModal(null));
      cancelButton.addEventListener("click", () => closeRejectEvidenceModal(null));
      confirmButton.addEventListener("click", () => {
        const selectedImageUrls = checkboxes
          .filter((checkbox) => checkbox.checked)
          .map((checkbox) => checkbox.value);
        closeRejectEvidenceModal(selectedImageUrls);
      });
      overlay.addEventListener("click", (event) => {
        if (event.target === overlay) {
          closeRejectEvidenceModal(null);
        }
      });

      dialog.append(header, closeButton, body, actions);
      overlay.append(dialog);
      document.body.append(overlay);
      document.body.classList.add("super-admin-reject-evidence-open");
      activeRejectEvidenceModal = overlay;
      window.requestAnimationFrame(() => overlay.classList.add("is-open"));
      window.setTimeout(() => dialog.focus({ preventScroll: true }), 0);
    });
  }

  function getProductDetailVideoItems(product) {
    const items = [];
    const seen = new Set();
    const videoUrls = normalizeProductDetailUrlList([
      product?.videoUrls,
      product?.videoUrl,
    ]);
    const thumbnailUrls = normalizeProductDetailUrlList([
      product?.videoThumbnailUrls,
      product?.videoThumbnailUrl,
    ]);
    videoUrls.forEach((url, index) => {
      appendProductDetailMediaItem(items, seen, `Video ${index + 1}`, url, {
        type: "video",
        thumbnailUrl: thumbnailUrls[index] || "",
      });
    });
    return items;
  }

  function getProductDetailHeroMediaItems(product) {
    return [
      ...getProductDetailImageItems(product),
      ...getProductDetailVideoItems(product),
    ].filter((item) => String(item?.url || "").trim());
  }

  function shouldUseProductDetailMediaOnlyHero(product, items) {
    const mediaCounts = getProductRequestMediaCounts(product);
    const mediaItems = Array.isArray(items) ? items : [];
    const hasVideo = mediaCounts.videoCount > 0 || mediaItems.some((item) => item?.type === "video");
    return mediaCounts.imageCount > 1 || hasVideo;
  }

  function getProductRequestMediaCounts(product) {
    const imageUrls = normalizeProductDetailUrlList([
      product?.imageUrls,
      product?.imageUrl,
      product?.mainImageUrl,
    ]);
    const videoUrls = normalizeProductDetailUrlList([
      product?.videoUrls,
      product?.videoUrl,
    ]);
    return {
      imageCount: imageUrls.length,
      videoCount: videoUrls.length,
    };
  }

  function getProductDetailVisualSearchItems(product) {
    const items = [];
    const seen = new Set();
    const angles = product?.visualSearchImageAngles && typeof product.visualSearchImageAngles === "object"
      ? product.visualSearchImageAngles
      : null;
    if (angles) {
      for (const [angle, url] of Object.entries(angles)) {
        appendProductDetailMediaItem(
          items,
          seen,
          `${formatProductDetailKeyLabel(angle)} angle`,
          url,
        );
      }
    }
    normalizeProductDetailUrlList([
      product?.visualSearchImageUrls,
      product?.visualSearchImageUrl,
    ]).forEach((url, index) => {
      appendProductDetailMediaItem(items, seen, `Visual search ${index + 1}`, url);
    });
    return items;
  }

  function createProductDetailMediaSection(title, items, emptyText, product = null) {
    const section = document.createElement("section");
    section.className = "super-admin-product-detail-modal__section";
    const heading = document.createElement("h3");
    heading.textContent = title;
    section.append(heading);

    if (!items.length) {
      const empty = document.createElement("p");
      empty.className = "super-admin-product-detail-modal__empty";
      empty.textContent = emptyText || "No media saved.";
      section.append(empty);
      return section;
    }

    const grid = document.createElement("div");
    grid.className = "super-admin-product-detail-modal__media-grid";
    for (const item of items) {
      const link = document.createElement("a");
      link.className = "super-admin-product-detail-modal__media-card";
      link.href = item.url;
      link.target = "_blank";
      link.rel = "noopener";
      const yoloEvidence = product
        ? getProductDetailMediaYoloEvidence(product, item)
        : null;
      link.classList.toggle("has-yolo-evidence", Boolean(yoloEvidence));
      if (yoloEvidence) {
        link.title = `${item.label || "Product media"} - ${yoloEvidence.label}`;
        link.setAttribute("aria-label", `${item.label || "Product media"}: ${yoloEvidence.label}`);
      }

      const preview = document.createElement("span");
      preview.className = "super-admin-product-detail-modal__media-preview";
      const previewUrl = item.type === "video" ? item.thumbnailUrl : item.url;
      if (previewUrl) {
        const image = document.createElement("img");
        image.src = previewUrl;
        image.alt = item.label;
        image.loading = "lazy";
        preview.append(image);
      } else {
        preview.append(createProductDetailIcon(
          item.type === "video"
            ? '<path d="m10 8 6 4-6 4Z" stroke-linejoin="round"></path><rect width="20" height="14" x="2" y="5" rx="2"></rect>'
            : '<path d="M5 7.5h14v9H5z" stroke-linejoin="round"></path><path d="m7.5 15 3.5-3.6 2.2 2.2 1.4-1.5 2 2.9" stroke-linecap="round" stroke-linejoin="round"></path><path d="M8.5 9.2h.01" stroke-linecap="round" stroke-width="3"></path>',
        ));
      }
      if (yoloEvidence) {
        const evidenceBadge = document.createElement("span");
        evidenceBadge.className = "super-admin-product-detail-modal__media-yolo-evidence";
        evidenceBadge.setAttribute("aria-label", yoloEvidence.message);
        evidenceBadge.title = yoloEvidence.message;
        evidenceBadge.innerHTML = createIconSvg(revisionWarningIconPaths);
        preview.append(evidenceBadge);
      }

      const label = document.createElement("span");
      label.className = "super-admin-product-detail-modal__media-label";
      label.textContent = item.label;
      const subLabel = document.createElement("span");
      subLabel.className = "super-admin-product-detail-modal__media-url";
      subLabel.textContent = item.subLabel || item.url;

      link.append(preview, label, subLabel);
      grid.append(link);
    }
    section.append(grid);
    return section;
  }

  function createProductDetailHeroMediaCarousel(product, mediaItems = null, headerBadges = []) {
    const items = Array.isArray(mediaItems)
      ? mediaItems
      : getProductDetailHeroMediaItems(product);
    if (!items.length) {
      return null;
    }

    const carousel = document.createElement("div");
    carousel.className = "super-admin-product-detail-modal__hero-gallery";
    carousel.classList.toggle("has-single-item", items.length === 1);
    carousel.setAttribute("aria-label", "Product media");

    const header = document.createElement("div");
    header.className = "super-admin-product-detail-modal__hero-gallery-header";
    const normalizedHeaderBadges = (Array.isArray(headerBadges) ? headerBadges : [])
      .filter((badge) => badge instanceof HTMLElement);
    if (normalizedHeaderBadges.length > 0) {
      const badgeRow = document.createElement("div");
      badgeRow.className = "super-admin-product-detail-modal__hero-badge-row";
      badgeRow.append(...normalizedHeaderBadges);
      header.append(badgeRow);
    }
    const controls = document.createElement("div");
    controls.className = "super-admin-product-detail-modal__hero-gallery-controls";
    const previousButton = document.createElement("button");
    previousButton.type = "button";
    previousButton.className = "super-admin-product-detail-modal__hero-gallery-button";
    previousButton.setAttribute("aria-label", "Previous media");
    previousButton.innerHTML = createIconSvg('<path d="m15 18-6-6 6-6"></path>');
    const nextButton = document.createElement("button");
    nextButton.type = "button";
    nextButton.className = "super-admin-product-detail-modal__hero-gallery-button";
    nextButton.setAttribute("aria-label", "Next media");
    nextButton.innerHTML = createIconSvg('<path d="m9 18 6-6-6-6"></path>');
    controls.append(previousButton, nextButton);
    header.append(controls);

    const track = document.createElement("div");
    track.className = "super-admin-product-detail-modal__hero-gallery-track";
    track.setAttribute("role", "list");

    items.forEach((item, index) => {
      const link = document.createElement("a");
      link.className = "super-admin-product-detail-modal__hero-gallery-item";
      link.href = item.url;
      link.target = "_blank";
      link.rel = "noopener";
      link.setAttribute("role", "listitem");
      link.setAttribute("aria-label", item.label || `Product image ${index + 1}`);
      link.title = item.label || `Product image ${index + 1}`;
      link.classList.toggle("is-video", item.type === "video");
      const yoloEvidence = getProductDetailMediaYoloEvidence(product, item);
      link.classList.toggle("has-yolo-evidence", Boolean(yoloEvidence));
      if (yoloEvidence) {
        link.title = `${item.label || `Product media ${index + 1}`} - ${yoloEvidence.label}`;
        link.setAttribute(
          "aria-label",
          `${item.label || `Product media ${index + 1}`}: ${yoloEvidence.label}`,
        );
      }

      const previewUrl = item.type === "video" ? item.thumbnailUrl : item.url;
      if (previewUrl) {
        const image = document.createElement("img");
        image.src = previewUrl;
        image.alt = item.label || `Product media ${index + 1}`;
        image.loading = "lazy";
        if (item.objectPosition) {
          image.style.objectPosition = item.objectPosition;
        }
        if (item.isSellerCrop) {
          link.classList.add("is-seller-crop");
        }
        image.addEventListener("load", () => syncControls());
        link.append(image);
        const overlay = document.createElement("div");
        overlay.className = "super-admin-product-detail-modal__hero-hover-overlay";
        overlay.innerHTML = `
          <svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
            <circle cx="11" cy="11" r="8"></circle>
            <path d="m21 21-4.35-4.35"></path>
          </svg>
        `;
        link.append(overlay);
      } else {
        link.append(createProductDetailIcon(
          '<path d="m10 8 6 4-6 4Z" stroke-linejoin="round"></path><rect width="20" height="14" x="2" y="5" rx="2"></rect>',
        ));
      }
      const typeBadge = document.createElement("span");
      typeBadge.className = "super-admin-product-detail-modal__hero-gallery-type";
      const isVideoType = item.type === "video";
      typeBadge.setAttribute("aria-label", isVideoType ? "Video" : "Image");
      typeBadge.title = isVideoType ? "Video" : "Image";
      typeBadge.innerHTML = createIconSvg(
        isVideoType
          ? '<path d="m16 13 5.223 3.482a.5.5 0 0 0 .777-.416V7.87a.5.5 0 0 0-.752-.432L16 10.5"></path><rect x="2" y="6" width="14" height="12" rx="2"></rect>'
          : '<rect width="18" height="18" x="3" y="3" rx="2" ry="2"></rect><circle cx="9" cy="9" r="2"></circle><path d="m21 15-3.086-3.086a2 2 0 0 0-2.828 0L6 21"></path>',
      );
      link.append(typeBadge);
      if (yoloEvidence) {
        const evidenceBadge = document.createElement("span");
        evidenceBadge.className = "super-admin-product-detail-modal__hero-gallery-yolo-evidence";
        evidenceBadge.setAttribute("aria-label", yoloEvidence.message);
        evidenceBadge.title = yoloEvidence.message;
        evidenceBadge.innerHTML = createIconSvg(revisionWarningIconPaths);
        link.append(evidenceBadge);
      }
      track.append(link);
    });

    const syncControls = () => {
      const canScroll = track.scrollWidth > track.clientWidth + 1;
      controls.hidden = !canScroll;
      if (!canScroll) {
        previousButton.disabled = true;
        nextButton.disabled = true;
        return;
      }
      previousButton.disabled = track.scrollLeft <= 1;
      nextButton.disabled = track.scrollLeft + track.clientWidth >= track.scrollWidth - 1;
    };
    const scrollTrack = (direction) => {
      track.scrollBy({
        left: direction * Math.max(160, track.clientWidth),
        behavior: "smooth",
      });
      window.setTimeout(syncControls, 180);
    };

    previousButton.addEventListener("click", () => scrollTrack(-1));
    nextButton.addEventListener("click", () => scrollTrack(1));
    track.addEventListener("scroll", syncControls, { passive: true });
    window.setTimeout(syncControls, 0);
    window.setTimeout(syncControls, 160);

    carousel.append(header, track);
    return carousel;
  }

  function getProductPartnerRecordById(type, id) {
    const normalizedId = String(id || "").trim();
    if (!normalizedId) {
      return null;
    }
    const config = getIntegratedPartnerConfig(type);
    const partners = Array.isArray(state[config.stateKey]) ? state[config.stateKey] : [];
    return partners.find((candidate) =>
      getIntegratedPartnerId(candidate).toLowerCase() === normalizedId.toLowerCase()
    ) || null;
  }

  function getProductPartnerNameById(type, id) {
    const partner = getProductPartnerRecordById(type, id);
    return partner ? getIntegratedPartnerName(partner) : "";
  }

  function createProductDetailPartnerList(type, ids) {
    const values = normalizeProductDetailUrlList(ids);
    const container = document.createElement("div");
    container.className = "super-admin-product-detail-modal__partner-list";

    if (!values.length) {
      const empty = document.createElement("span");
      empty.className = "super-admin-product-detail-modal__partner-empty";
      empty.textContent = "None selected";
      container.append(empty);
      return container;
    }

    const config = getIntegratedPartnerConfig(type);
    values.forEach((id) => {
      const partner = getProductPartnerRecordById(type, id);
      const badge = document.createElement("span");
      badge.className = "super-admin-product-detail-modal__partner-badge";
      badge.title = partner ? getIntegratedPartnerName(partner) : id;
      badge.setAttribute("aria-label", partner ? getIntegratedPartnerName(partner) : id);

      const imageUrl = getIntegratedPartnerImage(partner);
      if (imageUrl) {
        const image = document.createElement("img");
        image.src = imageUrl;
        image.alt = partner ? getIntegratedPartnerName(partner) : id;
        image.loading = "lazy";
        image.addEventListener("error", () => {
          image.remove();
          badge.append(createProductDetailIcon(config?.icon || integratedIconPaths[type === "delivery" ? "delivery" : "payment"]));
        }, { once: true });
        badge.append(image);
      } else {
        badge.append(createProductDetailIcon(config?.icon || integratedIconPaths[type === "delivery" ? "delivery" : "payment"]));
      }

      container.append(badge);
    });

    return container;
  }

  function getProductDetailHeroStatusBadge(product) {
    const rejectedEvidenceMatch = getProductRejectedEvidenceMatch(product);
    const revisionSignal = getProductRevisionSignal(product);
    const approvalStatus = String(product?.approvalStatus || "pending").trim().toLowerCase();
    const isReviewState = ["pending", "in review", "in_review", "review", "submitted"].includes(approvalStatus);
    const isRevisionRequested = String(revisionSignal?.status || "").trim().toLowerCase() === "requested";

    if (rejectedEvidenceMatch) {
      return { text: "Illegal product", tone: "danger" };
    }

    if (revisionSignal) {
      return { text: isRevisionRequested ? "Revision sent" : "Needs revision", tone: "warning" };
    }

    if (isReviewState) {
      return { text: "In review", tone: "info" };
    }

    return null;
  }

  function getProductDetailListingTypeLabel(product) {
    const explicitValue = String(
      product?.listingType ||
        product?.requestType ||
        product?.submissionType ||
        product?.changeType ||
        "",
    ).trim().toLowerCase();
    if (explicitValue.includes("edit") || explicitValue.includes("update")) {
      return "Edited";
    }
    if (explicitValue.includes("new") || explicitValue.includes("create")) {
      return "New listing";
    }

    const createdAt = new Date(product?.createdAt || product?.submittedAt || "");
    const updatedAt = new Date(product?.updatedAt || product?.approvalUpdatedAt || "");
    if (
      !Number.isNaN(createdAt.getTime()) &&
      !Number.isNaN(updatedAt.getTime()) &&
      updatedAt.getTime() - createdAt.getTime() > 60 * 1000
    ) {
      return "Edited";
    }
    return "New listing";
  }

  function isProductInLiveListing(product) {
    const productId = String(product?.id || "").trim();
    if (!productId) {
      return false;
    }
    return state.liveProductRequests.some((p) => String(p?.id || "").trim() === productId);
  }

  function getProductLiveListingAt(product) {
    return (
      product?.approvedAt ||
      product?.yoloInspection?.approvedEvidence?.approvedAt ||
      product?.approvalUpdatedAt ||
      product?.updatedAt ||
      product?.createdAt ||
      ""
    );
  }

  function isNewLiveListing(product) {
    const listingTypeLabel = getProductDetailListingTypeLabel(product);
    if (listingTypeLabel.toLowerCase().includes("edit")) {
      return false;
    }
    const timestamp = new Date(getProductLiveListingAt(product)).getTime();
    if (Number.isNaN(timestamp)) {
      return false;
    }
    return Date.now() - timestamp <= liveListingNewWindowMs;
  }

  function createProductRequestNewBadgeElement() {
    const badge = document.createElement("span");
    badge.className = "super-admin-product-request-card__new-badge";
    badge.textContent = "New";
    badge.setAttribute("aria-label", "New live listing");
    badge.title = "New live listing";
    return badge;
  }

  function setProductRequestCardTitle(titleElement, productName) {
    if (!(titleElement instanceof HTMLElement)) {
      return;
    }
    titleElement.className = "super-admin-product-request-card__title";
    titleElement.replaceChildren();
    const titleText = document.createElement("span");
    titleText.className = "super-admin-product-request-card__title-text";
    titleText.textContent = productName;
    titleElement.append(titleText);
  }

  function setProductRequestCardPriceMeta(priceMetaElement, product, isLiveListingView) {
    if (!(priceMetaElement instanceof HTMLElement)) {
      return;
    }
    priceMetaElement.replaceChildren();
    if (isLiveListingView) {
      const isNewListing = isNewLiveListing(product);
      priceMetaElement.className = "super-admin-product-request-card__rating super-admin-product-request-card__new-badge-wrap";
      priceMetaElement.hidden = false;
      priceMetaElement.title = "Listing rating";
      priceMetaElement.append(
        createProductRatingDisplayElement(product, {
          className: "super-admin-product-request-card__rating-display",
          emptyText: "0.0",
          valueFirst: true,
        }),
      );
      if (isNewListing) {
        priceMetaElement.append(createProductRequestNewBadgeElement());
      }
      return;
    }
    priceMetaElement.className = "super-admin-product-request-card__rating";
    priceMetaElement.hidden = false;
    priceMetaElement.title = "Listing rating";
    priceMetaElement.append(
      createProductRatingDisplayElement(product, {
        className: "super-admin-product-request-card__rating-display",
        emptyText: "New",
        valueFirst: true,
      }),
    );
  }

  function createProductDetailHeroLiveBadge() {
    const liveBadge = document.createElement("span");
    liveBadge.className = "super-admin-product-detail-modal__live-badge";
    liveBadge.innerHTML = `
      <svg xmlns="http://www.w3.org/2000/svg" width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
        <path d="M16.247 7.761a6 6 0 0 1 0 8.478"></path>
        <path d="M19.075 4.933a10 10 0 0 1 0 14.134"></path>
        <path d="M4.925 19.067a10 10 0 0 1 0-14.134"></path>
        <path d="M7.753 16.239a6 6 0 0 1 0-8.478"></path>
        <circle cx="12" cy="12" r="2"></circle>
      </svg>
      Live
    `;
    return liveBadge;
  }

  function createProductDetailHeroStatusBadgeElement(product) {
    const heroStatusBadge = getProductDetailHeroStatusBadge(product);
    if (!heroStatusBadge) {
      return null;
    }
    const badge = document.createElement("span");
    badge.className = `super-admin-product-detail-modal__hero-status-badge is-${heroStatusBadge.tone}`;
    badge.textContent = heroStatusBadge.text;
    return badge;
  }

  function createProductDetailHero(product) {
    const hero = document.createElement("section");
    hero.className = "super-admin-product-detail-modal__hero";

    const mediaItems = getProductDetailHeroMediaItems(product);
    const useMediaOnlyHero = shouldUseProductDetailMediaOnlyHero(product, mediaItems);
    const mediaCounts = getProductRequestMediaCounts(product);
    const cardDisplay = getProductCardDisplayImageData(product);
    const primaryHeroItem = mediaItems.find((item) => item?.type !== "video") || null;
    const imageUrl = String(primaryHeroItem?.url || cardDisplay.imageUrl || "").trim();
    const imageObjectPosition = String(
      primaryHeroItem?.objectPosition || cardDisplay.objectPosition || "50% 50%",
    ).trim();
    const isSellerCroppedHero = Boolean(primaryHeroItem?.isSellerCrop || cardDisplay.isCropped);
    const isSingleImageHero =
      Boolean(imageUrl) &&
      !useMediaOnlyHero &&
      mediaCounts.imageCount === 1 &&
      mediaCounts.videoCount === 0;
    const visual = document.createElement("div");
    visual.className = "super-admin-product-detail-modal__hero-visual";
    visual.classList.toggle("is-media-only", useMediaOnlyHero);
    visual.classList.toggle("is-single-image", isSingleImageHero);
    visual.classList.toggle("is-seller-crop-framing", isSellerCroppedHero || isSingleImageHero);
    const media = document.createElement("div");
    media.className = "super-admin-product-detail-modal__hero-media";
    media.hidden = useMediaOnlyHero;
    if (imageUrl) {
      const image = document.createElement("img");
      image.src = imageUrl;
      image.alt = String(product?.name || "Product image").trim();
      image.style.objectPosition = imageObjectPosition;
      media.append(image);
      if (isSingleImageHero) {
        const productTitle = String(product?.name || "Product image").trim();
        const heroZoomImageUrl =
          getProductCardZoomImageUrl(product, cardDisplay) ||
          getProductSellerFullUploadImageUrl(product) ||
          imageUrl;
        const zoomButton = createProductImageZoomButton({
          imageUrl: heroZoomImageUrl,
          title: productTitle,
          label: `Zoom ${productTitle}`,
          className: "super-admin-product-detail-modal__hero-zoom-button",
        });
        if (zoomButton) {
          media.classList.add("has-image-zoom");
          media.append(zoomButton);
        }
      }
    } else {
      media.append(createProductDetailIcon(
        '<path d="M5 7.5h14v9H5z" stroke-linejoin="round"></path><path d="m7.5 15 3.5-3.6 2.2 2.2 1.4-1.5 2 2.9" stroke-linecap="round" stroke-linejoin="round"></path><path d="M8.5 9.2h.01" stroke-linecap="round" stroke-width="3"></path>',
      ));
    }
    if (isProductInLiveListing(product)) {
      media.append(createProductDetailHeroLiveBadge());
    }
    const statusBadge = createProductDetailHeroStatusBadgeElement(product);
    if (statusBadge) {
      media.append(statusBadge);
    }

    const mediaOnlyHeaderBadges = [];
    if (useMediaOnlyHero) {
      if (isProductInLiveListing(product)) {
        mediaOnlyHeaderBadges.push(createProductDetailHeroLiveBadge());
      }
      const rowStatusBadge = createProductDetailHeroStatusBadgeElement(product);
      if (rowStatusBadge) {
        mediaOnlyHeaderBadges.push(rowStatusBadge);
      }
    }
    const imageCarousel = useMediaOnlyHero
      ? createProductDetailHeroMediaCarousel(product, mediaItems, mediaOnlyHeaderBadges)
      : null;
    visual.append(media);
    if (imageCarousel) {
      visual.append(imageCarousel);
    }

    const copy = document.createElement("div");
    copy.className = "super-admin-product-detail-modal__hero-copy";
    const titleRow = document.createElement("div");
    titleRow.className = "super-admin-product-detail-modal__title-row";
    const title = document.createElement("h3");
    title.dataset.superAdminProductDetailName = "true";
    const productTitleText = String(product?.name || "Unnamed product").trim();
    title.textContent = productTitleText;
    titleRow.append(title);

    copy.append(titleRow);
    hero.append(visual, copy);
    return hero;
  }

  function createProductDetailTagsSection(product) {
    const tags = getProductDetailTags(product);
    if (!tags.length) {
      return null;
    }

    const revision = getProductRevisionSignal(product);
    const tagList = document.createElement("div");
    tagList.className = "super-admin-product-detail-modal__tag-list";
    tags.forEach((tag) => {
      const evidence = findProductRevisionCategoryEvidence(revision, tag);
      const chip = document.createElement("span");
      chip.className = "super-admin-product-detail-modal__tag-chip";
      chip.classList.toggle("is-warning", Boolean(evidence));
      chip.append(document.createTextNode(tag));
      if (evidence) {
        const message = String(evidence.message || evidence.reason || "Tag needs revision.").trim();
        chip.title = message;
        chip.setAttribute("aria-label", `${tag}: ${message}`);
        const icon = document.createElement("span");
        icon.className = "super-admin-product-detail-modal__tag-warning-icon";
        icon.innerHTML = createIconSvg(revisionWarningIconPaths);
        chip.append(icon);
      }
      tagList.append(chip);
    });

    return createProductDetailSection("Tags", [tagList], {
      className: "super-admin-product-detail-modal__section--tags",
    });
  }

  function createProductDetailDescriptionSection(product) {
    const descriptionText = String(product?.description || "").trim();
    const descriptionImageUrls = normalizeProductDetailUrlList(product?.descriptionImageUrls);
    if (!descriptionText && !descriptionImageUrls.length) {
      return null;
    }

    const descriptionContent = [];
    if (descriptionText) {
      const description = document.createElement("p");
      description.className = "super-admin-product-detail-modal__description-text";
      description.dataset.productDetailDescriptionText = "true";
      description.textContent = descriptionText;

      const showMoreButton = document.createElement("button");
      showMoreButton.type = "button";
      showMoreButton.className = "super-admin-product-detail-modal__description-toggle";
      showMoreButton.dataset.productDetailDescriptionToggle = "true";
      showMoreButton.textContent = "Show more";
      showMoreButton.hidden = true;
      descriptionContent.push(description, showMoreButton);
    }

    if (descriptionImageUrls.length) {
      const mediaGrid = document.createElement("div");
      mediaGrid.className = "super-admin-product-detail-modal__description-media-grid";
      mediaGrid.setAttribute("aria-label", "Description images");
      const productName = String(product?.name || "Product").trim();

      descriptionImageUrls.forEach((imageUrl, index) => {
        const imageTitle = `${productName} description image ${index + 1}`;
        const mediaButton = document.createElement("button");
        mediaButton.type = "button";
        mediaButton.className = "super-admin-product-detail-modal__description-media-item";
        mediaButton.setAttribute("aria-label", `View ${imageTitle}`);
        mediaButton.title = "View image";

        const image = document.createElement("img");
        image.src = imageUrl;
        image.alt = imageTitle;
        image.loading = "lazy";

        const zoomHint = document.createElement("span");
        zoomHint.className = "super-admin-product-detail-modal__description-media-zoom";
        zoomHint.setAttribute("aria-hidden", "true");
        zoomHint.innerHTML = createIconSvg(
          '<circle cx="11" cy="11" r="8"></circle><path d="m21 21-4.35-4.35"></path>',
        );

        mediaButton.append(image, zoomHint);
        mediaButton.addEventListener("click", () => {
          openProductImageZoomModal(
            {
              imageUrl,
              title: `Description image ${index + 1}`,
              alt: imageTitle,
            },
            mediaButton,
          );
        });
        mediaGrid.append(mediaButton);
      });
      descriptionContent.push(mediaGrid);
    }

    return createProductDetailSection("Description", descriptionContent, {
      className: "super-admin-product-detail-modal__section--description",
    });
  }

  function isProductListingRestrictionActive(product) {
    const restriction = product?.listingRestriction && typeof product.listingRestriction === "object"
      ? product.listingRestriction
      : {};
    const expiresAtMs = new Date(
      restriction?.expiresAt || product?.listingRestrictionExpiresAt || "",
    ).getTime();
    const storedActive = restriction?.active === true || product?.isListingRestricted === true;
    return storedActive && Number.isFinite(expiresAtMs) && expiresAtMs > Date.now();
  }

  function closeProductListingRestrictionModal({ restoreFocus = true } = {}) {
    const overlay = activeProductListingRestrictionModal;
    const trigger = activeProductListingRestrictionTrigger;
    const aiController = activeProductListingRestrictionAiAbortController;
    activeProductListingRestrictionModal = null;
    activeProductListingRestrictionTrigger = null;
    activeProductListingRestrictionAiAbortController = null;
    if (aiController instanceof AbortController) {
      aiController.abort();
    }
    document.body.classList.remove("super-admin-product-listing-restriction-open");
    if (overlay instanceof HTMLElement) {
      overlay.classList.remove("is-open");
      window.setTimeout(() => overlay.remove(), 180);
    }
    if (restoreFocus && trigger instanceof HTMLElement && document.body.contains(trigger)) {
      trigger.focus({ preventScroll: true });
    }
  }

  function openProductListingRestrictionModal(product, trigger = null) {
    closeProductListingRestrictionModal({ restoreFocus: false });
    const productId = String(product?.id || "").trim();
    if (!productId) {
      setFeedback("Product listing is not available.", "error");
      return;
    }

    const productName = String(product?.name || "Product").trim() || "Product";
    const productImageUrl = [
      getProductImageUrl(product),
      product?.mainImageUrl,
      product?.thumbnailUrl,
      product?.productImageUrl,
    ]
      .map((value) => String(value || "").trim())
      .find(Boolean) || "";
    const productCategory = getProductCategoryLabel(product) || String(product?.category || "Product").trim() || "Product";
    const productSku = String(product?.sku || product?.code || product?.productCode || productId).trim();
    const productSeller = getProductCompanyLabel(product) || "Company";
    const productImageMarkup = productImageUrl
      ? `<img src="${escapeHtml(productImageUrl)}" alt="${escapeHtml(productName)}" loading="lazy" decoding="async" />`
      : `<span class="super-admin-product-listing-restriction-modal__product-placeholder" aria-hidden="true">${createIconSvg('<path d="M6 2h12a2 2 0 0 1 2 2v16l-8-4-8 4V4a2 2 0 0 1 2-2z"></path>')}</span>`;
    const titleId = `super-admin-listing-restriction-title-${Date.now()}`;
    const reasonMenuId = `${titleId}-reason-menu`;
    const durationMenuId = `${titleId}-duration-menu`;
    const sellerDescriptionId = `${titleId}-description`;
    const listingRestrictionReasons = [
      ["Misleading or inaccurate product information", "Misleading or inaccurate product information"],
      ["Prohibited or restricted product", "Prohibited or restricted product"],
      ["Counterfeit or intellectual property violation", "Counterfeit or intellectual property violation"],
      ["Unsafe, defective, or recalled product", "Unsafe, defective, or recalled product"],
      ["Price, discount, or promotion manipulation", "Price, discount, or promotion manipulation"],
      ["Stock or availability misrepresentation", "Stock or availability misrepresentation"],
      ["Other product policy violation", "Other product policy violation"],
    ];
    const listingRestrictionDurations = [
      ["1", "1 day"],
      ["3", "3 days"],
      ["7", "7 days"],
      ["14", "14 days"],
      ["30", "30 days"],
    ];
    const createListingRestrictionDropdown = ({
      name,
      placeholder,
      options,
      menuId,
      icon,
    }) => `
      <span class="universal-dropdown super-admin-product-listing-restriction-modal__dropdown" data-product-listing-restriction-dropdown>
        <select name="${escapeHtml(name)}" class="super-admin-product-listing-restriction-modal__native-select" tabindex="-1" aria-hidden="true" required>
          <option value="">${escapeHtml(placeholder)}</option>
          ${options.map(([value, label]) => `<option value="${escapeHtml(value)}">${escapeHtml(label)}</option>`).join("")}
        </select>
        <button
          type="button"
          class="super-admin-product-listing-restriction-modal__dropdown-trigger"
          data-product-listing-restriction-dropdown-trigger
          aria-haspopup="menu"
          aria-expanded="false"
          aria-controls="${escapeHtml(menuId)}"
        >
          ${icon ? createIconSvg(icon) : ""}
          <span data-product-listing-restriction-dropdown-label>${escapeHtml(placeholder)}</span>
          <svg class="super-admin-product-listing-restriction-modal__dropdown-arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
            <path d="m6 9 6 6 6-6"></path>
          </svg>
        </button>
        <div
          class="universal-dropdown__panel super-admin-company-card__action-menu super-admin-ban-modal__reason-menu super-admin-product-listing-restriction-modal__dropdown-menu"
          id="${escapeHtml(menuId)}"
          role="menu"
          hidden
          data-product-listing-restriction-dropdown-menu
        >
          ${options.map(([value, label]) => `
            <button
              type="button"
              class="super-admin-company-card__action-item super-admin-ban-modal__reason-option super-admin-product-listing-restriction-modal__dropdown-option"
              role="menuitemradio"
              aria-checked="false"
              data-product-listing-restriction-dropdown-option="${escapeHtml(value)}"
            >${escapeHtml(label)}</button>
          `).join("")}
        </div>
      </span>
    `;
    const overlay = document.createElement("div");
    overlay.className = "super-admin-product-listing-restriction-modal-overlay";
    overlay.setAttribute("aria-hidden", "false");
    overlay.innerHTML = `
      <section class="super-admin-product-listing-restriction-modal" role="dialog" aria-modal="true" aria-labelledby="${titleId}" tabindex="-1">
        <button type="button" class="super-admin-product-listing-restriction-modal__close" aria-label="Close restrict listing modal" title="Close">
          ${createCloseIconSvg()}
        </button>
        <header class="super-admin-product-listing-restriction-modal__header">
          <span class="super-admin-product-listing-restriction-modal__icon" aria-hidden="true">
            ${createIconSvg('<rect width="18" height="11" x="3" y="11" rx="2" ry="2"></rect><path d="M7 11V7a5 5 0 0 1 10 0v4"></path>')}
          </span>
          <h2 id="${titleId}">Restrict Product</h2>
          <p>Restrict this product from being visible to customers.</p>
          <article class="super-admin-product-listing-restriction-modal__product" aria-label="Product selected for restriction">
            <span class="super-admin-product-listing-restriction-modal__product-image">
              ${productImageMarkup}
            </span>
            <span class="super-admin-product-listing-restriction-modal__product-copy">
              <strong class="super-admin-product-listing-restriction-modal__product-name">${escapeHtml(productName)}</strong>
              <span class="super-admin-product-listing-restriction-modal__product-category">${escapeHtml(productCategory)}</span>
              <span class="super-admin-product-listing-restriction-modal__product-meta">
                <span>SKU: ${escapeHtml(productSku)}</span>
                <span>Seller: ${escapeHtml(productSeller)}</span>
              </span>
            </span>
          </article>
        </header>
        <form class="super-admin-product-listing-restriction-modal__form" novalidate>
          <label class="super-admin-product-listing-restriction-modal__field">
            <span>Restriction Reason <b class="super-admin-product-listing-restriction-modal__required-dot" aria-hidden="true"></b></span>
            ${createListingRestrictionDropdown({
              name: "reason",
              placeholder: "Select Restriction Reason",
              options: listingRestrictionReasons,
              menuId: reasonMenuId,
              icon: '<path d="M12 9v4"></path><path d="M12 17h.01"></path><path d="M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"></path>',
            })}
          </label>
          <label class="super-admin-product-listing-restriction-modal__field">
            <span>Restriction Duration <b class="super-admin-product-listing-restriction-modal__required-dot" aria-hidden="true"></b></span>
            ${createListingRestrictionDropdown({
              name: "durationDays",
              placeholder: "Select Duration",
              options: listingRestrictionDurations,
              menuId: durationMenuId,
              icon: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-clock-icon lucide-clock" aria-hidden="true"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg>',
            })}
          </label>
          <div class="super-admin-product-listing-restriction-modal__field">
            <div class="super-admin-product-listing-restriction-modal__description-heading">
              <label for="${sellerDescriptionId}">Description for Seller</label>
              <button
                type="button"
                class="super-admin-ban-modal__summarize-ai"
                data-product-listing-restriction-summarize-ai
                aria-label="Summarize listing restriction description with AI"
                title="Select a restriction reason, then create a seller-ready description"
                disabled
              >
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-sparkles-icon lucide-sparkles" aria-hidden="true">
                  <path d="M11.017 2.814a1 1 0 0 1 1.966 0l1.051 5.558a2 2 0 0 0 1.594 1.594l5.558 1.051a1 1 0 0 1 0 1.966l-5.558 1.051a2 2 0 0 0-1.594 1.594l-1.051 5.558a1 1 0 0 1-1.966 0l-1.051-5.558a2 2 0 0 0-1.594-1.594l-5.558-1.051a1 1 0 0 1 0-1.966l5.558-1.051a2 2 0 0 0 1.594-1.594z"></path>
                  <path d="M20 2v4"></path>
                  <path d="M22 4h-4"></path>
                  <circle cx="4" cy="20" r="2"></circle>
                </svg>
                <span data-product-listing-restriction-summarize-ai-label>Summarize with AI</span>
              </button>
            </div>
            <textarea id="${sellerDescriptionId}" name="sellerNote" rows="3" maxlength="500" placeholder="Add description (optional)"></textarea>
          </div>
          <label class="super-admin-product-listing-restriction-modal__notify">
            <span>Notify seller about this restriction</span>
            <input type="checkbox" name="notifySeller" checked />
            <span class="super-admin-product-listing-restriction-modal__toggle" aria-hidden="true"></span>
          </label>
          <p class="super-admin-product-listing-restriction-modal__status" role="status" aria-live="polite"></p>
          <div class="super-admin-product-listing-restriction-modal__actions">
            <button type="button" class="super-admin-product-listing-restriction-modal__cancel">Cancel</button>
            <button type="submit" class="super-admin-product-listing-restriction-modal__confirm">
              ${createIconSvg('<rect width="18" height="11" x="3" y="11" rx="2" ry="2"></rect><path d="M7 11V7a5 5 0 0 1 10 0v4"></path>')}
              <span>Restrict Product</span>
            </button>
          </div>
        </form>
      </section>
    `;

    const dialog = overlay.querySelector(".super-admin-product-listing-restriction-modal");
    const form = overlay.querySelector(".super-admin-product-listing-restriction-modal__form");
    const closeButton = overlay.querySelector(".super-admin-product-listing-restriction-modal__close");
    const cancelButton = overlay.querySelector(".super-admin-product-listing-restriction-modal__cancel");
    const confirmButton = overlay.querySelector(".super-admin-product-listing-restriction-modal__confirm");
    const status = overlay.querySelector(".super-admin-product-listing-restriction-modal__status");
    const productImage = overlay.querySelector(".super-admin-product-listing-restriction-modal__product-image img");
    const restrictionDropdowns = Array.from(overlay.querySelectorAll("[data-product-listing-restriction-dropdown]"));
    const restrictionReasonSelect = overlay.querySelector('select[name="reason"]');
    const restrictionDurationSelect = overlay.querySelector('select[name="durationDays"]');
    const sellerDescriptionInput = overlay.querySelector('textarea[name="sellerNote"]');
    const notifySellerInput = overlay.querySelector('input[name="notifySeller"]');
    const summarizeAiButton = overlay.querySelector("[data-product-listing-restriction-summarize-ai]");
    const summarizeAiLabel = overlay.querySelector("[data-product-listing-restriction-summarize-ai-label]");
    let listingAiSummarizing = false;

    const syncListingAiButton = () => {
      if (!(summarizeAiButton instanceof HTMLButtonElement)) {
        return;
      }
      const hasReason = Boolean(String(restrictionReasonSelect?.value || "").trim());
      summarizeAiButton.disabled = !hasReason || listingAiSummarizing;
      summarizeAiButton.classList.toggle("is-loading", listingAiSummarizing);
      summarizeAiButton.setAttribute("aria-busy", String(listingAiSummarizing));
      summarizeAiButton.title = !hasReason
        ? "Select a restriction reason, then create a seller-ready description"
        : listingAiSummarizing
          ? "AI is preparing the listing restriction description"
          : "Create a seller-ready description from the selected restriction reason";
      if (summarizeAiLabel instanceof HTMLElement) {
        summarizeAiLabel.textContent = listingAiSummarizing ? "Summarizing..." : "Summarize with AI";
      }
    };

    const cancelListingAiSummary = () => {
      const controller = activeProductListingRestrictionAiAbortController;
      activeProductListingRestrictionAiAbortController = null;
      if (controller instanceof AbortController) {
        controller.abort();
      }
      listingAiSummarizing = false;
      syncListingAiButton();
    };

    const summarizeListingRestrictionWithAi = async () => {
      if (listingAiSummarizing) {
        return;
      }
      const reason = String(restrictionReasonSelect?.value || "").replace(/\s+/g, " ").trim();
      if (!reason) {
        if (status instanceof HTMLElement) {
          status.textContent = "Select a restriction reason before using AI.";
          status.classList.add("is-error");
        }
        restrictionReasonSelect?.closest?.("[data-product-listing-restriction-dropdown]")
          ?.querySelector?.("[data-product-listing-restriction-dropdown-trigger]")
          ?.focus?.();
        return;
      }

      const controller = new AbortController();
      activeProductListingRestrictionAiAbortController?.abort?.();
      activeProductListingRestrictionAiAbortController = controller;
      listingAiSummarizing = true;
      syncListingAiButton();
      if (status instanceof HTMLElement) {
        status.textContent = "AI is preparing the seller description...";
        status.classList.remove("is-error");
      }

      try {
        const durationDays = Number(restrictionDurationSelect?.value || 0);
        const shouldNotifySeller = notifySellerInput instanceof HTMLInputElement && notifySellerInput.checked;
        const data = await requestSuperAdminAiModerationSummary({
          action: "restrict",
          subjectType: "listing",
          subjectName: productName,
          audience: "seller",
          reason,
          description: String(sellerDescriptionInput?.value || "").trim(),
          duration: Number.isInteger(durationDays) && durationDays > 0 ? `${durationDays} days` : "",
          impacts: [
            "Product listing hidden from customers",
            shouldNotifySeller ? "Seller receives a restriction notice" : "Seller notification is disabled",
          ],
        }, { signal: controller.signal });
        if (sellerDescriptionInput instanceof HTMLTextAreaElement) {
          sellerDescriptionInput.value = data.summary;
          sellerDescriptionInput.dispatchEvent(new Event("input", { bubbles: true }));
          sellerDescriptionInput.focus();
          sellerDescriptionInput.setSelectionRange(data.summary.length, data.summary.length);
        }
        if (status instanceof HTMLElement) {
          status.textContent = `${data.providerLabel || "AI"} prepared the description from the selected reason.`;
          status.classList.remove("is-error");
        }
        showSuperAdminAiSummarySnackbar();
      } catch (error) {
        if (controller.signal.aborted || error?.name === "AbortError") {
          return;
        }
        const needsIntegration = error?.status === 428 || error?.code === "CHAT_AI_UNAVAILABLE";
        if (status instanceof HTMLElement) {
          status.textContent = error instanceof Error ? error.message : "Unable to summarize the description with AI.";
          status.classList.add("is-error");
        }
        if (needsIntegration) {
          showSuperAdminSnackbar(
            "AI Integration Required",
            error instanceof Error ? error.message : "Connect and launch an AI integration before using this feature.",
            "error",
          );
        }
      } finally {
        if (activeProductListingRestrictionAiAbortController === controller) {
          activeProductListingRestrictionAiAbortController = null;
          listingAiSummarizing = false;
          syncListingAiButton();
        }
      }
    };

    summarizeAiButton?.addEventListener("click", () => {
      void summarizeListingRestrictionWithAi();
    });
    syncListingAiButton();

    if (productImage instanceof HTMLImageElement) {
      productImage.addEventListener("error", () => {
        productImage.closest(".super-admin-product-listing-restriction-modal__product-image")?.replaceChildren(
          createElement("span", "super-admin-product-listing-restriction-modal__product-placeholder"),
        );
        const placeholder = overlay.querySelector(".super-admin-product-listing-restriction-modal__product-placeholder");
        if (placeholder instanceof HTMLElement) {
          placeholder.setAttribute("aria-hidden", "true");
          placeholder.innerHTML = createIconSvg('<path d="M6 2h12a2 2 0 0 1 2 2v16l-8-4-8 4V4a2 2 0 0 1 2-2z"></path>');
        }
      }, { once: true });
    }

    const getRestrictionDropdownParts = (dropdown) => ({
      select: dropdown?.querySelector?.("select"),
      trigger: dropdown?.querySelector?.("[data-product-listing-restriction-dropdown-trigger]"),
      menu: dropdown?.querySelector?.("[data-product-listing-restriction-dropdown-menu]"),
      label: dropdown?.querySelector?.("[data-product-listing-restriction-dropdown-label]"),
      options: Array.from(dropdown?.querySelectorAll?.("[data-product-listing-restriction-dropdown-option]") || []),
    });
    const closeRestrictionDropdowns = (exceptDropdown = null) => {
      for (const dropdown of restrictionDropdowns) {
        if (!(dropdown instanceof HTMLElement) || dropdown === exceptDropdown) {
          continue;
        }
        const { trigger, menu } = getRestrictionDropdownParts(dropdown);
        dropdown.classList.remove("is-open");
        if (trigger instanceof HTMLElement) {
          trigger.setAttribute("aria-expanded", "false");
        }
        if (menu instanceof HTMLElement) {
          menu.hidden = true;
        }
      }
    };
    const syncRestrictionDropdown = (dropdown) => {
      const { select, label, options } = getRestrictionDropdownParts(dropdown);
      if (!(select instanceof HTMLSelectElement)) {
        return;
      }
      const selectedOption = select.selectedOptions?.[0];
      const fallbackLabel = select.options?.[0]?.textContent || "Select";
      const labelText = select.value && selectedOption ? selectedOption.textContent || select.value : fallbackLabel;
      if (label instanceof HTMLElement) {
        label.textContent = labelText;
        label.title = select.value ? labelText : "";
      }
      for (const option of options) {
        const isSelected = option.dataset.productListingRestrictionDropdownOption === select.value;
        option.classList.toggle("is-selected", isSelected);
        option.setAttribute("aria-checked", String(isSelected));
      }
    };
    const setRestrictionDropdownOpen = (dropdown, isOpen) => {
      if (!(dropdown instanceof HTMLElement)) {
        return;
      }
      const shouldOpen = Boolean(isOpen);
      if (shouldOpen) {
        closeRestrictionDropdowns(dropdown);
      }
      const { trigger, menu } = getRestrictionDropdownParts(dropdown);
      dropdown.classList.toggle("is-open", shouldOpen);
      if (trigger instanceof HTMLElement) {
        trigger.setAttribute("aria-expanded", String(shouldOpen));
      }
      if (menu instanceof HTMLElement) {
        menu.hidden = !shouldOpen;
      }
    };
    const setRestrictionDropdownValue = (dropdown, value) => {
      const { select } = getRestrictionDropdownParts(dropdown);
      if (select instanceof HTMLSelectElement) {
        select.value = String(value || "");
      }
      if (listingAiSummarizing) {
        cancelListingAiSummary();
      }
      syncRestrictionDropdown(dropdown);
      syncListingAiButton();
    };
    const focusRestrictionDropdownOption = (menu, nextIndex = 0) => {
      const items = Array.from(menu?.querySelectorAll?.("[data-product-listing-restriction-dropdown-option]") || [])
        .filter((item) => item instanceof HTMLElement && !item.hidden);
      if (!items.length) {
        return;
      }
      const normalizedIndex = ((nextIndex % items.length) + items.length) % items.length;
      items[normalizedIndex].focus();
    };

    for (const dropdown of restrictionDropdowns) {
      if (!(dropdown instanceof HTMLElement)) {
        continue;
      }
      const { trigger, menu, select, options } = getRestrictionDropdownParts(dropdown);
      trigger?.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        setRestrictionDropdownOpen(dropdown, !(menu instanceof HTMLElement) || menu.hidden);
      });
      trigger?.addEventListener("keydown", (event) => {
        if (!["Enter", " ", "ArrowDown"].includes(event.key)) {
          return;
        }
        event.preventDefault();
        setRestrictionDropdownOpen(dropdown, true);
        window.requestAnimationFrame(() => focusRestrictionDropdownOption(menu, 0));
      });
      menu?.addEventListener("keydown", (event) => {
        const items = Array.from(menu.querySelectorAll("[data-product-listing-restriction-dropdown-option]"));
        const currentIndex = items.indexOf(event.target);
        if (event.key === "ArrowDown" || event.key === "ArrowRight") {
          event.preventDefault();
          focusRestrictionDropdownOption(menu, currentIndex + 1);
        } else if (event.key === "ArrowUp" || event.key === "ArrowLeft") {
          event.preventDefault();
          focusRestrictionDropdownOption(menu, currentIndex - 1);
        } else if (event.key === "Home") {
          event.preventDefault();
          focusRestrictionDropdownOption(menu, 0);
        } else if (event.key === "End") {
          event.preventDefault();
          focusRestrictionDropdownOption(menu, items.length - 1);
        } else if (event.key === "Escape") {
          event.preventDefault();
          setRestrictionDropdownOpen(dropdown, false);
          trigger?.focus?.();
        }
      });
      for (const option of options) {
        option.addEventListener("click", (event) => {
          event.preventDefault();
          setRestrictionDropdownValue(dropdown, option.dataset.productListingRestrictionDropdownOption || "");
          setRestrictionDropdownOpen(dropdown, false);
          trigger?.focus?.();
        });
      }
      select?.addEventListener("change", () => {
        if (listingAiSummarizing) {
          cancelListingAiSummary();
        }
        syncRestrictionDropdown(dropdown);
        syncListingAiButton();
      });
      syncRestrictionDropdown(dropdown);
    }

    notifySellerInput?.addEventListener("change", () => {
      if (listingAiSummarizing) {
        cancelListingAiSummary();
      }
    });

    Object.assign(overlay.style, {
      position: "fixed",
      inset: "0",
      zIndex: "2600",
      display: "grid",
      placeItems: "center",
      padding: "20px",
      background: "rgba(15, 23, 42, 0.42)",
    });
    if (dialog instanceof HTMLElement) {
      Object.assign(dialog.style, {
        position: "relative",
        display: "block",
        width: "min(430px, calc(100vw - 32px))",
        maxHeight: "calc(100dvh - 32px)",
        overflowY: "auto",
        background: "#ffffff",
      });
    }

    const closeModal = () => closeProductListingRestrictionModal();
    closeButton?.addEventListener("click", closeModal);
    cancelButton?.addEventListener("click", closeModal);
    overlay.addEventListener("click", (event) => {
      if (event.target instanceof Element && !event.target.closest("[data-product-listing-restriction-dropdown]")) {
        closeRestrictionDropdowns();
      }
      if (event.target === overlay) {
        closeModal();
      }
    });
    form?.addEventListener("submit", async (event) => {
      event.preventDefault();
      if (!(form instanceof HTMLFormElement) || !(confirmButton instanceof HTMLButtonElement)) {
        return;
      }

      const formData = new FormData(form);
      const reason = String(formData.get("reason") || "").trim();
      const durationDays = Number(formData.get("durationDays"));
      const sellerNote = String(formData.get("sellerNote") || "").trim();
      const notifySeller = formData.get("notifySeller") === "on";
      if (!reason || !Number.isInteger(durationDays) || durationDays < 1) {
        if (status instanceof HTMLElement) {
          status.textContent = "Select a restriction reason and duration.";
          status.classList.add("is-error");
        }
        return;
      }

      if (!await requireSuperAdminFingerprint(`restrict listing for ${productName}`)) {
        return;
      }

      confirmButton.disabled = true;
      confirmButton.classList.add("is-loading");
      if (status instanceof HTMLElement) {
        status.textContent = "Restricting listing...";
        status.classList.remove("is-error");
      }
      try {
        const response = await fetch(
          `/api/super-admin/products/${encodeURIComponent(productId)}/restrict-listing`,
          {
            method: "POST",
            headers: rootHeaders({
              Accept: "application/json",
              "Content-Type": "application/json",
            }),
            body: JSON.stringify({ reason, durationDays, sellerNote, notifySeller }),
          },
        );
        const data = await response.json().catch(() => ({}));
        if (!response.ok) {
          throw new Error(data.message || "Unable to restrict product listing.");
        }

        closeProductListingRestrictionModal({ restoreFocus: false });
        if (isProductRequestDetailModalVisible()) {
          closeProductRequestDetails({ restoreFocus: false });
        }
        await loadProductRequests({ quiet: true, showLoading: false });
        renderProductRequests();
        void showSuccessValidationModal(
          "Listing Restricted",
          data.sellerNotified
            ? "The listing is hidden from customers and the seller was notified."
            : "The listing is hidden from customers.",
        );
      } catch (error) {
        confirmButton.disabled = false;
        confirmButton.classList.remove("is-loading");
        if (status instanceof HTMLElement) {
          status.textContent = error instanceof Error
            ? error.message
            : "Unable to restrict product listing.";
          status.classList.add("is-error");
        }
      }
    });

    document.body.append(overlay);
    document.body.classList.add("super-admin-product-listing-restriction-open");
    activeProductListingRestrictionModal = overlay;
    activeProductListingRestrictionTrigger = trigger instanceof HTMLElement ? trigger : null;
    window.requestAnimationFrame(() => {
      overlay.classList.add("is-open");
      dialog?.focus({ preventScroll: true });
    });
  }

  function createProductDetailLiveActionSection(product) {
    if (!isProductInLiveListing(product)) {
      return null;
    }

    const productId = String(product?.id || "").trim();
    if (!productId) {
      return null;
    }

    const productName = String(product?.name || "product").trim();
    const listingRestricted = isProductListingRestrictionActive(product);
    const createActionButton = ({ action, labelText, icon, danger = false, disabled = false }) => {
      const button = document.createElement("button");
      button.type = "button";
      button.className = `super-admin-product-detail-modal__inline-action${danger ? " is-danger" : ""}`;
      button.dataset.productDetailLiveAction = action;
      button.dataset.productId = productId;
      button.setAttribute("aria-label", `${labelText} for ${productName}`);
      button.title = labelText;
      button.disabled = disabled;
      button.innerHTML = `
        ${createIconSvg(icon)}
        <span>${labelText}</span>
      `;
      return button;
    };

    const actionRow = document.createElement("div");
    actionRow.className = "super-admin-product-detail-modal__action-row";
    actionRow.append(
      createActionButton({
        action: "restrict-listing",
        labelText: listingRestricted ? "Listing Restricted" : "Restrict Listing",
        icon: '<path d="M2.062 12.348a1 1 0 0 1 0-.696 10.75 10.75 0 0 1 19.876 0 1 1 0 0 1 0 .696 10.75 10.75 0 0 1-19.876 0"></path><circle cx="12" cy="12" r="3"></circle><path d="m3 3 18 18"></path>',
        disabled: listingRestricted,
      }),
      createActionButton({
        action: "restrict",
        labelText: "Restrict Company",
        icon: companyCardIconPaths.restrict,
      }),
      createActionButton({
        action: "delete",
        labelText: "Delete",
        icon: '<path d="M10 11v6"></path><path d="M14 11v6"></path><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6"></path><path d="M3 6h18"></path><path d="M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path>',
        danger: true,
      }),
    );
    actionRow.addEventListener("click", (event) => {
      if (!(event.target instanceof Element)) {
        return;
      }

      const actionButton = event.target.closest("[data-product-detail-live-action]");
      if (!(actionButton instanceof HTMLButtonElement) || actionButton.disabled) {
        return;
      }

      event.preventDefault();
      event.stopPropagation();
      closeProductRequestMenus();
      closeRejectedProductQuickMenu();

      const action = actionButton.dataset.productDetailLiveAction;
      if (action === "restrict-listing") {
        openProductListingRestrictionModal(product, actionButton);
        return;
      }
      if (action === "restrict") {
        restrictProductCompany(productId);
        return;
      }
      if (action === "delete") {
        void deleteProductRequest(productId, actionButton).then((didDelete) => {
          if (didDelete && isProductRequestDetailModalVisible()) {
            closeProductRequestDetails({ restoreFocus: false });
          }
        });
      }
    });

    return createProductDetailSection("Action", [actionRow], {
      className: "super-admin-product-detail-modal__section--actions",
    });
  }

  function createProductDetailBasicsSection(product) {
    const fields = [
      createProductDetailField("Product ID", product?.id),
      createProductDetailField("Admin ID", product?.adminId || product?.ownerAdminId || product?.companyId),
      createProductDetailField("Approval Status", getProductDetailApprovalLabel(product)),
      createProductDetailField("Visible / Active", product?.isActive !== false),
      createProductDetailField("Primary Category", createProductDetailCategoryValue(
        product,
        product?.category || getProductCategoryLabel(product),
      )),
      createProductDetailField("All Categories", createProductDetailCategoryValue(
        product,
        Array.isArray(product?.categories) ? product.categories : product?.category,
      )),
      createProductDetailField("Submitted", formatProductDetailDateTime(product?.submittedAt)),
      createProductDetailField("Created", formatProductDetailDateTime(product?.createdAt)),
      createProductDetailField("Updated", formatProductDetailDateTime(product?.updatedAt)),
      createProductDetailField("Approved At", formatProductDetailDateTime(product?.approvedAt)),
      createProductDetailField("Approved By", product?.approvedBy),
      createProductDetailField("Rejected At", formatProductDetailDateTime(product?.rejectedAt)),
      createProductDetailField("Rejected By", product?.rejectedBy),
      createProductDetailField("Rejection Reason", product?.rejectionReason, { wide: true, multiline: true }),
      createProductDetailField("Description", product?.description || "No product description provided.", { wide: true, multiline: true }),
    ];
    return createProductDetailSection("Product Information", [
      createProductDetailFieldGrid(fields),
    ]);
  }

  function createProductDetailCompanyValue(product) {
    const companyAdmin = getProductCompanyAdmin(product);
    const companyName = getProductCompanyLabel(product) || "Company";
    const companyImageUrl = getProductCompanyImageUrl(product);
    const value = document.createElement("span");
    value.className = "super-admin-product-detail-modal__company-value";

    const logo = document.createElement("span");
    logo.className = `super-admin-product-detail-modal__company-logo super-admin-company-card__logo super-admin-company-card__logo--tone-${getProductCompanyToneIndex(product, companyAdmin)}`;
    if (companyImageUrl) {
      const image = document.createElement("img");
      logo.classList.add("has-image");
      image.src = companyImageUrl;
      image.alt = `${companyName} logo`;
      image.loading = "lazy";
      image.addEventListener("error", () => {
        image.remove();
        logo.classList.remove("has-image");
        setCompanyLogoPlaceholder(logo);
      }, { once: true });
      logo.append(image);
    } else {
      setCompanyLogoPlaceholder(logo);
    }

    const name = document.createElement("span");
    name.className = "super-admin-product-detail-modal__company-name";
    name.textContent = companyName;
    name.title = companyName;
    value.append(logo, name);
    return value;
  }

  function createProductDetailPricingSection(product) {
    const displayPrice = product?.salesPrice ?? product?.originalPrice ?? product?.price;
    const approvalStatus = String(product?.approvalStatus || "").trim().toLowerCase();
    const isReviewListing =
      !isProductInLiveListing(product) &&
      ["pending", "in review", "in_review", "review", "submitted"].includes(approvalStatus);
    const listingTypeLabel = getProductDetailListingTypeLabel(product);
    const listingTypeTone = listingTypeLabel.toLowerCase().includes("edit") ? "edited" : "new";
    const listingTypeValue = document.createElement("span");
    listingTypeValue.className = `super-admin-product-detail-modal__listing-type-text is-${listingTypeTone}`;
    listingTypeValue.textContent = listingTypeLabel;
    const discountLabel = getProductDetailDiscountLabel(product);
    const discountValue = discountLabel === "No discount"
      ? discountLabel
      : createProductDetailChip(discountLabel, "discounted");
    const listingId = product?.sku || product?.code || product?.productCode || product?.id || "";
    const approvalDateValue =
      product?.approvedAt ||
      product?.yoloInspection?.approvedEvidence?.approvedAt ||
      (approvalStatus === "approved" || isProductInLiveListing(product)
        ? product?.approvalUpdatedAt
        : "");
    const fields = [
      createProductDetailField("Listing Type", listingTypeValue),
      createProductDetailField("Listing ID", createProductDetailCopyValue(listingId, "Listing ID")),
      createProductDetailField("Date of Approval", formatProductDetailDateTime(approvalDateValue)),
      createProductDetailField("Original Price", formatProductDetailMoney(product?.originalPrice ?? product?.price)),
      createProductDetailField("Sales Price", formatProductDetailMoney(product?.salesPrice)),
      createProductDetailField("Display Price", formatProductDetailMoney(displayPrice)),
      createProductDetailField("Discount", discountValue),
      createProductDetailField("Expiry Date", formatProductDetailDateDay(product?.expiryDate)),
      createProductDetailField("Barcode", product?.barcode || "Not set"),
      createProductDetailField("Stocked Date", formatProductDetailDateTime(product?.stockedDate)),
    ];
    if (!isReviewListing) {
      fields.splice(
        6,
        0,
        createProductDetailField("Stock", numberText(product?.stock ?? product?.inventoryStock ?? 0)),
        createProductDetailField("Sold", numberText(product?.sold ?? 0)),
        createProductDetailField("Rating", createProductDetailRatingValue(product)),
        createProductDetailField("Review / Comment Count", numberText(getProductReviewCount(product))),
      );
      fields.splice(fields.length - 1, 0, createProductDetailField("Move Barcode To Packing", Boolean(product?.moveBarcodeToPackingDashboard)));
    } else {
      fields.splice(
        6,
        0,
        createProductDetailField("Rating", createProductDetailRatingValue(product)),
      );
    }
    fields.push(createProductDetailField("Company", createProductDetailCompanyValue(product)));
    return createProductDetailSection("Listing Details", [
      createProductDetailFieldGrid(fields),
    ], { className: "super-admin-product-detail-modal__section--listing-details" });
  }

  function createProductDetailMediaInfoSection(product) {
    const detailCrops = Array.isArray(product?.detailsImageCrops) ? product.detailsImageCrops : [];
    const fields = [
      createProductDetailField("Main Image Index", numberText(product?.mainImageIndex ?? 0)),
      createProductDetailField("Card Image Source", product?.cardImageSourceUrl || "Not set", { multiline: true }),
      createProductDetailField("Card Position X", formatProductDetailPercent(product?.cardImagePositionX)),
      createProductDetailField("Card Position Y", formatProductDetailPercent(product?.cardImagePosition)),
      createProductDetailField("Buy Modal Image Source", product?.buyModalImageSourceUrl || "Not set", { multiline: true }),
      createProductDetailField("Buy Modal Position X", formatProductDetailPercent(product?.buyModalImagePositionX)),
      createProductDetailField("Buy Modal Position Y", formatProductDetailPercent(product?.buyModalImagePositionY)),
      createProductDetailField("Details Image Crops", numberText(detailCrops.length)),
      createProductDetailField("Details Video Source", product?.detailsVideoSourceUrl || "Not set", { multiline: true }),
      createProductDetailField("Details Video Position X", formatProductDetailPercent(product?.detailsVideoPositionX)),
      createProductDetailField("Details Video Position Y", formatProductDetailPercent(product?.detailsVideoPositionY)),
      createProductDetailField("Details Video Zoom", formatProductDetailPercent(product?.detailsVideoZoomPercent)),
      createProductDetailField("3D Model URL", product?.model3dUrl || product?.modelUrl || "Not set", { wide: true, multiline: true }),
      createProductDetailField(
        "3D Scan Images",
        numberText(Array.isArray(product?.model3dScanImageUrls) ? product.model3dScanImageUrls.length : 0),
      ),
    ];
    return createProductDetailSection("Media Details", [
      createProductDetailFieldGrid(fields),
    ]);
  }

  function createProductDetailPartnersSection(product) {
    const section = document.createElement("section");
    section.className = "super-admin-product-detail-modal__section super-admin-product-detail-modal__section--partner-methods";

    const createPartnerMethodBlock = (label, content) => {
      const block = document.createElement("div");
      block.className = "super-admin-product-detail-modal__partner-method";
      const title = document.createElement("h3");
      title.className = "super-admin-product-detail-modal__partner-method-title";
      title.textContent = label;
      block.append(title, content);
      return block;
    };

    section.append(
      createPartnerMethodBlock("Type of Delivery", createProductDetailPartnerList("delivery", product?.deliveryPartnerIds)),
      createPartnerMethodBlock("Payment Method", createProductDetailPartnerList("payment", product?.paymentPartnerIds)),
    );
    return section;
  }

  function createProductDetailVariantsSection(product) {
    const variants = Array.isArray(product?.variants) ? product.variants : [];
    if (!variants.length) {
      return null;
    }

    const section = document.createElement("section");
    section.className = "super-admin-product-detail-modal__section super-admin-product-detail-modal__section--variants";
    const heading = document.createElement("h3");
    heading.textContent = "Variants";
    section.append(heading);

    const list = document.createElement("div");
    list.className = "super-admin-product-detail-modal__variant-list";
    variants.forEach((variant, index) => {
      const dropdown = document.createElement("details");
      dropdown.className = "super-admin-product-detail-modal__variant-dropdown";
      dropdown.dataset.variantAnimating = "false";
      const summary = document.createElement("summary");
      summary.className = "super-admin-product-detail-modal__variant-summary";
      const title = document.createElement("span");
      title.className = "super-admin-product-detail-modal__variant-title";
      const variantTitleText = String(variant?.name || `Variant ${index + 1}`).trim();
      const titleTrack = document.createElement("span");
      titleTrack.className = "super-admin-product-detail-modal__variant-title-track";
      titleTrack.dataset.variantTitle = variantTitleText;
      titleTrack.textContent = variantTitleText;
      title.append(titleTrack);
      const meta = document.createElement("span");
      summary.append(title, meta);

      const imageUrl = String(variant?.imageUrl || "").trim();
      const fields = [
        createProductDetailField("Variant ID", variant?.id),
        createProductDetailField("Original Price", formatProductDetailMoney(variant?.originalPrice ?? variant?.price)),
        createProductDetailField("Sales Price", formatProductDetailMoney(variant?.salesPrice)),
        createProductDetailField("Stock", numberText(variant?.stock ?? 0)),
      ];

      const addOns = Array.isArray(variant?.addOns) ? variant.addOns : [];
      if (addOns.length) {
        fields.push(createProductDetailField(
          "Add-ons",
          addOns
            .map((addOn) => `${String(addOn?.name || addOn?.id || "Add-on").trim()} x ${numberText(addOn?.quantity ?? 1)}`)
            .join(", "),
          { wide: true, multiline: true },
        ));
      }
      const grid = createProductDetailFieldGrid(fields);
      grid.classList.add("super-admin-product-detail-modal__variant-field-grid");
      const content = document.createElement("div");
      content.className = "super-admin-product-detail-modal__variant-content";
      const contentInner = document.createElement("div");
      contentInner.className = "super-admin-product-detail-modal__variant-content-inner";
      if (imageUrl) {
        const imagePreview = document.createElement("span");
        imagePreview.className = "super-admin-product-detail-modal__variant-image-preview";
        const image = document.createElement("img");
        image.src = imageUrl;
        image.alt = `${variantTitleText} image`;
        image.loading = "lazy";
        imagePreview.append(image);
        contentInner.append(imagePreview);
      }
      contentInner.append(grid);
      content.append(contentInner);
      dropdown.append(summary, content);
      window.requestAnimationFrame(() => {
        title.classList.toggle("is-marquee", titleTrack.scrollWidth > title.clientWidth + 2);
      });
      summary.addEventListener("click", (event) => {
        if (dropdown.dataset.variantAnimating === "true") {
          event.preventDefault();
          return;
        }
        if (!dropdown.open) {
          event.preventDefault();
          dropdown.dataset.variantAnimating = "true";
          dropdown.open = true;
          content.getBoundingClientRect();
          window.requestAnimationFrame(() => {
            dropdown.classList.add("is-open");
            window.setTimeout(() => {
              dropdown.dataset.variantAnimating = "false";
            }, 220);
          });
          return;
        }
        event.preventDefault();
        dropdown.dataset.variantAnimating = "true";
        dropdown.classList.remove("is-open");
        dropdown.classList.add("is-closing");
        window.setTimeout(() => {
          dropdown.open = false;
          dropdown.classList.remove("is-closing");
          dropdown.dataset.variantAnimating = "false";
        }, 220);
      });
      list.append(dropdown);
    });
    section.append(list);
    return section;
  }

  function createProductDetailInspectionSection(product) {
    const revisionSignal = getProductRevisionSignal(product);
    const revisionMessage = String(revisionSignal?.message || "").trim();
    if (!revisionMessage) {
      return null;
    }

    const message = document.createElement("p");
    message.className = "super-admin-product-detail-modal__description-text super-admin-product-detail-modal__ai-inspection-text";
    message.textContent = revisionMessage;
    const isManualRevision =
      String(revisionSignal?.engine || "").trim().toLowerCase() === "manual-super-admin-revision" ||
      String(revisionSignal?.matchType || "").trim().toLowerCase() === "manual-super-admin-revision";
    return createProductDetailSection(isManualRevision ? "Revision Request" : "AI Inspection", [message], {
      className: "super-admin-product-detail-modal__section--ai-inspection",
    });
  }

