  async function handleDeliveryPartnerImageSelection() {
    const file = elements.deliveryPartnerImageInput instanceof HTMLInputElement
      ? elements.deliveryPartnerImageInput.files?.[0]
      : null;
    setDeliveryPartnerModalFeedback("");
    if (!(file instanceof File)) {
      deliveryPartnerImageFile = null;
      clearDeliveryPartnerImagePreview();
      if (elements.deliveryPartnerImageFileName) {
        elements.deliveryPartnerImageFileName.textContent = "No logo selected";
      }
      return;
    }
    if (!isSupportedProductImageUpload(file)) {
      deliveryPartnerImageFile = null;
      clearDeliveryPartnerImagePreview();
      elements.deliveryPartnerImageInput.value = "";
      if (elements.deliveryPartnerImageFileName) {
        elements.deliveryPartnerImageFileName.textContent = "No logo selected";
      }
      setDeliveryPartnerModalFeedback("Choose a JPG, PNG, or WEBP image.");
      return;
    }
    if (file.size > paymentPartnerImageMaxBytes) {
      deliveryPartnerImageFile = null;
      clearDeliveryPartnerImagePreview();
      elements.deliveryPartnerImageInput.value = "";
      if (elements.deliveryPartnerImageFileName) {
        elements.deliveryPartnerImageFileName.textContent = "No logo selected";
      }
      setDeliveryPartnerModalFeedback("The partner logo must be 4MB or smaller.");
      return;
    }

    const preparedFile = await prepareSquareImageUploadFile(file, {
      title: "Crop partner logo",
      copy: "Square logos are used as-is. Wider or taller images can be cropped to a square.",
    });
    if (elements.deliveryPartnerImageInput instanceof HTMLInputElement) {
      elements.deliveryPartnerImageInput.value = "";
    }
    if (!(preparedFile instanceof File)) {
      return;
    }

    deliveryPartnerImageFile = preparedFile;
    clearDeliveryPartnerImagePreview();
    deliveryPartnerImagePreviewUrl = URL.createObjectURL(preparedFile);
    if (elements.deliveryPartnerImagePreview instanceof HTMLImageElement) {
      elements.deliveryPartnerImagePreview.src = deliveryPartnerImagePreviewUrl;
      elements.deliveryPartnerImagePreview.hidden = false;
    }
    if (elements.deliveryPartnerImagePlaceholder instanceof SVGElement) {
      elements.deliveryPartnerImagePlaceholder.setAttribute("hidden", "");
    }
    if (elements.deliveryPartnerImageFileName) {
      elements.deliveryPartnerImageFileName.textContent = preparedFile.name;
    }
  }

  async function saveDeliveryPartnerFromModal() {
    if (deliveryPartnerModalSaving) {
      return;
    }
    const branch = String(elements.deliveryPartnerBranchInput?.value || "").trim();
    const apiKey = String(elements.deliveryPartnerApiKeyInput?.value || "").trim();
    const existingPartner = editingDeliveryPartnerId
      ? findIntegratedPartner("delivery", editingDeliveryPartnerId)
      : null;
    const isEditing = Boolean(existingPartner);
    setDeliveryPartnerModalFeedback("");
    if (!branch) {
      setDeliveryPartnerModalFeedback("Enter the delivery partner name.");
      elements.deliveryPartnerBranchInput?.focus();
      return;
    }
    if (!isEditing && !(deliveryPartnerImageFile instanceof File)) {
      setDeliveryPartnerModalFeedback("Choose a logo for the delivery partner.");
      return;
    }
    const duplicatePartner = state.deliveryPartners.some((partner) =>
      getIntegratedPartnerId(partner) !== editingDeliveryPartnerId
      &&
      getIntegratedPartnerName(partner).localeCompare(branch, undefined, { sensitivity: "accent" }) === 0
    );
    if (duplicatePartner) {
      setDeliveryPartnerModalFeedback("A delivery partner with this name already exists.");
      elements.deliveryPartnerBranchInput?.focus();
      elements.deliveryPartnerBranchInput?.select();
      return;
    }

    setDeliveryPartnerModalSaving(true);
    try {
      const imageUrl = deliveryPartnerImageFile instanceof File
        ? await uploadSuperAdminProductImageFile(deliveryPartnerImageFile)
        : getIntegratedPartnerImage(existingPartner);
      const endpoint = isEditing
        ? `/api/delivery-partners/${encodeURIComponent(editingDeliveryPartnerId)}`
        : "/api/delivery-partners";
      const payload = isEditing ? { branch, imageUrl } : { branch, imageUrl, apiKey };
      const response = await fetch(endpoint, {
        method: isEditing ? "PATCH" : "POST",
        headers: rootHeaders({
          Accept: "application/json",
          "Content-Type": "application/json",
        }),
        body: JSON.stringify(payload),
      });
      const data = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(data.message || `Unable to ${isEditing ? "update" : "save"} delivery partner.`);
      }
      await loadIntegratedPartners("delivery", { quiet: true });
      const successMessage = data.message || `Delivery partner ${isEditing ? "updated" : "saved"}.`;
      setDeliveryPartnerModalOpen(false, { restoreFocus: false });
      void showSuccessValidationModal(
        isEditing ? "Delivery Partner Updated" : "Delivery Partner Added",
        successMessage,
      );
    } catch (error) {
      setDeliveryPartnerModalFeedback(
        error instanceof Error ? error.message : `Unable to ${isEditing ? "update" : "save"} delivery partner.`,
      );
    } finally {
      setDeliveryPartnerModalSaving(false);
    }
  }

