  document.addEventListener("click", (event) => {
    const dropdown = elements.platformFeedbackFilterToggle;
    const panel = elements.platformFeedbackFilterPanel;
    if (!dropdown || !panel || dropdown.contains(event.target) || panel.contains(event.target)) return;
    togglePlatformFeedbackFilterDropdown(false);
  });

  document.addEventListener("click", (event) => {
    const dropdown = elements.filterDropdownToggle;
    const panel = elements.filterDropdownPanel;
    if (!dropdown || !panel || dropdown.contains(event.target) || panel.contains(event.target)) return;
    toggleFilterDropdown(false);
    if (!(event.target instanceof Element && event.target.closest(".super-admin-company-search"))) {
      closeCompanyActionMenus();
    }
  });

  document.addEventListener("click", (event) => {
    const dropdown = elements.productRequestFilterToggle;
    const panel = elements.productRequestFilterPanel;
    if (!dropdown || !panel || dropdown.contains(event.target) || panel.contains(event.target)) return;
    toggleProductRequestFilterDropdown(false);
  });

  document.addEventListener("click", (event) => {
    const dropdown = elements.storeTypeFilterToggle;
    const panel = elements.storeTypeFilterPanel;
    if (!dropdown || !panel || dropdown.contains(event.target) || panel.contains(event.target)) return;
    toggleStoreTypeFilterDropdown(false);
  });

  elements.filterClearBtn?.addEventListener("click", () => {
    state.companyFilters = {
      workspace: "all",
      team: "all",
      activity: "all",
      accountState: "all",
    };
    state.companySort = ["created-desc"];
    saveCompanyAccountFilter("all");
    state.companyPage = 1;
    syncCompanyFilterControlsFromState();
    syncCompanyFilterSummary();
    renderAdmins();
  });

  const workspaceColors = platformPaletteColors;

  function getSavedWorkspaceColor() {
    try {
      const savedColor = String(window.localStorage.getItem(workspaceColorStorageKey) || "")
        .trim()
        .toLowerCase();
      return /^#[0-9a-f]{6}$/i.test(savedColor) ? savedColor : "";
    } catch (error) {
      return "";
    }
  }

  // Reads or derives active workspace color for the current super admin flow.
  function getActiveWorkspaceColor() {
    const activeSharedColor = String(window.WebTheme?.getWorkspaceColor?.() || "")
      .trim()
      .toLowerCase();
    if (/^#[0-9a-f]{6}$/i.test(activeSharedColor)) {
      return activeSharedColor;
    }

    const savedColor = getSavedWorkspaceColor();
    if (savedColor) {
      return savedColor;
    }

    try {
      const theme = window.WebTheme?.loadThemeConfig?.()?.theme || window.WebTheme?.loadTheme?.();
      if (theme && window.WebTheme?.rgbToHex) {
        return window.WebTheme.rgbToHex(theme).toLowerCase();
      }
    } catch (error) {
      // Fall back to the legacy key below.
    }
    return "#2563eb";
  }

  function syncWorkspaceColorVariables(color) {
    const normalizedColor = String(color || "").trim().toLowerCase();
    const hexMatch = normalizedColor.match(/^#([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/i);
    if (!hexMatch) {
      return;
    }
    const rgb = hexMatch
      .slice(1)
      .map((part) => String(Number.parseInt(part, 16)))
      .join(", ");

    document.documentElement.style.setProperty("--accent", normalizedColor);
    document.documentElement.style.setProperty("--accent-text", normalizedColor);
    document.documentElement.style.setProperty("--accent-button-bg", normalizedColor);
    document.documentElement.style.setProperty("--accent-rgb", rgb);
  }

  // Applies workspace color to state and UI.
  async function applyWorkspaceColor(color) {
    const normalizedColor = String(color || "").trim().toLowerCase();
    if (!/^#[0-9a-f]{6}$/i.test(normalizedColor)) {
      return;
    }

    if (normalizedColor === getActiveWorkspaceColor()) {
      setColorPickerOpen(false);
      return;
    }

    setColorPickerOpen(false);
    if (!await requireSuperAdminFingerprint("change the workspace color")) {
      return;
    }

    if (window.WebTheme?.applyWorkspaceColor) {
      window.WebTheme.applyWorkspaceColor(normalizedColor, {
        source: "super-admin-picker",
      });
    } else {
      syncWorkspaceColorVariables(normalizedColor);
    }

    try {
      window.localStorage.setItem(workspaceColorStorageKey, normalizedColor);
    } catch (error) {
      // The theme API below still applies the color for this session.
    }

    if (window.WebTheme?.saveThemeConfig && window.WebTheme?.hexToTheme) {
      window.WebTheme.saveThemeConfig({
        mode: "solid",
        theme: window.WebTheme.hexToTheme(normalizedColor),
      });
    }

    renderColorOptions();

    let workspaceColorSaved = true;
    if (window.WebTheme?.saveWorkspaceColor) {
      try {
        await window.WebTheme.saveWorkspaceColor(normalizedColor, {
          headers: rootHeaders(),
        });
      } catch (error) {
        workspaceColorSaved = false;
        console.error("Unable to save the shared workspace color:", error);
        setFeedback("The color was applied locally but could not be saved for the workspace.", "error");
      }
    }

    if (typeof window.gmsApplyWorkspaceColorToRetinaScan === "function") {
      try {
        await window.gmsApplyWorkspaceColorToRetinaScan(normalizedColor, {
          source: "super-admin-picker",
          persist: true,
          preview: true,
        });
      } catch (error) {
        console.error("Unable to sync retina scan lighting to the workspace color:", error);
      }
    }

    if (workspaceColorSaved) {
      void showSuccessValidationModal(
        "Workspace Color Updated",
        `Workspace color changed to ${normalizedColor.toUpperCase()}.`,
      );
    }
  }

  // Renders color options from the latest state.
  function renderColorOptions() {
    if (!elements.colorOptions) return;
    elements.colorOptions.innerHTML = "";
    const savedColor = getActiveWorkspaceColor();

    workspaceColors.forEach((color) => {
      const optionButton = document.createElement("button");
      optionButton.type = "button";
      optionButton.className = "super-admin-color-option" + (color.toLowerCase() === savedColor ? " is-selected" : "");
      optionButton.style.backgroundColor = color;
      optionButton.setAttribute("aria-label", `Select ${color} color`);
      optionButton.setAttribute("aria-pressed", color.toLowerCase() === savedColor ? "true" : "false");
      optionButton.setAttribute("title", color);
      optionButton.addEventListener("click", () => {
        void applyWorkspaceColor(color);
      });
      elements.colorOptions.appendChild(optionButton);
    });
  }

  // Updates color picker open and synchronizes related UI state.
  function setColorPickerOpen(isOpen) {
    if (!elements.colorBtn || !elements.colorPanel) return;
    elements.colorBtn.setAttribute("aria-expanded", String(Boolean(isOpen)));
    elements.colorPanel.hidden = !isOpen;
    if (isOpen) {
      renderColorOptions();
    }
  }

  // Toggles color picker between open and closed states.
  function toggleColorPicker(show) {
    const shouldShow = show === undefined ? Boolean(elements.colorPanel?.hidden) : Boolean(show);
    setColorPickerOpen(shouldShow);
    if (shouldShow) {
      togglePlatformFeedbackFilterDropdown(false);
      toggleFilterDropdown(false);
      toggleProductRequestFilterDropdown(false);
      toggleNotificationPanel(false);
    }
  }

  elements.colorBtn?.addEventListener("click", (event) => {
    event.stopPropagation();
    toggleColorPicker();
  });

  document.addEventListener("click", (event) => {
    const colorBtn = elements.colorBtn;
    const colorPanel = elements.colorPanel;
    if (!colorBtn || !colorPanel || colorBtn.contains(event.target) || colorPanel.contains(event.target)) return;
    toggleColorPicker(false);
  });

  const restoredWorkspaceColor = getActiveWorkspaceColor();
  if (window.WebTheme?.applyWorkspaceColor) {
    window.WebTheme.applyWorkspaceColor(restoredWorkspaceColor, {
      source: "super-admin-cache",
    });
  } else {
    syncWorkspaceColorVariables(restoredWorkspaceColor);
  }
  renderColorOptions();

  async function initializeSharedWorkspaceColor() {
    if (!window.WebTheme?.syncWorkspaceColor) {
      return;
    }

    const sharedColor = await window.WebTheme.syncWorkspaceColor();
    if (!sharedColor && window.WebTheme?.saveWorkspaceColor) {
      try {
        await window.WebTheme.saveWorkspaceColor(getActiveWorkspaceColor(), {
          headers: rootHeaders(),
        });
      } catch (error) {
        console.error("Unable to initialize the shared workspace color:", error);
      }
    }
    renderColorOptions();
  }

  window.addEventListener("gms:workspace-color-changed", renderColorOptions);
  void initializeSharedWorkspaceColor();

  function normalizeProductRequestNotification(product = {}) {
    const explicitId = [product?.id, product?._id, product?.productId, product?.requestId]
      .map((value) => String(value || "").trim())
      .find(Boolean) || "";
    return {
      id: explicitId,
      productId: String(product?.productId || product?.id || "").trim(),
      requestId: String(product?.requestId || "").trim(),
      name: String(product?.name || "Unnamed product").trim(),
      adminId: String(product?.adminId || "").trim(),
      ownerAdminId: String(product?.ownerAdminId || "").trim(),
      companyId: String(product?.companyId || "").trim(),
      sellerId: String(product?.sellerId || "").trim(),
      sellerAdminId: String(product?.sellerAdminId || "").trim(),
      storeId: String(product?.storeId || "").trim(),
      workspaceId: String(product?.workspaceId || "").trim(),
      tenantId: String(product?.tenantId || "").trim(),
      submittedAt: String(product?.submittedAt || "").trim(),
      createdAt: String(product?.createdAt || "").trim(),
      updatedAt: String(product?.updatedAt || "").trim(),
      approvalUpdatedAt: String(product?.approvalUpdatedAt || "").trim(),
      companyName: String(product?.companyName || "").trim(),
      storeName: String(product?.storeName || "").trim(),
      businessName: String(product?.businessName || "").trim(),
      companyPictureUrl: String(product?.companyPictureUrl || "").trim(),
      companyProfileImageUrl: String(product?.companyProfileImageUrl || "").trim(),
      companyImageUrl: String(product?.companyImageUrl || "").trim(),
      companyLogoUrl: String(product?.companyLogoUrl || "").trim(),
      storeLogoUrl: String(product?.storeLogoUrl || "").trim(),
      profileImageUrl: String(product?.profileImageUrl || "").trim(),
      logoUrl: String(product?.logoUrl || "").trim(),
    };
  }

  function setProductRequestNotifications(products) {
    state.productNotifications = (Array.isArray(products) ? products : [])
      .filter((product) => product && typeof product === "object")
      .map(normalizeProductRequestNotification);
    try {
      const cachedNotifications = state.productNotifications.slice(0, 100).map((product) => {
        const cachedProduct = { ...product };
        for (const field of [
          "companyPictureUrl",
          "companyProfileImageUrl",
          "companyImageUrl",
          "companyLogoUrl",
          "storeLogoUrl",
          "profileImageUrl",
          "logoUrl",
        ]) {
          if (String(cachedProduct[field] || "").length > 250000) {
            cachedProduct[field] = "";
          }
        }
        return cachedProduct;
      });
      window.localStorage.setItem(notificationCacheStorageKey, JSON.stringify(cachedNotifications));
    } catch (error) {
      // The live notification state remains available when browser storage is full.
    }
    updateNotificationCount();
    renderNotificationPanel();
    syncAutoSeenSuperAdminNotifications();
  }

  function setLinkedNotifications(notifications) {
    state.linkedNotifications = (Array.isArray(notifications) ? notifications : [])
      .filter((notification) => notification && typeof notification === "object");
    try {
      window.localStorage.setItem(
        linkedNotificationCacheStorageKey,
        JSON.stringify(state.linkedNotifications.slice(0, 200)),
      );
    } catch (error) {
      // The live inbox remains available when browser storage is full.
    }
    updateNotificationCount();
    renderNotificationPanel();
    syncAutoSeenSuperAdminNotifications();
  }

  function getProductRequestNotificationId(product, index = 0) {
    const explicitId = [product?.id, product?._id, product?.productId, product?.requestId]
      .map((value) => String(value || "").trim())
      .find(Boolean);
    if (explicitId) {
      return explicitId;
    }
    return [
      String(product?.name || "product").trim(),
      String(product?.submittedAt || product?.createdAt || product?.updatedAt || "").trim(),
      String(index),
    ].join("::");
  }

  function getProductRequestNotificationEntries() {
    return state.productNotifications.map((product, index) => ({
      id: getProductRequestNotificationId(product, index),
      product,
    }));
  }

  function getLinkedNotificationEntries() {
    return (Array.isArray(state.linkedNotifications) ? state.linkedNotifications : [])
      .filter((notification) => notification && typeof notification === "object")
      .map((notification, index) => ({
        kind: "inbox",
        id: String(notification.id || `inbox-${index}`).trim(),
        notification,
        product: {
          id: notification.productId,
          productId: notification.productId,
          name: notification.productName,
          submittedAt: notification.createdAt,
          createdAt: notification.createdAt,
          adminId: notification.adminId,
          companyName: notification.companyName,
          storeName: notification.storeName,
          businessName: notification.businessName,
          companyPictureUrl: notification.companyPictureUrl,
          companyProfileImageUrl: notification.companyProfileImageUrl,
          companyLogoUrl: notification.companyLogoUrl,
          profileImageUrl: notification.profileImageUrl,
          logoUrl: notification.logoUrl,
          feedbackId: notification.feedbackId,
        },
        createdAt: String(notification.createdAt || "").trim(),
      }));
  }

  function isSuperAdminNotificationRead(entry) {
    if (!entry?.id) {
      return true;
    }
    const notification = entry?.notification;
    if (notification) {
      if (notification.read === true) {
        return true;
      }
      const status = String(notification.status || "").trim().toLowerCase();
      if (status === "read") {
        return true;
      }
    }
    return state.notificationReadIds.has(entry.id);
  }

  function applyLocalSuperAdminNotificationRead(entry) {
    if (!entry?.id) {
      return;
    }
    state.notificationReadIds.add(entry.id);
    if (entry?.notification && typeof entry.notification === "object") {
      entry.notification.status = "read";
      entry.notification.read = true;
    }
    const linkedIndex = (Array.isArray(state.linkedNotifications) ? state.linkedNotifications : [])
      .findIndex((notification) => String(notification?.id || "").trim() === entry.id);
    if (linkedIndex >= 0) {
      state.linkedNotifications[linkedIndex] = {
        ...state.linkedNotifications[linkedIndex],
        status: "read",
        read: true,
      };
    }
  }

  async function markSuperAdminNotificationsReadOnServer(criteria = {}) {
    try {
      const response = await fetch("/api/super-admin/notifications/read", {
        method: "PATCH",
        headers: rootHeaders({
          Accept: "application/json",
          "Content-Type": "application/json",
        }),
        body: JSON.stringify(criteria),
      });
      const payload = await response.json().catch(() => ({}));
      if (!response.ok) {
        return null;
      }
      if (Array.isArray(payload?.notifications)) {
        setLinkedNotifications(payload.notifications);
      }
      return payload;
    } catch (error) {
      return null;
    }
  }

  function markSuperAdminNotificationRead(entry, options = {}) {
    if (!entry?.id || isSuperAdminNotificationRead(entry)) {
      return;
    }
    applyLocalSuperAdminNotificationRead(entry);
    saveNotificationReadIds();
    updateNotificationCount();
    if (!options.skipRender) {
      renderNotificationPanel();
    }
    if (!options.skipPersist) {
      void markSuperAdminNotificationsReadOnServer({ ids: [entry.id] });
    }
  }

  function markSuperAdminNotificationsReadForProduct(productId, options = {}) {
    const normalizedProductId = String(productId || "").trim();
    if (!normalizedProductId) {
      return;
    }
    const entries = getNotificationPanelEntries().filter((entry) => {
      const entryProductId = String(
        entry?.product?.id
        || entry?.product?.productId
        || entry?.notification?.productId
        || "",
      ).trim();
      return entryProductId === normalizedProductId;
    });
    for (const entry of entries) {
      markSuperAdminNotificationRead(entry, { skipRender: true, skipPersist: true });
    }
    saveNotificationReadIds();
    updateNotificationCount();
    if (!options.skipRender) {
      renderNotificationPanel();
    }
    void markSuperAdminNotificationsReadOnServer({
      productId: normalizedProductId,
      types: ["product-submitted", "product-resubmitted", "product-revision-resubmitted", "product-created"],
    });
  }

  function markSuperAdminNotificationsReadForFeedback(feedbackId, options = {}) {
    const normalizedFeedbackId = String(feedbackId || "").trim();
    if (!normalizedFeedbackId) {
      return;
    }
    const entries = getNotificationPanelEntries().filter((entry) => {
      const type = getSuperAdminNotificationType(entry);
      if (!["seller-feedback", "user-feedback"].includes(type)) {
        return false;
      }
      return resolveFeedbackIdFromNotificationEntry(entry) === normalizedFeedbackId
        || String(entry?.notification?.feedbackId || "").trim() === normalizedFeedbackId;
    });
    for (const entry of entries) {
      markSuperAdminNotificationRead(entry, { skipRender: true, skipPersist: true });
    }
    saveNotificationReadIds();
    updateNotificationCount();
    if (!options.skipRender) {
      renderNotificationPanel();
    }
    void markSuperAdminNotificationsReadOnServer({
      feedbackId: normalizedFeedbackId,
      types: ["seller-feedback", "user-feedback"],
    });
  }

  function syncAutoSeenSuperAdminNotifications() {
    const pendingProductIds = new Set(
      (Array.isArray(state.productNotifications) ? state.productNotifications : [])
        .map((product) => String(product?.id || product?.productId || "").trim())
        .filter(Boolean),
    );
    const feedbackRows = [
      ...(Array.isArray(state.platformFeedback?.seller) ? state.platformFeedback.seller : []),
      ...(Array.isArray(state.platformFeedback?.user) ? state.platformFeedback.user : []),
    ];
    const resolvedFeedbackIds = new Set(
      feedbackRows
        .filter((entry) => normalizePlatformFeedbackStatusValue(entry?.status) === "resolved")
        .map((entry) => String(entry?.id || "").trim())
        .filter(Boolean),
    );
    let changed = false;
    for (const entry of getNotificationPanelEntries()) {
      if (isSuperAdminNotificationRead(entry)) {
        continue;
      }
      const type = getSuperAdminNotificationType(entry);
      const productId = String(
        entry?.product?.id
        || entry?.product?.productId
        || entry?.notification?.productId
        || "",
      ).trim();
      if (
        productId &&
        ["product-submitted", "product-resubmitted", "product-revision-resubmitted", "product-created"].includes(type) &&
        !pendingProductIds.has(productId)
      ) {
        applyLocalSuperAdminNotificationRead(entry);
        changed = true;
        continue;
      }
      const feedbackId = resolveFeedbackIdFromNotificationEntry(entry);
      if (
        feedbackId &&
        ["seller-feedback", "user-feedback"].includes(type) &&
        resolvedFeedbackIds.has(feedbackId)
      ) {
        applyLocalSuperAdminNotificationRead(entry);
        changed = true;
      }
    }
    if (changed) {
      saveNotificationReadIds();
      updateNotificationCount();
      renderNotificationPanel();
    }
  }

  function resolveFeedbackIdFromNotificationEntry(entry) {
    const notification = entry?.notification;
    const explicitId = String(notification?.feedbackId || entry?.product?.feedbackId || "").trim();
    if (explicitId) {
      return explicitId;
    }
    const type = String(notification?.type || "").trim().toLowerCase() === "user-feedback" ? "user" : "seller";
    const createdAtMs = Date.parse(String(notification?.createdAt || entry?.createdAt || "").trim()) || 0;
    const adminId = String(notification?.adminId || "").trim();
    const entries = Array.isArray(state.platformFeedback?.[type]) ? state.platformFeedback[type] : [];
    let bestMatch = "";
    let bestDelta = Number.POSITIVE_INFINITY;
    for (const item of entries) {
      const itemMs = Date.parse(String(item?.createdAt || "").trim()) || 0;
      if (!itemMs) {
        continue;
      }
      const itemAdminId = String(item?.adminId || "").trim();
      if (adminId && itemAdminId && itemAdminId !== adminId) {
        continue;
      }
      const delta = Math.abs(itemMs - createdAtMs);
      if (delta <= 15000 && delta < bestDelta) {
        bestDelta = delta;
        bestMatch = String(item?.id || "").trim();
      }
    }
    return bestMatch;
  }

  function preparePlatformFeedbackNotificationNavigation(feedbackType, feedbackId) {
    const type = feedbackType === "user" ? "user" : "seller";
    if (!state.platformFeedback.page || typeof state.platformFeedback.page !== "object") {
      state.platformFeedback.page = { seller: 1, user: 1 };
    }
    const normalizedFeedbackId = String(feedbackId || "").trim();
    if (normalizedFeedbackId) {
      const entries = getFilteredPlatformFeedbackEntries(type);
      const targetIndex = entries.findIndex(
        (entry) => String(entry?.id || "").trim() === normalizedFeedbackId,
      );
      if (targetIndex >= 0) {
        const pageSize = Math.max(1, Number(state.platformFeedback?.pageSize) || superAdminListViewPageSize);
        state.platformFeedback.page[type] = Math.floor(targetIndex / pageSize) + 1;
      }
      state.platformFeedback.selectedId = normalizedFeedbackId;
      state.platformFeedback.selectedType = type;
    }
  }

  function prepareCompanyNotificationNavigation(adminId) {
    const normalizedAdminId = String(adminId || "").trim();
    if (!normalizedAdminId) {
      return;
    }
    const filteredAdmins = sortAdmins(getFilteredAdmins(state.admins));
    const targetIndex = filteredAdmins.findIndex(
      (admin) => String(getCompanyId(admin) || "").trim() === normalizedAdminId,
    );
    if (targetIndex >= 0) {
      const pageSize = getCompanyPageSizeForAccountFilter(
        state.companyAccountFilter,
        filteredAdmins.length,
      );
      state.companyPage = Math.floor(targetIndex / Math.max(1, pageSize)) + 1;
    }
  }

  function prepareSuperAdminNotificationTrace(entry) {
    const destination = getSuperAdminNotificationDestination(entry);
    const type = getSuperAdminNotificationType(entry);
    const productId = String(
      entry?.product?.id
      || entry?.product?.productId
      || entry?.notification?.productId
      || entry?.id
      || "",
    ).trim();
    const adminId = String(entry?.notification?.adminId || entry?.product?.adminId || "").trim();

    state.notificationTrace = {
      kind: "",
      productId: "",
      feedbackId: "",
      feedbackType: "",
      adminId: "",
      openDrawer: false,
    };
    state.notificationTraceProductId = "";

    if (destination === "product-requests" && productId) {
      state.notificationTrace.kind = "product";
      state.notificationTrace.productId = productId;
      state.notificationTraceProductId = productId;
      prepareProductRequestNotificationNavigation(productId);
      return;
    }

    if (destination === "seller-feedback" || destination === "user-feedback") {
      const feedbackType = destination === "user-feedback" ? "user" : "seller";
      const feedbackId = resolveFeedbackIdFromNotificationEntry(entry);
      state.notificationTrace.kind = "feedback";
      state.notificationTrace.feedbackId = feedbackId;
      state.notificationTrace.feedbackType = feedbackType;
      state.notificationTrace.openDrawer = Boolean(feedbackId);
      preparePlatformFeedbackNotificationNavigation(feedbackType, feedbackId);
      return;
    }

    if (destination === "companies" && adminId) {
      state.notificationTrace.kind = "company";
      state.notificationTrace.adminId = adminId;
      state.notificationTrace.openDrawer = [
        "seller-profile-updated",
        "seller-account-deletion",
        "seller-account-deletion-canceled",
        "seller-account-deleted",
      ].includes(type);
      prepareCompanyNotificationNavigation(adminId);
    }
  }

  function getNotificationPanelEntries() {
    const inboxEntries = getLinkedNotificationEntries();
    const inboxProductIds = new Set(
      inboxEntries
        .filter((entry) =>
          ["product-submitted", "product-resubmitted", "product-revision-resubmitted", "product-created"].includes(
            String(entry.notification?.type || "").trim().toLowerCase(),
          ),
        )
        .map((entry) => String(entry.notification?.productId || entry.product?.id || "").trim())
        .filter(Boolean),
    );
    const productEntries = getProductRequestNotificationEntries()
      .filter((entry) => !inboxProductIds.has(String(entry.id || entry.product?.id || "").trim()))
      .map((entry) => ({
        kind: "product-request",
        ...entry,
        createdAt: String(entry.product?.submittedAt || entry.product?.createdAt || "").trim(),
      }));
    return [...inboxEntries, ...productEntries].sort((left, right) => {
      const leftWelcome = getSuperAdminNotificationType(left) === "welcome";
      const rightWelcome = getSuperAdminNotificationType(right) === "welcome";
      if (leftWelcome && !rightWelcome) return -1;
      if (!leftWelcome && rightWelcome) return 1;
      return String(right.createdAt || "").localeCompare(String(left.createdAt || ""));
    });
  }

  function isProductRequestNotificationUnread(entry) {
    return !isSuperAdminNotificationRead(entry);
  }

  function saveNotificationReadIds() {
    try {
      const values = Array.from(state.notificationReadIds).slice(-2000);
      window.localStorage.setItem(notificationReadStorageKey, JSON.stringify(values));
    } catch (error) {
      // Notification filtering still works for the current page session.
    }
  }

  function markProductRequestNotificationRead(entry) {
    markSuperAdminNotificationRead(entry, { skipPersist: false });
  }

  function prepareProductRequestNotificationNavigation(productId) {
    state.notificationTraceProductId = String(productId || "").trim();
    state.productRequestView = "in-review";
    state.productRequestPage = 1;
    state.productRequestSearchTerm = "";
    state.productRequestSearchLoading = false;
    window.clearTimeout(productRequestSearchTimer);

    if (elements.productRequestSearch) {
      elements.productRequestSearch.value = "";
      setSuperAdminSearchInputBusy(elements.productRequestSearch, false);
    }
    setProductRequestRadioChecked('[data-super-admin-product-request-filter="category"]', "all");
    setProductRequestRadioChecked('[data-super-admin-product-request-filter="pricing"]', "all");
    setProductRequestRadioChecked('[data-super-admin-product-request-filter="signal"]', "all");
    setProductRequestSortControlsChecked(["newest"]);
    state.productRequestFilters = {
      category: "all",
      pricing: "all",
      signal: "all",
    };
    state.productRequestSort = ["newest"];
    syncProductRequestFilterSummary();
    syncProductRequestView();
    toggleProductRequestFilterDropdown(false);
  }

  function syncNotificationFilterControls() {
    for (const button of elements.notificationFilterButtons) {
      const isActive = button.dataset.notificationFilter === state.notificationFilter;
      button.classList.toggle("is-active", isActive);
      button.setAttribute("aria-selected", isActive ? "true" : "false");
      button.tabIndex = isActive ? 0 : -1;
    }
  }

  // Updates notification count and dependent UI.
  function updateNotificationCount() {
    const entries = getNotificationPanelEntries();
    const unreadCount = entries.filter(isProductRequestNotificationUnread).length;
    if (elements.notificationBadge) {
      elements.notificationBadge.textContent = unreadCount > 99 ? "99+" : numberText(unreadCount);
      elements.notificationBadge.hidden = unreadCount <= 0;
    }
  }

  function getSuperAdminNotificationType(entry) {
    if (entry?.kind === "product-request") {
      return "product-submitted";
    }
    return String(entry?.notification?.type || "notice").trim().toLowerCase();
  }

  function getSuperAdminNotificationActorName(entry) {
    return String(
      entry?.notification?.createdBy
      || entry?.notification?.companyName
      || entry?.notification?.storeName
      || entry?.notification?.businessName
      || getProductCompanyLabel(entry?.product || {})
      || "Seller",
    ).trim();
  }

  function parseFeedbackNotificationCategory(notification) {
    const reason = String(notification?.reason || "").trim();
    const parts = reason.split("·").map((part) => part.trim()).filter(Boolean);
    for (let index = 1; index < parts.length; index += 1) {
      const part = parts[index];
      if (!/attachment/i.test(part)) {
        return part;
      }
    }
    return "";
  }

  function getFeedbackNotificationLabel(notification) {
    const category = parseFeedbackNotificationCategory(notification);
    if (category) {
      return category;
    }
    const type = String(notification?.type || "").trim().toLowerCase();
    if (type === "user-feedback") {
      return "user feedback";
    }
    return "company feedback";
  }

  function getSuperAdminNotificationVisualConfig(entry) {
    const type = getSuperAdminNotificationType(entry);
    const configs = {
      "product-submitted": {
        modifier: "listing",
        iconPaths: superAdminNotificationIconPaths.listingReview,
        badgeTitle: "Listing in review",
      },
      "product-created": {
        modifier: "listing",
        iconPaths: superAdminNotificationIconPaths.listingReview,
        badgeTitle: "Listing in review",
      },
      "product-resubmitted": {
        modifier: "updated",
        iconPaths: superAdminNotificationIconPaths.edit,
        badgeTitle: "Listing updated",
      },
      "product-revision-resubmitted": {
        modifier: "revision",
        iconPaths: superAdminNotificationIconPaths.revision,
        badgeTitle: "Revision submitted",
      },
      "product-deleted": {
        modifier: "deleted",
        iconPaths: superAdminNotificationIconPaths.delete,
        badgeTitle: "Listing deleted",
      },
      "seller-feedback": {
        modifier: "feedback",
        iconPaths: superAdminNotificationIconPaths.feedback,
        badgeTitle: "Feedback",
      },
      "user-feedback": {
        modifier: "feedback",
        iconPaths: superAdminNotificationIconPaths.feedback,
        badgeTitle: "Feedback",
      },
      "seller-profile-updated": {
        modifier: "profile",
        iconPaths: superAdminNotificationIconPaths.edit,
        badgeTitle: "Profile updated",
      },
      "seller-account-deletion": {
        modifier: "deleted",
        iconPaths: superAdminNotificationIconPaths.delete,
        badgeTitle: "Account deleting",
      },
      "seller-account-deletion-canceled": {
        modifier: "profile",
        iconPaths: superAdminNotificationIconPaths.edit,
        badgeTitle: "Deletion canceled",
      },
      "seller-account-deleted": {
        modifier: "deleted",
        iconPaths: superAdminNotificationIconPaths.delete,
        badgeTitle: "Account deleted",
      },
      welcome: {
        modifier: "welcome",
        iconPaths: superAdminNotificationIconPaths.welcome,
        badgeTitle: "Welcome",
      },
    };
    return configs[type] || configs["product-submitted"];
  }

  function buildSuperAdminNotificationMessageParts(entry) {
    const type = getSuperAdminNotificationType(entry);
    const name = getSuperAdminNotificationActorName(entry);
    const productName = String(
      entry?.product?.name
      || entry?.notification?.productName
      || "Unnamed product",
    ).trim();

    if (type === "product-submitted" || type === "product-created") {
      return [
        { kind: "company", text: name },
        { kind: "text", text: " has submitted " },
        { kind: "important", text: productName },
        { kind: "text", text: ", which is now pending " },
        { kind: "important", text: "listing review" },
        { kind: "text", text: "." },
      ];
    }
    if (type === "product-resubmitted") {
      return [
        { kind: "company", text: name },
        { kind: "text", text: " updated " },
        { kind: "important", text: productName },
        { kind: "text", text: " and it is pending " },
        { kind: "important", text: "listing review" },
        { kind: "text", text: "." },
      ];
    }
    if (type === "product-revision-resubmitted") {
      return [
        { kind: "company", text: name },
        { kind: "text", text: " submitted revisions for " },
        { kind: "important", text: productName },
        { kind: "text", text: " and it is pending " },
        { kind: "important", text: "listing review" },
        { kind: "text", text: "." },
      ];
    }
    if (type === "product-deleted") {
      return [
        { kind: "company", text: name },
        { kind: "text", text: " deleted " },
        { kind: "important", text: productName },
        { kind: "text", text: "." },
      ];
    }
    if (type === "seller-feedback" || type === "user-feedback") {
      return [
        { kind: "company", text: name },
        { kind: "text", text: " submitted " },
        { kind: "important", text: getFeedbackNotificationLabel(entry?.notification) },
        { kind: "text", text: "." },
      ];
    }
    if (type === "seller-profile-updated") {
      return [
        { kind: "company", text: name },
        { kind: "text", text: " updated seller profile." },
      ];
    }
    if (type === "seller-account-deletion") {
      return [
        { kind: "company", text: name },
        { kind: "text", text: " scheduled seller account deletion in 30 days." },
      ];
    }
    if (type === "seller-account-deletion-canceled") {
      return [
        { kind: "company", text: name },
        { kind: "text", text: " canceled seller account deletion." },
      ];
    }
    if (type === "seller-account-deleted") {
      return [
        { kind: "company", text: name },
        { kind: "text", text: " completed the 30-day deletion period." },
      ];
    }
    if (type === "welcome") {
      const message = String(
        entry?.notification?.message
        || "Your command center is ready. Seller onboarding, listing reviews, account actions, and platform alerts will land here.",
      ).trim();
      return [{ kind: "text", text: message }];
    }

    return [{
      kind: "text",
      text: String(
        entry?.notification?.message
        || entry?.notification?.title
        || "Notification received.",
      ).trim(),
    }];
  }

  function renderSuperAdminNotificationMessage(messageEl, parts) {
    if (!(messageEl instanceof HTMLElement)) {
      return;
    }
    messageEl.replaceChildren();
    for (const part of parts) {
      if (part.kind === "company") {
        const label = document.createElement("span");
        label.className = "super-admin-notification-activity__company";
        label.textContent = part.text;
        messageEl.append(label);
        continue;
      }
      if (part.kind === "important") {
        const label = document.createElement("span");
        label.className = "super-admin-notification-activity__important";
        label.textContent = part.text;
        messageEl.append(label);
        continue;
      }
      messageEl.append(part.text);
    }
  }

  function applySuperAdminNotificationBadge(item, entry) {
    const badge = item.querySelector(".activity-item__action-badge");
    if (!(badge instanceof HTMLElement)) {
      return;
    }
    const config = getSuperAdminNotificationVisualConfig(entry);
    badge.className = `activity-item__action-badge activity-item__action-badge--${config.modifier}`;
    badge.setAttribute("title", config.badgeTitle);
    badge.innerHTML = createIconSvg(config.iconPaths);
  }

  function getSuperAdminNotificationTimestampLabel(entry) {
    const timestamp = String(
      entry?.createdAt
      || entry?.notification?.createdAt
      || entry?.product?.submittedAt
      || entry?.product?.createdAt
      || "",
    ).trim();
    if (entry?.product && (entry?.kind === "product-request" || isListingSuperAdminNotificationType(entry))) {
      return getProductRequestAgeLabel({
        ...entry.product,
        submittedAt: timestamp || entry.product.submittedAt,
        createdAt: timestamp || entry.product.createdAt,
      });
    }
    const parsed = Date.parse(timestamp);
    if (Number.isNaN(parsed)) {
      return "Recently";
    }
    const elapsedSeconds = Math.max(0, Math.floor((Date.now() - parsed) / 1000));
    if (elapsedSeconds < 3600) {
      const minutes = Math.max(1, Math.floor(elapsedSeconds / 60));
      return `${numberText(minutes)}m ago`;
    }
    if (elapsedSeconds < 86400) {
      return `${numberText(Math.floor(elapsedSeconds / 3600))}h ago`;
    }
    const days = Math.floor(elapsedSeconds / 86400);
    if (days < 30) {
      return `${numberText(days)} day${days === 1 ? "" : "s"} ago`;
    }
    return formatRelativeTime(timestamp);
  }

  function isListingSuperAdminNotificationType(entry) {
    return ["product-submitted", "product-resubmitted", "product-revision-resubmitted", "product-created", "product-deleted"].includes(
      getSuperAdminNotificationType(entry),
    );
  }

  function getSuperAdminNotificationDestination(entry) {
    const targetUrl = String(entry?.notification?.targetUrl || "").trim();
    const hashMatch = targetUrl.match(/#([a-z0-9-]+)/i);
    if (hashMatch?.[1]) {
      return hashMatch[1];
    }
    if (entry?.kind === "product-request" || isListingSuperAdminNotificationType(entry)) {
      return "product-requests";
    }
    const type = getSuperAdminNotificationType(entry);
    if (type === "seller-feedback") {
      return "seller-feedback";
    }
    if (type === "user-feedback") {
      return "user-feedback";
    }
    if (
      type === "seller-flash-deal-submitted" ||
      type === "seller-flash-deal-cancelled" ||
      type === "seller-flash-deal-ended" ||
      type === "flash-deal-submitted"
    ) {
      return "flash-deals";
    }
    if (type === "welcome") {
      return "dashboard";
    }
    return "companies";
  }

  function getSuperAdminNotificationAriaLabel(entry) {
    const parts = buildSuperAdminNotificationMessageParts(entry);
    const text = parts.map((part) => part.text).join("").trim();
    if (text) {
      return text.endsWith(".") ? text : `${text}.`;
    }
    return "Open super admin notification";
  }

  function applyNotificationCompanyAvatar(item, product, companyName) {
    const avatar = item.querySelector(".activity-item__avatar");
    const avatarIcon = item.querySelector(".activity-item__avatar-icon");
    if (!(avatar instanceof HTMLElement) || !(avatarIcon instanceof HTMLElement)) {
      return;
    }

    const companyAdmin = getProductCompanyAdmin(product);
    const toneIndex = getProductCompanyToneIndex(product, companyAdmin);
    avatar.classList.remove(
      "has-image",
      "super-admin-company-card__logo--tone-1",
      "super-admin-company-card__logo--tone-2",
      "super-admin-company-card__logo--tone-3",
      "super-admin-company-card__logo--tone-4",
      "super-admin-company-card__logo--tone-5",
      "super-admin-company-card__logo--tone-6",
    );
    avatar.classList.add(
      "super-admin-company-card__logo",
      `super-admin-company-card__logo--tone-${toneIndex}`,
    );

    const applyDefaultCompanyLogo = () => {
      avatar.classList.remove("has-image");
      avatarIcon.textContent = "";
      avatarIcon.innerHTML = createIconSvg(companyBuildingIconPaths);
    };

    // Live company account is the source of truth (same as company cards).
    // Default / skipped logos must not fall back to stale product snapshots.
    let companyImageUrl = "";
    if (companyAdmin) {
      companyImageUrl = getCompanyImageUrl(companyAdmin);
    } else {
      companyImageUrl = String(
        product?.companyPictureUrl ||
          product?.companyProfileImageUrl ||
          product?.companyLogoUrl ||
          product?.companyImageUrl ||
          product?.profileImageUrl ||
          product?.logoUrl ||
          "",
      ).trim();
    }

    if (!companyImageUrl) {
      applyDefaultCompanyLogo();
      return;
    }

    const companyImage = document.createElement("img");
    companyImage.src = companyImageUrl;
    companyImage.alt = `${companyName || "Company"} logo`;
    companyImage.loading = "lazy";
    companyImage.decoding = "async";
    companyImage.addEventListener("error", applyDefaultCompanyLogo, { once: true });
    avatar.classList.add("has-image");
    avatarIcon.replaceChildren(companyImage);
  }

  const SWITCH_LOGO_PATH = "/switch-logo.svg";

  function applySwitchLogoAvatar(item) {
    const avatar = item.querySelector(".activity-item__avatar");
    const avatarIcon = item.querySelector(".activity-item__avatar-icon");
    if (!(avatar instanceof HTMLElement) || !(avatarIcon instanceof HTMLElement)) {
      return;
    }
    avatar.classList.add("has-image", "is-switch-logo");
    const logo = document.createElement("img");
    logo.src = SWITCH_LOGO_PATH;
    logo.alt = "Switch";
    logo.loading = "lazy";
    logo.decoding = "async";
    avatarIcon.replaceChildren(logo);
  }

  function createSuperAdminNotificationItem(entry) {
    const item = document.createElement("article");
    const isUnread = isProductRequestNotificationUnread(entry);
    const companyName = getProductCompanyLabel(entry?.product || {});
    const productId = String(entry?.product?.id || entry?.product?.productId || entry?.notification?.productId || entry?.id || "").trim();
    const isWelcome = getSuperAdminNotificationType(entry) === "welcome";
    item.className = "activity-item activity-item--notification activity-item--clickable super-admin-notification-activity";
    item.classList.toggle("is-new-notification", isUnread);
    item.classList.toggle("is-welcome-notification", isWelcome);
    if (productId && !isWelcome) {
      item.dataset.productId = productId;
    }
    item.tabIndex = 0;
    item.setAttribute("role", "link");
    item.setAttribute("aria-label", getSuperAdminNotificationAriaLabel(entry));
    item.innerHTML = `
      <span class="activity-item__avatar activity-item__avatar--admin${isWelcome ? " activity-item__avatar--welcome" : ""}" aria-hidden="true">
        <span class="activity-item__avatar-icon">
          ${createIconSvg(companyBuildingIconPaths)}
        </span>
      </span>
      <div class="activity-item__body">
        <p></p>
        <span class="activity-item__timestamp"></span>
      </div>
      <span class="super-admin-notification-activity__unread-dot" aria-hidden="true"></span>
    `;
    if (isWelcome) {
      applySwitchLogoAvatar(item);
    } else {
      applyNotificationCompanyAvatar(item, entry?.product || {}, companyName);
    }
    renderSuperAdminNotificationMessage(item.querySelector("p"), buildSuperAdminNotificationMessageParts(entry));
    const timestampEl = item.querySelector(".activity-item__timestamp");
    if (timestampEl) {
      timestampEl.textContent = getSuperAdminNotificationTimestampLabel(entry);
    }

    let isActivating = false;
    const openNotificationDestination = () => {
      if (isActivating) {
        return;
      }
      isActivating = true;
      markSuperAdminNotificationRead(entry);
      item.classList.add("is-activating");
      item.setAttribute("aria-busy", "true");

      const destination = getSuperAdminNotificationDestination(entry);
      const navigate = async () => {
        prepareSuperAdminNotificationTrace(entry);
        setNotificationPanelOpen(false);
        if (destination === "seller-feedback" || destination === "user-feedback") {
          if (!state.platformFeedback.loaded) {
            await loadPlatformFeedback({ quiet: true });
          }
          const feedbackType = destination === "user-feedback" ? "user" : "seller";
          const feedbackId = resolveFeedbackIdFromNotificationEntry(entry);
          if (feedbackId) {
            state.notificationTrace.kind = "feedback";
            state.notificationTrace.feedbackId = feedbackId;
            state.notificationTrace.feedbackType = feedbackType;
            state.notificationTrace.openDrawer = true;
            preparePlatformFeedbackNotificationNavigation(feedbackType, feedbackId);
          }
        }
        if (destination === "companies" && !state.admins.length) {
          await loadAdmins({ quiet: true });
          const adminId = String(entry?.notification?.adminId || entry?.product?.adminId || "").trim();
          if (adminId) {
            prepareCompanyNotificationNavigation(adminId);
          }
        }
        setActiveSection(destination);
        window.location.hash = destination;
      };
      if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
        void navigate();
        return;
      }
      window.setTimeout(() => {
        void navigate();
      }, 240);
    };
    item.addEventListener("click", openNotificationDestination);
    item.addEventListener("keydown", (event) => {
      if (event.key !== "Enter" && event.key !== " ") {
        return;
      }
      event.preventDefault();
      openNotificationDestination();
    });
    return item;
  }

  function createProductRequestNotificationItem(entry) {
    return createSuperAdminNotificationItem(entry);
  }

  function createNotificationPanelItem(entry) {
    return createSuperAdminNotificationItem(entry);
  }

  // Renders notification panel from the latest state.
  function renderNotificationPanel() {
    if (!elements.notificationList) {
      return;
    }

    const nextSignature = getNotificationPanelRenderSignature();
    if (
      nextSignature === lastNotificationPanelSignature &&
      elements.notificationList.childElementCount > 0
    ) {
      updateNotificationCount();
      syncNotificationFilterControls();
      return;
    }
    lastNotificationPanelSignature = nextSignature;

    elements.notificationList.innerHTML = "";
    const entries = getNotificationPanelEntries();
    const visibleEntries = state.notificationFilter === "unread"
      ? entries.filter(isProductRequestNotificationUnread)
      : entries;
    const canExpand = visibleEntries.length > notificationCollapsedLimit;
    if (!canExpand) {
      state.notificationExpanded = false;
    }
    const isExpanded = canExpand && state.notificationExpanded;
    const isScrollable = isExpanded && visibleEntries.length >= notificationScrollThreshold;
    elements.notificationPanel?.classList.toggle("is-notification-expanded", isExpanded);
    elements.notificationPanel?.classList.toggle("is-notification-scrollable", isScrollable);
    elements.notificationList.classList.toggle("is-notification-expanded", isExpanded);
    elements.notificationList.classList.toggle("is-notification-scrollable", isScrollable);
    if (elements.notificationFooter) {
      elements.notificationFooter.hidden = !canExpand;
    }
    if (elements.notificationShowAll) {
      elements.notificationShowAll.textContent = isExpanded
        ? "Show fewer notifications"
        : "Show all notifications";
      elements.notificationShowAll.setAttribute("aria-expanded", String(isExpanded));
    }
    syncNotificationFilterControls();
    updateNotificationCount();
    if (!visibleEntries.length) {
      const emptyState = document.createElement("div");
      emptyState.className = "empty-state";
      if (!entries.length && state.productNotificationsLoading) {
        emptyState.textContent = "Loading notifications...";
      } else if (!entries.length && state.productNotificationsError) {
        emptyState.textContent = "Unable to load notifications.";
      } else {
        emptyState.textContent = state.notificationFilter === "unread"
          ? "No unread notification."
          : "No notification yet.";
      }
      elements.notificationList.append(emptyState);
      if (!elements.notificationPanel?.hidden) {
        positionNotificationPanel();
      }
      return;
    }

    const renderedEntries = isExpanded
      ? visibleEntries
      : visibleEntries.slice(0, notificationCollapsedLimit);
    for (const entry of renderedEntries) {
      elements.notificationList.append(createNotificationPanelItem(entry));
    }
    if (!elements.notificationPanel?.hidden) {
      positionNotificationPanel();
    }
    renderDashboard();
  }

  function positionNotificationPanel() {
    if (!elements.notificationBtn || !elements.notificationPanel) {
      return;
    }
    if (!window.matchMedia("(max-width: 640px)").matches) {
      elements.notificationPanel.style.removeProperty("--super-admin-notification-panel-top");
    } else {
      const buttonRect = elements.notificationBtn.getBoundingClientRect();
      const preferredTop = Math.max(12, Math.ceil(buttonRect.bottom + 8));
      const panelTop = window.innerHeight - preferredTop >= 320 ? preferredTop : 12;
      elements.notificationPanel.style.setProperty(
        "--super-admin-notification-panel-top",
        `${panelTop}px`,
      );
    }

    const panelTop = elements.notificationPanel.getBoundingClientRect().top;
    const availableHeight = Math.max(240, Math.floor(window.innerHeight - panelTop - 20));
    elements.notificationPanel.style.setProperty(
      "--super-admin-notification-expanded-height",
      `${availableHeight}px`,
    );
  }

  // Updates notification panel open and synchronizes related UI state.
  function setNotificationPanelOpen(isOpen) {
    if (!elements.notificationBtn || !elements.notificationPanel) return;
    if (!isOpen) {
      state.notificationExpanded = false;
      elements.notificationPanel.classList.remove("is-notification-expanded", "is-notification-scrollable");
      elements.notificationList?.classList.remove("is-notification-expanded", "is-notification-scrollable");
    }
    elements.notificationBtn.setAttribute("aria-expanded", String(Boolean(isOpen)));
    elements.notificationPanel.hidden = !isOpen;
    if (isOpen) {
      renderNotificationPanel();
      positionNotificationPanel();
    }
  }

  // Toggles notification panel between open and closed states.
  function toggleNotificationPanel(show) {
    const shouldShow = show === undefined ? Boolean(elements.notificationPanel?.hidden) : Boolean(show);
    setNotificationPanelOpen(shouldShow);
    if (shouldShow) {
      togglePlatformFeedbackFilterDropdown(false);
      toggleFilterDropdown(false);
      toggleProductRequestFilterDropdown(false);
      toggleColorPicker(false);
    }
  }

